import java.math.*;

public class Main {
    private static List<Integer> primeFactorization(int x) {
        List<Integer> answer = new ArrayList<>();
        int i = 2;
        while (i * i <= x) {
            if (x % i == 0) {
                answer.add(i);
                while (x % i == 0)
                    x /= i;
            }
            i += 1;
        }
        if (x > 1)
            answer.add(x);
        return answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int n = sc.nextInt();
        System.out.println(main(x, n));
    }

    public static int main(int x, int n) {
        int mod = (int) Math.pow(10, 9) + 7;
        List<Integer> xPrimes = primeFactorization(x);
        int answer = 1;
        for (int prime : xPrimes) {
            int power = 0;
            int factor = prime;
            while (factor <= n) {
                power += n / factor;
                factor *= prime;
            }
            answer = (answer * BigInteger.valueOf(prime).modPow(BigInteger.valueOf(power), BigInteger.valueOf(mod)).intValue()) % mod;
        }
        return answer;
    }
}

