import java.util.*;

public class Main {
    static final long MOD = 1000000007;
    static ArrayList<Long> primeFactors(long x) {
        ArrayList<Long> ans = new ArrayList<Long>();
        long i = 2;
        while (i * i <= x) {
            if (x % i == 0) {
                ans.add(i);
                while (x % i == 0)
                    x = x / i;
            }
            i = i + 1;
        }
        if (x > 1)
            ans.add(x);
        return ans;
    }
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long n = scanner.nextLong();
        scanner.close();
        ArrayList<Long> prime = primeFactors(x);
        long ans = 1;
        for (long num : prime) {
            long p = 0;
            long tmp = num;
            while (tmp <= n) {
                p = p + n / tmp;
                tmp = tmp * num;
            }
            ans = (ans * pow(num, p, MOD)) % MOD;
        }
        System.out.println(ans);
    }
    static long pow(long x, long p, long MOD) {
        if (p == 0)
            return 1;
        if (p % 2 == 0) {
            long temp = pow(x, p / 2, MOD);
            return (temp * temp) % MOD;
        } else
            return (x * pow(x, p - 1, MOD)) % MOD;
    }
}

