import java.util.*;
import java.lang.*;
import java.io.*;

class Main {
    static int[] spf;
    static int MAXN = 100005;
    static void spf_sieve() {
        spf = new int[MAXN];
        for(int i = 0; i < MAXN; i++)
            spf[i] = i;
        for(int i = 4; i < MAXN; i+=2)
            spf[i] = 2;
        for(int i = 3; i <= Math.sqrt(MAXN); i+=2) {
            if(spf[i] == i) {
                for(int j = i * i; j < MAXN; j += i) {
                    if(spf[j] == j)
                        spf[j] = i;
                }
            }
        }
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] str = br.readLine().split(" ");
        int n = Integer.parseInt(str[0]);
        int x = Integer.parseInt(str[1]);
        str = br.readLine().split(" ");
        int[] a = new int[n];
        for(int i = 0; i < n; i++)
            a[i] = Integer.parseInt(str[i]);
        int[] cnt = new int[n];
        int k = x;
        for(int i = n - 1; i >= 0; i--) {
            int p = (int) Math.pow(2, i);
            cnt[i] += k / p;
            k %= p;
        }
        int[] mnt = a.clone();
        for(int i = 1; i < n; i++)
            mnt[i] = Math.min(2 * mnt[i - 1], mnt[i]);
        int ans = 0;
        for(int i = 0; i < n; i++)
            ans += mnt[i] * cnt[i];
        int this_ = 0;
        for(int i = n - 1; i >= 0; i--) {
            this_ += (cnt[i] + 1) * mnt[i];
            ans = Math.min(ans, this_);
            this_ -= mnt[i];
        }
        System.out.println(ans);
    }
}

