import java.util.stream.*;

class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int d = scanner.nextInt();
        scanner.nextLine();

        List<String> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String s = scanner.nextLine();
            list.add(s);
        }

        String st = "";
        for (int i = 0; i < d; i++) {
            st += String.valueOf(i);
        }

        int maxDiff = (int) Math.pow(10, 9);
        for (String permutation : permutations(st)) {
            String[] arr = permutation.split("");
            int[] ans = new int[arr.length];
            for (int i = 0; i < arr.length; i++) {
                ans[i] = Integer.parseInt(arr[i]);
            }

            int[] aa = new int[list.size()];
            for (int i = 0; i < list.size(); i++) {
                String str = list.get(i);
                String k = "";
                for (int m : ans) {
                    k += str.charAt(m);
                }
                aa[i] = Integer.parseInt(k);
            }

            int maxAa = Arrays.stream(aa).max().getAsInt();
            int minAa = Arrays.stream(aa).min().getAsInt();
            maxDiff = Math.min(maxAa - minAa, maxDiff);
        }

        System.out.println(maxDiff);
    }

    public static String permutations(String str) {
        List<String> result = new ArrayList<>();
        permutation("", str, result);
        return String.join(",", result);
    }

    private static void permutation(String prefix, String str, List<String> result) {
        int n = str.length();
        if (n == 0) {
            result.add(prefix);
        } else {
            for (int i = 0; i < n; i++)
                permutation(prefix + str.charAt(i), str.substring(0, i) + str.substring(i + 1, n), result);
        }
    }
}

