import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        System.out.println(solve(n, m));
    }

    static boolean[] digits(int x, int k) {
        boolean[] d = new boolean[7];
        for (int i = 0; i < k; i++) {
            if (d[x % 7]) {
                return false;
            }
            d[x % 7] = true;
            x /= 7;
        }
        return true;
    }

    static int solve(int n, int m) {
        if (n * m > 7 * 7 * 7 * 7 * 7 * 7 * 7) {
            return 0;
        }
        int k1 = (int) Math.ceil(Math.log(n) / Math.log(7)) > 1? (int) Math.ceil(Math.log(n) / Math.log(7)) : 1;
        int k2 = (int) Math.ceil(Math.log(m) / Math.log(7)) > 1? (int) Math.ceil(Math.log(m) / Math.log(7)) : 1;
        int s = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (digits(i * (int) Math.pow(7, k2) + j, k1 + k2)) {
                    s++;
                }
            }
        }
        return s;
    }
}

