public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.close();

        int[] len = new int[n+1];
        for(int i=1; i<=n; i++) {
            len[i] = len[i-1]*2 + 1;
        }

        System.out.println(get(n, k, len));
    }

    private static int get(int n, int k, int[] len) {
        if(k == len[n-1] + 1) {
            return n;
        }
        if(k > len[n-1] + 1) {
            return get(n - 1, k - len[n-1] - 1, len);
        }
        return get(n - 1, k, len);
    }
}

