import java.util.*;

public class Main {

    static HashMap<String, Integer> possibleTable = new HashMap<>();
    static String phoneNumbers;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        phoneNumbers = scanner.next();
        int count = 0;
        for (int i = 0; i < 10; i++) {
            count += findPossibleNumber(i, 1);
        }
        if (hasException(Integer.parseInt(String.valueOf(phoneNumbers.charAt(0))))) {
            count -= 1;
        }
        System.out.println(count);
    }

    public static int findPossibleNumber(int guessNumber, int digit) {
        if (digit == phoneNumbers.length()) {
            return 1;
        }
        int mNumber = Integer.parseInt(String.valueOf(phoneNumbers.charAt(digit)));
        guessNumber = Integer.parseInt(String.valueOf(guessNumber));
        String numIndexConfiguration = guessNumber + "" + digit;
        if (possibleTable.containsKey(numIndexConfiguration)) {
            return possibleTable.get(numIndexConfiguration);
        }
        possibleTable.put(numIndexConfiguration, 0);
        int hasRemainder = (mNumber + guessNumber) % 2;
        if (hasRemainder!= 0) {
            hasRemainderCase(mNumber, guessNumber, numIndexConfiguration, digit);
        } else {
            hasNoRemainderCase(mNumber, guessNumber, numIndexConfiguration, digit);
        }
        return possibleTable.get(numIndexConfiguration);
    }

    public static void hasRemainderCase(int mNumber, int guessNumber, String numIndexConfiguration, int digit) {
        int upperNumber = (int) Math.ceil((mNumber + guessNumber) / 2.0);
        possibleTable.put(numIndexConfiguration, possibleTable.get(numIndexConfiguration) + findPossibleNumber(upperNumber, digit + 1));
        int lowerNumber = (int) Math.floor((mNumber + guessNumber) / 2.0);
        possibleTable.put(numIndexConfiguration, possibleTable.get(numIndexConfiguration) + findPossibleNumber(lowerNumber, digit + 1));
    }

    public static void hasNoRemainderCase(int mNumber, int guessNumber, String numIndexConfiguration, int digit) {
        int nextNumber = (mNumber + guessNumber) / 2;
        possibleTable.put(numIndexConfiguration, possibleTable.get(numIndexConfiguration) + findPossibleNumber(nextNumber, digit + 1));
    }

    public static boolean hasException(int number) {
        for (int i = 0; i < phoneNumbers.length() - 1; i++) {
            if (Math.abs(Integer.parseInt(String.valueOf(phoneNumbers.charAt(i))) - Integer.parseInt(String.valueOf(phoneNumbers.charAt(i + 1)))) <= 1) {
                continue;
            } else {
                return false;
            }
        }
        return true;
    }
}

