import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();
        String[] cards = sc.nextLine().split(" ");
        sc.close();

        if (cards.length == 1) {
            System.out.println(0);
            return;
        }

        int answer = 9;
        String chars = "RGBYW12345";

        for (int mask = 1; mask < 1024; mask++) {
            String cover = "";
            for (int i = 0; i < 10; i++) {
                if ((mask & (1 << i))!= 0) {
                    cover += chars.charAt(i);
                }
            }

            Map<Character, Integer> d = new HashMap<>();
            for (String card : cards) {
                if (cover.contains(String.valueOf(card.charAt(0))) && cover.contains(String.valueOf(card.charAt(1)))) {
                    continue;
                }
                if (cover.contains(String.valueOf(card.charAt(0)))) {
                    d.put(card.charAt(0), d.getOrDefault(card.charAt(0), 0) + 1);
                } else if (cover.contains(String.valueOf(card.charAt(1)))) {
                    d.put(card.charAt(1), d.getOrDefault(card.charAt(1), 0) + 1);
                } else {
                    d.put('*', d.getOrDefault('*', 0) + 1);
                }
            }

            if (d.values().stream().allMatch(val -> val <= 1)) {
                answer = Math.min(answer, cover.length());
            }
        }

        System.out.println(answer);
    }
}

