        int m = scanner.nextInt();
        int t = scanner.nextInt();
        long ways = 0;
        int a = 4;
        int b = t - a;
        while (a <= n && b!= 0) {
            if (b <= m) {
                ways += ncr(n, a) * ncr(m, b);
            }
            a = a + 1;
            b = t - a;
        }
        System.out.println(ways);
    }

    public static long ncr(int n, int r) {
        r = Math.min(r, n - r);
        long numer = 1;
        long denom = 1;
        for (int i = n; i >= n - r + 1; i--) {
            numer *= i;
        }
        for (int i = 1; i <= r; i++) {
            denom *= i;
        }
        return numer / denom;
    }
}

