        int xl = l;
        while (xl % 3!= 0 && xl < r) xl++;
        int xr = r;
        while (xr % 3!= 0 && xr > xl) xr--;
        if (xl <= xr && xl % 3 == 0 && xr % 3 == 0) a0 = (xr - xl) / 3 + 1;

        xl = l;
        while (xl % 3!= 1 && xl < r) xl++;
        xr = r;
        while (xr % 3!= 1 && xr > xl) xr--;
        if (xl <= xr && xl % 3 == 1 && xr % 3 == 1) a1 = (xr - xl) / 3 + 1;

        xl = l;
        while (xl % 3!= 2 && xl < r) xl++;
        xr = r;
        while (xr % 3!= 2 && xr > xl) xr--;
        if (xl <= xr && xl % 3 == 2 && xr % 3 == 2) a2 = (xr - xl) / 3 + 1;

        int[][] dp = new int[n + 1][3];

        dp[1][0] = a0 % MOD;
        dp[1][1] = a1 % MOD;
        dp[1][2] = a2 % MOD;

