public class Main {
    public static void binaryMedian(int[][] m, int r, int d) {
        int mi = m[0][0];
        int mx = 0;
        for (int i = 0; i < r; i++) {
            if (m[i][0] < mi) {
                mi = m[i][0];
            }
            if (m[i][d - 1] > mx) {
                mx = m[i][d - 1];
            }
        }
        int desired = (r * d + 1) / 2;
        while (mi < mx) {
            int mid = mi + (mx - mi) / 2;
            int[] place = new int[1];
            for (int i = 0; i < r; i++) {
