                mi = mid + 1;
            } else {
                mx = mid;
            }
        }
        System.out.println("Median is " + mi);
    }

    public static int upperBound(int[] arr, int target) {
        int index = Arrays.binarySearch(arr, target);
        return index < 0? -index - 1 : index;
    }

