import java.util.*;

public class Main {
    static int INF = (int) 1e9;
    static long MOD = (long) 1e9 + 7;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n == 1) {
            System.out.println(0);
            return;
        }
        Map<Integer, Integer> fac = primeFactorize(n);
        int ans = 0;
        for (int p : fac.keySet()) {
            int x = fac.get(p);
            for (int i = 1; i < 100000000; i++) {
                if (x >= i) {
                    x -= i;
                    ans += 1;
                } else {
                    break;
                }
            }
        }
        System.out.println(ans);
    }

    static Map<Integer, Integer> primeFactorize(int n) {
        Map<Integer, Integer> a = new HashMap<>();
        while (n % 2 == 0) {
            a.put(2, a.getOrDefault(2, 0) + 1);
            n /= 2;
        }
        int f = 3;
        while (f * f <= n) {
            if (n % f == 0) {
                a.put(f, a.getOrDefault(f, 0) + 1);
                n /= f;
            } else {
                f += 2;
            }
        }
        if (n!= 1) {
            a.put(n, a.getOrDefault(n, 0) + 1);
        }
        return a;
    }
}

