public class Main {
    static int n, m, ci, cb, cc;
    static int[] vis;
    static List<Integer>[] g;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        m = in.nextInt();
        vis = new int[n + 1];
        g = new ArrayList[n + 1];
        for (int i = 1; i <= n; ++i) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < m; ++i) {
            int u = in.nextInt();
            int v = in.nextInt();
            g[u].add(v);
            g[v].add(u);
        }
        for (int i = 1; i <= n; ++i) {
            if (vis[i] == 0) {
                if (g[i].isEmpty()) {
                    ci++;
                } else {
                    if (dfs(i)) {
                        cb++;
                    } else {
                        cc++;
                    }
                }
            }
        }
        System.out.println((long) ci * ci + 2 * ci * (n - ci) + (long) cc * cc + 2L * cb * cc + 2L * cb * cb);
    }

    private static boolean dfs(int x) {
        Deque<int[]> stk = new ArrayDeque<>();
        stk.add(new int[]{x, 1});
        boolean flag = true;
        while (!stk.isEmpty()) {
            int[] cur = stk.removeLast();
            int u = cur[0], col = cur[1];
            if (vis[u]!= 0) {
                flag &= vis[u] == col;
                continue;
            }
            vis[u] = col;
            for (int i : g[u]) {
                stk.add(new int[]{i, 3 - col});
            }
        }
        return flag;
    }
}

