import java.util.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int K = in.nextInt();
        int R = N - K;
        long mod = (long)Math.pow(10, 9) + 7;

        for (int i = 1; i <= K; i++) {
            long ans = 0;
            if (N - K + 1 < i) {
                ans = 0;
            } else {
                ans = fact(R+1, i)*fact(K-1,i-1);
            }
            System.out.println(ans%mod);
        }
    }

    static BigInteger fact(int n, int r) {
        BigInteger fact = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            fact = fact.multiply(BigInteger.valueOf(i));
        }
        BigInteger denom = BigInteger.ONE;
        for (int i = 1; i <= r; i++) {
            denom = denom.multiply(BigInteger.valueOf(i));
        }
        for (int i = 1; i <= n-r; i++) {
            denom = denom.multiply(BigInteger.valueOf(i));
        }
        return fact.divide(denom);
    }
}

