    static long comb(long n, long k) {
        return (F[(int)n] * IF[(int)k] % MOD * IF[(int)(n - k)]) % MOD;
    }

    static long g(long n, long x) {
        if (n == 1) return 0;
        assert x >= 1;

        long dmg = n - 1;
        if (dmg >= x) {
            return pow(x, n, MOD);
        }

        long r = pow(dmg, n, MOD);
        for (long rem = 2; rem <= n; rem++) {
            long attr = (comb(n, rem) * pow(dmg, n - rem, MOD) % MOD * g(rem, x - dmg)) % MOD;
            r = (r + attr) % MOD;
        }

        return r;
    }

    static long pow(long a, long b, long m) {
        a %= m;
        long res = 1;
        while (b > 0) {
            if ((b & 1)!= 0)
                res = res * a % m;
            a = a * a % m;
            b >>= 1;
        }
        return res;
    }
}

