public class Main {
    static int DIGITS = 55;
    static int MAX_CNT = 6;
    static int[] NUMBERS = new int[DIGITS + 1];
    static int[] CUTOFFS = new int[DIGITS + 1];
    static int INF = (int)1e9;
    static Map<Integer, Integer>[] save = new HashMap[DIGITS];

    public static void main(String[] args) {
        for (int i = 0; i < DIGITS; i++) {
            save[i] = new HashMap<>();
        }

        for (int d = 1; d <= DIGITS; d++) {
            NUMBERS[d] = 10 * NUMBERS[d - 1] + 1;
            CUTOFFS[d] = (int)Math.pow(10, d - 1) * 50 / 81 + 15;
        }

        Scanner scanner = new Scanner(System.in);
        int X = scanner.nextInt();
        System.out.println(recurse(X, String.valueOf(X).length() + 1));
    }

    static int recurse(int value, int d) {
        if (d == 0) {
            return value == 0? 0 : INF;
        }

        if (save[d - 1].containsKey(value)) {
            return save[d - 1].get(value);
        }

        int ans = INF;

        for (int cnt = 0; cnt <= MAX_CNT; cnt++) {
            int nvalue = Math.abs(value - cnt * NUMBERS[d]);

            if (nvalue <= CUTOFFS[d]) {
                ans = Math.min(ans, cnt * d + recurse(nvalue, d - 1));
            }
        }

        save[d - 1].put(value, ans);
        return ans;
    }
}

