import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int c = scanner.nextInt();
        scanner.close();

        if (c <= 1) {
            System.out.println(0);
            return;
        }

        int sHigh = 1;
        while (cells(n, x, y, sHigh) < c) {
            sHigh *= 2;
        }

        int sLow = sHigh / 2;
        while (sHigh - sLow > 1) {
            int sMid = (sLow + sHigh) / 2;
            if (cells(n, x, y, sMid) >= c) {
                sHigh = sMid;
            } else {
                sLow = sMid;
            }
        }

        System.out.println(sHigh);
    }

    private static int corner(int a, int b, int s) {
        if (a > b) {
            int temp = a;
            a = b;
            b = temp;
        }

        if (s > b) {
            return a * b - corner(a, b, Math.max(0, a + b - 1 - s));
        }

        int s1 = Math.min(s, a);
        int res = s1 * (s1 + 1) / 2;
        int s2 = Math.max(0, Math.min(s - a, b - a));
        res += s2 * a;
        return res;
    }

    private static int cells(int n, int x, int y, int s) {
        int res = corner(x - 1, y - 1, s - 1) + corner(x - 1, n - y, s - 1);
        res += corner(n - x, y - 1, s - 1) + corner(n - x, n - y, s - 1);
        res += Math.min(s, x - 1) + Math.min(s, y - 1) + Math.min(s, n - x) + Math.min(s, n - y);
        return res + 1;
    }
}

