import java.util.*;

public class Main {
    static final int N = 400;
    static int[] v = new int[N];
    static int[] t = new int[N];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int t = scanner.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        if (t > n * 2) {
            mk(a);
            mk(reverse(a));
            int z = 0;
            for (int x : a) {
                z = Math.max(z, t[x] + t[321 - x] + count(a, x) * (t - 2 * n));
            }
            System.out.println(z);
        } else {
            mk(a);
            System.out.println(Arrays.stream(t).max().getAsInt());
        }
    }

    static void mk(int[] s) {
        Arrays.fill(v, 0);
        Arrays.fill(t, 0);
        for (int x : s) {
            int c = 0;
            int i = x;
            while (i > 0) {
                c = Math.max(c, v[i]);
                i -= i & -i;
            }
            t[x] = Math.max(t[x], c + 1);
            i = x;
            while (i < N) {
                v[i] = Math.max(v[i], c + 1);
                i += i & -i;
            }
        }
    }

    static int[] reverse(int[] a) {
        int[] b = new int[a.length];
        for (int i = 0; i < a.length; i++) {
            b[i] = 321 - a[a.length - 1 - i];
        }
        return b;
    }

    static int count(int[] a, int x) {
        int count = 0;
        for (int i : a) {
            if (i == x) {
                count++;
            }
        }
        return count;
    }
}

