import java.util.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int s = scanner.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }
        Map<Integer, Integer>[] dl = f(a, 0, n / 2, k, s);
        Map<Integer, Integer>[] dr = g(a, n / 2, n, k, s);
        int ans = 0;
        for (int i = 0; i <= k; i++) {
            for (Map.Entry<Integer, Integer> entry : dl[i].entrySet()) {
                int x = entry.getKey();
                int t = entry.getValue();
                for (int j = k - i; j <= k; j++) {
                    ans += t * dr[j].getOrDefault(x, 0);
                }
            }
        }
        System.out.println(ans);
    }

    private static Map<Integer, Integer>[] f(int[] a, int start, int end, int k, int s) {
        Map<Integer, Integer>[] res = new HashMap[k + 1];
        for (int i = 0; i <= k; i++) {
            res[i] = new HashMap<>();
        }
        res[k].put(0, 1);
        for (int i = start; i < end; i++) {
            Map<Integer, Integer>[] nr = new HashMap[k + 1];
            for (int j = 0; j <= k; j++) {
                nr[j] = new HashMap<>();
                for (Map.Entry<Integer, Integer> entry : res[j].entrySet()) {
                    int y = entry.getKey();
                    int t = entry.getValue();
                    if (j > 0 && a[i] <= 18 && factorial(a[i]) + y <= s) {
                        nr[j - 1].put(factorial(a[i]) + y, nr[j - 1].getOrDefault(factorial(a[i]) + y, 0) + t);
                    }
                    if (y + a[i] <= s) {
                        nr[j].put(y + a[i], nr[j].getOrDefault(y + a[i], 0) + t);
                    }
                    nr[j].put(y, nr[j].getOrDefault(y, 0) + t);
                }
            }
            res = nr;
        }
        return res;
    }

    private static Map<Integer, Integer>[] g(int[] a, int start, int end, int k, int s) {
        Map<Integer, Integer>[] res = new HashMap[k + 1];
        for (int i = 0; i <= k; i++) {
            res[i] = new HashMap<>();
        }
        res[k].put(s, 1);
        for (int i = start; i < end; i++) {
            Map<Integer, Integer>[] nr = new HashMap[k + 1];
            for (int j = 0; j <= k; j++) {
                nr[j] = new HashMap<>();
                for (Map.Entry<Integer, Integer> entry : res[j].entrySet()) {
                    int y = entry.getKey();
                    int t = entry.getValue();
                    if (j > 0 && a[i] <= 18 && y - factorial(a[i]) >= 0) {
                        nr[j - 1].put(y - factorial(a[i]), nr[j - 1].getOrDefault(y - factorial(a[i]), 0) + t);
                    }
                    if (y - a[i] >= 0) {
                        nr[j].put(y - a[i], nr[j].getOrDefault(y - a[i], 0) + t);
                    }
                    nr[j].put(y, nr[j].getOrDefault(y, 0) + t);
                }
            }
            res = nr;
        }
        return res;
    }

    private static int factorial(int n) {
        int result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }
}

