    public static int reflection(int num) {
        StringBuilder tmp = new StringBuilder();
        String numStr = String.valueOf(num);
        for (char c : numStr.toCharArray()) {
            int i = Character.getNumericValue(c);
            int ni = 9 - i;
            if (ni == 0 && tmp.length() == 0) {
                continue;
            }
            tmp.append(ni);
        }
        if (tmp.length() == 0) {
            return 0;
        }
        return Integer.parseInt(tmp.toString());
    }

    public static int solve(int l, int r) {
        int result = 0;
        result = Math.max(result, l * reflection(l));
        result = Math.max(result, r * reflection(r));

        int start = 0;
        while (5 * Math.pow(10, start) <= l) {
            start++;
        }

        while (5 * Math.pow(10, start) <= r) {
            int curNum = (int) (5 * Math.pow(10, start));
            result = Math.max(result, curNum * reflection(curNum));
            start++;
        }
        return result;
    }
}

