    public static int[] solve(int m, int cubes, int volume) {
        if (m == 0) {
            return new int[]{cubes, volume};
        }

        int x = 1;
        while (Math.pow(x, 3) <= m) {
            x += 1;
        }
        x -= 1;

        int[] best = solve(m - (int) Math.pow(x, 3), cubes + 1, volume + (int) Math.pow(x, 3));
        if (x > 1) {
            best = max(best, solve((int) Math.pow(x, 3) - 1 - ((int) Math.pow(x - 1, 3)), cubes + 1, volume + (int) Math.pow(x - 1, 3)));
        }

        return best;
    }

    public static int[] max(int[] a, int[] b) {
        if (a[0] > b[0]) {
            return a;
        } else if (a[0] < b[0]) {
            return b;
        } else {
            if (a[1] > b[1]) {
                return a;
            } else {
                return b;
            }
        }
    }
