    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null ||!st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    static int[][] process(int[][] grid, int a, int n, int m) {
        int[][] aux = new int[3000][3000];
        for (int i = 0; i < n; i++) {
            Deque<Integer> mi = new ArrayDeque<>();
            for (int j = 0; j < a; j++) {
                while (!mi.isEmpty() && grid[i][j] < mi.peekLast()) {
                    mi.pollLast();
                }
                mi.add(grid[i][j]);
            }

            aux[0][i] = mi.peekFirst();
            for (int j = a; j < m; j++) {
                if (mi.peekFirst() == grid[i][j - a]) {
                    mi.pollFirst();
                }
                while (!mi.isEmpty() && grid[i][j] < mi.peekLast()) {
                    mi.pollLast();
                }
                mi.add(grid[i][j]);
                aux[j - a + 1][i] = mi.peekFirst();
            }
        }

        return aux;
    }

    static void main() {
        int n = in.nextInt(), m = in.nextInt(), a = in.nextInt(), b = in.nextInt();
        double g = in.nextDouble(), x = in.nextDouble(), y = in.nextDouble(), z = in.nextDouble();

        int MOD = (int) z;
        double MODF = z;
        double MAGIC = 6755399441055744.0;
        double SHRT = 65536.0;

        double MODF_INV = 1.0 / MODF;
        double SHRT_INV = 1.0 / SHRT;

        double fround = (double x) -> (x + MAGIC) - MAGIC;
        double fmod = (double a) -> a - MODF * fround(MODF_INV * a);
        double fmul = (double a, double b, double c) -> fmod(fmod(a * SHRT) * fround(SHRT_INV * b) + a * (b - SHRT * fround(b * SHRT_INV)) + c);

        int[][] grid = new int[3000][3000];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = (int) g % MOD;
                g = fmul(g, x, y);
            }
        }

        int[][] aux1 = process(grid, b, n, m);
        int[][] aux2 = process(aux1, a, m - b + 1, n);

        long ans = 0;
        for (int i = 0; i < n - a + 1; i++) {
            for (int j = 0; j < m - b + 1; j++) {
                ans += aux2[i][j];
            }
        }

        out.println(ans);
    }

    public static void main(String[] args) {
        main();
        out.close();
    }
}

