    static List<Integer> printMin(int[] arr, int n, int k) {
        List<Integer> res = new ArrayList<>();
        Deque<Integer> Qi = new ArrayDeque<>();
        for (int i = 0; i < k; i++) {
            while (!Qi.isEmpty() && arr[i] <= arr[Qi.peekLast()])
                Qi.removeLast();
            Qi.addLast(i);
        }

        for (int i = k; i < n; i++) {
            res.add(arr[Qi.peekFirst()]);
            while (!Qi.isEmpty() && Qi.peekFirst() <= i - k)
                Qi.removeFirst();
            while (!Qi.isEmpty() && arr[i] <= arr[Qi.peekLast()])
                Qi.removeLast();
            Qi.addLast(i);
        }
        res.add(arr[Qi.peekFirst()]);
        return res;
    }

    static int modmuladd(int x, int y, int c, int z, double zinv) {
        int ans = sub(add(mul(x, y), c), mul(z, (int) (zinv * x * y + zinv * c)));
        if (ans >= z)
            return ans - z;
        else if (ans < 0)
            return ans + z;
        else
            return ans;
    }

