            System.out.println(pow(P, P - 1, M));
            return;
        }

        int[] f = new int[P];
        int[] c = new int[P];
        int ans = 1;

        for (int i = 0; i < P; i++) {
            if (f[i]!= 0) continue;

            int cnt = 1;
            int u = i;
            f[u] = 1;

            while (f[k[u]] == 0) {
                u = k[u];
                f[u] = 1;
                cnt++;
            }

            c[cnt]++;
        }

        for (int i = 1; i < P; i++) {
            if (c[i]!= 0) {
                int cnt = i * c[i] + (i > 1? 1 : 0);
                ans = (ans * pow(cnt, c[i], M)) % M;
            }
        }

        System.out.println(ans);
    }

    static int pow(int a, int b, int m) {
        int res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res * a) % m;
            }
            a = (a * a) % m;
            b >>= 1;
        }
        return res;
    }
