public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();

        for (int t = 0; t < T; t++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();

            if (a - b == 1) {
                if (millerRabin(a + b)) {
                    System.out.println("YES");
                } else {
                    System.out.println("NO");
                }
            } else {
                System.out.println("NO");
            }
        }
    }

    private static boolean millerRabin(int n) {
        if (n == 2 || n == 3) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        int s = 0;
        int d = n - 1;

        while (d % 2 == 0) {
            d >>= 1;
            s += 1;
        }

        for (int i = 0; i < 10; i++) {
            int a = 2 + (int) (Math.random() * (n - 4));
            if (!check(a, s, d, n)) {
                return false;
            }
        }
        return true;
    }

    private static boolean check(int a, int s, int d, int n) {
        BigInteger x = BigInteger.valueOf(a).modPow(BigInteger.valueOf(d), BigInteger.valueOf(n));
        if (x.equals(BigInteger.ONE) || x.equals(BigInteger.valueOf(n - 1))) {
            return true;
        }

        for (int i = 0; i < s - 1; i++) {
            if (x.equals(BigInteger.valueOf(n - 1))) {
                return true;
            }
            x = x.modPow(BigInteger.valueOf(2), BigInteger.valueOf(n));
        }
        return x.equals(BigInteger.valueOf(n - 1));
    }
}

