import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int K = scanner.nextInt();
        int A = scanner.nextInt();
        int B = scanner.nextInt();

        int cur = 1 + A;
        int[] nxt = new int[2 * N];

        for (int i = 0; i < N; i++) {
            nxt[2 * i] = (1 + i * K) - B;
            nxt[2 * i + 1] = (1 + i * K) + B;
        }

        int[] ans = new int[]{0, 10000000000};

        for (int i : nxt) {
            int L = i - cur;
            if (L > N * K || L < 0) {
                L %= N * K;
            }
            if (L == 0) {
                L = N * K;
            }
            int temp = gcd(L, N * K);
            ans[0] = Math.max(ans[0], N * K / temp);
            ans[1] = Math.min(ans[1], N * K / temp);
        }

        System.out.println(ans[1] + " " + ans[0]);
    }

    public static int gcd(int a, int b) {
        if (a == 0) {
            return b;
        }
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

import java.util.*;

public class Main {

    public static List<Integer> primeFactors(int n) {
        int i = 2;
        List<Integer> factors = new ArrayList<>();
        while (i * i <= n) {
            if (n % i!= 0) {
                i += 1;
            } else {
                n /= i;
                factors.add(i);
            }
        }
        if (n > 1) {
            factors.add(n);
        }
        return factors;
    }

    public static int myGcd(List<Integer> fact, int mm) {
        // print("my_gcd",fact,mm)
        int res = 1;
        for (int i : fact) {
            if (mm % i == 0) {
                mm = mm / i;
                res = res * i;
            }
        }
        // print("my_gcd", res)
        return res;
    }

    public static int[] solve(int n, int k, int a, int b) {
        int[] qq = {a + b, a - b, -a - b, -a + b};
        int mini = n * k;
        int maxi = 0;

        List<Integer> factN = primeFactors(n);
        List<Integer> fact = new ArrayList<>(factN);
        fact.addAll(primeFactors(k));

        int m = n * k;
        for (int q : qq) {
            for (int t = 1; t <= n; t++) {
                int mm = t * k + q;
                if (mm > 0) {
                    int x = myGcd(fact, mm);
                    // System.out.println(x);
                    int y = m / x;
                    if (y < mini) {
                        mini = y;
                    }
                    if (y > maxi) {
                        maxi = y;
                    }
                }
            }
        }
        return new int[]{mini, maxi};
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        int a = scanner.nextInt();
        int b = scanner.nextInt();

        int[] result = solve(n, k, a, b);
        System.out.println(result[0] + " " + result[1]);
    }
}

