import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        List<Double> l = new ArrayList<>();
        for (int k = 2; k <= 180000; k++) {
            l.add(Math.pow(k, 3.0));
        }
        long ma = 5 * (long) Math.pow(10, 15);
        long mi = (long) (4.8 * m);
        while (ma - mi > 1) {
            long mid = (ma + mi) / 2;
            if (check(mid, m, l)) {
                mi = mid;
            } else {
                ma = mid;
            }
        }
        if (check2(ma, m, l) == m) {
            System.out.println(ma);
        } else {
            System.out.println(-1);
        }
    }

    private static boolean check(long num, int m, List<Double> l) {
        return m > check2(num, m, l);
    }

    private static long check2(long num, int m, List<Double> l) {
        long sum = 0;
        for (int i = 0; i < Math.pow(num, 1.0 / 3); i++) {
            sum += Math.floor(num / l.get(i));
        }
        return sum;
    }
}

