import java.util.*;
import java.io.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter pr = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(br.readLine());
        int a = Integer.parseInt(br.readLine());
        List<Integer> g = new ArrayList<>();
        int t = a;
        for (int i = 0; i < n; i++) {
            if (t % 10!= 0) {
                g.add(t % 10);
            }
            t /= 10;
        }
        List<Integer> b = new ArrayList<>();
        for (int i : g) {
            if (i!= 1) {
                int gg = 2;
                for (int j = 2; j <= i; j++) {
                    if (gg < maxPrime(j)) {
                        gg = maxPrime(j);
                    }
                }
                b.add(gg);
                if (i == 9) {
                    b.addAll(Arrays.asList(2, 3, 3));
                } else {
                    for (int k = gg + 1; k <= i; k++) {
                        if (k == 6) {
                            b.add(3);
                        } else {
                            b.addAll(primes(k));
                        }
                    }
                }
            }
        }
        Collections.sort(b);
        Collections.reverse(b);
        for (int i : b) {
            pr.print(i);
        }
        pr.flush();
    }

    static int maxPrime(int n) {
        int maxPrime = -1;
        while (n % 2 == 0) {
            maxPrime = 2;
            n >>= 1;
        }
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            while (n % i == 0) {
                maxPrime = i;
                n /= i;
            }
        }
        if (n > 2) {
            maxPrime = n;
        }
        return maxPrime;
    }

    static List<Integer> primes(int n) {
        List<Integer> primfac = new ArrayList<>();
        while (n % 2 == 0) {
            primfac.add(2);
            n >>= 1;
        }
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            while (n % i == 0) {
                primfac.add(i);
                n /= i;
            }
        }
        if (n > 2) {
            primfac.add(n);
        }
        return primfac;
    }
}

