import java.util.*;

public class Main {
    static int INF = (int) Math.pow(10, 18);
    static int n;
    static int ans = INF;
    static ArrayList<Integer> p = new ArrayList<>();
    static HashMap<String, Integer> m = new HashMap<>();

    static boolean isPrime(int n) {
        int i = 2;
        while (i * i <= n) {
            if (n % i == 0) {
                return false;
            }
            i += 1;
        }
        return true;
    }

    static void f(int a, int b, int div) {
        if (b >= p.size()) {
            return;
        }
        if (div == n) {
            ans = Math.min(ans, a);
            return;
        }
        for (int j = 1; j < 60; j++) {
            if (a <= ans / p.get(b)) {
                a *= p.get(b);
                f(a, b + 1, div * (j + 1));
            } else {
                break;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int i = 2;
        while (p.size() < 12) {
            if (isPrime(i)) {
                p.add(i);
            }
            i += 1;
        }
        f(1, 0, 1);
        System.out.println(ans);
    }
}

