    static final int M = 1000000009;
    static long[] p = new long[4010];
    static long[] r = new long[4010];

    static long C(int n, int m) {
        return p[n] * r[m] * r[n - m];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int w = sc.nextInt();
        int b = sc.nextInt();

        p[0] = 1;
        r[0] = 1;
        for (int i = 1; i < 4010; i++) {
            p[i] = (p[i - 1] * i) % M;
            r[i] = pow(p[i], M - 2, M);
        }

        long sum = 0;
        for (int i = Math.max(1, n - w); i <= Math.min(n - 2, b); i++) {
            sum = (sum + p[w] * p[b] * (n - i - 1) * C(b - 1, i - 1) * C(w - 1, n - i - 1)) % M;
        }

        System.out.println(sum);
    }

    static long pow(long a, long b, long m) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res * a) % m;
            }
            a = (a * a) % m;
            b >>= 1;
        }
        return res;
    }
}

