import java.util.*;

public class Main {
    static int M = 1000000007;
    static int[] c = new int[32];
    static int s = 0;
    static int k;

    static void acc(int k, int s, int v) {
        if (k > 0) {
            acc(k - 1, s + 1, v * 2);
            acc(k - 1, s, v * 8);
        } else {
            c[s] += v;
        }
    }

    static int win(int u, int v, int w) {
        int x = 0;
        if (v < 10) {
            if (u < 6) {
                for (int i = 0; i < 11; i++) {
                    if (c[i] > 0) {
                        c[i]--;
                        x = (x + win(u + 1, v + i, w * (c[i] + 1) % M)) % M;
                        c[i]++;
                    }
                }
            } else {
                for (int i = v + 1; i < 10; i++) {
                    x = (x + w * c[i]) % M;
                }
            }
        }
        return x;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        int[] n = new int[input.length()];
        for (int i = 0; i < input.length(); i++) {
            n[i] = input.charAt(i) - '0';
