import java.util.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        int[] mArr = new int[input.length()];
        for (int i = 0; i < input.length(); i++) {
            mArr[i] = Integer.parseInt(String.valueOf(input.charAt(i)));
        }
        int[] lucky = new int[mArr.length + 1];
        for (int luckySize = 0; luckySize < mArr.length + 1; luckySize++) {
            lucky[luckySize] = getLuckyCount(mArr, luckySize);
        }
        System.out.println(resultMod(lucky, (int) Math.pow(10, 9) + 7));
    }

    private static int getLuckyCount(int[] mArr, int luckySize) {
        int maxWidth = mArr.length;
        int result = 0;
        for (int[] combination : combinations(maxWidth, luckySize)) {
            Set<Integer> luckySubset = new HashSet<>();
            for (int i : combination) {
                luckySubset.add(i);
            }
            result += getLuckySubsetCount(mArr, luckySubset);
        }
        return result - (luckySize == 0? 1 : 0);
    }

    private static int getLuckySubsetCount(int[] mArr, Set<Integer> luckySubset) {
        int width = mArr.length;
        int[][] A = new int[width][3];
        for (int i = 0; i < width; i++) {
            A[i][0] = (luckySubset.contains(i))? 2 : 8;
            A[i][1] = (int) Arrays.stream(range(10)).filter(x -> ((x!= 7 && x!= 4)?!luckySubset.contains(i) : (x == 7 || x == 4)) && x <= mArr[i]).count();
            A[i][2] = (int) Arrays.stream(range(10)).filter(x -> ((x!= 7 && x!= 4)?!luckySubset.contains(i) : (x == 7 || x == 4)) && x <= mArr[i]).max().getAsInt() == mArr[i];
        }
        int[][] B = new int[width][2];
        for (int i = 0; i < width; i++) {
            if (i == 0) {
                B[i][0] = A[i][0];
                B[i][1] = A[i][1];
            } else {
                B[i][0] = B[i - 1][0] * A[i][0];
                B[i][1] = (A[i][1] - 1) * B[i - 1][0] + (A[i][2]? B[i - 1][0] : B[i - 1][1]);
            }
        }
        return B[width - 1][1];
    }

    private static int[] range(int end) {
        return IntStream.range(0, end).toArray();
    }

    private static int[][] combinations(int n, int r) {
        int[][] combinations = new int[factorial(n) / (factorial(r) * factorial(n - r))][r];
        int[] data = new int[n];
        for (int i = 0; i < n; i++) {
            data[i] = i;
        }
        combination(combinations, data, n, r, 0, 0);
        return combinations;
    }

    private static void combination(int[][] combinations, int[] data, int n, int r, int index, int i) {
        if (index == r) {
            for (int j = 0; j < r; j++) {
                combinations[i][j] = data[j];
            }
            i++;
        } else {
            for (int j = i; j <= n - r + index; j++) {
                swap(data, i, j);
                combination(combinations, data, n, r, index + 1, i + 1);
                swap(data, i, j);
            }
        }
    }

    private static void swap(int[] data, int i, int j) {
        int temp = data[i];
        data[i] = data[j];
        data[j] = temp;
    }

    private static int factorial(int n) {
        int result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    private static int resultMod(int[] lucky, int modulo) {
        int result = 0;
        for (int luckyDigits = 1; luckyDigits < lucky.length; luckyDigits++) {
            Map<int[], Integer> combinations = new HashMap<>();
            for (int[] combination : sumCombinations(luckyDigits - 1, 6)) {
                int[] count = new int[10];
                for (int i : combination) {
                    count[i]++;
                }
                combinations.put(count, combinations.getOrDefault(count, 0) + 1);
            }
            for (Map.Entry<int[], Integer> entry : combinations.entrySet()) {
                int subResult = lucky[luckyDigits];
                for (int i = 0; i < entry.getKey().length; i++) {
                    subResult *= combinationOrderedMod(lucky[i], entry.getKey()[i], modulo) % modulo;
                    subResult %= modulo;
                }
                result += subResult * entry.getValue();
                result %= modulo;
            }
        }
        return result;
    }

    private static int[][] sumCombinations(int resultSum, int members) {
        List<int[]> combinations = new ArrayList<>();
        if (members == 1) {
            combinations.add(new int[]{resultSum});
        } else {
            for (int i = 0; i <= resultSum; i++) {
                for (int subSum = 0; subSum <= resultSum - i; subSum++) {
                    for (int[] combination : sumCombinations(subSum, members - 1)) {
                        int[] newCombination = new int[combination.length + 1];
                        System.arraycopy(combination, 0, newCombination, 0, combination.length);
                        newCombination[combination.length] = i;
                        combinations.add(newCombination);
                    }
                }
            }
        }
        return combinations.toArray(new int[0][]);
    }

    private static int combinationOrderedMod(int fullSet, int subset, int modulo) {
        int result = 1;
        for (int i = 0; i < subset; i++) {
            result *= (fullSet - i) % modulo;
            result %= modulo;
        }
        return result;
    }
}

