public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (isPrime(n)) {
            System.out.println(1);
            return;
        }
        if (!(n & 1)) {
            System.out.println(2);
            return;
        }
        if (isPrime(n - 2)) {
            System.out.println(2);
            return;
        }
        System.out.println(3);
    }

    static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        if (number == 2) {
            return true;
        }
        if (!(number & 1)) {
            return false;
        }
        int temp = 2;
        while (temp * temp <= number) {
            if (number % temp == 0) {
                return false;
            }
            temp += 1;
        }
        return true;
    }
}

