    static final int MOD = 1000000007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.close();

        System.out.println(calc(n, m, k));
    }

    public static long calc(int n, int m, int k) {
        if (k == -1 && n % 2!= m % 2) {
            return 0;
        }
        n = (n - 1);
        m = (m - 1);
        n = (n * m);
        long r = 1;
        long s = 2;
        while (n > 0) {
            if (n % 2 == 1) {
                r = (r * s) % MOD;
            }
            n /= 2;
            s = (s * s) % MOD;
        }
        return r;
    }
}

