import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = getIntList(scanner);
        int n = input[0];
        int m = input[1];
        int x = input[2];
        int y = input[3];
        int vx = input[4];
        int vy = input[5];

        if (vx == 0) {
            if (x!= 0 && x!= n) {
                System.out.println(-1);
            } else if (vy == 1) {
                System.out.println(x + " " + m);
            } else {
                System.out.println(x + " " + 0);
            }
        } else if (vy == 0) {
            if (y!= 0 && y!= m) {
                System.out.println(-1);
            } else if (vx == 1) {
                System.out.println(n + " " + y);
            } else {
                System.out.println(0 + " " + y);
            }
        } else {
            int[] result = solveSystemCongruence(-x * vx, n, -y * vy, m);
            if (result == null) {
                System.out.println(-1);
            } else {
                int t = result[0];
                x = x + t * vx;
                y = y + t * vy;
                x /= n;
                y /= m;
                x %= 2;
                y %= 2;
                x = Math.abs(x);
                y = Math.abs(y);
                System.out.println(x * n + " " + y * m);
            }
        }
    }

    public static int[] getIntList(Scanner scanner) {
        String[] input = scanner.nextLine().split(" ");
        int[] result = new int[input.length];
        for (int i = 0; i < input.length; i++) {
            result[i] = Integer.parseInt(input[i]);
        }
        return result;
    }

    public static int[] GCDKoef(int n1, int n2) {
        int k11 = 1;
        int k12 = 0;
        int k21 = 0;
        int k22 = 1;
        while (n2 > 0) {
            int k = n1 / n2;
            int r = n1 - k * n2;
            n1 = n2;
            n2 = r;
            int temp = k11;
            k11 = k21;
            k12 = k22;
            k21 = temp - k21 * k;
            k22 = k12 - k22 * k;
        }
        return new int[]{n1, k11, k12};
    }

    public static int[] solveSystemCongruence(int a1, int n1, int a2, int n2) {
        int[] result = GCDKoef(n1, n2);
        int d = result[0];
        int k1 = result[1];
        int k2 = result[2];
        if ((a1 - a2) % d!= 0) {
            return null;
        }
        int r = a1 % d;
        int x1 = (a1 - r) / d;
        int x2 = (a2 - r) / d;
        int t = r + x1 * n2 * k2 + x2 * n1 * k1;
        int mod = n1 * n2 / d;
        t %= mod;
        if (t < 0) {
            t += mod;
        }
        return new int[]{t};
    }
}

