                c[mx] += Math.max(0, right / L - (left - 1) / L);
            } else {
                c[mx] -= Math.max(0, right / L - (left - 1) / L);
            }
        }

        for (int i = 1; i < 20; i++) {
            c[i] += c[i - 1];
        }

        boolean[] seen = new boolean[n + 1];
        seen[1] = true;
        int ans = 1;

        for (int i = 2; i <= n; i++) {
            if (seen[i]) {
                continue;
            }
            int tmp = 1;
            int now = i;
            seen[now] = true;
            while (now * i <= n) {
                tmp++;
                now *= i;
                seen[now] = true;
            }
            ans += c[tmp - 1];
        }
        System.out.println(ans);
    }
}

