        for (int i = 0; i < 55; i++) {
            for (int j = 0; j <= i; j++) {
                if (i == 0 || j == 0) {
                    comb[i][j] = 1;
                } else {
                    comb[i][j] = comb[i - 1][j] + comb[i - 1][j - 1];
                }
            }
        }

