            System.out.println(0);
        } else {
            int k = (int) Math.log(t) / Math.log(2);
            int ans = gao(n + 1, k + 1);
            if (t == 1) {
                ans -= 1;
            }
            System.out.println(ans);
        }
    }

    static int gao(int m, int k) {
        int ret = 0;
        while (m > 0) {
            int p = (int) Math.log(m) / Math.log(2);
            ret += comb[p][k];
            k -= 1;
            m -= Math.pow(2, p);
            if (m == 0) {
