import java.util.*;

class Planet {
    List<Integer> a = new ArrayList<>();
    List<Integer> b = new ArrayList<>();
    List<Integer> c = new ArrayList<>();
    String n;

    @Override
    public String toString() {
        return n + ": a:" + a + ", b:" + b + ", c:" + c;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int capacity = scanner.nextInt();

        List<Planet> planets = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            Planet p = new Planet();
            p.n = scanner.next();
            for (int j = 0; j < m; j++) {
                int a = scanner.nextInt();
                int b = scanner.nextInt();
                int c = scanner.nextInt();
                p.a.add(a);
                p.b.add(b);
                p.c.add(c);
            }
            planets.add(p);
        }

        int maxProfit = -1;

        for (int n1 = 0; n1 < n; n1++) {
            for (int n2 = 0; n2 < n; n2++) {
                if (n1!= n2) {
                    int profit = calcProfit(planets.get(n1), planets.get(n2), m, capacity);
                    maxProfit = Math.max(maxProfit, profit);
                }
            }
        }

        System.out.println(maxProfit);
    }

    private static int calcProfit(Planet p1, Planet p2, int m, int capacity) {
        List<int[]> profits = new ArrayList<>();
        for (int j = 0; j < m; j++) {
            if (p1.c.get(j) == 0) {
                continue;
            }
            int profit = p2.b.get(j) - p1.a.get(j);
            if (profit > 0) {
                profits.add(new int[]{profit, p1.c.get(j)});
            }
        }
        profits.sort(Comparator.comparingInt(o -> o[0]).reversed());
        int load = 0;
        int totalProfit = 0;
        for (int[] p : profits) {
            int c = Math.min(capacity - load, p[1]);
            totalProfit += p[0] * c;
            load += c;
            if (c!= p[1]) {
                break;
            }
        }
        return totalProfit;
    }
}

