import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int T = scanner.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = scanner.nextInt();
        }
        if (Arrays.stream(A).sum() > N / 2) {
            for (int i = 0; i < N; i++) {
                A[i] = 1 - A[i];
            }
            A = reverse(A);
        }
        int K = Arrays.stream(A).sum();
        int S = Arrays.stream(Arrays.copyOfRange(A, A.length - K, A.length)).sum();
        int M = K + 1;
        int P = 1000000007;
        int inv = (int) Math.pow(N * (N - 1) / 2, P - 2) % P;
        int[][] X = new int[M][M];
        for (int i = 0; i < M; i++) {
            if (i > 0) {
                X[i - 1][i] = ((K - i + 1) * (K - i + 1) * inv) % P;
            }
            if (i < M - 1) {
                X[i + 1][i] = (N - 2 * K + i + 1) * (i + 1) * inv % P;
            }
            X[i][i] = (1 - ((K - i) * (K - i) * inv) - (N - 2 * K + i) * (i) * inv) % P;
        }
        X = poww(X, T);
        System.out.println(X[S][K]);
    }

    public static int[][] poww(int[][] MM, int n) {
        if (n == 1) {
            return MM;
        }
        if (n % 2!= 0) {
            return mult(poww(MM, n - 1), MM);
        }
        return poww(mult(MM, MM), n / 2);
    }

    public static int[][] mult(int[][] M1, int[][] M2) {
        int M = M1.length;
        int[][] Y = new int[M][M];
        for (int i = 0; i < M; i++) {
            for (int j = 0; j < M; j++) {
                for (int k = 0; k < M; k++) {
                    Y[i][j] += M1[i][k] * M2[k][j];
                    Y[i][j] %= 1000000007;
                }
            }
        }
        return Y;
    }

    public static int[] reverse(int[] array) {
        int[] reversed = new int[array.length];
        for (int i = 0; i < array.length; i++) {
            reversed[i] = array[array.length - 1 - i];
        }
        return reversed;
    }
}

