import java.util.*;

public class Main {
    static long mod = (long) Math.pow(10, 9) + 7;
    static int n, k;
    static int[] a;
    static long[][] dp;

    static long binom(int n, int k) {
        if (n < k) return 0;
        if (n == k || k == 0) return 1;
        if (dp[n][k] > 0) return dp[n][k];
        else dp[n][k] = (binom(n - 1, k - 1) + binom(n - 1, k)) % mod;
        return dp[n][k];
    }

    static long[] egcd(long a, long b) {
        if (a == 0) return new long[]{b, 0, 1};
        else {
            long[] g = egcd(b % a, a);
            return new long[]{g[0], g[2] - (b / a) * g[1], g[1]};
        }
    }

    static long modinv(long a, long m) {
        long[] g = egcd(a, m);
        if (g[0]!= 1) throw new RuntimeException("modular inverse does not exist");
        else return g[1] % m;
    }

    static long[][] multiply(long[][] A, long[][] B, long mod) {
        long[][] C = new long[A.length][B[0].length];
        for (int row = 0; row < A.length; row++) {
            for (int col = 0; col < B[0].length; col++) {
                for (int k = 0; k < B.length; k++) {
                    C[row][col] += A[row][k] * B[k][col] % mod;
                }
                C[row][col] %= mod;
            }
        }
        return C;
    }

    static long[][] matrix_pow(long[][] M, int n, long mod) {
        if (n == 1) return M;
        long[][] sub_M = matrix_pow(M, n / 2, mod);
        if (n % 2 == 0) return multiply(sub_M, sub_M, mod);
        return multiply(sub_M, matrix_pow(M, n - n / 2, mod), mod);
    }

    static long solve(int n, int k, int[] a, long mod) {
        int ones = Arrays.stream(a).sum();
        int zeros = n - ones;
        long[][] M = new long[zeros + 1][zeros + 1];
        for (int row = 0; row <= zeros; row++) {
            int pre_zeros = row;
            int pre_ones = zeros - pre_zeros;
            int post_zeros = pre_ones;
            int post_ones = ones - pre_ones;
            M[row][row] = (pre_ones * post_ones + pre_zeros * post_zeros
                    + binom(zeros, 2) + binom(ones, 2)) % mod;
            if (row > 0) M[row - 1][row] = pre_zeros * post_ones;
            if (row < zeros) M[row + 1][row] = post_zeros * pre_ones;
        }
        long[] b = new long[zeros + 1];
        b[zeros - Arrays.stream(a, 0, zeros).sum()] = 1;
        long[] C = multiply(matrix_pow(M, k, mod), b, mod)[0];
        return C[zeros];
    }

