import java.util.*;

public class Main {
    static int[] l1 = {1, 2, 3, 0, 4, 5};
    static int[] l2 = {4, 1, 5, 3, 2, 0};
    static int[] l3 = {0, 4, 2, 5, 3, 1};

    static String perm(int[] l, int[] p) {
        StringBuilder sb = new StringBuilder();
        for (int c : p) {
            sb.append(l[c]);
        }
        return sb.toString();
    }

    static String incr_inst(String orig) {
        char[] curr = orig.toCharArray();
        Set<String> s = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    s.add(new String(curr));
                    curr = perm(curr, l1).toCharArray();
                }
                curr = perm(curr, l3).toCharArray();
            }
            curr = perm(curr, l2).toCharArray();
        }
        return Collections.min(s);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String orig = scanner.next();

        Set<String> s = new HashSet<>();
        for (char[] c : permutations(orig.toCharArray())) {
            s.add(incr_inst(new String(c)));
        }
        System.out.println(s.size());
    }

    static char[][] permutations(char[] orig) {
        List<char[]> list = new ArrayList<>();
        permute(orig, 0, orig.length - 1, list);
        return list.toArray(new char[0][]);
    }

    static void permute(char[] arr, int l, int r, List<char[]> list) {
        if (l == r) {
            list.add(arr.clone());
        } else {
            for (int i = l; i <= r; i++) {
                swap(arr, l, i);
                permute(arr, l + 1, r, list);
                swap(arr, l, i);
            }
        }
    }

    static void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

