import java.util.*;

public class Main {
    static int n;
    static long mod = (long) Math.pow(10, 9) + 7;
    static long[][] ANS;

    static long bra(int x, int y) {
        if (ANS[x][y]!= 0) {
            return ANS[x][y];
        }

        if (x == y && x == 0) {
            ANS[x][y] = 0;
            return 0;
        }

        long A;
        if ((x + y) % 2 == 1) {
            A = 1;
        } else {
            A = 0;
        }

        if (x == y) {
            ANS[x][y] = A + bra(x - 1, y);
            return ANS[x][y];
        } else if (x == 0) {
            ANS[x][y] = A + bra(x, y - 1);
            return ANS[x][y];
        } else if (y == 0) {
            ANS[x][y] = A + bra(x - 1, y);
            return ANS[x][y];
        } else if (x < y && x!= 0 && y!= 0) {
            ANS[x][y] = A + bra(x - 1, y) + bra(x, y - 1);
            return ANS[x][y];
        }

        return 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        ANS = new long[n + 1][n + 1];
        System.out.println(bra(n, n) % mod);
    }
