import java.util.Scanner;
import java.util.HashMap;

public class Main {
    static long m = 998244353;
    static HashMap<Integer, Long> fm_cache = new HashMap<>();

    static long fmod(int x) {
        if (!fm_cache.containsKey(x)) {
            long val = (x > 0)? x * fmod(x - 1) % m : 1;
            fm_cache.put(x, val);
        }
        return fm_cache.get(x);
    }

    static long imod(int x) {
        return pow(x, (int)(m - 2), m);
    }

    static long C(int n, int k) {
        return (fmod(n) * imod(fmod(k)) * imod(fmod(n - k))) % m;
    }

    static long pow(int x, int n, int m) {
        if (n == 0) return 1;
        long half = pow(x, n / 2, m);
        return (n % 2 == 0)? (half * half) % m : (((half * half) % m) * x) % m;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        long tot = 0;
        for (int b = 1; b <= n; b++) {
            int dv = n / b - 1;
            if (dv >= k - 1) {
                tot = (tot + C(dv, k - 1)) % m;
            }
        }
        System.out.println(tot);
    }
}

