import java.util.*;

public class Main {
    static long[] K = new long[1000];
    static Map<Pair, Long> M = new HashMap<>();

    static class Pair {
        int a, b;
        Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass()!= o.getClass()) return false;
            Pair pair = (Pair) o;
            return a == pair.a && b == pair.b;
        }

        @Override
        public int hashCode() {
            return Objects.hash(a, b);
        }
    }

    static long F(int a, int b) {
        if (a == 0 && b == 0) return 1;
        if (b == 0) return K[a];
        Pair p = new Pair(a, b);
        if (M.containsKey(p)) return M.get(p);
        long t = 0;
        if (a > 0) t += a * F(a - 1, b);
        t += F(a, b - 1);
        if (b > 1) {
            long k = b - 1;
            for (int i = 0; i <= a; i++) {
                t += k * F(a - i, b - 2);
                k *= (a - i);
            }
        }
        M.put(p, t);
        return t;
    }

    public static void main(String[] args) {
        K[0] = 1;
        for (int i = 1; i < 1000; i++) K[i] = i * K[i - 1];

        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] d = new int[n];
