import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        System.out.println(sumC(n, k));
    }

    private static int fall_fac(int n, int k) {
        int ans = 1;
        for (int i = 0; i < k; i++) {
            ans *= n - i;
        }
        return ans;
    }

    private static int C(int n, int k) {
        if (!(0 <= k && k <= n)) {
            return 0;
        } else {
            return fall_fac(n, k) / fall_fac(k, k);
        }
    }

    private static int derangement(int n) {
        if (n == 0) {
            return 1;
        } else if (n == 1) {
            return 0;
        } else {
            return (n - 1) * (derangement(n - 1) + derangement(n - 2));
        }
    }

    private static int sumC(int n, int k) {
        int sum = 0;
        for (int i = 0; i <= k; i++) {
            sum += C(n, i) * derangement(i);
        }
        return sum;
    }
}

