public class Main {
    static int[][][] q;
    static String s, t;
    static int n, k;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        k = in.nextInt();
        s = in.next();
        t = in.next();
        q = new int[n][n][k + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int l = 0; l <= k; l++) {
                    q[i][j][l] = -1;
                }
            }
        }
        System.out.println(g(0, 0, k));
    }

    static int g(int i, int z, int k) {
        if (i >= n) return 0;
        if (q[i][z][k] > -1) return q[i][z][k];
        int o = g(i + 1, z, k);
        int c = s.charAt(i)!= t.charAt(0);
        if (k >= c) o = Math.max(o, g(i + 1, z + 1, k - c));
        c = s.charAt(i)!= t.charAt(1);
        if (k >= c) o = Math.max(o, g(i + 1, z + (t.charAt(0) == t.charAt(1)? 1 : 0), k - c) + z);
        q[i][z][k] = o;
        return o;
    }
}

