import java.util.*;

public class Main {
    static Set<Integer> st = new HashSet<>();

    static int debin(String s) {
        int ret = 0;
        int mn = 1;
        for (int i = s.length() - 1; i >= 0; i--) {
            ret += Integer.parseInt(String.valueOf(s.charAt(i))) * mn;
            mn *= 2;
        }
        return ret;
    }

    static boolean ch(int x, int y, int deep) {
        if (st.contains(x)) {
            return false;
        }
        st.add(x);
        if (x == y) {
            return true;
        }
        if (deep == 150) {
            return false;
        }
        String s = Integer.toBinaryString(x);
        if (ch(debin(new StringBuilder(s).reverse().toString()), y, deep + 1) || ch(debin("1" + new StringBuilder(s).reverse().toString()), y, deep + 1)) {
            return true;
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        if (ch(x, y, 0)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

