import java.io.*;

class Main {
    static Set<Integer> ng = new HashSet<>();
    static String solve(int X, int Y) {
        if (X == Y) {
            return "YES";
        }

        String SX = Integer.toBinaryString(X);
        String SY = Integer.toBinaryString(Y);

        if (dfs(SX, SY)) {
            return "YES";
        }

        return "NO";
    }

    static boolean dfs(String s, String SY) {
        if (s.equals(SY)) {
            return true;
        }
        int n = Integer.parseInt(s, 2);
        if (ng.contains(n)) {
            return false;
        }
        if (s.length() > 100) {
            return false;
        }
        ng.add(n);
        String s1 = new StringBuilder(s).reverse().toString();
        if (!ng.contains(Integer.parseInt(s1, 2))) {
            if (dfs(s1, SY)) {
                return true;
            }
        }
        s1 = s + "1";
        if (!ng.contains(Integer.parseInt(s1, 2))) {
            if (dfs(s1, SY)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int X = scanner.nextInt();
        int Y = scanner.nextInt();
        System.out.println(solve(X, Y));
    }
}

