import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int r = 0;
        while (n!= 0) {
            int d = prime(n);
            if (d == n) {
                r++;
                break;
            } else {
                if (n % 2 == 0) {
                    r += n / 2;
                    break;
                } else {
                    n -= d;
                    r++;
                }
            }
        }
        System.out.println(r);
    }

    static int prime(int n) {
        int i = 2;
        while (i <= Math.sqrt(n)) {
            if (n % i == 0) {
                return i;
            } else {
                if (i == 2) {
                    i++;
                } else {
                    i += 2;
                }
            }
        }
        return n;
    }
}

