import java.util.*;

public class Main {
    static List<Integer> primes = new ArrayList<>();

    public static void main(String[] args) {
        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) {
                    break;
                }
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(p);
            }
        }

        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        System.out.println(process(n, m));
    }

    static Map<Integer, Integer> factor(int n) {
        Map<Integer, Integer> d = new HashMap<>();
        for (int p : primes) {
            if (p * p > n) {
                break;
            }
            if (n % p == 0) {
                int c = 0;
                while (n % p == 0) {
                    n = n / p;
                    c++;
                }
                d.put(p, c);
            }
        }
        if (n > 1) {
            d.put(n, 1);
        }
        return d;
    }

    static List<Integer> factors(int n) {
        Map<Integer, Integer> d = factor(n);
        List<Integer> answer = new ArrayList<>();
        answer.add(1);
        for (int p : d.keySet()) {
            List<Integer> a2 = new ArrayList<>();
            for (int x : answer) {
                for (int i = 0; i <= d.get(p); i++) {
                    a2.add(x * (int) Math.pow(p, i));
                }
            }
            answer = a2;
        }
        return answer;
    }

    static int process(int n, int m) {
        int[] fDict = new int[n + 1];
        fDict[0] = 0;
        fDict[1] = 1;
        fDict[2] = 2;
        for (int i = 3; i <= n; i++) {
            fDict[i] = 2 * fDict[i - 1];
            for (int x : factors(i)) {
                if (2 <= x && x <= i) {
                    fDict[i] += fDict[(i / x)] - fDict[(i - 1) / x];
                    fDict[i] = fDict[i] % m;
                }
            }
            fDict[i] = fDict[i] % m;
        }
        return fDict[n];
    }
}

