import java.util.*;

public class Main {
    static int n, s, k;
    static int[] amounts;
    static char[] colors;
    static int[][] dp;

    static int getAns(int nth, int left) {
        if (left <= 0) {
            return 0;
        }
        if (dp[nth][left]!= -1) {
            return dp[nth][left];
        }

        int ret = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (amounts[i] <= amounts[nth] || colors[i] == colors[nth]) {
                continue;
            }
            ret = Math.min(ret, Math.abs(nth - i) + getAns(i, left - amounts[i]));
        }

        dp[nth][left] = ret;
        return ret;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        s = scanner.nextInt();
        k = scanner.nextInt();
        amounts = new int[n];
        colors = new char[n];
        dp = new int[n][k + 1];
        for (int i = 0; i < n; i++) {
