        int N = scanner.nextInt();
        int T = scanner.nextInt();
        int[][] A = new int[N][2];
        for (int i = 0; i < N; i++) {
            A[i][0] = scanner.nextInt();
            A[i][1] = scanner.nextInt();
        }
        int s = 0;
        for (int i = 1; i <= N; i++) {
            List<int[]> comb = combinations(A, i);
            for (int[] x : comb) {
                int a = 0, b = 0, c = 0;
                for (int j = 0; j < x.length; j++) {
                    if (x[j][0] == 1) a++;
                    if (x[j][1] == 1) b++;
                    if (x[j][1] == 2) c++;
                }
                if (a == T) {
                    s += (out1(a, b, c) + out2(a, b, c) + out3(a, b, c));
                }
            }
        }
        System.out.println(s % 1000000007);
    }

    private static int out1(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0) return 0;
        if (a == 1 && b == 0 && c == 0) return 1;
        return a * (out2(a - 1, b, c) + out3(a - 1, b, c));
    }

    private static int out2(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0) return 0;
        if (a == 0 && b == 1 && c == 0) return 1;
        return b * (out1(a, b - 1, c) + out3(a, b - 1, c));
    }

    private static int out3(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0) return 0;
        if (a == 0 && b == 0 && c == 1) return 1;
        return c * (out2(a, b, c - 1) + out1(a, b, c - 1));
    }

    private static List<int[]> combinations(int[][] arr, int r) {
        List<int[]> list = new ArrayList<>();
        combination(arr, r, 0, new int[r], 0, list);
        return list;
    }

    private static void combination(int[][] arr, int r, int index, int[] data, int start, List<int[]> list) {
        if (index == r) {
            list.add(Arrays.copyOf(data, r));
            return;
        }
        for (int i = start; i < arr.length; i++) {
            data[index] = arr[i][0];
            combination(arr, r, index + 1, data, i + 1, list);
        }
    }
}

