            System.out.println("NO");
            return;
        }

        if (vert.get(1).get(0)!= Collections.min(hor).get(1)) {
            System.out.println("NO");
            return;
        }

        if (vert.get(1).get(1)!= Collections.max(hor).get(1)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
    }

    private static List<Integer> readLine() {
        Scanner scanner = new Scanner(System.in);
        String[] line = scanner.nextLine().split(" ");
        List<Integer> result = new ArrayList<>();
        for (String item : line) {
            result.add(Integer.parseInt(item));
        }
        return result;
    }

    private static boolean isVertical(List<Integer> line) {
        return line.get(0).equals(line.get(2));
