import java.util.*;

public class Main {
    static int[] tree;
    static int mod;
    static int[] fact;
    static int[] dp;

    static int makeTree(int n) {
        int i = 2;
        while (true) {
            if (i >= n * 2) {
                tree = new int[i];
                break;
            } else {
                i *= 2;
            }
        }
        return tree.length;
    }

    static void update(int i, int x) {
        i += tree.length / 2;
        tree[i] = x;
        i /= 2;
        while (i > 0) {
            tree[i] = tree[2 * i] + tree[2 * i + 1];
            i /= 2;
        }
    }

    static int getSum(int s, int t) {
        s += tree.length / 2;
        t += tree.length / 2;
        int ans = 0;
        while (s <= t) {
            if (s % 2 == 0) {
                s /= 2;
            } else {
                ans += tree[s];
                s = (s + 1) / 2;
            }
            if (t % 2 == 1) {
                t /= 2;
            } else {
                ans += tree[t];
                t = (t - 1) / 2;
            }
        }
        return ans;
    }

    static ArrayList<Integer> primeFactorize(int n) {
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = 2; i <= Math.sqrt(n); i++) {
            while (n % i == 0) {
                ans.add(i);
                n /= i;
            }
        }
        if (n!= 1) {
            ans.add(n);
        }
        return ans;
    }

    static int eulerFunc(int n) {
        Set<Integer> p = new HashSet<>(primeFactorize(n));
        int x = n;
        for (int i : p) {
            x *= (i - 1);
            x /= i;
        }
        return x;
    }

    static int f(int a, int b) {
        int ans = 1;
        for (int i = a + 1; i <= b; i++) {
            ans *= i;
            ans %= mod;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        mod = sc.nextInt();
        int x = eulerFunc(mod);
        int l = n + 5;
        fact = new int[l + 1];
        fact[0] = 1;
        for (int i = 1; i <= l; i++) {
            fact[i] = i * fact[i - 1] % mod;
        }
        if (n <= 3) {
            System.out.println(0);
        } else {
            dp = new int[2000];
            dp[0] = 1;
            dp[1] = 2;
            dp[2] = 2;
            dp[3] = 1;
            makeTree(2005);
            for (int i = 0; i < 4; i++) {
                update(i, dp[i]);
            }
            int m = 3;
            int ans = 0;
            for (int i = 0; i < n - 3; i++) {
                int[] dp0 = Arrays.copyOf(dp, dp.length);
                int ans0 = 0;
                for (int j = 0; j < i + 3; j++) {
                    for (int k = 1; k < m + 2; k++) {
                        ans0 += getSum(j + k + 1, 2004) * dp0[k - 1] % mod;
                        ans0 %= mod;
                        dp[j + k] += dp0[k - 1];
                        dp[j + k] %= mod;
                        update(j + k, dp[j + k]);
                    }
                }
                m += i + 3;
                ans += f(i + 4, n) * ans0 % mod;
                ans %= mod;
            }
            System.out.println(ans);
        }
    }
}

