public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        System.out.println(solve(n, mod));
    }

    public static int solve(int n, int mod) {
        if (n <= 3) {
            return 0;
        } else {
            int last_ans = 17;
            int ans = 17;
            int size = (n - 1) * (n - 2) / 2 + 1;
            int inv = 1;
            int[][] record = new int[2][size + 1];
            record[0][0] = 1;
            record[0][1] = 2;
            record[0][2] = 2;
            record[0][3] = 1;
            for (int m = 4; m < n; m++) {
                int tp_size = m * (m - 1) / 2;
                ans = (m + 1) * last_ans;
                int tp = 0;
                for (int i = 0; i < m; i++) {
                    tp += record[inv ^ 1][i];
                    record[inv][i] = tp % mod;
                }
                for (int i = m; i <= tp_size / 2; i++) {
                    tp += record[inv ^ 1][i];
                    tp -= record[inv ^ 1][i - m];
                    record[inv][i] = tp % mod;
                }
                for (int i = 0; i <= tp_size / 2; i++) {
                    record[inv][tp_size - i] = record[inv][i];
                }
                int total = 0;
                for (int i = 0; i < tp_size - 1; i++) {
                    tp = 0;
                    for (int j = Math.max(1, -tp_size + i + m + 2); j <= m; j++) {
                        tp += j * record[inv][m + 2 - j + i];
                    }
                    total += record[inv][i];
                    total %= mod;
                    tp *= total;
                    tp %= mod;
                    ans += tp;
                    ans %= mod;
                }
                last_ans = ans;
                inv ^= 1;
            }
            return ans % mod;
        }
    }
}

