import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long a1 = scanner.nextLong();
        long b1 = scanner.nextLong();
        long a2 = scanner.nextLong();
        long b2 = scanner.nextLong();
        long l = scanner.nextLong();
        long r = scanner.nextLong();

        if (b2 < b1) {
            long temp = a1;
            a1 = a2;
            a2 = temp;

            temp = b1;
            b1 = b2;
            b2 = temp;
        }

        long[] result = xgcd(a1, a2);
        long g = result[0];
        long x = result[1];
        long y = result[2];

        if ((b2 - b1) % g!= 0) {
            System.out.println(0);
        } else {
            x = x * ((b2 - b1) / g);
            y = y * ((b2 - b1) / g);
            double li1 = Math.max(upw(-x * g, a2), upw(y * g, a1));
            double li2 = upw((l - a1 * x - b1) * g, a1 * a2);
            double ls = dwn((r - a1 * x - b1) * g, a1 * a2);
            double li = Math.max(li1, li2);

            if (li > ls) {
                System.out.println(0);
            } else {
                System.out.println((int) (ls - li + 1));
            }
        }
    }

    public static double upw(double a, double b) {
        if (a > 0) {
            return (a + b - 1) / b;
        }
        a = -a;
        return -(a / b);
    }

    public static double dwn(double a, double b) {
        if (a > 0) {
            return a / b;
        }
        a = -a;
        return -((a + b - 1) / b);
    }

    public static long[] xgcd(long a, long b) {
        if (b == 0) {
            return new long[]{a, 1, 0};
        }
        long[] result = xgcd(b, a % b);
        return new long[]{result[0], result[2], result[1] - (a / b) * result[2]};
    }
}

