public class Main {
    static final long M = 998244353;
    static final int MAXNUM = 260;
    static long[] factor = new long[MAXNUM+2];
    static Map<Pair<Integer, Integer>, Long> storecomb = new HashMap<>();

    static {
        factor[0] = 1;
        for (int i = 1; i <= MAXNUM; i++) {
            factor[i] = (factor[i-1]*i)%M;
        }
    }

    static long fastfrac(long a, long b) {
        long numb = pow(b, M-2, M);
        return ((a%M)*(numb%M))%M;
    }

    static long comb(int n, int k) {
        if (n<k) return 0;
        if (n==k) return 1;
        Pair<Integer, Integer> key = new Pair<>(n, k);
        if (storecomb.containsKey(key))  return storecomb.get(key);

        long num1 = factor[n];
        long num2 = factor[k];
        long num3 = factor[n-k];
        long num = (num2*num3)%M;
        long output = fastfrac(num1,num);
        storecomb.put(key, output);
        return output;
    }

    static long pow(long a, long b, long m) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res * a) % m;
            }
            a = (a * a) % m;
            b >>= 1;
        }
        return res;
    }

    static void main(int t) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        long[][] dp = new long[n+1][k+1];

        for (int j = 1; j <= k; j++) {
            dp[2][j] = 1;
            dp[1][j] = 1;
        }
        for (int i = 3; i <= n; i++) {
            dp[i][1] = pow(k, (i-1)*(i-2)/2, M);
        }

        for (int i = 3; i <= n; i++) {
            for (int j = 2; j <= k; j++) {
                dp[i][j] = pow(k-j+1, (i-1)*(i-2)/2, M);
            }
        }

        for (int i = 3; i <= n; i++) {
            for (int same = 1; same < i-1; same++) {
                long part1 = 0;
                for (int j = 2; j <= k; j++) {
                    part1 += dp[i-same][j-1];
                    long part2 = (pow(k-j+1, same*(i-1-same)+same*(same-1)/2, M) * comb(i-1, same)) % M;
                    dp[i][j] += (part1*part2)%M;
                    dp[i][j] %= M;
                }
            }
        }

        long sum = 0;
        for (int j = 1; j <= k; j++) {
            sum += dp[n][j];
            sum %= M;
        }
        System.out.println(sum);
    }

    public static void main(String[] args) throws IOException {
        int T = 1;
        for (int t = 1; t <= T; t++) {
            main(t);
        }
    }
}

class Pair<T, U> {
    T first;
    U second;

    public Pair(T first, U second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        Pair<?,?> pair = (Pair<?,?>) o;
        return Objects.equals(first, pair.first) && Objects.equals(second, pair.second);
    }

    @Override
    public int hashCode() {
        return Objects.hash(first, second);
    }
}

