        System.out.println(maxNum(a, b));
    }

    public static String maxNum(String a, String b) {
        if (b.length() > a.length()) {
            char[] arr = a.toCharArray();
            Arrays.sort(arr);
            return new StringBuilder(new String(arr)).reverse().toString();
        } else {
            List<Character> listA = new ArrayList<>();
            for (char c : a.toCharArray()) {
                listA.add(c);
            }
            Collections.sort(listA, Collections.reverseOrder());

            StringBuilder res = new StringBuilder();
            for (char c : b.toCharArray()) {
                if (listA.contains(c)) {
                    listA.remove(Character.valueOf(c));
                    if (b.substring(res.length() + 1).compareTo(new StringBuilder(listA).reverse().toString()) >= 0) {
                        res.append(c);
                    } else {
                        listA.add(c);
                        break;
                    }
                } else {
                    break;
                }
            }

            if (res.length() == 0) {
                return res.toString();
            }

            for (int i = Character.getNumericValue(b.charAt(res.length())) - 1; i >= 0; i--) {
                if (a.contains(String.valueOf(i))) {
                    a = a.replaceFirst(String.valueOf(i), "");
                    return res.append(i).append(new StringBuilder(a).reverse().toString()).toString();
                }
            }
        }
        return "";
    }
}

