import java.util.*;

public class Main {
    static class Primes {
        int prime_num;
        int[] min_prime;
        List<Integer> prime = new ArrayList<>();
        Map<Integer, Map<Integer, Integer>> memo_prifac = new HashMap<>();

        Primes(int n) {
            this.prime_num = n;
            this.min_prime = new int[this.prime_num + 1];
            Arrays.fill(this.min_prime, -1);
            this.min_prime[0] = 0;
            this.min_prime[1] = 1;
            int i = 2;
            while (i <= this.prime_num) {
                if (this.min_prime[i] == -1) {
                    this.min_prime[i] = i;
                    this.prime.add(i);
                }
                for (int j : this.prime) {
                    if (i * j > this.prime_num || j > this.min_prime[i]) break;
                    this.min_prime[j * i] = j;
                }
                i += 1;
            }
        }

        Map<Integer, Integer> prifac(int n) {
            if (this.memo_prifac.containsKey(n)) {
                return this.memo_prifac.get(n);
            }
            Map<Integer, Integer> res = new HashMap<>();
            int x = n;
            while (x > 1) {
                int p = this.min_prime[x];
                if (res.containsKey(p)) {
                    res.put(p, res.get(p) + 1);
                } else {
                    res.put(p, 1);
                }
                x /= p;
            }
            this.memo_prifac.put(n, res);
            return res;
        }

        List<Integer> divisors(int n) {
            if (n == 1) return Arrays.asList(1);
            Map<Integer, Integer> prf = this.prifac(n);
            List<Integer> keys = new ArrayList<>(prf.keySet());
            List<Integer> res = new ArrayList<>();
            divsearch(keys, 0, prf, 1, res);
            return res;
        }

        void divsearch(List<Integer> keys, int i, Map<Integer, Integer> prf, int mul, List<Integer> res) {
            if (i == keys.size() - 1) {
                for (int j = 0; j <= prf.get(keys.get(i)); j++) {
                    res.add(mul * (int) Math.pow(keys.get(i), j));
                }
            } else {
                for (int j = 0; j <= prf.get(keys.get(i)); j++) {
                    divsearch(keys, i + 1, prf, mul * (int) Math.pow(keys.get(i), j), res);
                }
            }
        }
    }

    static int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    static int lcm(int a, int b) {
        return a * b / gcd(a, b);
    }

    static final int mod = (int) 1e9 + 7;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long ans = 0;
        Primes pri = new Primes(n + 3);
        int[] dp = new int[n + 3];
        for (int c = 1; c < n - 1; c++) {
            int k = n - c;
            List<Integer> yaku = pri.divisors(k);
            Collections.sort(yaku, Collections.reverseOrder());
            for (int g : yaku) {
                int m = k / g;
                dp[g] = m - 1;
                for (int j : yaku) {
                    if (j > g && j % g == 0) dp[g] -= dp[j];
                }
                ans += (c * g / gcd(g, c)) * dp[g];
                ans %= mod;
            }
            for (int g : yaku) dp[g] = 0;
        }
        System.out.println(ans);
    }
}

