import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int[] a;
    static int[][] c;
    static int[] degIn;
    static List<Integer>[] graph;
    static boolean[] visited;
    static List<Integer> s;
    static List<Integer> t;

    static boolean isSubset(int a, int b) {
        return (a & b) == a;
    }

    static boolean isIntersect(int a, int b) {
        return (a & b)!= 0;
    }

    static int cntOrder(List<Integer> s, List<Integer> t) {
        int p = s.size();
        int m = t.size();
        int[] inMask = new int[m];
        for (int x = 0; x < p; x++) {
            for (int i = 0; i < m; i++) {
                if (t.get(i) % s.get(x) == 0) {
                    inMask[i] |= 1 << x;
                }
            }
        }
        int[] cnt = new int[1 << p];
        for (int mask = 0; mask < (1 << p); mask++) {
            for (int i = 0; i < m; i++) {
                if (isSubset(inMask[i], mask)) {
                    cnt[mask]++;
                }
            }
        }
        int[][] dp = new int[m + 1][1 << p];
        for (int i = 0; i < m; i++) {
            dp[1][inMask[i]]++;
        }
        for (int k = 0; k < m; k++) {
            for (int mask = 0; mask < (1 << p); mask++) {
                for (int i = 0; i < m; i++) {
                    if (!isSubset(inMask[i], mask) && isIntersect(inMask[i], mask)) {
                        dp[k + 1][mask | inMask[i]] = (dp[k + 1][mask | inMask[i]] + dp[k][mask]) % MOD;
                    }
                }
                dp[k + 1][mask] = (dp[k + 1][mask] + dp[k][mask] * (cnt[mask] - k)) % MOD;
            }
        }
        return dp[m][(1 << p) - 1];
    }

    static void dfs(int u) {
        visited[u] = true;
        if (degIn[u] == 0) {
            s.add(a[u]);
        } else {
            t.add(a[u]);
        }

        for (int v : graph[u]) {
            if (!visited[v]) {
                dfs(v);
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }
        c = new int[n][n];
        for (int i = 0; i < n; i++) {
            c[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % MOD;
            }
        }
        degIn = new int[n];
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int u = 0; u < n; u++) {
            for (int v = 0; v < n; v++) {
                if (u!= v && a[v] % a[u] == 0) {
                    graph[u].add(v);
                    graph[v].add(u);
                    degIn[v]++;
                }
            }
        }
        int ans = 1;
        int curLen = 0;
        visited = new boolean[n];
        for (int u = 0; u < n; u++) {
            if (!visited[u]) {
                s = new ArrayList<>();
                t = new ArrayList<>();
                dfs(u);
                if (!t.isEmpty()) {
                    int sz = t.size() - 1;
                    int cnt = cntOrder(s, t);
                    ans = (ans * cnt) % MOD;
                    ans = (ans * c[curLen + sz][sz]) % MOD;
                    curLen += sz;
                }
            }
        }
        System.out.println(ans);
    }
}

