            t++;
            z *= t;
        }
        if (t > n) {
            System.out.println(-1);
            System.exit(0);
        }

        int res = before(n - t + 1);
        if (t > 0) {
            boolean[] used = new boolean[t];
            List<Integer> perm = new ArrayList<>();
