            while (t > 0) {
                z /= t;
                int x = 0;
                while (used[x]) {
                    x++;
                }
                while (k >= z) {
                    k -= z;
                    x++;
                    while (used[x]) {
                        x++;
                    }
                }
                t--;
                used[x] = true;
                perm.add(x);
