import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x1 = scanner.nextInt();
        int y1 = scanner.nextInt();
        int x2 = scanner.nextInt();
        int y2 = scanner.nextInt();
        int cx = scanner.nextInt();
        int cy = scanner.nextInt();
        scanner.close();

        boolean possible = canSolve(x1, y1, x2, y2, cx, cy) ||
                canSolve(-y1, x1, x2, y2, cx, cy) ||
                canSolve(-x1, -y1, x2, y2, cx, cy) ||
                canSolve(y1, -x1, x2, y2, cx, cy);

        System.out.println(possible? "YES" : "NO");
    }

    private static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }

    private static boolean isSolvable(int a, int b, int c1, int c2) {
        if (a == 0 && b == 0) {
            return c1 == 0 && c2 == 0;
        }
        if ((c1 * b + c2 * a) % (a * a + b * b)!= 0) {
            return false;
        }
        int y = (c1 * b + c2 * a) / (a * a + b * b);
        if (a!= 0) {
            return (c1 - b * y) % a == 0;
        } else {
            return (c2 - a * y) % b == 0;
        }
    }

    private static boolean canSolve(int x0, int y0, int x1, int y1, int cx, int cy) {
        int dx = x1 - x0;
        int dy = y1 - y0;
        if (cx == 0 && cy == 0) {
            return dx == 0 && dy == 0;
        }
        if (cx == 0) {
            return dx % cy == 0 && dy % cy == 0;
        }
        if (cy == 0) {
            return dx % cx == 0 && dy % cx == 0;
        }
        int d = gcd(Math.abs(cx), Math.abs(cy));
        if ((dx % d!= 0) || (dy % d!= 0)) {
            return false;
        }
        return isSolvable(cx / d, cy / d, dx / d, -dy / d);
    }
}

