public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int l = scanner.nextInt();
        int r = scanner.nextInt();
        int gcd = scanner.nextInt();
        int lcm = scanner.nextInt();
        scanner.close();

        if (lcm % gcd!= 0) {
            System.out.println(0);
            return;
        }

        Set<Integer> lcmDivisors = new HashSet<>();
        for (int num = 1; num <= Math.sqrt(lcm) + 1; num++) {
            if (lcm % num == 0) {
                lcmDivisors.add(num);
                lcmDivisors.add(lcm / num);
            }
        }

        int product = gcd * lcm;
        Set<Pair<Integer, Integer>> answers = new HashSet<>();
        for (int divisor : lcmDivisors) {
            if (divisor < l || divisor > r) {
                continue;
            }
            int dop = product / divisor;
            if (dop < l || dop > r) {
                continue;
            }
            if (gcd(divisor, dop)!= gcd) {
                continue;
            }
            answers.add(new Pair<>(divisor, dop));
            answers.add(new Pair<>(dop, divisor));
        }

        System.out.println(answers.size());
    }

    private static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

class Pair<T, U> {
    T first;
    U second;

    public Pair(T first, U second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        Pair<?,?> pair = (Pair<?,?>) o;
        return Objects.equals(first, pair.first) && Objects.equals(second, pair.second);
    }

    @Override
    public int hashCode() {
        return Objects.hash(first, second);
    }
}

