            int now = 0;
            for (int j = 0; j < first.length; j++) {
                if ((i & (1 << j))!= 0) {
                    now += first[j];
                }
            }
            s1.add(now % m);
        }
        List<Integer> s2 = new ArrayList<>();
        for (int i = 0; i < t2; i++) {
            int now = 0;
            for (int j = 0; j < sec.length; j++) {
                if ((i & (1 << j))!= 0) {
                    now += sec[j];
                }
            }
            s2.add(now % m);
        }
        Collections.sort(s1);
        Collections.sort(s2);
        int maxi = 0;
        for (int i : s1) {
            int req = m - i;
            int pair = check(s2, req);
            maxi = Math.max(maxi, (i + pair) % m);
        }
        System.out.println(maxi);
    }

    public static int check(List<Integer> l, int x) {
        int lo = 0;
        int hi = l.size() - 1;
        int ans = 0;
        while (lo <= hi) {
            int mi = (lo + hi) >> 1;
            if (l.get(mi) < x) {
                ans = l.get(mi);
                lo = mi + 1;
            } else {
                hi = mi - 1;
            }
        }
        return ans;
    }
