class AvlTree {
    TreeNode _tree;

    AvlTree() {
        this._tree = null;
    }

    void add(int k, int v) {
        if (this._tree == null) {
            this._tree = new TreeNode(k, v);
            return;
        }
        TreeNode node = this._add(k, v);
        if (node!= null) {
            this._rebalance(node);
        }
    }

    TreeNode _add(int k, int v) {
        TreeNode node = this._tree;
        while (node!= null) {
            if (k < node.key) {
                if (node.left!= null) {
                    node = node.left;
                } else {
                    node.left = new TreeNode(k, v);
                    node.left.parent = node;
                    return node.left;
                }
            } else if (node.key < k) {
                if (node.right!= null) {
                    node = node.right;
                } else {
                    node.right = new TreeNode(k, v);
                    node.right.parent = node;
                    return node.right;
                }
            } else {
                node.value = v;
                return null;
            }
        }
        return null;
    }

    static int getHeight(TreeNode x) {
        return x!= null? x.height : 0;
    }

    static int getNumTotal(TreeNode x) {
        return x!= null? x.num_total : 0;
    }

    void _rebalance(TreeNode node) {
        TreeNode n = node;
        while (n!= null) {
            int lh = getHeight(n.left);
            int rh = getHeight(n.right);
            n.height = Math.max(lh, rh) + 1;
            int balance_factor = lh - rh;
            n.num_total = 1 + getNumTotal(n.left) + getNumTotal(n.right);
            n.num_left = 1 + getNumTotal(n.left);

            if (balance_factor > 1) {
                if (getHeight(n.left.left) < getHeight(n.left.right)) {
                    this._rotate_left(n.left);
                }
                this._rotate_right(n);
            } else if (balance_factor < -1) {
                if (getHeight(n.right.right) < getHeight(n.right.left)) {
                    this._rotate_right(n.right);
                }
                this._rotate_left(n);
            } else {
                n = n.parent;
            }
        }
    }

    void _remove_one(TreeNode node) {
        TreeNode replacement = node.left!= null? node.left : node.right;
        if (node.parent!= null) {
            if (this._is_left(node)) {
                node.parent.left = replacement;
            } else {
                node.parent.right = replacement;
            }
            replacement.parent = node.parent;
            node.parent = null;
        } else {
            this._tree = replacement;
            replacement.parent = null;
        }
        node.left = null;
        node.right = null;
        node.parent = null;
        this._rebalance(replacement);
    }

    void _remove_leaf(TreeNode node) {
        if (node.parent!= null) {
            if (this._is_left(node)) {
                node.parent.left = null;
            } else {
                node.parent.right = null;
            }
            this._rebalance(node.parent);
        } else {
            this._tree = null;
        }
        node.parent = null;
        node.left = null;
        node.right = null;
    }

    void remove(int k) {
        TreeNode node = this._get_node(k);
        if (node == null) {
            return;
        }
        if (this._is_leaf(node)) {
            this._remove_leaf(node);
            return;
        }
        if (node.left!= null && node.right!= null) {
            TreeNode nxt = this._get_next(node);
            node.key = nxt.key;
            node.value = nxt.value;
            if (this._is_leaf(nxt)) {
                this._remove_leaf(nxt);
            } else {
                this._remove_one(nxt);
            }
            this._rebalance(node);
        } else {
            this._remove_one(node);
        }
    }

    int get(int k) {
        TreeNode node = this._get_node(k);
        return node!= null? node.value : -1;
    }

    TreeNode _get_node(int k) {
        if (this._tree == null) {
            return null;
        }
        TreeNode node = this._tree;
        while (node!= null) {
            if (k < node.key) {
                node = node.left;
            } else if (node.key < k) {
                node = node.right;
            } else {
                return node;
            }
        }
        return null;
    }

    int[] get_at(int pos) {
        int x = pos + 1;
        TreeNode node = this._tree;
        while (node!= null) {
            if (x < node.num_left) {
                node = node.left;
            } else if (node.num_left < x) {
                x -= node.num_left;
                node = node.right;
            } else {
                return new int[]{node.key, node.value};
            }
        }
        throw new IndexOutOfBoundsException("Out of ranges");
    }

    static boolean _is_left(TreeNode node) {
        return node.parent.left!= null && node.parent.left == node;
    }

    static boolean _is_leaf(TreeNode node) {
        return node.left == null && node.right == null;
    }

    void _rotate_right(TreeNode node) {
        if (node.parent == null) {
            this._tree = node.left;
            node.left.parent = null;
        } else if (this._is_left(node)) {
            node.parent.left = node.left;
            node.left.parent = node.parent;
        } else {
            node.parent.right = node.left;
            node.left.parent = node.parent;
        }
        TreeNode bk = node.left.right;
        node.left.right = node;
        node.parent = node.left;
        node.left = bk;
        if (bk!= null) {
            bk.parent = node;
        }
        node.height = Math.max(getHeight(node.left), getHeight(node.right)) + 1;
        node.num_total = 1 + getNumTotal(node.left) + getNumTotal(node.right);
        node.num_left = 1 + getNumTotal(node.left);
    }

    void _rotate_left(TreeNode node) {
        if (node.parent == null) {
            this._tree = node.right;
            node.right.parent = null;
        } else if (this._is_left(node)) {
            node.parent.left = node.right;
            node.right.parent = node.parent;
        } else {
            node.parent.right = node.right;
            node.right.parent = node.parent;
        }
        TreeNode bk = node.right.left;
        node.right.left = node;
        node.parent = node.right;
        node.right = bk;
        if (bk!= null) {
            bk.parent = node;
        }
        node.height = Math.max(getHeight(node.left), getHeight(node.right)) + 1;
        node.num_total = 1 + getNumTotal(node.left) + getNumTotal(node.right);
        node.num_left = 1 + getNumTotal(node.left);
    }

    static TreeNode _get_next(TreeNode node) {
        if (node.right == null) {
            return node.parent;
        }
        TreeNode n = node.right;
        while (n.left!= null) {
            n = n.left;
        }
        return n;
    }
}

class SegmentTree {
    int[] data;
    int defaultValue;
    int size;
    int length;
    int[] func;

    SegmentTree(int[] data, int defaultValue, int[] func) {
        this.defaultValue = defaultValue;
        this.func = func;
        this.length = data.length;
        this.size = 1 << (this.length - 1).bitCount();

        this.data = new int[2 * this.size];
        System.arraycopy(data, 0, this.data, this.size, this.length);
        for (int i = this.size - 1; i > 0; --i) {
            this.data[i] = this.func[this.data[i + i]][this.data[i + i + 1]];
        }
    }

    void set(int idx, int value) {
        idx += this.size;
        this.data[idx] = value;
        idx >>= 1;
        while (idx > 0) {
            this.data[idx] = this.func[this.data[2 * idx]][this.data[2 * idx + 1]];
            idx >>= 1;
        }
    }

    int get(int idx) {
        return this.data[idx + this.size];
    }

    int query(int start, int stop) {
        if (start == stop) {
            return this.get(start);
        }
        stop += 1;
        start += this.size;
        stop += this.size;

        int res = this.defaultValue;
        while (start < stop) {
            if ((start & 1)!= 0) {
                res = this.func[res][this.data[start]];
                ++start;
            }
            if ((stop & 1)!= 0) {
                --stop;
                res = this.func[res][this.data[stop]];
            }
            start >>= 1;
            stop >>= 1;
        }
        return res;
    }
}

class Factorial {
    int MOD;
    int[] factorials;
    int[] invModulos;
    int[] invFactorial_;

    Factorial(int MOD) {
        this.MOD = MOD;
        this.factorials = new int[]{1, 1};
        this.invModulos = new int[]{0, 1};
        this.invFactorial_ = new int[]{1, 1};
    }

    int calc(int n) {
        if (n <= -1) {
            System.out.println("Invalid argument to calculate n!");
            System.out.println("n must be non-negative value. But the argument was " + n);
            System.exit(0);
        }
        if (n < this.factorials.length) {
            return this.factorials[n];
        }
        int[] nextArr = new int[n + 1 - this.factorials.length];
        int initialI = this.factorials.length;
        int prev = this.factorials[this.factorials.length - 1];
        int m = this.MOD;
        for (int i = initialI; i < n + 1; ++i) {
            prev = nextArr[i - initialI] = prev * i % m;
        }
        this.factorials = Arrays.copyOf(this.factorials, this.factorials.length + nextArr.length);
        System.arraycopy(nextArr, 0, this.factorials, this.factorials.length - nextArr.length, nextArr.length);
        return this.factorials[n];
    }

    int inv(int n) {
        if (n <= -1) {
            System.out.println("Invalid argument to calculate n^(-1)");
            System.out.println("n must be non-negative value. But the argument was " + n);
            System.exit(0);
        }
        int pi = n % this.MOD;
        if (pi < this.invModulos.length) {
            return this.invModulos[pi];
        }
        int[] nextArr = new int[n + 1 - this.invModulos.length];
        int initialI = this.invModulos.length;
        for (int i = initialI; i < Math.min(this.MOD, n + 1); ++i) {
            nextArr[i - initialI] = -this.invModulos[this.MOD % i] * (this.MOD / i) % this.MOD;
        }
        this.invModulos = Arrays.copyOf(this.invModulos, this.invModulos.length + nextArr.length);
        System.arraycopy(nextArr, 0, this.invModulos, this.invModulos.length - nextArr.length, nextArr.length);
        return this.invModulos[pi];
    }

    int invFactorial(int n) {
        if (n <= -1) {
            System.out.println("Invalid argument to calculate (n^(-1))!");
            System.out.println("n must be non-negative value. But the argument was " + n);
            System.exit(0);
        }
        if (n < this.invFactorial_.length) {
            return this.invFactorial_[n];
        }
        this.inv(n);
        int[] nextArr = new int[n + 1 - this.invFactorial_.length];
        int initialI = this.invFactorial_.length;
        int prev = this.invFactorial_[this.invFactorial_.length - 1];
        int p = this.MOD;
        for (int i = initialI; i < n + 1; ++i) {
            prev = nextArr[i - initialI] = prev * this.invModulos[i % p] % p;
        }
        this.invFactorial_ = Arrays.copyOf(this.invFactorial_, this.invFactorial_.length + nextArr.length);
        System.arraycopy(nextArr, 0, this.invFactorial_, this.invFactorial_.length - nextArr.length, nextArr.length);
        return this.invFactorial_[n];
    }
}

class Combination {
    int MOD;
    Factorial factorial;

    Combination(int MOD) {
        this.MOD = MOD;
        this.factorial = new Factorial(MOD);
    }

    int ncr(int n, int k) {
        if (k < 0 || n < k) {
