import java.util.*;

public class Main {

    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static int dist(Point p, Point q) {
        return Math.abs(p.x - q.x) + Math.abs(p.y - q.y);
    }

    static int go(int i, int tt, ArrayList<Point> pts) {
        int ans = 0;
        for (int j = 0; j <= i; j++) {
            for (int k = i; k < 64; k++) {
                int jk = dist(pts.get(i), pts.get(j)) + dist(pts.get(j), pts.get(k));
                int kj = dist(pts.get(i), pts.get(k)) + dist(pts.get(k), pts.get(j));
                if (jk <= tt || kj <= tt) {
                    ans = Math.max(ans, Math.abs(j - k) + 1);
                }
            }
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x0 = sc.nextInt();
        int y0 = sc.nextInt();
        int ax = sc.nextInt();
        int ay = sc.nextInt();
        int bx = sc.nextInt();
        int by = sc.nextInt();
        int xs = sc.nextInt();
        int ys = sc.nextInt();
        int t = sc.nextInt();

        ArrayList<Point> pts = new ArrayList<>();
        pts.add(new Point(x0, y0));
        for (int i = 1; i < 64; i++) {
            int xi = ax * pts.get(i - 1).x + bx;
            int yi = ay * pts.get(i - 1).y + by;
            pts.add(new Point(xi, yi));
        }

        int ans = 0;
        Point s = new Point(xs, ys);
        for (int i = 0; i < 64; i++) {
            int tt = t - dist(s, pts.get(i));
            if (tt >= 0) {
                ans = Math.max(ans, go(i, tt, pts));
            }
        }
        System.out.println(ans);
    }
}

