public class Main {
    static long p = 1000000007;

    static long lcm(long x, long y) {
        return (x * y) / BigInteger.valueOf(x).gcd(BigInteger.valueOf(y)).longValue();
    }

    static long[] readarrint() {
        Scanner sc = new Scanner(System.in);
        String[] arr = sc.nextLine().split(" ");
        long[] res = new long[arr.length];
        for (int i = 0; i < arr.length; i++) {
            res[i] = Long.parseLong(arr[i]);
        }
        return res;
    }

    static int N = 1000001;
    static long[] factorialNumInverse = new long[N + 1];
    static long[] naturalNumInverse = new long[N + 1];
    static long[] fact = new long[N + 1];

    static void InverseofNumber(long p) {
        naturalNumInverse[0] = naturalNumInverse[1] = 1;
        for (int i = 2; i <= N; i++) {
            naturalNumInverse[i] = (naturalNumInverse[(int) (p % i)] *
                    (p - (p / i)) % p);
        }
    }

    static void InverseofFactorial(long p) {
        factorialNumInverse[0] = factorialNumInverse[1] = 1;
        for (int i = 2; i <= N; i++) {
            factorialNumInverse[i] = (naturalNumInverse[i] *
                    factorialNumInverse[i - 1]) % p;
        }
    }

    static void factorial(long p) {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = (fact[i - 1] * i) % p;
        }
    }

    static long Binomial(int N, int R, long p) {
        long ans = ((fact[N] * factorialNumInverse[R]) % p *
                factorialNumInverse[N - R]) % p;
        return ans;
    }

    public static void main(String[] args) {
        for (int i = 0; i < 1; i++) {
            long[] a = readarrint();
            int n = (int) a[0];
            int k = (int) a[1];
            if (k >= n) {
                System.out.println((int) Math.pow(2, n) % p);
            } else {
                long ans = 0;
                InverseofNumber(p);
                InverseofFactorial(p);
                factorial(p);
                for (int j = 0; j <= k; j++) {
                    ans = (ans + Binomial(n, j, p)) % p;
                }
                System.out.println(ans);
            }
        }
    }
}

