import java.util.*;

public class Main {
    static final int MOD = (int) Math.pow(10, 9) + 7;
    static int[][] multMM(int[][] a, int[][] b) {
        int n = a.length;
        int[][] r = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    r[i][j] += a[i][k] * b[k][j];
                    r[i][j] %= MOD;
                }
            }
        }
        return r;
    }
    static int[] multMV(int[][] a, int[] v) {
        int n = a.length;
        int[] r = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                r[i] += a[i][j] * v[j];
                r[i] %= MOD;
            }
        }
        return r;
    }
    static int[][] powM(int[][] a, int p) {
        int n = a.length;
        if (p == 0) {
            int[][] r = new int[n][n];
            for (int i = 0; i < n; i++) r[i][i] = 1;
            return r;
        }
        if (p % 2 == 0) {
            int[][] t = powM(a, p / 2);
            return multMM(t, t);
        } else {
            return multMM(a, powM(a, p - 1));
        }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
