        long x1 = 0, y1 = 1;

        while (b!= 0) {
            long q = a / b;

            long temp = a;
            a = b;
            b = temp - b * q;

            long temp2 = x0;
            x0 = x1;
            x1 = temp2 - q * x1;

            long temp3 = y0;
