public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int k = scanner.nextInt();
        int b = scanner.nextInt();
        int n = scanner.nextInt();
        int t = scanner.nextInt();
        System.out.println(getP(k, b, n, t));
    }

    public static int getP(int k, int b, int n, int t) {
        if (k == 1) {
            int z = 1 + n * b;
            if (t >= z) {
                return 0;
            }
            return (z - t) % b == 0? (z - t) / b : (z - t) / b + 1;
        }
        int tt = (k - 1) + b;
        int z = t * (k - 1) + b;
        int ans = 0;
        for (int i = 0; i <= n; i++) {
            if (tt * Math.pow(k, i) <= z) {
                ans = i;
            } else {
                break;
            }
        }
        return Math.max(n - ans, 0);
    }
}

