public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int rock1 = sc.nextInt();
        int sci1 = sc.nextInt();
        int paper1 = sc.nextInt();
        int rock2 = sc.nextInt();
        int sci2 = sc.nextInt();
        int paper2 = sc.nextInt();

        System.out.println(minimum(n, rock1, sci1, paper1, rock2, sci2, paper2) + " " + maximum(rock1, sci1, paper1, rock2, sci2, paper2));
    }

    private static int maximum(int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        int ans = Math.min(rock1, sci2) + Math.min(sci1, paper2) + Math.min(paper1, rock2);
        return ans;
    }

    private static int match(int a, int b) {
        if (a == b) return 0;
        else if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) return 1;
        else return -1;
    }

    private static int give(List<List<Integer>> l1, List<List<Integer>> l2) {
        int ans = 0;
        int curr1 = 0, curr2 = 0;
        while (!l1.isEmpty() ||!l2.isEmpty()) {
            if (curr1 == 0 &&!l1.isEmpty()) curr1 = l1.remove(0).get(0);
            if (curr2 == 0 &&!l2.isEmpty()) curr2 = l2.remove(0).get(0);
            if (curr1 == 0 || curr2 == 0) return ans;

            ans += Math.max(0, Math.min(curr1, curr2) * match(l1.get(0).get(1), l2.get(0).get(1)));

            if (curr1 < curr2) {
                curr2 -= curr1;
                curr1 = 0;
            } else if (curr1 > curr2) {
                curr1 -= curr2;
                curr2 = 0;
            } else {
                curr1 = curr2 = 0;
            }
        }
        return ans;
    }

    private static int minimum(int n, int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        List<List<Integer>> l1 = new ArrayList<>();
        l1.add(Arrays.asList(rock1, 1));
        l1.add(Arrays.asList(sci1, 2));
        l1.add(Arrays.asList(paper1, 3));

        List<List<Integer>> l2 = new ArrayList<>();
        l2.add(Arrays.asList(rock2, 1));
        l2.add(Arrays.asList(sci2, 2));
        l2.add(Arrays.asList(paper2, 3));

        int ans = Integer.MAX_VALUE;
        for (List<Integer> i : permutations(l1)) {
            for (List<Integer> j : permutations(l2)) {
                List<List<Integer>> myList1 = new ArrayList<>(i);
                List<List<Integer>> myList2 = new ArrayList<>(j);
                ans = Math.min(ans, give(myList1, myList2));
            }
        }

        return ans;
    }

    private static List<List<Integer>> permutations(List<List<Integer>> l) {
        List<List<Integer>> result = new ArrayList<>();
        permutationsHelper(l, 0, l.size(), result);
        return result;
    }

    private static void permutationsHelper(List<List<Integer>> l, int start, int end, List<List<Integer>> result) {
        if (start == end) {
            result.add(new ArrayList<>(l));
        } else {
            for (int i = start; i < end; i++) {
                Collections.swap(l, start, i);
                permutationsHelper(l, start + 1, end, result);
                Collections.swap(l, start, i);
            }
        }
    }
}

