        Scanner in = new Scanner(System.in);
        int T = 1;
        while (T-- > 0) {
            int p = in.nextInt();
            int q = in.nextInt();
            int mx = 10000010;
            boolean[] prime = primetilln(mx - 1);
            int[] a1 = new int[mx];
            int[] a2 = new int[mx];
            for (int i = 0; i < mx; i++) {
                if (prime[i]) {
                    a1[i]++;
                }
            }
            for (int i = 1; i < mx; i++) {
                if (checkPalindrom(i)) {
                    a2[i]++;
                }
            }
            for (int i = 1; i < mx; i++) {
                a1[i] += a1[i - 1];
                a2[i] += a2[i - 1];
            }
            int ans = 0;
            for (int i = 1; i < mx; i++) {
                if (a1[i] * q <= p * a2[i]) {
                    ans = Math.max(ans, i);
                }
            }
            System.out.println(ans!= 0? ans : "Palindromic tree is better than splay tree");
        }
    }

    static boolean[] primetilln(int n) {
        boolean[] prime = new boolean[n + 1];
        Arrays.fill(prime, true);
        for (int p = 2; p * p <= n; p++) {
            if (prime[p]) {
                for (int i = p * 2; i <= n; i += p) {
                    prime[i] = false;
                }
            }
        }
        return prime;
    }

    static boolean checkPalindrom(int x) {
        String s = String.valueOf(x);
        return s.equals(new StringBuilder(s).reverse().toString());
    }
