            this.n = n;
            a = new int[n][n];
        }

        Matrix multiply(Matrix b) {
            Matrix res = new Matrix(n);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        res.a[i][j] += a[i][k] * b.a[k][j] % mod;
                        res.a[i][j] %= mod;
                    }
                }
            }
