            Matrix res = new Matrix(n);
            for (int i = 0; i < n; i++) {
                res.a[i][i] = 1;
            }
            Matrix tmp = this;
            while (e > 0) {
                if ((e & 1) == 1) {
                    res = res.multiply(tmp);
                }
                e >>= 1;
                tmp = tmp.multiply(tmp);
            }
            return res;
        }
    }

