            ifact.set(i - 1, (ifact.get(i) * i) % mod);
        }
    }

    static long ncr(long n, long r, long p) {
        if (r > n) return 0;
        return (fact.get((int)n) * ((ifact.get((int)(n - r)) * ifact.get((int)r)) % p)) % p;
    }

    static long modinv(long n, long p) {
        return pow(n, p - 2, p);
    }

    static long pow(long x, long y, long p) {
        long res = 1L;
        x = x % p;
        while (y > 0) {
            if ((y & 1) == 1) res = (res * x) % p;
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }

