        int k1 = a.get(0);
        int k2 = b.get(0);
        ArrayList<Integer> initiala = new ArrayList<>(a.subList(1, a.size()));
        ArrayList<Integer> initialb = new ArrayList<>(b.subList(1, b.size()));
        ArrayDeque<Integer> queuea = new ArrayDeque<>(a.subList(1, a.size()));
        ArrayDeque<Integer> queueb = new ArrayDeque<>(b.subList(1, b.size()));
        int ans = 0;
        while (true) {
            if (ans > 200) {
                out.println(-1);
                out.flush();
                System.exit(0);
            }
            if (queuea.isEmpty() || queueb.isEmpty()) {
                if (queuea.isEmpty()) {
                    out.println(ans + " " + 2);
                } else {
                    out.println(ans + " " + 1);
                }
                out.flush();
                System.exit(0);
            }
            if (queuea.peek() > queueb.peek()) {
                int num1 = queuea.poll();
                int num2 = queueb.poll();
                queuea.add(num2);
                queuea.add(num1);
                ans += 1;
            } else {
                int num1 = queuea.poll();
                int num2 = queueb.poll();
                queueb.add(num1);
                queueb.add(num2);
                ans += 1;
            }
            if (check(queuea, queueb, initiala, initialb, ans)) {
                out.println(-1);
                out.flush();
                System.exit(0);
            }
        }
    }

    public static boolean check(ArrayDeque<Integer> a, ArrayDeque<Integer> b, ArrayList<Integer> initiala, ArrayList<Integer> initialb, int ans) {
        if (a.size()!= initiala.size() || b.size()!= initialb.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            if (a.get(i)!= initiala.get(i)) {
                return false;
            }
        }
        for (int i = 0; i < b.size(); i++) {
            if (b.get(i)!= initialb.get(i)) {
                return false;
            }
        }
        return true;
    }
}

