        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int A = scanner.nextInt();
        int B = scanner.nextInt();
        scanner.close();

        int cost = 0;
        if (k == 1) {
            cost = (n-1)*A;
            n = 0;
        }
        while (n > 0) {
            int steps = n-((n/k)*k);
            steps = Math.min(steps, n-1);
            cost += steps * A;
            n -= steps;
            if (n == 1) {
                break;
            }
            steps = n-n/k;
            if (steps*A < B) {
                cost += steps*A;
            } else {
                cost += B;
            }
            n -= steps;
        }

        System.out.println(cost);
    }
}

