import java.util.*;

public class Main {
    static int[][] dp;

    static int t(int n, int h) {
        if (dp[n][h] == -1) {
            dp[n][h] = 0;
            for (int m = 1; m <= n; m++) {
                int sum1 = 0, sum2 = 0;
                for (int i = 0; i < h; i++) {
                    sum1 += t(m - 1, h - 1) * t(n - m, i);
                }
                for (int i = 0; i < h - 1; i++) {
                    sum2 += t(n - m, h - 1) * t(m - 1, i);
                }
                dp[n][h] += sum1 + sum2;
            }
        }
        return dp[n][h];
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        dp = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
