import java.util.Scanner;

public class Main {
    static Map<Integer, Integer> tab1 = new HashMap<>();
    static Map<Integer, Integer> tab2 = new HashMap<>();

    static int num1(int n) {
        if (n < 0) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (!tab1.containsKey(n)) {
            int r = 0;
            for (int i = 0; i < n; i++) {
                r += num1(i) * num1(n - 1 - i);
            }
            tab1.put(n, r);
        }
        return tab1.get(n);
    }

    static int num2(int n, int h) {
        if (n < 0 || h <= 0 || n >= Math.pow(2, h - 1)) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (n < h) {
            return num1(n);
        }
        if (!tab2.containsKey(n * 1000 + h)) {
            int r = 0;
            for (int i = 0; i < n; i++) {
                r += num2(i, h - 1) * num2(n - 1 - i, h - 1);
            }
            tab2.put(n * 1000 + h, r);
        }
        return tab2.get(n * 1000 + h);
    }

