def binary_search(n1, n2, p1, p2):
    l, r = 0, 1<<61
    while (l <= r):
        mid = l+r >> 1
        if (valid(n1, n2, p1, p2, mid)):
            l = mid+1
        else:
            r = mid-1
    return l

