        int ans = x * y + c - (int) ((x * y * zinv + c * zinv) / z) * z;
        if (ans >= z) {
            return ans - z;
        } else if (ans < 0) {
            return ans + z;
        } else {
            return ans;
        }
    }

    private static ArrayList<Integer> printMin(int[] arr, int n, int k) {
        ArrayList<Integer> res = new ArrayList<>();
        Deque<Integer> Qi = new ArrayDeque<>();
        for (int i = 0; i < k; i++) {
            while (!Qi.isEmpty() && arr[i] <= arr[Qi.peekLast()]) {
                Qi.removeLast();
            }
            Qi.add(i);
