            G[i] = pow(F[i], mod - 2, mod);
        }

        for (int i = 0; i < n; i++) {
            if (i * 2 > n) {
                break;
            }
            B[i] = (F[n - i] * G[i] * G[n - i * 2]) % mod;
        }
        for (int i = 0; i <= n / 2; i++) {
