            }
        }
        for (int i = 0; i <= n; i++) {
            A[i] = (A[i] * F[n - i]) % mod;
        }
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                C[j] = (C[j] + A[i] * F[i] * G[j] * G[i - j] * (1 - (i - j) % 2 * 2)) % mod;
            }
        }
