import java.util.*;

public class Main {
    static Map<String, Integer> mem = new HashMap<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int f = scanner.nextInt();
        int h = scanner.nextInt();
        int kf_init = scanner.nextInt();
        int kh_init = scanner.nextInt();
        scanner.close();

        System.out.println(C(f, h, kf_init, kh_init, kf_init, kh_init) % 100000000);
    }

    static int C(int f, int h, int kf, int kh, int kf_init, int kh_init) {
        if (f + h == 0) {
            return 1;
        } else {
            String key = f + "_" + h + "_" + kf + "_" + kh;
            if (!mem.containsKey(key)) {
                mem.put(key, F(f, h, kf, kh, kf_init, kh_init) + H(f, h, kf, kh, kf_init, kh_init));
            }
            return mem.get(key);
        }
    }

    static int F(int f, int h, int kf, int kh, int kf_init, int kh_init) {
        if (f > 0 && kf > 0) {
            return C(f - 1, h, kf - 1, kh_init, kf_init, kh_init);
        } else {
            return 0;
        }
    }

    static int H(int f, int h, int kf, int kh, int kf_init, int kh_init) {
        if (h > 0 && kh > 0) {
            return C(f, h - 1, kf_init, kh - 1, kf_init, kh_init);
        } else {
            return 0;
        }
    }
}

