public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int x1 = scanner.nextInt();
        int y1 = scanner.nextInt();
        int x2 = scanner.nextInt();
        int y2 = scanner.nextInt();
        scanner.close();

        int A = a * 2;
        int B = b * 2;

        int[] X1Y1 = rot(x1, y1);
        int X1 = X1Y1[0];
        int Y1 = X1Y1[1];
        List<int[]> P1 = cand(X1, Y1, A, B);

        int[] X2Y2 = rot(x2, y2);
        int X2 = X2Y2[0];
        int Y2 = X2Y2[1];
        List<int[]> P2 = cand(X2, Y2, A, B);

        long res = Long.MAX_VALUE;
        for (int[] p1 : P1) {
            for (int[] p2 : P2) {
                res = Math.min(res, dist(p1, p2, A, B));
            }
        }

        System.out.println(res);
    }

    private static int[] rot(int x, int y) {
        return new int[]{(x - y) / 2, (x + y) / 2};
    }

    private static List<int[]> cand(int X, int Y, int A, int B) {
        List<int[]> P = new ArrayList<>();
        if (X % B == 0) {
            if (Y % A == 0) {
                P.add(new int[]{X - 1, Y - 1});
                P.add(new int[]{X - 1, Y + 1});
                P.add(new int[]{X + 1, Y - 1});
                P.add(new int[]{X + 1, Y + 1});
            } else {
                P.add(new int[]{X - 1, Y});
                P.add(new int[]{X + 1, Y});
            }
        } else {
            if (Y % A == 0) {
                P.add(new int[]{X, Y - 1});
                P.add(new int[]{X, Y + 1});
            } else {
                P.add(new int[]{X, Y});
            }
        }
        return P;
    }

    private static long dist(int[] p1, int[] p2, int A, int B) {
        int x1 = p1[0] / B;
        int y1 = p1[1] / A;
        int x2 = p2[0] / B;
        int y2 = p2[1] / A;
        int dx = Math.abs(x1 - x2);
        int dy = Math.abs(y1 - y2);
        return Math.max(dx, dy);
    }
}

