public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int prime = 998244353;
        long z = 0;

        for (int i = 1; i <= n; i++) {
            z += modInverse(i, prime);
        }

        long ans = (1 + m * z) * (1 + n * modInverse(m + 1, prime));
        System.out.println(ans % prime);
    }

    public static long modInverse(long a, long m) {
        long m0 = m;
        long y = 0;
        long x = 1;

        if (m == 1) {
            return 0;
        }

        while (a > 1) {
            long q = a / m;
            long t = m;
            m = a % m;
            a = t;
            t = y;
            y = x - q * y;
            x = t;
        }

        if (x < 0) {
            x = x + m0;
        }

        return x;
    }
}

