            if (Collections.frequency(Arrays.asList(nums), nums[0]) == 3) {
                result = Integer.toString(Math.min(nums[0] * Collections.frequency(Arrays.asList(nums), nums[0]), nums[nums.length - 1] * Collections.frequency(Arrays.asList(nums), nums[nums.length - 1])));
            } else {
                result = Integer.toString(nums[0] + nums[nums.length - 1]);
            }
        } else if (new HashSet<>(Arrays.asList(nums)).size() == 5) {
            result = Integer.toString(Arrays.stream(nums).sum());
        } else if (new HashSet<>(Arrays.asList(nums)).size() == 1) {
            result = Integer.toString(nums[0] * 2);
        } else if (new HashSet<>(Arrays.asList(nums)).size() == 4) {
            int rep = (int) Arrays.stream(nums).filter(x -> Collections.frequency(Arrays.asList(nums), x) == 2).findFirst().getAsInt();
            result = Integer.toString(Arrays.stream(nums).sum() - 2 * rep);
        } else {
            int d = 3;
            if (Collections.frequency(Arrays.asList(nums), nums[0]) == 2) {
                d = 2;
            }
            int[] rep = Arrays.stream(nums).filter(x -> Collections.frequency(Arrays.asList(nums), x) > 1).distinct().sorted().toArray();
            result = Integer.toString(Arrays.stream(nums).sum() - d * rep[rep.length - 1]);
        }
        System.out.println(result);
    }
}

