import java.util.*;
import java.io.*;

class Main {
    static int MOD = 998244353;
    static int n, k;
    static Map<Integer, Integer> memo = new HashMap<>();
    static Map<Integer, Integer> memo2 = new HashMap<>();
    static int[][] memo3;

    static int mexp(int b, int e, int m) {
        if (e == 0) return 1;
        if (e == 1) return b % m;
        int s = mexp(b, e >> 1, m);
        return (int) ((long) s * s * (e & 1 == 1? b : 1) % m);
    }

    static int inv(int x) {
        if (!memo2.containsKey(x)) {
            memo2.put(x, mexp(x, MOD - 2, MOD));
        }
        return memo2.get(x);
    }

    static int go(int left, int last) {
        if (left == 0) return 1;
        if (last == k) return 0;
        int st = left * 300 + last;
        if (!memo.containsKey(st)) {
            int scale = 1;
            memo.put(st, 0);
            int comp = n - left;
            for (int i = 0; i <= left; i++) {
                int ex = (comp - 1) * i + ((i * (i - 1)) >> 1);
                memo.put(st, (memo.get(st) + (int) ((long) go(left - i, last + 1) * scale * memo3[k - last][ex] % MOD)) % MOD);
                scale = (int) ((long) scale * (left - i) % MOD * inv(i + 1) % MOD);
            }
        }
        return memo.get(st);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
