            memo3[i][0] = 1;
            for (int j = 1; j <= ((n * (n - 1)) >> 1) + 1; j++) {
                memo3[i][j] = (int) ((long) memo3[i][j - 1] * i % MOD);
            }
        }
        System.out.println(go(n - 1, 0));
    }
}

