import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] size = countCycle();
        System.out.println(solve(scanner.nextInt(), size));
    }

    private static int[] countCycle() {
        int[] size = new int[14];
        size[0] = 1;
        size[1] = 60;
        int Mod = 10;
        for (int i = 2; i < 14; i++) {
            Mod *= 10;
            int x = fib(size[i - 1] - 1, Mod);
            int f0 = x;
            int f1 = (x + fib(size[i - 1], Mod)) % Mod;
            size[i] = size[i - 1];
            while (f0!= 0 || f1!= 1) {
                int temp = f1;
                f1 = (f1 * fib(size[i - 1], Mod) + f0 * fib(size[i - 1] - 1, Mod)) % Mod;
                f0 = temp;
                size[i] += size[i - 1];
            }
        }
        return size;
    }

    private static int solve(int f, int[] size) {
        int Mod = 10;
        int f0 = 0;
        int f1 = 1;
        List<Integer> ans = new ArrayList<>();
        if (f % 10 == 0) {
            ans.add(0);
        } else if (f % 10 == 1) {
            ans.add(1);
        }
        for (int i = 2; i < size[1]; i++) {
            int temp = f1;
            f1 = (f0 + f1) % 10;
            f0 = temp;
            if (f1 == f % 10) {
                ans.add(i);
            }
        }
        for (int i = 2; i < 14; i++) {
            Mod *= 10;
            List<Integer> temp = new ArrayList<>();
            for (int x : ans) {
                if (x + size[i - 1] < size[i]) {
                    temp.add(x + size[i - 1]);
                }
            }
            ans.clear();
            for (int x : temp) {
                if (fib(x, Mod) == f % Mod) {
                    ans.add(x);
                }
            }
        }
        return ans.isEmpty()? -1 : Collections.min(ans);
    }

    private static int fib(int x, int Mod) {
        x--;
        int[][] base = {{1, 1}, {1, 0}};
        int[][] ret = {{1, 0}, {0, 1}};
        while (x > 0) {
            if ((x & 1) == 1) {
                int[][] temp = new int[2][2];
                for (int i = 0; i < 2; i++) {
                    for (int j = 0; j < 2; j++) {
                        for (int k = 0; k < 2; k++) {
                            temp[i][j] = (temp[i][j] + base[i][k] * ret[k][j]) % Mod;
                        }
                    }
                }
                ret = temp;
            }
            int[][] temp = new int[2][2];
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 2; j++) {
                    for (int k = 0; k < 2; k++) {
                        temp[i][j] = (temp[i][j] + base[i][k] * base[k][j]) % Mod;
                    }
                }
            }
            base = temp;
            x /= 2;
        }
        return ret[0][0];
    }
}

