import java.util.*;

public class Main {
    static long MOD = 998244353;
    static long inv(long a) {
        return pow(a, MOD-2, MOD);
    }

    static long fat(long a) {
        long ans = 1;
        for (long i = 1; i <= a; i++) {
            ans = (ans*i)%MOD;
        }
        return ans;
    }

    static long pow(long a, long b, long m) {
        a %= m;
        long res = 1;
        while (b > 0) {
            if ((b & 1)!= 0)
                res = res * a % m;
            a = a * a % m;
            b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long k = sc.nextLong();
        long p = inv(m);

        // O(Burro) O(n2)-> Fórmula da experança = sum(x^k * C(n, x) * p^x * q^(n-x))
        long resp = 0;
        long q = (1 - p + MOD) % MOD;
        for (long x = 1; x <= n; x++) {
            resp += pow(x, k, MOD) %MOD * fat(n) %MOD * inv(n-x) %MOD * inv(x) %MOD *pow(p, x, MOD) %MOD * pow(q, n-x, MOD) %MOD;
        }

        // O(menos burro) O(nlog(k)) -> atualiza somatório usando valores ja calculados
        if (n<=k) {
            q = (1 - p + MOD) % MOD;
            long inv_q = inv(q);
            long p_aux = p;
            long q_aux = pow(q, n-1, MOD);
            long fn = n;
            resp = n * p%MOD * q_aux%MOD;
            resp = resp%MOD;

            for (long i = 2; i <= n; i++) {
                long x = pow(i, k, MOD);
                p_aux = p_aux * p %MOD;
                q_aux = q_aux * inv_q;
                fn = fn*(n-i+1)%MOD*inv(i)%MOD;

                resp = resp + x * fn %MOD * p_aux %MOD * q_aux %MOD;
                resp = resp%MOD;
            }
            System.out.println(resp);
        }

        // O(inteligente) O(k2) -> A partir da FGM M(X), identifica padrão das derivadas
        // k-ésima derivada de M(X) = E(x^k)
        // E(x^k) = n!/(n-k)! * p^k + k*(deriv[k-1] - sum(ind[i]*deriv[i])) + sum(ind[i]*deriv[i+1])
        else {
            ArrayList<Long> deriv = new ArrayList<>();
            deriv.add((n*p)%MOD); //E(x) = np
            long resp = n*n%MOD*p%MOD*p%MOD - n*p%MOD*p%MOD + n*p%MOD; //E(x^2) = n^2p^2 - np^2 + np
            deriv.add(resp%MOD);
            long fn = (n*(n-1))%MOD;
            ArrayList<Long> v=new ArrayList<>();
            v.add(1L);

            for (long i = 3; i <= k; i++) {
                fn = (fn * (n-i+1) %MOD)%MOD;
                ArrayList<Long> w = new ArrayList<>();
                w.add((-(i-1)*v.get(0).longValue())%MOD);
                for (long j = 0; j < v.size()-1; j++) {
                    w.add((v.get(j).longValue() - (i-1)*v.get(j+1).longValue()%MOD)%MOD);
                }
                w.add((v.get(v.size()-1).longValue() + i-1)%MOD);
                v = w;

                resp = (fn * pow(p, i, MOD))%MOD;
                for (long j = 0; j < v.size(); j++) {
                    resp = (resp + v.get(j).longValue()*deriv.get(j.intValue())%MOD)%MOD;
                }
                resp %= MOD;
                deriv.add(resp);
            }

            System.out.println(deriv.get(k.intValue()-1));
        }
    }
}

