import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int l1 = scanner.nextInt();
        int r1 = scanner.nextInt();
        int l2 = scanner.nextInt();
        int r2 = scanner.nextInt();
        Set<Pair> la = new HashSet<>();
        Set<Pair> lb = new HashSet<>();

        int pv = 1;
        for (int i = 0; i < 32; i++) {
            pv = pv * 2 + 1;
        }
        foo(l1, r1, pv, la);
        foo(l2, r2, pv, lb);

        int ans = 0;
        for (Pair a : la) {
            for (Pair b : lb) {
                ans = Math.max(ans, Math.min(a.r, b.r) - Math.max(a.l, b.l) + 1);
            }
        }
        System.out.println(ans);
    }

    private static void foo(int l, int r, int pv, Set<Pair> li) {
        if (l > r) {
            return;
        }
        while (pv > 1 && (pv - 1) / 2 >= r) {
            pv = (pv - 1) / 2;
        }
        li.add(new Pair(l, r));
        if (l <= r && pv >= 3) {
            pv = (pv - 1) / 2;
            foo(l, Math.min(pv, r), pv, li);
            foo(Math.max(l - pv - 1, 1), Math.min(pv, r - pv - 1), pv, li);
        }
    }

    static class Pair {
        int l;
        int r;

        Pair(int l, int r) {
            this.l = l;
            this.r = r;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass()!= o.getClass()) return false;
            Pair pair = (Pair) o;
            return l == pair.l && r == pair.r;
        }

        @Override
        public int hashCode() {
            return Objects.hash(l, r);
        }
    }
}

