public class Main {
    public static void main(String[] args) {
        int[] a = {1, 2, 3, 4, 5}; // input array
        int n = a.length; // length of the array

        System.out.println(minimumCost(a, n));
    }

    static long minimumCost(int[] a, int n) {
        int mn = Integer.MAX_VALUE;
        long sum = 0;
        for (int i = 0; i < n; i++) {
            mn = Math.min(a[i], mn);
            sum += a[i];
        }
        return mn * (sum - mn);
    }
}

