public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[] vis = new int[n + 1];
        int ci = 0, cb = 0, cc = 0;
        List<Integer>[] g = new ArrayList[n + 1];

        for (int i = 1; i <= n; i++) {
            g[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        for (int i = 1; i <= n; i++) {
            if (vis[i] == 0) {
                if (g[i].isEmpty()) {
                    ci++;
                } else {
                    if (dfs(i, 1, vis, g)) {
                        cb++;
                    } else {
                        cc++;
                    }
                }
            }
        }

        System.out.println(ci * ci + 2 * ci * (n - ci) + cc * cc + 2 * cb * cc + 2 * cb * cb);
    }

    public static boolean dfs(int x, int col, int[] vis, List<Integer>[] g) {
        Stack<int[]> stk = new Stack<>();
        stk.push(new int[]{x, col});
        boolean flag = true;

        while (!stk.isEmpty()) {
            int[] current = stk.pop();
            int u = current[0];
            int color = current[1];

            if (vis[u] != 0) {
                flag &= (vis[u] == color);
                continue;
            }

            vis[u] = color;
            for (int i : g[u]) {
                stk.push(new int[]{i, 3 - color});
            }
        }

        return flag;
