                zero++;
            }
        }

        int patternA = 0;
        int patternB = 0;

        for (int j = 0; j <= zero; j++) {
            patternB += combi(zero, j);
        }

        int time = 0;
        while (time <= one) {
            if (time % 2 == P) {
                patternA += combi(one, time);
            }
            time++;
        }

        System.out.println((int) (patternA * patternB));
    }

    public static int combi(int N, int K) {
        long a = 1;
        for (int i = 0; i < K; i++) {
            a *= N - i;
        }
        for (int j = 0; j < K; j++) {
            a /= j + 1;
        }
        return (int) a;
    }
}

