import java.util.ArrayList;
import java.util.List;

public class Main {
    private static final long[] Z = new long[102];
    private static int[][] M;

    public static void main(String[] args) {
        for (int i = 0; i < Z.length; i++) {
            Z[i] = 1L << 62;
        }

        for (int n = 1; n < 12; n++) {
            M = new int[n + 2][n + 2];
            magic(1, 1, n, 0);
            System.out.println(n);
        }

        for (long value : Z) {
            System.out.print(value + " ");
        }
        System.out.println();

        List<Long> zList = new ArrayList<>();
        for (long value : Z) {
            zList.add(value);
        }

        zList.add(1L);
        zList.add(1L);
        zList.add(3L);
        zList.add(5L);
        zList.add(3L);
        zList.add(3L);

        int n = 8;
        for (int i = 5; i < 16; i += 2) {
            for (int j = 0; j < n; j++) {
                zList.add((long) i);
            }
            n += 4;
        }

        // Simulating input for demonstration purposes
        int x = Integer.parseInt(System.console().readLine());
        System.out.println(zList.get(x));
    }

    private static void magic(int i, int j, int n, int s) {
        if (s > 100) {
            return;
        }
        Z[s] = Math.min(Z[s], n);
        if (j > (n + 1) / 2.0) {
            return magic(i + 1, 1, n, s);
        }
        if (i > (n + 1) / 2.0) {
            return;
        }
        if (M[i - 1][j] == 0 && M[i][j - 1] == 0) {
            M[i][j] = 1;
            double t = 4;
            if (i == (n + 1) / 2.0) {
                t /= 2;
            }
            if (j == (n + 1) / 2.0) {
                t /= 2;
            }
            magic(i, j + 1, n, s + (int) t);
            M[i][j] = 0;
        }
        magic(i, j + 1, n, s);
    }
}

