    public static int bintodec(String s) {
        int num = 0;
        int mod = 1000003;
        int p = 2;
        int k = 0;

        for (int i = s.length() - 1; i >= 0; i--) {
            num += Integer.parseInt(String.valueOf(s.charAt(i))) * Math.pow(p, k);
            k++;
            num %= mod;
        }

        return num % mod;
    }
}

