import java.util.Scanner;

public class Main {
    public static int Count(int n) {
        int cnt = 0;
        int x = 1;
        while (true) {
            if (x > n) {
                break;
            }
            int y = 1;
            while (true) {
                if (x * y > n) {
                    break;
                }
                cnt++;
                y *= 3;
            }
            x *= 2;
        }
        return cnt;
    }

    public static int Result(int l, int r) {
        if (l == 0) {
            return Count(r);
        }
        return Count(r) - Count(l - 1);
    }

