import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Integer> a = new ArrayList<>();
        List<Integer> b = new ArrayList<>();
        List<Integer> c = new ArrayList<>();
        String s = scanner.next();

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 'V') {
                a.add(i);
            } else if (s.charAt(i) == 'K') {
                b.add(i);
            } else {
                c.add(i);
            }
        }

        Map<String, Double> dp = new HashMap<>();
        dp.put("0,0,0,0", 0.0);

        for (int i = 0; i <= a.size(); i++) {
            for (int j = 0; j <= b.size(); j++) {
                for (int k = 0; k <= c.size(); k++) {
                    for (int p = 0; p < 2; p++) {
                        if (i < a.size()) {
                            dp.putIfAbsent((i + 1) + "," + j + "," + k + ",1", Double.MAX_VALUE);
                            dp.put((i + 1) + "," + j + "," + k + ",1", Math.min(dp.get((i + 1) + "," + j + "," + k + ",1"), dp.getOrDefault(i + "," + j + "," + k + "," + p, Double.MAX_VALUE) + count(a, i, a.get(i)) + count(b, j, a.get(i)) + count(c, k, a.get(i))));
                        }
                        if (j < b.size() && p == 0) {
                            dp.putIfAbsent(i + "," + (j + 1) + "," + k + ",0", Double.MAX_VALUE);
                            dp.put(i + "," + (j + 1) + "," + k + ",0", Math.min(dp.get(i + "," + (j + 1) + "," + k + ",0"), dp.getOrDefault(i + "," + j + "," + k + "," + p, Double.MAX_VALUE) + count(a, i, b.get(j)) + count(b, j, b.get(j)) + count(c, k, b.get(j))));
                        }
                        if (k < c.size()) {
                            dp.putIfAbsent(i + "," + j + "," + (k + 1) + ",0", Double.MAX_VALUE);
                            dp.put(i + "," + j + "," + (k + 1) + ",0", Math.min(dp.get(i + "," + j + "," + (k + 1) + ",0"), dp.getOrDefault(i + "," + j + "," + k + "," + p, Double.MAX_VALUE) + count(a, i, c.get(k)) + count(b, j, c.get(k)) + count(c, k, c.get(k))));
                        }
                    }
                }
            }
        }

        System.out.println(Math.min(dp.getOrDefault(a.size() + "," + b.size() + "," + c.size() + ",0", Double.MAX_VALUE), dp.getOrDefault(a.size() + "," + b.size() + "," + c.size() + ",1", Double.MAX_VALUE)));
    }

    private static int count(List<Integer> list, int start, int x) {
        int ret = 0;
        int i = start;
        while (i < list.size() && list.get(i) < x) {
            ret++;
            i++;
        }
        return ret;
    }
}

