import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static int k, pa, pb;
    static final long MOD = 1000000007;
    static long INF;
    static long rAB, rB;
    static Map<String, Long> memo = new HashMap<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        k = scanner.nextInt();
        pa = scanner.nextInt();
        pb = scanner.nextInt();

        INF = ((pa + pb) * modInverse(pb, MOD)) % MOD;
        rAB = modInverse(pa + pb, MOD);
        rB = modInverse(pb, MOD);

        System.out.println(dfs(1, 0));
    }

    static long dfs(int a, int ab) {
        if (ab >= k) {
            return ab;
        }
        if (a + ab >= k) {
            return ((a + MOD - 1) + (pa + pb) * rB + ab) % MOD;
        }
        String key = a + "," + ab;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        long res = (dfs(a + 1, ab) * pa * rAB + dfs(a, ab + a) * pb * rAB) % MOD;
        memo.put(key, res);
        return res;
    }

    static long modInverse(long a, long m) {
        return power(a, m - 2, m);
    }

    static long power(long x, long y, long m) {
        if (y == 0) return 1;
        long p = power(x, y / 2, m) % m;
        p = (p * p) % m;
        return (y % 2 == 0) ? p : (p * x) % m;
    }
}

