import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static Map<Integer, Integer> dp = new HashMap<>();

    public static int solve(int x) {
        if (x == 0) {
            return 0;
        }
        if (dp.containsKey(x)) {
            return dp.get(x);
        }
        int limit = 1;
        int cnt = 1;
        while (limit <= x) {
            limit = limit * 10 + 1;
            cnt += 1;
        }
        int prv = limit / 10;
        int c1 = solve(x % prv) + (x / prv) * (cnt - 1);
        int c2 = solve((limit - x) % prv) + cnt + (cnt - 1) * ((limit - x) / prv);
        dp.put(x, Math.min(c1, c2));
        return Math.min(c1, c2);
    }

