    static int recurse(int value, int d) {
        if (d == 0) {
            return value == 0 ? 0 : Integer.MAX_VALUE;
        }

        if (save[d].containsKey(value)) {
            return save[d].get(value);
        }

        int ans = Integer.MAX_VALUE;

        for (int cnt = 0; cnt <= MAX_CNT; cnt++) {
            int nvalue = Math.abs(value - cnt * (int) NUMBERS[d]);

            if (nvalue <= CUTOFFS[d]) {
                ans = Math.min(ans, cnt * d + recurse(nvalue, d - 1));
            }
        }

        save[d].put(value, ans);
        return ans;
    }
}

