import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int a0 = scanner.nextInt();
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int k = scanner.nextInt();
        int M = scanner.nextInt();
        scanner.close();

        int[] a = new int[n];
        a[0] = a0;
        for (int i = 1; i < n; i++) {
            a[i] = (int)(((long)a[i - 1] * x + y) % M);
        }

        int invN = inv(n);
        int base = lcmRange(1, Math.max(k, 2));
        int[] pr = new int[base];
        for (int val : a) {
            pr[val % base] = (int)(((long)pr[val % base] + invN) % MOD);
        }

        long result = (reduce(a, 0, (total, val) -> (total + (val - val % base)) % MOD) * invN) % MOD;
        result = (result * k) % MOD;

        for (int i = 1; i <= k; i++) {
            result = (result + reduce(pr, 0, (total, val) -> (total + (long)val * pr[val]) % MOD)) % MOD;
            for (int j = 0; j < base; j++) {
                int change = (int)(((long)pr[j] * invN) % MOD);
                pr[j] = (int)(((long)pr[j] - change + MOD) % MOD);
                pr[(j - j % i + base) % base] = (int)(((long)pr[(j - j % i + base) % base] + change) % MOD);
            }
        }

        result = (result * pow(n, k, MOD)) % MOD;
        System.out.println(result);
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    private static int lcm(int x, int y) {
        return (int)(((long)x / gcd(x, y) * y) % MOD);
    }

    private static int inv(int n) {
        return pow(n, MOD - 2, MOD);
    }

    private static int pow(int base, int exp, int mod) {
        int result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (int)(((long)result * base) % mod);
            }
            exp >>= 1;
            base = (int)(((long)base * base) % mod);
        }
        return result;
    }

    private static int lcmRange(int start, int end) {
        int result = 1;
        for (int i = start; i <= end; i++) {
            result = lcm(result, i);
        }
        return result;
    }

    @FunctionalInterface
    interface LongBinaryOperator {
        int applyAsInt(int left, int right);
    }

    private static int reduce(int[] array, int identity, LongBinaryOperator op) {
        int result = identity;
        for (int value : array) {
            result = op.applyAsInt(result, value);
        }
        return result;
    }
}

