        r = [[a11, a12], [a21, a22]]
        return r

    def __get_matrix_power(self, M, p):

        if p == 1:
            return M
        if p in self.__memo:
            return self.__memo[p]
        K = self.__get_matrix_power(M, int(p/2))
        R = self.__multiply_matrices(K, K)
        self.__memo[p] = R
        return R

