            this.memo = new int[100000][2][2]; // Adjust size as needed
        }

        private int[][] multiplyMatrices(int[][] M1, int[][] M2) {
            int a11 = (int) ((long) M1[0][0] * M2[0][0] + (long) M1[0][1] * M2[1][0]) % m;
            int a12 = (int) ((long) M1[0][0] * M2[0][1] + (long) M1[0][1] * M2[1][1]) % m;
            int a21 = (int) ((long) M1[1][0] * M2[0][0] + (long) M1[1][1] * M2[1][0]) % m;
            int a22 = (int) ((long) M1[1][0] * M2[0][1] + (long) M1[1][1] * M2[1][1]) % m;
            return new int[][]{{a11, a12}, {a21, a22}};
        }

        private int[][] getMatrixPower(int[][] M, int p) {
            if (p == 1) {
                return M;
            }
            if (memo[p][0][0] != 0 || memo[p][0][1] != 0 || memo[p][1][0] != 0 || memo[p][1][1] != 0) {
                return memo[p];
            }
            int[][] K = getMatrixPower(M, p / 2);
            int[][] R = multiplyMatrices(K, K);
            memo[p] = R;
            return R;
        }

        public int getNumber(int n) {
            if (n == 0) {
                return 0;
            }
            if (n == 1) {
                return 1;
            }
            String binary = Integer.toBinaryString(n - 1);
            int[] powers = new int[binary.length()];
            int index = 0;
            for (int b = binary.length() - 1; b >= 0; b--) {
                if (binary.charAt(b) == '1') {
                    powers[index++] = (int) Math.pow(2, binary.length() - 1 - b);
                }
            }

            int[][][] matrices = new int[index][][];
            for (int i = 0; i < index; i++) {
                matrices[i] = getMatrixPower(Q, powers[i]);
            }
            while (index > 1) {
                int[][] M1 = matrices[--index];
                int[][] M2 = matrices[--index];
                int[][] R = multiplyMatrices(M1, M2);
                matrices[index] = R;
            }
            return matrices[0][0][0];
        }
    }

    static int all(int n) {
        int res = 1;
        int t = 2;
        while (n > 0) {
            if ((n & 1) != 0) {
                res = (int) ((long) res * t % m);
            }
            n >>= 1;
            t = (int) ((long) t * t % m);
        }
        return res;
    }
}

