import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;
    private static final double MODF = (double) MOD;
    private static final double SHRT = (double) (1 << 16);
    private static final double G = 3.0;
    private static final int MAXSIZ = 1 << 20;

    public static double fmod(double x) {
        return x - MODF * Math.floor(x / MODF);
    }

    public static double modProd(double a, double b) {
        return fmod(Math.floor(a / SHRT) * fmod(b * SHRT) + (a - SHRT * Math.floor(a / SHRT)) * b);
    }

    public static double fpow(double a, int b) {
        double r = 1.0;
        while (b > 0) {
            if ((b & 1) != 0) {
                r = modProd(r, a);
            }
            a = modProd(a, a);
            b >>= 1;
        }
        return r;
    }

    public static void nttTransform(double[] a) {
        int m = MAXSIZ;
        int m2 = m / 2;
        double[] w = new double[m2];
        w[1] = fpow(G, (MOD - 1) / m);
        for (int i = 2; i < m2; i++) {
            w[i] = modProd(w[i - 1], w[1]);
        }

        int[] rev = new int[m];
        for (int i = 0; i < m; i++) {
            rev[i] = rev[i >> 1] >> 1;
            if ((i & 1) != 0) {
                rev[i] |= m2;
            }
        }

        for (int i = 0; i < m; i++) {
            if (i < rev[i]) {
                double temp = a[i];
                a[i] = a[rev[i]];
                a[rev[i]] = temp;
            }
        }

        int l = 2;
        while (l <= m) {
            int half = l >> 1;
            int diff = m / l;
            for (int i = 0; i < m; i += l) {
                int pw = 0;
                for (int j = i; j < i + half; j++) {
                    double v = modProd(a[j + half], w[pw]);
                    a[j + half] = a[j] - v;
                    a[j] = a[j] + v;
                    pw += diff;
                }
            }
            l <<= 1;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        double[] f = new double[MAXSIZ];
        for (int i = 0; i < k; i++) {
            int d = scanner.nextInt();
            f[d] = 1.0;
        }

        nttTransform(f);
        for (int i = 0; i < MAXSIZ; i++) {
            f[i] = fpow(f[i], n >> 1);
        }
        nttTransform(f);

        double invM = fpow(MAXSIZ, MOD - 2);
        double sum = 0.0;
        for (double x : f) {
            sum = (sum + modProd(x, x)) % MODF;
        }
        double ans = modProd(sum, modProd(invM, invM));
        System.out.println((int) ans);
        scanner.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);
        int S = Integer.parseInt(input[2]);

        input = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(input[i]);
        }

        Set<Integer> aset = new HashSet<>();
        for (int num : a) {
            aset.add(num);
        }

        List<Integer> alist = new ArrayList<>(aset);
        Collections.sort(alist);

        List<Pair> plist = new ArrayList<>();
        for (int i : alist) {
            int count = 0;
            for (int num : a) {
                if (num == i) {
                    count++;
                }
            }
            plist.add(new Pair(i, count));
        }

        List<List<Triple>> oplist = new ArrayList<>();
        for (Pair pair : plist) {
            int x = pair.first;
            int c = pair.second;
            List<Triple> tlist = new ArrayList<>();
            if (x > 18) {
                for (int i = 0; i <= c; i++) {
                    tlist.add(new Triple(i * x, 0, comb(c, i)));
                }
            } else {
                long xfact = factorial(x);
                for (int nf = 0; nf <= c; nf++) {
                    for (int i = nf; i <= c; i++) {
                        tlist.add(new Triple(nf * xfact + (i - nf) * x, nf, comb(c, i) * comb(i, nf)));
                    }
                }
            }
            oplist.add(tlist);
        }

        int[][][] dl1 = new int[k + 1][S + 1][1];
        dl1[0][0][0] = 1;
        int nn = n / 2;
        Set<Integer> s = new HashSet<>();
        rec(1, dl1, s, 0, 0, nn, 0);
        List<Integer> l1 = new ArrayList<>(s);
        l1.add(0);
        int[][][] dl2 = new int[k + 1][S + 1][1];
        dl2[0][0][0] = 1;
        s.clear();
        rec(1, dl2, s, nn, 0, n, 0);
        List<Integer> l2 = new ArrayList<>(s);
        l2.add(0);

        Collections.sort(l1);
        Collections.sort(l2, Collections.reverseOrder());

        int count = 0;
        int i = 0, j = 0;

        while (i < l1.size()) {
            while (j < l2.size() && l2.get(j) > S - l1.get(i)) {
                j++;
            }
            if (j < l2.size() && l1.get(i) + l2.get(j) == S) {
                for (int m = 0; m <= k; m++) {
                    for (int r = 0; r <= m; r++) {
                        count += dl1[r][l1.get(i)][0] * dl2[m - r][l2.get(j)][0];
                    }
                }
            }
            i++;
        }

        out.println(count);
        out.close();
    }

    private static long factorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    private static long comb(int n, int r) {
        if (r > n - r) {
            r = n - r;
        }
        long result = 1;
        for (int i = 0; i < r; i++) {
            result *= (n - i);
            result /= (i + 1);
        }
        return result;
    }

    private static void rec(int mult, int[][][] d, Set<Integer> l, int i, int f, int nn, int s) {
        if (i < nn) {
            for (Triple triple : oplist.get(i)) {
                int add = triple.add;
                int nf = triple.nf;
                long mm = triple.mm;
                int x = s + add;
                int ff = f + nf;
                if (x <= S && ff <= k) {
                    if (add > 0) {
                        l.add(x);
                        d[ff][x][0] += mult * mm;
                    }
                    rec((int) (mult * mm), d, l, i + 1, ff, nn, x);
                }
            }
        }
    }

    static class Pair {
        int first;
        int second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static class Triple {
        int add;
        int nf;
        long mm;

        Triple(int add, int nf, long mm) {
            this.add = add;
            this.nf = nf;
            this.mm = mm;
        }
    }
}

