import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int[] fact = new int[20];
        fact[0] = 1;
        for (int i = 1; i < 20; i++) {
            fact[i] = fact[i - 1] * i;
        }

        int N = scanner.nextInt();
        int K = scanner.nextInt();
        int S = scanner.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = scanner.nextInt();
        }

        Map<Integer, Integer>[][] ldp = new HashMap[2][K + 1];
        Map<Integer, Integer>[][] rdp = new HashMap[2][K + 1];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= K; j++) {
                ldp[i][j] = new HashMap<>();
                rdp[i][j] = new HashMap<>();
            }
        }
        ldp[0][0].put(0, 1);
        rdp[0][0].put(0, 1);

        for (int i = 0; i < N / 2; i++) {
            for (int j = 0; j <= K; j++) {
                ldp[(~i) & 1][j].clear();
            }
            for (int j = 0; j <= K; j++) {
                for (Map.Entry<Integer, Integer> entry : ldp[i & 1][j].entrySet()) {
                    int key = entry.getKey();
                    int value = entry.getValue();
                    ldp[(~i) & 1][j].put(key, ldp[(~i) & 1][j].getOrDefault(key, 0) + value); // toranai
                    ldp[(~i) & 1][j].put(key + A[i], ldp[(~i) & 1][j].getOrDefault(key + A[i], 0) + value); // toru
                    if (j + 1 <= K && A[i] <= 18) {
                        ldp[(~i) & 1][j + 1].put(key + fact[A[i]], ldp[(~i) & 1][j + 1].getOrDefault(key + fact[A[i]], 0) + value); // kaijyou totte toru
                    }
                }
            }
        }

        for (int i = 0; i < N - N / 2; i++) {
            for (int j = 0; j <= K; j++) {
                rdp[(~i) & 1][j].clear();
            }
            for (int j = 0; j <= K; j++) {
                for (Map.Entry<Integer, Integer> entry : rdp[i & 1][j].entrySet()) {
                    int key = entry.getKey();
                    int value = entry.getValue();
                    rdp[(~i) & 1][j].put(key, rdp[(~i) & 1][j].getOrDefault(key, 0) + value);
                    rdp[(~i) & 1][j].put(key + A[N / 2 + i], rdp[(~i) & 1][j].getOrDefault(key + A[N / 2 + i], 0) + value);
                    if (j + 1 <= K && A[N / 2 + i] <= 18) {
                        rdp[(~i) & 1][j + 1].put(key + fact[A[N / 2 + i]], rdp[(~i) & 1][j + 1].getOrDefault(key + fact[A[N / 2 + i]], 0) + value);
                    }
                }
            }
        }

        int ans = 0;
        for (int i = 0; i <= K; i++) {
            for (Map.Entry<Integer, Integer> entry : ldp[N / 2 & 1][i].entrySet()) {
                int key = entry.getKey();
                int value = entry.getValue();
                for (int j = 0; j <= K - i; j++) {
                    ans += value * rdp[(N - N / 2) & 1][j].getOrDefault(S - key, 0);
                }
            }
        }

        System.out.println(ans);
    }
}

