        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int c_a = scanner.nextInt();
        int c_b = scanner.nextInt();

        int n_a = N / a;
        int n_b = N / b;
        int n_ab = N / mmc(a, b);
        n_a -= n_ab;
        n_b -= n_ab;

        int cont = 0;
        cont += n_a * c_a;
        cont += n_b * c_b;
        cont += n_ab * Math.max(c_a, c_b);

        System.out.println(cont);
    }

    public static int gcd(int a, int b) {
        a = Math.max(a, b);
        b = Math.min(a, b);
        while (a % b != 0) {
            int aux = b;
            b = a % b;
            a = aux;
        }
        return b;
    }

    public static int mmc(int a, int b) {
        a = Math.max(a, b);
        b = Math.min(a, b);
        return a * (b / gcd(a, b));
    }
}

