    private static List<Integer> ans = new ArrayList<>();

    public static int maximize(int n, int X, int l) {
        if (l == 0) {
            return 0;
        }
        int cur = ans.get(l - 1);
        X -= Math.pow(cur, 3);
        while (X + Math.pow(cur + 1, 3) <= n) {
            cur++;
        }
        int Xy = (int) Math.pow(cur, 3);
        Xy += maximize(Math.min(n - Xy, (int) Math.pow(cur + 1, 3) - Xy - 1), X, l - 1);
        ans.set(l - 1, cur);
        return Xy;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int c = 1;
        int X = 0;
        while (X + Math.pow(c, 3) <= n) {
            while (X < Math.pow(c + 1, 3) - Math.pow(c, 3) && X + Math.pow(c, 3) <= n) {
                ans.add(c);
                X += Math.pow(c, 3);
            }
            c++;
        }
        X = maximize(n, X, ans.size());
        System.out.println(ans.size() + " " + X);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        int[] result = solve(m, 0, 0);
        System.out.println(result[0] + " " + result[1]);
    }

    public static int[] solve(int m, int cubes, int volume) {
        if (m == 0) {
            return new int[]{cubes, volume};
        }

        int x = 1;
        while (Math.pow(x, 3) <= m) {
            x++;
        }
        x--;

        int[] best = solve(m - (int) Math.pow(x, 3), cubes + 1, volume + (int) Math.pow(x, 3));
        if (x > 1) {
            int[] alternative = solve((int) Math.pow(x, 3) - 1 - (int) Math.pow(x - 1, 3), cubes + 1, volume + (int) Math.pow(x - 1, 3));
            if (alternative[1] > best[1]) {
                best = alternative;
            }
        }

        return best;
    }
}

