public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int l = scanner.nextInt();
        int r = scanner.nextInt();

        String bnry = Integer.toBinaryString(n);
        int[] prefixSum = new int[51];

        if (n == 0) {
            System.out.println(0);
        } else {
            recur(bnry, prefixSum, 1);
            System.out.println(cal(bnry, r, prefixSum, bnry.length()) - cal(bnry, l - 1, prefixSum, bnry.length()));
        }

        scanner.close();
    }

    public static void recur(String bnry, int[] prefixSum, int idx) {
        if (bnry.charAt(0) == '1') {
            prefixSum[idx] = 2 * prefixSum[idx - 1] + 1;
        } else if (bnry.charAt(0) == '0') {
            prefixSum[idx] = 2 * prefixSum[idx - 1];
        }
        bnry = bnry.substring(1);
        if (bnry.length() > 0) {
            recur(bnry, prefixSum, idx + 1);
        }
    }

    public static int cal(String bnry, int num, int[] prefixSum, int idx) {
        if (num == Math.pow(2, idx) - 1) {
            if (bnry.charAt(idx - 1) == '1') {
                return prefixSum[idx - 1] * 2 + 1;
            } else {
                return prefixSum[idx - 1] * 2;
            }
        } else if (num == Math.pow(2, idx - 1)) {
            if (bnry.charAt(idx - 1) == '1') {
                return prefixSum[idx - 1] + 1;
            } else {
                return prefixSum[idx - 1];
            }
        } else if (num == Math.pow(2, idx - 1) - 1) {
            return prefixSum[idx - 1];
        }
        if (num > Math.pow(2, idx - 1)) {
            if (bnry.charAt(idx - 1) == '1') {
                return prefixSum[idx - 1] + 1 + cal(bnry, num - (int)Math.pow(2, idx - 1), prefixSum, idx - 1);
            } else {
                return prefixSum[idx - 1] + cal(bnry, num - (int)Math.pow(2, idx - 1), prefixSum, idx - 1);
            }
        } else if (num < Math.pow(2, idx - 1)) {
            return cal(bnry, num, prefixSum, idx - 1);
        }
        return 0;
    }
}

