import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        int n = reader.nextInt();
        int m = reader.nextInt();
        int a = reader.nextInt();
        int b = reader.nextInt();
        int g = reader.nextInt();
        int x = reader.nextInt();
        int y = reader.nextInt();
        int z = reader.nextInt();

        double zinv = 1.0 / z;

        int[] grid = new int[n * m];
        grid[0] = g;
        for (int i = 1; i < n * m; i++) {
            grid[i] = modMulAdd(grid[i - 1], x, y, z, zinv);
        }

        List<List<Integer>> B = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            B.add(printMin(Arrays.copyOfRange(grid, i * m, (i + 1) * m), m, b));
        }

        long ans = 0;
        for (int i = 0; i < B.get(0).size(); i++) {
            List<Integer> temp = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                temp.add(B.get(j).get(i));
            }
            for (int tmp : printMin(temp.toArray(new Integer[0]), temp.size(), a)) {
                ans += tmp;
            }
        }
        System.out.println(ans);
    }

    private static List<Integer> printMin(int[] arr, int n, int k) {
        List<Integer> res = new ArrayList<>();
        Deque<Integer> Qi = new LinkedList<>();
        for (int i = 0; i < k; i++) {
            while (!Qi.isEmpty() && arr[i] <= arr[Qi.getLast()]) {
                Qi.removeLast();
            }
            Qi.addLast(i);
        }

        for (int i = k; i < n; i++) {
            res.add(arr[Qi.getFirst()]);
            while (!Qi.isEmpty() && Qi.getFirst() <= i - k) {
                Qi.removeFirst();
            }
            while (!Qi.isEmpty() && arr[i] <= arr[Qi.getLast()]) {
                Qi.removeLast();
            }
            Qi.addLast(i);
        }
        res.add(arr[Qi.getFirst()]);
        return res;
    }

    private static int modMulAdd(int x, int y, int c, int z, double zinv) {
        int ans = (int) (x * (long) y + c - z * (zinv * x * y + zinv * c));
        if (ans >= z) {
            return ans - z;
        } else if (ans < 0) {
            return ans + z;
        } else {
            return ans;
        }
    }

    static class FastReader {
        final private int BUFFER_SIZE = 8192;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public FastReader(String file_name) throws IOException {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException {
            byte[] buf = new byte[64]; // line length
            int cnt = 0, c;
            while ((c = read()) != -1) {
                if (c == '\n')
                    break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (neg)
                return -ret;
            return ret;
        }

        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public double nextDouble() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();

            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (c == '.') {
                while ((c = read()) >= '0' && c <= '9') {
                    ret += (c - '0') / (div *= 10);
                }
            }

            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            if (din == null)
                return;
            din.close();
        }
    }
}

