public class Main {
    static int[][] process(int[][] grid, int a, int n, int m) {
        int[][] aux = new int[3000][3000];
        for (int i = 0; i < n; i++) {
            Deque<Integer> mi = new ArrayDeque<>();
            for (int j = 0; j < a; j++) {
                while (!mi.isEmpty() && grid[i][j] < mi.peekLast()) {
                    mi.pollLast();
                }
                mi.offerLast(grid[i][j]);
            }

            aux[0][i] = mi.peekFirst();
            for (int j = a; j < m; j++) {
                if (mi.peekFirst() == grid[i][j - a]) {
                    mi.pollFirst();
                }
                while (!mi.isEmpty() && grid[i][j] < mi.peekLast()) {
                    mi.pollLast();
                }
                mi.offerLast(grid[i][j]);
                aux[j - a + 1][i] = mi.peekFirst();
            }
        }

        return aux;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());

        st = new StringTokenizer(br.readLine());
        long g = Long.parseLong(st.nextToken());
        long x = Long.parseLong(st.nextToken());
        long y = Long.parseLong(st.nextToken());
        long z = Long.parseLong(st.nextToken());

        double zinv = 1.0 / z;

        int[][] grid = new int[3000][3000];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = (int) g;
                g = modMulAdd(g, x, y, z, zinv);
            }
        }

        int[][] aux1 = process(grid, b, n, m);
        int[][] aux2 = process(aux1, a, m - b + 1, n);

        long ans = 0;
        for (int i = 0; i < n - a + 1; i++) {
            for (int j = 0; j < m - b + 1; j++) {
                ans += aux2[i][j];
            }
        }

        System.out.println(ans);
    }

    static long modMulAdd(long x, long y, long c, long z, double zinv) {
        long ans = (long) ((x * y + c) - z * (zinv * x * y + zinv * c));
        if (ans >= z) {
            return ans - z;
        } else if (ans < 0) {
            return ans + z;
        } else {
            return ans;
        }
    }
}

