public class Main {
    private static Map<Integer, Integer> mp = new HashMap<>();

    public static void primeFactor(int a) {
        int i = 2;
        while (i * i <= a) {
            while (a % i == 0) {
                mp.put(i, mp.getOrDefault(i, 0) + 1);
                a /= i;
            }
            i++;
        }
        if (a > 1) {
            mp.put(a, mp.getOrDefault(a, 0) + 1);
        }
    }

    public static int trailingZero(int a, int n) {
        int ans = 0;
        while (n > 0) {
            ans += n / a;
            n /= a;
        }
        return ans;
    }

    public static void main(String[] args) {
