import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {

    public static boolean isGood(int[] f, int p, int k) {
        for (int i = 0; i < p; i++) {
            if (f[(k * i) % p] != (k * f[i]) % p) {
                return false;
            }
        }
        return true;
    }

    public static int gen(int[] f, int p, int k, int i) {
        if (i == p) {
            return isGood(f, p, k) ? 1 : 0;
        } else {
            int ans = 0;
            for (int j = 0; j < p; j++) {
                f[i] = j;
                ans += gen(f, p, k, i + 1);
            }
            return ans;
        }
    }

    public static long solve(int p, int k) {
        int num = 0;
        Set<Integer> used = new HashSet<>();
        for (int j = 0; j < p; j++) {
            if (!used.contains(j)) {
                num++;
            }
            int i = j;
            while (!used.contains(i)) {
                used.add(i);
                i = (i * k) % p;
            }
        }
        return power(p, num - (k != 1 ? 1 : 0), 1000000007);
    }

    public static long power(long base, int exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        System.out.println(solve(p, k));
        scanner.close();
    }
}

