            }
        }

        if (k != 1) cmps--;

        System.out.println(power(p, cmps, MOD));
    }

    private static long power(int base, int exp, int mod) {
        long result = 1;
        long b = base % mod;

        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * b) % mod;
            }
            exp >>= 1;
            b = (b * b) % mod;
        }

        return result;
    }
}

