import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        String d = "0123456789ABCDEFGH";
        Map<Character, Character> prev = new HashMap<>();
        Map<Character, Character> next = new HashMap<>();

        for (int i = 1; i < 18; i++) {
            prev.put(d.charAt(i), d.charAt(i - 1));
        }
        for (int i = 0; i < 17; i++) {
            next.put(d.charAt(i), d.charAt(i + 1));
        }

        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        String n = input[0];
        int m = Integer.parseInt(input[1]);

        char[] p = new char[10];
        for (int i = 0; i < 10; i++) {
            p[i] = '0';
        }
        int k = 1;
        int l = n.length();

        for (char x : n.toCharArray()) {
            p[x - '0'] = next.get(p[x - '0']);
        }

        String a = new String(p);
        Map<String, int[]> u = new HashMap<>();
        Map<String, int[]> v = new HashMap<>();

        u.put(a, new int[m]);
        u.get(a)[0] = 1;

        for (int r = 1; r <= l; r++) {
            if (r == l && n.contains("0")) {
                u.remove("1000000000");
            }
            for (String key : u.keySet()) {
                for (int i = 0; i < 10; i++) {
                    if (key.charAt(i) != '0') {
                        StringBuilder sb = new StringBuilder(key);
                        sb.setCharAt(i, prev.get(key.charAt(i)));
                        String b = sb.toString();
                        if (!v.containsKey(b)) {
                            v.put(b, new int[m]);
                        }
                        int index = (k * i) % m - m;
                        int[] x = v.get(b);
                        int[] y = u.get(key);
                        for (int j = 0; j < m; j++) {
                            x[(j + index + m) % m] += y[j];
                        }
                    }
                }
            }
            u = v;
            v = new HashMap<>();
            k = (10 * k) % m;
        }

        System.out.println(u.get("0000000000")[0]);
    }
}

