import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        long lo, hi;
        if (m < 1000000) {
            lo = m * 4L;
            hi = m * 8L;
        } else {
            lo = (long) (4.949 * m);
            hi = (long) (4.9492 * m);
        }
        while (lo < hi - 1) {
            long mid = (lo + hi) / 2;
            int nposs = countPoss((int) mid);
            if (nposs < m) {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        if (m == countPoss((int) hi)) {
            System.out.println(hi);
        } else {
            System.out.println(-1);
        }
        scanner.close();
    }

    public static int countPoss(int maxTake) {
        int k = 2;
        int ans = 0;
        while (true) {
            int term = maxTake / (k * k * k);
            if (term == 0) {
                return ans;
            }
            ans += term;
            k++;
        }
    }
}

