import java.util.Scanner;

public class Main {
    static final int base = 998244353;

    public static long power(long x, long y) {
        if (y == 0) {
            return 1;
        }
        long t = power(x, y / 2);
        t = (t * t) % base;
        if (y % 2 != 0) {
            t = (t * x) % base;
        }
        return t;
    }

    public static long inverse(long x) {
        return power(x, base - 2);
    }

    public static void main(String[] args) {
        long[] f = new long[5556];
        long[] iv = new long[5556];
        f[0] = 1;
        iv[0] = 1;
        for (int i = 1; i < 5556; i++) {
            f[i] = (f[i - 1] * i) % base;
            iv[i] = inverse(f[i]);
        }

        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int s = scanner.nextInt();
        int r = scanner.nextInt();
        scanner.close();

        long gamesize = countGame(p, s - r, (long) 1e18);
        gamesize = inverse(gamesize);
        long ans = 0;
        for (int q = r; q <= s; q++) {
            for (int i = 0; i < p; i++) { // exactly i people have the same score
                long t = s - (i + 1) * q;
                if (t < 0) {
                    break;
                }
                ans = (ans + C(p - 1, i) * countGame(p - i - 1, t, q) * gamesize * inverse(i + 1)) % base;
            }
        }
        System.out.println(ans);
    }

    public static long C(long n, long k) {
        return (f[(int) n] * iv[(int) k] % base) * iv[(int) (n - k)] % base;
    }

    public static long candy(long n, long k) {
        return C(n + k - 1, k - 1);
    }

    public static long countGame(int k, int n, long x) { // k players, n points total, no player can have x points or more
        if (k == 0) {
            return n == 0 ? 1 : 0;
        }
        long ans = 0;
        for (int i = 0; i <= k; i++) {
            long t = n - x * i;
            if (t < 0) {
                break;
            }
            if (i % 2 != 0) {
                ans = (ans - C(k, i) * candy(t, k)) % base;
            } else {
                ans = (ans + C(k, i) * candy(t, k)) % base;
            }
        }
        return ans;
    }
}

