import java.util.*;

public class Main {
    static BufferedReader br;
    static PrintWriter out;
    static String[] line;
    static int idx;

    static int rrI() throws IOException {
        return Integer.parseInt(next());
    }

    static int[] rrM() throws IOException {
        line = br.readLine().split(" ");
        int[] arr = new int[line.length];
        for (int i = 0; i < line.length; i++) {
            arr[i] = Integer.parseInt(line[i]);
        }
        return arr;
    }

    static boolean goodMask(int x) {
        return x != 0 && ((x + 1) & x) == 0;
    }

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new OutputStreamWriter(System.out));

        int N = rrI();
        String S = br.readLine().trim();

        int[] lenBin = new int[32];
        for (int n = 0; n < 32; n++) {
            lenBin[n] = Integer.toBinaryString(n).length();
        }

        final int MOD = 1_000_000_007;
        int[][] number = new int[N][N + 1];
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j <= N; j++) {
                number[i][j] = Math.min(22, Integer.parseInt(S.substring(i, j), 2));
            }
        }

        final int UPPER = 22;
        Map<Integer, Integer>[] memo = new HashMap[N + 1];
        for (int i = 0; i <= N; i++) {
            memo[i] = new HashMap<>();
        }

        class DP {
            int dp(int i, int mask, int sumToMake, int curMax) {
                if (i == N) {
                    return sumToMake == 0 && mask != 0 ? 1 : 0;
                }
                if (memo[i].containsKey(mask)) {
                    return memo[i].get(mask);
                }
                int ans = sumToMake == 0 && mask != 0 ? 1 : 0;
                for (int j = i + 1; j <= N; j++) {
                    int num = number[i][j];
                    if (num == 0) continue;
                    if (num >= UPPER) break;
                    if (sumToMake > N - j + 5) break;
                    if ((mask & (1 << (num - 1))) != 0) {
                        ans += dp(j, mask, sumToMake, curMax);
                    } else if (num <= curMax) {
                        ans += dp(j, mask | (1 << (num - 1)), sumToMake - lenBin[num], curMax);
                    } else {
                        int sumLen = 0;
                        for (int x = curMax + 1; x < num; x++) {
                            sumLen += lenBin[x];
                        }
                        ans += dp(j, mask | (1 << (num - 1)), sumToMake + sumLen, num);
                    }
                    if (ans >= MOD) {
                        ans %= MOD;
                    }
                }
                memo[i].put(mask, ans);
                return ans;
            }
        }

        DP dpInstance = new DP();
        int fans = 0;
        for (int i = 0; i < N; i++) {
            fans += dpInstance.dp(i, 0, 0, 0);
            fans %= MOD;
        }

        out.println(fans);
        out.close();
    }

    static String next() throws IOException {
        while (line == null || idx >= line.length) {
            line = br.readLine().split(" ");
            idx = 0;
        }
        return line[idx++];
    }
}

