public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int w = scanner.nextInt();
        int b = scanner.nextInt();
        scanner.close();

        final int M = 1000000009;
        long[] p = new long[4011];
        long[] r = new long[4011];
        p[0] = 1;

        for (int i = 0; i < 4010; i++) {
            p[i + 1] = (p[i] * (i + 1)) % M;
            r[i] = power(p[i], M - 2, M);
        }

        long result = 0;
        for (int i = Math.max(1, n - w); i <= Math.min(n - 2, b); i++) {
            result = (result + p[w] * p[b] * (n - i - 1) % M * C(b - 1, i - 1, p, r) % M * C(w - 1, n - i - 1, p, r) % M) % M;
        }

        System.out.println(result);
    }

    private static long C(int n, int m, long[] p, long[] r) {
        return p[n] * r[m] % 1000000009 * r[n - m] % 1000000009;
    }

    private static long power(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if (exp % 2 == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp /= 2;
        }
        return result;
    }
}

