import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int m = scanner.nextInt();

        if (k == 1) {
            System.out.println((9 * modPow(10, n - 1, m)) % m);
            return;
        }
        if (n == 1) {
            int count = 0;
            for (int i = 1; i < 10; i++) {
                if (i % k == 0) {
                    count++;
                }
            }
            System.out.println(count % m);
            return;
        }

        int[] dp = new int[k];
        for (int i = 0; i < 10; i++) {
            if (i % k != 0) {
                dp[i % k]++;
            }
        }

        int t = 10 % k;
        int[][] kk = new int[k][11];
        for (int i = 0; i < k; i++) {
            for (int j = 0; j <= 10; j++) {
                kk[i][j] = (i * j) % k;
            }
        }

        for (int i = 0; i < n - 1; i++) {
            int[] ndp = new int[k];
            for (int j = 1; j < k; j++) {
                for (int l = (i == n - 2 ? 1 : 0); l < 10; l++) {
                    int x = j + kk[t][l];
                    if (x >= k) {
                        x -= k;
                    }
                    if (x > 0) {
                        ndp[x] += dp[j];
                        if (ndp[x] >= m) {
                            ndp[x] -= m;
                        }
                    }
                }
            }
            for (int l = (i == n - 2 ? 1 : 0); l < 10; l++) {
                if (kk[t][l] > 0) {
                    ndp[kk[t][l]]++;
                }
            }
            dp = ndp.clone();
            t = kk[t][10];
        }

        int result = (9 * modPow(10, n - 1, m) - sum(dp) % m + m) % m;
        System.out.println(result);
    }

    private static int modPow(int base, int exp, int mod) {
        int result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }

    private static int sum(int[] array) {
        int sum = 0;
        for (int value : array) {
            sum += value;
        }
        return sum;
    }
}

