public class Main {
    public static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }

    public static void solve(int x, int y, String a, String b) {
        StringBuilder ans = new StringBuilder();
        while (x != 1 || y != 1) {
            if (x < y) {
                int tempX = x;
                x = y;
                y = tempX;
                String tempA = a;
                a = b;
                b = tempA;
            }
            ans.append((x - 1) / y).append(a);
            x = x - ((x - 1) / y) * y;
        }
        System.out.println(ans.toString());
    }

