import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();

        int[] result = ggcd(a, b);
        int y = result[0];
        int x = result[1];
        int d = result[2];

        if (d != 1) {
            System.out.println("Impossible");
            return;
        }

        StringBuilder ans = new StringBuilder();
        x += a;
        int t = (x - 1) / a;
        x -= t * a;
        y += t * b;
        assert 0 < x && x <= a && 0 < y && y <= b;
        gao(x, b - y, a - x, y, ans);
        System.out.println(ans.toString());
    }

    public static int[] ggcd(int a, int b) {
        if (b == 0) {
            return new int[]{1, 0, a};
        } else {
            int[] temp = ggcd(b, a % b);
            int x = temp[0];
            int y = temp[1];
            int d = temp[2];
            return new int[]{y, x - a / b * y, d};
        }
    }

    public static void gao(int a, int b, int c, int d, StringBuilder ans) {
        if (a == 1 && b == 0 && c == 0 && d == 1) return;
        if (a > c) {
            int t = b / d;
            ans.insert(0, t + "B");
            a -= c * t;
            b -= d * t;
            gao(a, b, c, d, ans);
        } else {
            int t = c / a;
            ans.insert(0, t + "A");
            c -= a * t;
            d -= b * t;
            gao(a, b, c, d, ans);
        }
    }
}

