import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = getIntList(scanner);
        int n = input[0], m = input[1], x = input[2], y = input[3], vx = input[4], vy = input[5];

        if (vx == 0) {
            if (x != 0 && x != n) {
                System.out.println(-1);
            } else if (vy == 1) {
                System.out.println(x + " " + m);
            } else {
                System.out.println(x + " " + 0);
            }
        } else if (vy == 0) {
            if (y != 0 && y != m) {
                System.out.println(-1);
            } else if (vx == 1) {
                System.out.println(n + " " + y);
            } else {
                System.out.println(0 + " " + y);
            }
        } else {
            Integer t = solveSystemCongruence(-x * vx, n, -y * vy, m);
            if (t == null) {
                System.out.println(-1);
            } else {
                x = x + t * vx;
                y = y + t * vy;
                x /= n;
                y /= m;
                x %= 2;
                y %= 2;
                x = Math.abs(x);
                y = Math.abs(y);
                System.out.println(x * n + " " + y * m);
            }
        }
    }

    private static int[] getIntList(Scanner scanner) {
        String[] input = scanner.nextLine().split(" ");
        int[] result = new int[input.length];
        for (int i = 0; i < input.length; i++) {
            result[i] = Integer.parseInt(input[i]);
        }
        return result;
    }

    private static int[][] getTransIntList(int n, Scanner scanner) {
        int[] first = getIntList(scanner);
        int m = first.length;
        int[][] result = new int[m][n];
        for (int i = 0; i < m; i++) {
            result[i][0] = first[i];
        }
        for (int j = 1; j < n; j++) {
            int[] curr = getIntList(scanner);
            for (int i = 0; i < m; i++) {
                result[i][j] = curr[i];
            }
        }
        return result;
    }

    private static int[] GCDKoef(int n1, int n2) {
        int k11 = 1, k12 = 0, k21 = 0, k22 = 1;
        while (n2 > 0) {
            int k = n1 / n2;
            int r = n1 % n2;
            n1 = n2;
            n2 = r;
            int tempK11 = k21, tempK12 = k22;
            k21 = k11 - k21 * k;
            k22 = k12 - k22 * k;
            k11 = tempK11;
            k12 = tempK12;
        }
        return new int[]{n1, k11, k12};
    }

    private static Integer solveSystemCongruence(int a1, int n1, int a2, int n2) {
        int[] gcdResult = GCDKoef(n1, n2);
        int d = gcdResult[0], k1 = gcdResult[1], k2 = gcdResult[2];
        if ((a1 - a2) % d != 0) {
            return null;
        }
        int r = a1 % d;
        int x1 = (a1 - r) / d;
        int x2 = (a2 - r) / d;
        int t = r + x1 * n2 * k2 + x2 * n1 * k1;
        int mod = n1 * n2 / d;
        t %= mod;
        if (t < 0) {
            t += mod;
        }
        return t;
    }
}

