import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int x1 = scanner.nextInt();
        int y1 = scanner.nextInt();
        int x2 = scanner.nextInt();
        int y2 = scanner.nextInt();
        scanner.close();

        int A = a * 2;
        int B = b * 2;

        Point rotated1 = rot(x1, y1);
        int X1 = (int) (rotated1.x * 2);
        int Y1 = (int) (rotated1.y * 2);
        List<Point> P1 = cand(X1, Y1, A, B);

        Point rotated2 = rot(x2, y2);
        int X2 = (int) (rotated2.x * 2);
        int Y2 = (int) (rotated2.y * 2);
        List<Point> P2 = cand(X2, Y2, A, B);

        long res = Long.MAX_VALUE;
        for (Point p1 : P1) {
            for (Point p2 : P2) {
                res = Math.min(res, dist(p1, p2, A, B));
            }
        }

        System.out.println(res);
    }

    static Point rot(double x, double y) {
        return new Point(0.5 * x - 0.5 * y, 0.5 * x + 0.5 * y);
    }

    static List<Point> cand(int X, int Y, int A, int B) {
        List<Point> P = new ArrayList<>();
        if (X % B == 0) {
            if (Y % A == 0) {
                P.add(new Point(X - 1, Y - 1));
                P.add(new Point(X - 1, Y + 1));
                P.add(new Point(X + 1, Y - 1));
                P.add(new Point(X + 1, Y + 1));
            } else {
                P.add(new Point(X - 1, Y));
                P.add(new Point(X + 1, Y));
            }
        } else {
            if (Y % A == 0) {
                P.add(new Point(X, Y - 1));
                P.add(new Point(X, Y + 1));
            } else {
                P.add(new Point(X, Y));
            }
        }
        return P;
    }

    static long dist(Point p1, Point p2, int A, int B) {
        System.err.println(p1 + " " + p2);
        int x1 = p1.x / B;
        int y1 = p1.y / A;
        int x2 = p2.x / B;
        int y2 = p2.y / A;
        int dx = Math.abs(x1 - x2);
        int dy = Math.abs(y1 - y2);
        System.err.println("dx: " + dx + "  dy: " + dy);
        return Math.max(dx, dy);
    }

    static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }
}

