import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<List<int[]>> v = new ArrayList<>();
        for (int i = 0; i < 12; i++) {
            v.add(new ArrayList<>());
        }

        String[] str = scanner.nextLine().split(" ");
        int n = Integer.parseInt(str[0]);
        int m = Integer.parseInt(str[1]);
        int k = Integer.parseInt(str[2]);

        for (int i = 0; i < n; i++) {
            scanner.nextLine();
            for (int j = 0; j < m; j++) {
                String[] tupleStr = scanner.nextLine().split(" ");
                int[] tuple = {Integer.parseInt(tupleStr[0]), Integer.parseInt(tupleStr[1]), Integer.parseInt(tupleStr[2])};
                v.get(i).add(tuple);
            }
        }

        int mx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                int val = 0;
                List<int[]> pro = new ArrayList<>();
                for (int kk = 0; kk < v.get(i).size(); kk++) {
                    if (v.get(j).get(kk)[1] <= v.get(i).get(kk)[0]) continue;
                    pro.add(new int[]{v.get(j).get(kk)[1] - v.get(i).get(kk)[0], v.get(i).get(kk)[2]});
                }

                int lim = k;
                Collections.sort(pro, new Comparator<int[]>() {
                    @Override
                    public int compare(int[] o1, int[] o2) {
                        return Integer.compare(o2[0], o1[0]);
                    }
                });

                for (int kk = 0; kk < pro.size(); kk++) {
                    if (pro.get(kk)[1] <= lim) {
                        lim -= pro.get(kk)[1];
                        val += pro.get(kk)[0] * pro.get(kk)[1];
                    } else {
                        val += pro.get(kk)[0] * lim;
                        break;
                    }
                }

                mx = Math.max(mx, val);
            }
        }

        System.out.println(mx);
    }
}

