import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int T = scanner.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = scanner.nextInt();
        }

        if (sum(A) > N / 2) {
            for (int i = 0; i < N; i++) {
                A[i] = 1 - A[i];
            }
            reverseArray(A);
        }

        int K = sum(A);
        int S = sumLastKElements(A, K);
        int M = K + 1;
        int P = 1000000007;
        long inv = modInverse(N * (N - 1) / 2, P);

        long[][] X = new long[M][M];
        for (int i = 0; i < M; i++) {
            if (i > 0) {
                X[i - 1][i] = (((K - i + 1) * (K - i + 1)) % P * inv) % P;
            }
            if (i < M - 1) {
                X[i + 1][i] = (((N - 2 * K + i + 1) % P * (i + 1) % P) * inv) % P;
            }
            X[i][i] = (1 - (((K - i) * (K - i)) % P * inv) - ((N - 2 * K + i) % P * i % P * inv) + P) % P;
        }

        X = matrixPower(X, T, P);

        System.out.println(X[S][K]);
    }

    private static int sum(int[] array) {
        int sum = 0;
        for (int value : array) {
            sum += value;
        }
        return sum;
    }

    private static int sumLastKElements(int[] array, int K) {
        int sum = 0;
        for (int i = Math.max(0, array.length - K); i < array.length; i++) {
            sum += array[i];
        }
        return sum;
    }

    private static void reverseArray(int[] array) {
        int left = 0;
        int right = array.length - 1;
        while (left < right) {
            int temp = array[left];
            array[left] = array[right];
            array[right] = temp;
            left++;
            right--;
        }
    }

    private static long modInverse(long a, long m) {
        long m0 = m;
        long y = 0, x = 1;
        if (m == 1) return 0;
        while (a > 1) {
            long q = a / m;
            long t = m;
            m = a % m;
            a = t;
            t = y;
            y = x - q * y;
            x = t;
        }
        if (x < 0) x += m0;
        return x;
    }

    private static long[][] matrixPower(long[][] base, int exp, int mod) {
        long[][] result = new long[base.length][base.length];
        for (int i = 0; i < base.length; i++) {
            result[i][i] = 1;
        }
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = multiplyMatrices(result, base, mod);
            }
            base = multiplyMatrices(base, base, mod);
            exp >>= 1;
        }
        return result;
    }

    private static long[][] multiplyMatrices(long[][] A, long[][] B, int mod) {
        int n = A.length;
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod;
                }
            }
        }
        return C;
    }
}

