        ans = ans * (t / lcm + 1);
        ans -= 1;
        int lastNum = t / lcm * lcm;
        ans -= Math.max(0, lastNum + Math.min(w, b) - 1 - t);
        int den = t;

        int gcdAnsDen = gcd(ans, den);
