        int[] lis = new int[n];
        for (int i = 0; i < n; i++) {
            lis[i] = scanner.nextInt();
        }
        Arrays.sort(lis);

        int l = 1;
        int r = n;
        while (l <= r) {
            int mid = l + (r - l) / 2;
