import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static List<Integer> d_a = new ArrayList<>();
    static List<Integer> d_b = new ArrayList<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        scanner.close();

        for (int i = 1; i <= Math.sqrt(a); i++) {
            if (a % i == 0) d_a.add(i);
        }
        for (int i = 1; i <= Math.sqrt(b); i++) {
            if (b % i == 0) d_b.add(i);
        }

        System.out.println(solve(a, b));
    }

    public static int solve(int a, int b) {
        int n = a + b;
        int ans = (1 + n) << 1;

        for (int i = 1; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                int idx_a = binarySearchRight(d_a, i);
                int idx_b = binarySearchRight(d_b, i);
                int x_a = d_a.get(idx_a - 1);
                int x_b = d_b.get(idx_b - 1);
                if ((a / x_a <= n / i) || (b / x_b <= n / i)) {
                    ans = Math.min(ans, (i + n / i) << 1);
                }
            }
        }

        return ans;
    }

    public static int binarySearchRight(List<Integer> list, int key) {
        int low = 0;
        int high = list.size();
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (list.get(mid) > key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

