import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        int[] counts = IntStream.range(0, 10)
                                .map(i -> (int) s.chars().filter(ch -> ch == ('0' + i)).count())
                                .toArray();

        List<Integer>[] ranges = new List[10];
        for (int i = 0; i < 10; i++) {
            ranges[i] = IntStream.rangeClosed(counts[i] / Math.max(counts[i], 1), counts[i])
                                 .boxed()
                                 .collect(Collectors.toList());
        }

        List<List<Integer>> products = cartesianProduct(ranges);

        double result = products.stream()
                              .mapToDouble(x -> (factorial(sum(x)) - factorial(sum(x) - 1) * x.get(0)) / (double) factorial(product(factorial(x))))
                              .sum();

        System.out.println(result);
    }

    private static long factorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    private static int sum(List<Integer> list) {
        return list.stream().mapToInt(Integer::intValue).sum();
    }

    private static long product(List<Long> list) {
        return list.stream().reduce(1L, (a, b) -> a * b);
    }

    private static List<List<Integer>> cartesianProduct(List<Integer>[] lists) {
        List<List<Integer>> result = new ArrayList<>();
        if (lists.length > 0) {
            cartesianProduct(0, lists, new ArrayList<>(), result);
        }
        return result;
    }

    private static void cartesianProduct(int depth, List<Integer>[] lists, List<Integer> current, List<List<Integer>> result) {
        if (depth == lists.length) {
            result.add(new ArrayList<>(current));
        } else {
            for (Integer item : lists[depth]) {
                current.add(item);
                cartesianProduct(depth + 1, lists, current, result);
                current.remove(current.size() - 1);
            }
        }
    }
}

