        if (b == 1) {
            return 1;
        }
        Set<Integer> used = new HashSet<>();
        used.add(1);
        used.add(b);
        for (int i = 2; i <= Math.sqrt(b) + 1; i++) {
            if (b % i == 0) {
                used.add(i);
                used.add(b / i);
            }
        }
        return used.size();
    }
}

