        int W = scanner.nextInt();
        int[] M = new int[8];
        for (int i = 0; i < 8; i++) {
            M[i] = scanner.nextInt();
        }
        int[] A = new int[8];
        long sTime = System.currentTimeMillis();

        int s = 0;
        int mi = (int) 1e20;
        for (int i = 0; i < 8; i++) {
            if (s + M[i] * (i + 1) <= W) {
