    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        int[] a = new int[3];
        for (int i = 0; i < "BSC".length(); i++) {
            a[i] = countOccurrences(s, "BSC".charAt(i));
        }

        int[] n = readIntArray(scanner);
        int[] p = readIntArray(scanner);
        int S = scanner.nextInt();

        int l = 0, r = S + getMax(n);
        while (l < r) {
            int m = (l + r) / 2 + 1;
            if (check(m, n, p, a, S)) {
                l = m;
            } else {
                r = m - 1;
            }
        }
        System.out.println(l);
    }

    private static int countOccurrences(String str, char ch) {
        int count = 0;
        for (char c : str.toCharArray()) {
            if (c == ch) {
                count++;
            }
        }
        return count;
    }

    private static int[] readIntArray(Scanner scanner) {
        String[] line = scanner.nextLine().split(" ");
        int[] array = new int[line.length];
        for (int i = 0; i < line.length; i++) {
            array[i] = Integer.parseInt(line[i]);
        }
        return array;
    }

    private static boolean check(int x, int[] n, int[] p, int[] a, int S) {
        int sum = 0;
        for (int i = 0; i < 3; i++) {
            sum += Math.max(p[i] * (a[i] * x - n[i]), 0);
        }
        return sum <= S;
    }

    private static int getMax(int[] array) {
        int max = array[0];
        for (int value : array) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }
}

