        int[] q = new int[z];
        boolean[] w = new boolean[z];
        Arrays.fill(w, true);
        int o = 0, po = 0;

        for (int i = 0; i < z; i++) {
            if (w[i]) {
                w[i] = false;
                q[po++] = i;
                int poi = o;
                int e = 0;
                Set<Integer> xs = new HashSet<>();
                Set<Integer> ys = new HashSet<>();

                while (o < po) {
                    int v = q[o++];
                    int[] s = a[v];

                    if (xs.add(s[0])) {
                        e--;
                        for (int u : x.get(s[0])) {
                            e++;
                            if (w[u]) {
                                w[u] = false;
                                q[po++] = u;
                            }
                        }
                    }

                    if (ys.add(s[1])) {
