                int vc = o - poi;
                if (vc - 1 == e) {
                    r = (r * (modPow(2, vc + 1, qwe) - 1)) % qwe;
                } else {
                    r = (r * modPow(2, xs.size() + ys.size(), qwe)) % qwe;
                }
            }
        }
        System.out.println(r);
    }

    private static long modPow(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
