    public static long exp(long a, long p, long m) {
        if (p == 0) {
            return 1;
        } else if (p == 1) {
            return a;
        } else if (p % 2 == 0) {
            long x = exp(a, p >> 1, m);
            return (x * x) % m;
        } else {
            return (a * exp(a, p - 1, m)) % m;
        }
