    static int size_m;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        String[] firstLine = scanner.nextLine().strip().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);

        String[] secondLine = scanner.nextLine().strip().split(" ");
        int xs = Integer.parseInt(secondLine[0]);
        int ys = Integer.parseInt(secondLine[1]);
        String direction = secondLine[2];

        size_n = n;
        size_m = m;
        int[] dir = getDirection(direction);
        int down = dir[0];
        int right = dir[1];
        int[] turn = turnInside(n, m, xs, ys, down, right);
        down = turn[0];
        right = turn[1];

        Map<String, Integer> visitedPoints = new HashMap<>();
        int totalToCheck = totalBlackBoundCells(n, m);
        visitedPoints.put(xs + "," + ys, 1);
        totalToCheck--;

        int x = xs;
        int y = ys;
        int dye = 1;

        while (totalToCheck > 0) {
            int[] path = findPath(x, y, down, right);
            int xn = path[0];
            int yn = path[1];
            down = path[2];
            right = path[3];
            dye += movesCount(x, y, xn, yn);
            x = xn;
            y = yn;

            String pointKey = x + "," + y;
            if (!visitedPoints.containsKey(pointKey)) {
                visitedPoints.put(pointKey, 1);
                totalToCheck--;
            } else if (visitedPoints.get(pointKey) == 1) {
                visitedPoints.put(pointKey, visitedPoints.get(pointKey) + 1);
            } else {
                System.out.println(-1);
                return;
            }
        }
        System.out.println(dye);
    }

    static int sg(int p) {
        return (p == 0) ? -1 : 1;
    }

    static int[] minim(int w, int h) {
        if (w < h) {
            return new int[]{w, 0};
        } else {
            return new int[]{h, 1};
        }
    }

    static int[] findPath(int x, int y, int down, int right) {
        int h = (down == 1) ? size_n - x : x - 1;
        int w = (right == 1) ? size_m - y : y - 1;
        int[] minimum = minim(w, h);
        int p = minimum[0];
        int ansX = x + p * sg(down);
        int ansY = y + p * sg(right);

        if (ansX == 1) {
            down = 1;
        }
        if (ansY == 1) {
            right = 1;
        }
        if (ansX == size_n) {
            down = 0;
        }
        if (ansY == size_m) {
            right = 0;
        }
        return new int[]{ansX, ansY, down, right};
    }

    static int totalBlackBoundCells(int n, int m) {
        return n + m - 2;
    }

    static int movesCount(int x, int y, int xn, int yn) {
        return Math.abs(x - xn);
    }

    static int[] getDirection(String direction) {
        switch (direction) {
            case "UL":
                return new int[]{0, 0};
            case "UR":
                return new int[]{0, 1};
            case "DL":
                return new int[]{1, 0};
            case "DR":
                return new int[]{1, 1};
            default:
                return new int[]{0, 0}; // Default case, should not happen
        }
    }

    static int[] turnInside(int n, int m, int xs, int ys, int down, int right) {
        if (xs == 1) {
            down = 1;
        }
        if (ys == 1) {
            right = 1;
        }
        if (xs == n) {
            down = 0;
        }
        if (ys == m) {
            right = 0;
        }
        return new int[]{down, right};
    }
}

