import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static long[] K = new long[1000];
    private static Map<String, Long> M = new HashMap<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Initialize K array
        K[0] = 1;
        for (int i = 1; i < 1000; i++) {
            K[i] = i * K[i - 1];
        }

        int n = scanner.nextInt();
        int[] d = new int[n];
        for (int i = 0; i < n; i++) {
            d[i] = scanner.nextInt();
        }

        int x = 0;
        int y = 0;

        for (int i = 0; i < n; i++) {
            if (d[i] == 1) {
                x++;
            }
            if (d[i] == 2) {
                y++;
            }
        }

        System.out.println(F(y, x));
    }

    private static long F(int a, int b) {
        if (a == 0 && b == 0) {
            return 1;
        }
        if (b == 0) {
            return K[a];
        }
        String key = a + "," + b;
        if (M.containsKey(key)) {
            return M.get(key);
        }
        long t = 0;
        if (a > 0) {
            t += a * F(a - 1, b);
        }
        t += F(a, b - 1);
        if (b > 1) {
            long k = b - 1;
            for (int i = 0; i <= a; i++) {
                t += k * F(a - i, b - 2);
                k *= (a - i);
            }
        }
        M.put(key, t);
        return t;
    }
}

