import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int[] l = new int[29];

        for (int i = 0; i < 19; i++) {
            int e = nine(19 - i);
            l[i] = k / e;
            k -= l[i] * e;

            if (k == 0) {
                break;
            }
            if (i == 18 || k % e > prosh(19 - i - 1)) {
                l[i]++;
                break;
            }
        }

        int otv = 0;
        for (int i = 0; i < 19; i++) {
            otv += Math.pow(10, 19 - i) * l[i];
        }

        System.out.println(Math.max(n - otv + 1, 0));
    }

    public static int nine(int p) {
        StringBuilder s = new StringBuilder();
        for (int i = 0; i < p; i++) {
            s.append('9');
        }
        return Integer.parseInt(s.toString());
    }

    public static int prosh(int p) {
        int ans = 0;
        for (int i = 1; i <= p; i++) {
            ans += nine(i) * 9;
        }
        return ans;
    }
}

