            f1[i] = (int) ((long) f1[i - 1] * i % M);
        }
        int[] f2 = new int[N + 1];
        f2[0] = 1;
        for (int i = 1; i <= N; i++) {
            f2[i] = (int) ((long) f2[i - 1] * iv[i] % M);
        }
        int left = m % n;

        int[][] c = new int[2][n + 1];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= n; j++) {
                c[i][j] = powM((int) ((long) f1[n] * f2[j] % M * f2[n - j] % M), m / n + i);
            }
        }

        int[][] dp = new int[n + 1][k + 1];
        dp[0][0] = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= k; j++) {
                if (j > i * n || j < k - (n - i) * n) {
                    continue;
                }
                for (int l = 0; l <= Math.min(n, k - j); l++) {
                    dp[i + 1][j + l] = (dp[i + 1][j + l] + (int) ((long) c[i < left ? 1 : 0][l] * dp[i][j] % M)) % M;
                }
            }
        }
        System.out.println(dp[n][k]);
    }

    public static int powM(int b, int p) {
        int r = 1;
        while (p > 0) {
            if (p % 2 > 0) {
                r = (int) ((long) r * b % (int) (1e9 + 7));
            }
            b = (int) ((long) b * b % (int) (1e9 + 7));
            p /= 2;
        }
        return r;
    }
}

