import java.util.Set;

public class Main {
    private static Set<Integer> st = new HashSet<>();

    public static int debin(String s) {
        int ret = 0;
        int mn = 1;
        for (int i = s.length() - 1; i >= 0; i--) {
            ret += (s.charAt(i) - '0') * mn;
            mn *= 2;
        }
        return ret;
    }

    public static boolean ch(int x, int y, int deep) {
        if (st.contains(x)) {
