public class Main {
    static final long INF = 10000000000L;
    static final String YES = "YES";
    static final String NO = "NO";
    static Set<Long> ng = new HashSet<>();

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        long X = Long.parseLong(input[0]);
        long Y = Long.parseLong(input[1]);
        System.out.println(solve(X, Y));
    }

    static boolean dfs(String s, String SY) {
        if (s.equals(SY)) {
            return true;
        }
        long n = Long.parseLong(s);
        if (ng.contains(n)) {
            return false;
        }
        if (s.length() > 100) {
            return false;
        }
        ng.add(n);
        for (String s1 : new String[]{new StringBuilder(s).reverse().toString(), new StringBuilder(s + "1").reverse().toString()}) {
            if (ng.contains(Long.parseLong(s1))) {
                continue;
            }
            if (dfs(s1, SY)) {
                return true;
            }
        }
        return false;
    }

    static String solve(long X, long Y) {
        if (X == Y) {
            return YES;
        }
        String SX = Long.toBinaryString(X);
        String SY = Long.toBinaryString(Y);

        if (dfs(SX, SY)) {
            return YES;
        }

        return NO;
    }
}

