        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) {
                    break;
                }
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(p);
            }
        }
    }

    private static Map<Integer, Integer> factor(int n) {
        Map<Integer, Integer> d = new HashMap<>();
        for (int p : primes) {
            if (p * p > n) {
                break;
            }
            if (n % p == 0) {
                int c = 0;
                while (n % p == 0) {
                    n /= p;
                    c++;
                }
                d.put(p, c);
            }
        }
        if (n > 1) {
            d.put(n, 1);
        }
        return d;
    }

    private static List<Integer> factors(int n) {
        Map<Integer, Integer> d = factor(n);
        List<Integer> answer = new ArrayList<>();
        answer.add(1);
        for (int p : d.keySet()) {
            List<Integer> a2 = new ArrayList<>();
            for (int x : answer) {
                for (int i = 0; i <= d.get(p); i++) {
                    a2.add(x * (int) Math.pow(p, i));
                }
            }
            answer = a2;
        }
        return answer;
    }

    private static int process(int n, int m) {
        Map<Integer, Integer> fDict = new HashMap<>();
        fDict.put(0, 0);
        fDict.put(1, 1);
        fDict.put(2, 2);
        for (int i = 3; i <= n; i++) {
            fDict.put(i, 2 * fDict.get(i - 1));
            for (int x : factors(i)) {
                if (2 <= x && x <= i) {
                    fDict.put(i, (fDict.get(i) + fDict.get(i / x) - fDict.get((i - 1) / x)) % m);
                }
            }
            fDict.put(i, fDict.get(i) % m);
        }
        return fDict.get(n);
    }
}

