import java.util.Scanner;

public class Main {
    static final int N = 200001;
    static final int MOD = 1000000007;
    static long[] fact = new long[N];
    static long[] invFact = new long[N];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int f = scanner.nextInt();
        int w = scanner.nextInt();
        int h = scanner.nextInt();
        int n = f + w;

        preProcess(n);

        long q = nCr(n, w);
        long p = 0;

        for (int i = 0; i <= w; i++) {
            if (i * (h + 1) > w) {
                break;
            } else {
                p += (beggar(w - i * (h + 1), i) * ((beggar(f - i - 1, i + 1) + beggar(f - i + 1, i - 1) + 2 * beggar(f - i, i)) % MOD)) % MOD;
                p %= MOD;
            }
        }

        q = modInverse(q);
        long ans = (p * q) % MOD;

        System.out.println(ans);
    }

    static long modExp(long a, long n) {
        long ans = 1;
        while (n > 0) {
            if (n % 2 == 1) {
                ans = (ans * a) % MOD;
            }
            a = (a * a) % MOD;
            n /= 2;
        }
        return ans;
    }

    static long modInverse(long a) {
        return modExp(a, MOD - 2);
    }

    static void preProcess(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (i * fact[i - 1]) % MOD;
        }

        invFact[n] = modInverse(fact[n]);
        for (int i = n - 1; i > 0; i--) {
            invFact[i] = ((i + 1) * invFact[i + 1]) % MOD;
        }
    }

    static long nCr(int n, int r) {
        if (n < 0 || r < 0 || n < r) {
            return 0;
        } else {
            return (fact[n] * (invFact[r] * invFact[n - r] % MOD)) % MOD;
        }
    }

    static long beggar(int m, int n) {
        if (m < 0 || n < 0 || (n == 0 && m != 0)) {
            return 0;
        } else {
            if (m + n == 0) {
                return 1;
            } else {
                return nCr(m + n - 1, m);
            }
        }
    }
}

