        Scanner scanner = new Scanner(System.in);
        BigDecimal x = new BigDecimal(scanner.next());
        BigDecimal y = new BigDecimal(scanner.next());
        BigDecimal z = new BigDecimal(scanner.next());

        List<Pair> pairs = new ArrayList<>();
        pairs.add(new Pair(negLn(x).multiply(y.pow(z.intValueExact())), "x^y^z"));
        pairs.add(new Pair(negLn(x).multiply(z.pow(y.intValueExact())), "x^z^y"));
        pairs.add(new Pair(negLn(x).multiply(y.multiply(z)), "(x^y)^z"));
        pairs.add(new Pair(negLn(y).multiply(x.pow(z.intValueExact())), "y^x^z"));
        pairs.add(new Pair(negLn(y).multiply(z.pow(x.intValueExact())), "y^z^x"));
        pairs.add(new Pair(negLn(y).multiply(x.multiply(z)), "(y^x)^z"));
        pairs.add(new Pair(negLn(z).multiply(x.pow(y.intValueExact())), "z^x^y"));
        pairs.add(new Pair(negLn(z).multiply(y.pow(x.intValueExact())), "z^y^x"));
        pairs.add(new Pair(negLn(z).multiply(x.multiply(y)), "(z^x)^y"));

        Collections.sort(pairs, Comparator.comparing(Pair::getValue));

        System.out.println(pairs.get(0).getName());
