        int n = scanner.nextInt();
        int s = scanner.nextInt() - 1;
        int k = scanner.nextInt();

        int[][] a = new int[n][3];
        for (int i = 0; i < n; i++) {
            a[i][0] = scanner.nextInt();
        }

        String colors = scanner.next();
        for (int i = 0; i < n; i++) {
            a[i][2] = "RGB".indexOf(colors.charAt(i));
        }

        Arrays.sort(a, Comparator.comparingInt(x -> x[0]));

        Long[][] dp = new Long[n][2001];
        long r = Long.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            int c = a[i][0];
            dp[i][c] = Math.abs(s - a[i][1]);

            for (int j = 0; j < i; j++) {
                if (a[j][2] == a[i][2] || a[j][0] == a[i][0]) {
