import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int T = scanner.nextInt();
        List<List<Integer>> A = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            List<Integer> row = Arrays.asList(scanner.nextInt(), scanner.nextInt());
            A.add(row);
        }

        int s = 0;
        for (int i = 1; i <= N; i++) {
            List<List<List<Integer>>> comb = combinations(A, i);
            for (List<List<Integer>> x : comb) {
                if (column(x, 0).stream().mapToInt(Integer::intValue).sum() == T) {
                    int a = Collections.frequency(column(x, 1), 1);
                    int b = Collections.frequency(column(x, 1), 2);
                    int c = Collections.frequency(column(x, 1), 3);
                    s += (out1(a, b, c) + out2(a, b, c) + out3(a, b, c));
                    s %= 1000000007;
                }
            }
        }
        System.out.println(s);
    }

    private static List<List<List<Integer>>> combinations(List<List<Integer>> list, int length) {
        List<List<List<Integer>>> result = new ArrayList<>();
        combinationsHelper(list, length, 0, new ArrayList<>(), result);
        return result;
    }

    private static void combinationsHelper(List<List<Integer>> list, int length, int start, List<List<Integer>> current, List<List<List<Integer>>> result) {
        if (current.size() == length) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int i = start; i < list.size(); i++) {
            current.add(list.get(i));
            combinationsHelper(list, length, i + 1, current, result);
            current.remove(current.size() - 1);
        }
    }

    private static List<Integer> column(List<List<Integer>> matrix, int index) {
        List<Integer> result = new ArrayList<>();
        for (List<Integer> row : matrix) {
            result.add(row.get(index));
        }
        return result;
    }

    private static int out1(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0) return 0;
        if (a == 1 && b == 0 && c == 0) return 1;
        return a * (out2(a - 1, b, c) + out3(a - 1, b, c));
    }

    private static int out2(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0) return 0;
        if (a == 0 && b == 1 && c == 0) return 1;
        return b * (out1(a, b - 1, c) + out3(a, b - 1, c));
    }

    private static int out3(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0) return 0;
        if (a == 0 && b == 0 && c == 1) return 1;
        return c * (out2(a, b, c - 1) + out1(a, b, c - 1));
    }
}

