import java.util.Scanner;

public class Main {
    static final int MOD = (int) (1e9 + 7);
    static int[][] f = new int[60][60];
    static int[][] g = new int[60][60];
    static int[][] s = new int[60][60];
    static int[] inv = new int[61];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        f[0][0] = s[0][0] = 1;
        inv[1] = 1;

        for (int i = 1; i <= n; i++) {
            inv[i] = pow(i, MOD - 2);
        }

        for (int node = 1; node <= n; node++) {
            for (int cut = 1; cut <= n; cut++) {
                int tmp = 0;
                for (int ln = 0; ln < node; ln++) {
                    for (int lc = cut - 1; lc <= n; lc++) {
                        if (f[ln][lc] == 0) continue;
                        if (lc == cut - 1) {
                            tmp = (tmp + (long) f[ln][lc] * s[node - ln - 1][cut - 1]) % MOD;
                        } else {
                            tmp = (tmp + (long) f[ln][lc] * f[node - ln - 1][cut - 1]) % MOD;
                        }
                    }
                }
                int cnt = 1;
                if (tmp != 0) {
                    int cn = 0, cc = 0;
                    for (int i = 1; i <= n; i++) {
                        cn += node;
                        cc += cut;
                        cnt = (int) (((long) cnt * (tmp + i - 1) % MOD) * inv[i] % MOD);
                        if (cn > n || cc > n) break;
                        for (int j = n - cn; j >= 0; j--) {
                            for (int k = n - cc; k >= 0; k--) {
                                if (f[j][k] == 0) continue;
                                g[j + cn][k + cc] += (long) f[j][k] * cnt % MOD;
                                g[j + cn][k + cc] %= MOD;
                            }
                        }
                    }
                    for (int i = 0; i <= n; i++) {
                        for (int j = 0; j <= n; j++) {
                            f[i][j] = (f[i][j] + g[i][j]) % MOD;
                            g[i][j] = 0;
                        }
                    }
                }
            }
            for (int cut = n; cut >= 0; cut--) {
                s[node][cut] = (s[node][cut + 1] + f[node][cut]) % MOD;
            }
        }
        System.out.println(f[n][m - 1]);
    }

    static int pow(int x, int exp) {
        int res = 1;
        for (int i = 0; i < 31; i++) {
            if ((exp & 1) != 0) {
                res = (int) ((long) res * x % MOD);
            }
            exp >>= 1;
            if (exp == 0) break;
            x = (int) ((long) x * x % MOD);
        }
        return res;
    }
}

