        long g = result[0];
        long x = result[1];
        long y = result[2];

        if ((b2 - b1) % g != 0) {
            System.out.println(0);
        } else {
            x = x * ((b2 - b1) / g);
            y = y * ((b2 - b1) / g);
            long li1 = Math.max(upw(-x * g, a2), upw(y * g, a1));
            long li2 = upw((l - a1 * x - b1) * g, a1 * a2);
            long ls = dwn((r - a1 * x - b1) * g, a1 * a2);
            long li = Math.max(li1, li2);

            if (li > ls) {
                System.out.println(0);
            } else {
                System.out.println(ls - li + 1);
            }
        }
    }

    public static long upw(long a, long b) {
        if (a > 0) return (a + b - 1) / b;
        a = -a;
        return -(a / b);
    }

    public static long dwn(long a, long b) {
        if (a > 0) return a / b;
        a = -a;
        return -(long) ((a + b - 1) / b);
    }

    public static long[] xgcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] result = xgcd(b, a % b);
        long g = result[0];
        long x1 = result[1];
        long y1 = result[2];
        return new long[]{g, y1, x1 - (a / b) * y1};
    }
}

