        for (int i = 1; i <= n; i++) {
            int j = Math.min(i, k);
            while (j > 0) {
                C[j] = (C[j] + C[j - 1]) % MOD;
                j--;
            }
        }
        return C[k];
    }

    static long power(int x, int y, int p) {
        long res = 1;
        x = x % p;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = (res * x) % p;
            }
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }
}

