        } else if (p == 9) {
            if (n >= a[9]) {
                dp[n][p] = 1;
            } else {
                dp[n][p] = 0;
            }
        } else if (p == 0) {
            long ans = 0;
            for (int i = a[0]; i < n; i++) {
                long z = solve(n - i, 1);
                z *= factorial(n - 1).divide(factorial(i)).divide(factorial(n - 1 - i));
                ans += z;
            }
            dp[n][p] = (int) (ans % MOD);
        } else {
            long ans = 0;
            for (int i = a[p]; i <= n; i++) {
                long z = solve(n - i, p + 1);
                z *= factorial(n).divide(factorial(i)).divide(factorial(n - i));
                ans += z;
            }
            dp[n][p] = (int) (ans % MOD);
        }
        return dp[n][p];
    }

    static BigInteger factorial(int num) {
        BigInteger result = BigInteger.ONE;
        for (int factor = 2; factor <= num; factor++) {
            result = result.multiply(BigInteger.valueOf(factor));
        }
        return result;
    }
}

