        System.out.println(getAnswer(n));
    }

    public static int getAnswer(int n) {
        if (n < 5) {
            return (n * (n - 1)) / 2;
        } else if (nine.contains(2 * n - 1)) {
            return 1;
        } else if (nine.contains(n)) {
            return (n - 1) / 2;
        }

        String strN = Integer.toString(n);
        int lenN = strN.length();
        int len2N = Integer.toString(2 * n - 1).length();

        if (lenN == len2N) { // n < 50..0
            // pattern: A9..9, |9..9| = |n| - 1
            String suf = "9".repeat(lenN - 1);
            int k = Integer.parseInt(suf);
            int res = 0;
            for (int c = 0; c < 10; c++) {
                if (Integer.parseInt(c + suf) <= 2 * n - 1) {
                    if (Integer.parseInt(c + suf) <= n) {
                        for (int i = 0; i <= c / 2; i++) {
                            if (i == c - i) {
                                if (i == 0) { // (0, 0): 01 -> 49
                                    res += (k - 1) / 2;
                                } else { // (1, 1): 00 -> 49
                                    res += (k + 1) / 2;
                                }
                            } else {
                                if (i == 0) { // (0, 1): 01 -> 99
                                    res += k;
                                } else { // (1, 2): 00 -> 99
                                    res += k + 1;
                                }
                            }
                        }
                    } else {
                        for (int i = 0; i <= c / 2; i++) {
                            if (i > Character.getNumericValue(strN.charAt(0)) || c - i > Character.getNumericValue(strN.charAt(0))) {
                                continue;
                            } else if (i < Character.getNumericValue(strN.charAt(0)) && c - i < Character.getNumericValue(strN.charAt(0))) {
                                if (i == c - i) {
                                    if (i == 0) { // (0, 0): 01 -> 49
                                        res += (k - 1) / 2;
                                    } else { // (1, 1): 00 -> 49
                                        res += (k + 1) / 2;
                                    }
                                } else {
                                    if (i == 0) { // (0, 1): 01 -> 99
                                        res += k;
                                    } else { // (1, 2): 00 -> 99
                                        res += k + 1;
                                    }
                                }
                            } else {
                                if (i != c - i) {
                                    res += n - Character.getNumericValue(strN.charAt(0)) * (k + 1) + 1;
                                } else {
