public class Main {

    public static int powmod(int a, int b, int m) {
        a %= m;
        int r = 1;
        while (b > 0) {
            if ((b & 1) != 0) {
                r = (int)(((long)r * a) % m);
            }
            a = (int)(((long)a * a) % m);
            b >>= 1;
        }
        return r;
    }

    public static List<int[]> f(int n) {
        List<int[]> r = new ArrayList<>();
        if ((n & 1) == 0) {
            int e = 0;
            while ((n & 1) == 0) {
                n >>= 1;
                e++;
            }
            r.add(new int[]{2, e});
        }
        int p = 3;
        while (n > 1) {
            if (p * p > n) {
                p = n;
            }
            if (n % p != 0) {
                p += 2;
                continue;
            }
            int e = 1;
            n /= p;
            while (n % p == 0) {
                n /= p;
                e++;
            }
            r.add(new int[]{p, e});
            p += 2;
        }
        return r;
    }

    public static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        int x = scanner.nextInt();
        int p = 2;
        List<int[]> r = new ArrayList<>();
        r.add(new int[]{1, 1});
        for (int[] pair : f(m)) {
            int e = pair[1];
            int ord = pair[0] - 1;
            for (int[] piEiPair : f(ord)) {
                int pi = piEiPair[0];
                while (ord % pi == 0 && powmod(x, ord / pi, pair[0]) == 1) {
                    ord /= pi;
                }
            }
            List<int[]> ords = new ArrayList<>();
            ords.add(new int[]{1, 1});
            ords.add(new int[]{ord, pair[0] - 1});
            int q = pair[0];
            for (int v = 2; v <= e; v++) {
                q *= pair[0];
                if (powmod(x, ord, q) != 1) {
                    ord *= pair[0];
                }
                ords.add(new int[]{ord, q / pair[0] * (pair[0] - 1)});
            }
            List<int[]> newR = new ArrayList<>();
            for (int[] ab : r) {
                for (int[] cd : ords) {
                    int a = ab[0];
                    int b = ab[1];
                    int c = cd[0];
                    int d = cd[1];
                    newR.add(new int[]{a / gcd(a, c) * c, b * d});
                }
            }
            r = newR;
        }
        int sum = 0;
        for (int[] xy : r) {
            sum += xy[1] / xy[0];
        }
        System.out.println(sum);
        scanner.close();
    }
}

