        Map<String, Integer> d = new HashMap<>();

        for (int n = 1; n <= N; n++) {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (i == j) continue;
                    int other = (i != 0 && j != 0) ? 0 : (i != 1 && j != 1) ? 1 : 2;
                    int way1 = getOrDefault(d, n - 1, i, other) + getOrDefault(d, n - 1, other, j) + cost.get(i)[j];
                    int way2 = 2 * getOrDefault(d, n - 1, i, j) + getOrDefault(d, n - 1, j, i) + cost.get(i)[other] + cost.get(other)[j];
                    d.put(n + "," + i + "," + j, Math.min(way1, way2));
                }
            }
        }

        System.out.println(d.get(N + ",0,2"));
    }

    private static int getOrDefault(Map<String, Integer> map, int n, int i, int j) {
        return map.getOrDefault(n + "," + i + "," + j, 0);
    }
