            for (int i = 0; i < m; i++) {
                if (t.get(i) % s.get(x) == 0) {
                    inMask[i] |= 1 << x;
                }
            }
        }
        int[] cnt = new int[1 << p];
        for (int mask = 0; mask < (1 << p); mask++) {
            for (int i = 0; i < m; i++) {
                if (isSubset(inMask[i], mask)) {
                    cnt[mask]++;
                }
            }
        }
        int[][] dp = new int[m + 1][1 << p];
        for (int i = 0; i < m; i++) {
            dp[1][inMask[i]]++;
        }
        for (int k = 0; k < m; k++) {
            for (int mask = 0; mask < (1 << p); mask++) {
                for (int i = 0; i < m; i++) {
                    if (!isSubset(inMask[i], mask) && isIntersect(inMask[i], mask)) {
                        dp[k + 1][mask | inMask[i]] = (dp[k + 1][mask | inMask[i]] + dp[k][mask]) % MOD;
                    }
                }
                dp[k + 1][mask] = (dp[k + 1][mask] + (long) dp[k][mask] * (cnt[mask] - k) % MOD) % MOD;
            }
        }
        return dp[m][(1 << p) - 1];
    }

    public static void dfs(int u) {
        visited[u] = true;
        if (degIn[u] == 0) {
            s.add(a[u]);
        } else {
            t.add(a[u]);
        }
        for (int v : graph[u]) {
            if (!visited[v]) {
                dfs(v);
            }
        }
    }

