import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class FibonacciMod {

    public static int[][] multMod(int[][] a, int[][] b, int m) {
        int[][] c = new int[2][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                c[i][j] = (a[i][0] * b[0][j] + a[i][1] * b[1][j]) % m;
            }
        }
        return c;
    }

    public static int[][] powMod(int n, int m) {
        int[][] p = {{1, 1}, {1, 0}};
        int[][] a = {{1, 0}, {0, 1}};

        while (n > 0) {
            if (n % 2 != 0) {
                a = multMod(a, p, m);
            }
            p = multMod(p, p, m);
            n /= 2;
        }
        return a;
    }

    public static int fib(int n, int m) {
        return powMod(n, m)[0][0];
    }

    public static int[] egcd(int a, int b) {
        if (b == 0) {
            return new int[]{1, 0, a};
        }
        int[] temp = egcd(b, a % b);
        return new int[]{temp[1], temp[0] - (a / b) * temp[1], temp[2]};
    }

    public static long[] crt(long a0, long n0, long a1, long n1) {
        if (Math.min(n0, n1) < 0) {
            return new long[]{0, -1};
        }
        int[] gcdResult = egcd((int) n0, (int) n1);
        int x = gcdResult[0];
        int y = gcdResult[1];
        int g = gcdResult[2];
        if ((a0 - a1) % g != 0) {
            return new long[]{0, -1};
        }
        x *= (a1 - a0) / g;
        y *= (a1 - a0) / g;
        long k = n1 * n0 / g;
        return new long[]{(n0 * x + a0) % k, k};
    }

    public static List<Integer> find(int f, int m, int l) {
        List<Integer> resp = new ArrayList<>();
        int x0 = 0;
        int x1 = 1;
        for (int i = 0; i < l; i++) {
            if (x0 == f % m) {
                resp.add(i);
            }
            int temp = x1;
            x1 = (x0 + x1) % m;
            x0 = temp;
        }
        return resp;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int f = Integer.parseInt(scanner.nextLine());
        List<Integer> a = find(f, (int) Math.pow(2, 13), 12288);
        List<Integer> b = find(f, (int) Math.pow(5, 9), 7812500);

        if (a.isEmpty() || b.isEmpty()) {
            System.out.println("-1");
        } else {
            long ans = (long) Math.pow(10, 30);
            int[][] fm = powMod(24000000000L, (int) Math.pow(10, 13));
            for (int i : a) {
                for (int j : b) {
                    long[] result = crt(i, 12288, j, 7812500);
                    if (result[1] != -1) {
                        long a0 = result[0];
                        int[] fibResult = powMod((int) a0, (int) Math.pow(10, 13));
                        int x1 = fibResult[0];
                        int x0 = fibResult[1];
                        if (x0 == f) {
                            ans = Math.min(ans, a0);
                        } else {
                            a0 += result[1];
                            long x3 = (x1 * fm[0][0] + x0 * fm[1][0]) % (long) Math.pow(10, 13);
                            long x2 = (x1 * fm[0][1] + x0 * fm[1][1]) % (long) Math.pow(10, 13);
                            while ((x2 != x0 || x3 != x1)) {
                                if (x2 == f) {
                                    ans = Math.min(ans, a0);
                                    break;
                                }
                                a0 += result[1];
                                long temp = x3;
                                x3 = (x3 * fm[0][0] + x2 * fm[1][0]) % (long) Math.pow(10, 13);
                                x2 = (temp * fm[0][1] + x2 * fm[1][1]) % (long) Math.pow(10, 13);
                            }
                        }
                    }
                }
            }
            if (ans < Math.pow(10, 30)) {
                System.out.println(ans);
            } else {
                System.out.println("-1");
            }
        }
    }
}

