        final int M = 998244353;
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long a = 1, b = 1;

        for (int i = 0; i < n - 1; i++) {
            long temp = b;
            b = (a + b) % M;
            a = temp;
        }

        System.out.println((a * modPow(1 << n, M - 2, M)) % M);
    }

    private static long modPow(long base, int exp, int mod) {
        long result = 1;
        base = base % mod;

        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }

        return result;
    }
}

