        int a = Integer.parseInt(input[1]);

        Pair[] m = new Pair[n + 10];
        for (int i = 0; i < m.length; i++) {
            m[i] = new Pair(Double.POSITIVE_INFINITY, -1);
        }
        Deque<Pair> queue = new ArrayDeque<>();
        queue.addFirst(new Pair(a, 0));
        m[String.valueOf(a).length()] = new Pair(0, a);
        Set<Integer> dict = new HashSet<>();
        dict.add(a);

        while (!queue.isEmpty()) {
            Pair current = queue.pollLast();
            int c = current.value;
            int q = current.distance;
            for (char d : String.valueOf(c).toCharArray()) {
                if (d - '0' > 1) {
                    int newC = c * (d - '0');
                    String strC = String.valueOf(newC);
                    if (m[strC.length()].distance > q + 1) {
                        m[strC.length()] = new Pair(q + 1, newC);
                    }
                    Set<Integer> set = new HashSet<>();
                    for (char ch : strC.toCharArray()) {
                        set.add(ch - '0');
                    }
                    if (!(setMax(set) < 2 || strC.length() >= n || dict.contains(newC))) {
                        dict.add(newC);
                        queue.addFirst(new Pair(newC, q + 1));
                    }
                }
            }
        }

        System.out.println(m[n].distance < Double.POSITIVE_INFINITY ? (int) m[n].distance : -1);
    }

    private static int setMax(Set<Integer> set) {
        int max = Integer.MIN_VALUE;
        for (int num : set) {
            if (num > max) {
                max = num;
            }
        }
        return max;
    }

    static class Pair {
        double distance;
        int value;

        Pair(double distance, int value) {
            this.distance = distance;
            this.value = value;
        }
    }
}

