public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int l = scanner.nextInt();
        int r = scanner.nextInt();
        int gcd = scanner.nextInt();
        int lcm = scanner.nextInt();

        if (lcm % gcd != 0) {
            System.out.println(0);
            return;
        }

        Set<Integer> lcmDivisors = new HashSet<>();
        for (int num = 1; num <= Math.sqrt(lcm) + 1; num++) {
            if (lcm % num == 0) {
                lcmDivisors.add(num);
                lcmDivisors.add(lcm / num);
            }
        }

        int product = gcd * lcm;
        Set<String> answers = new HashSet<>();
        for (int divisor : lcmDivisors) {
            if (divisor < l || divisor > r) {
                continue;
            }
            int dop = product / divisor;
            if (dop < l || dop > r) {
                continue;
            }
            if (gcd(divisor, dop) != gcd) {
                continue;
            }
            answers.add(divisor + "," + dop);
            answers.add(dop + "," + divisor);
        }

        System.out.println(answers.size());
    }

    public static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

