                }
            }
            s1.add(now % m);
        }

        List<Integer> s2 = new ArrayList<>();
        for (int i = 0; i < t2; i++) {
            int now = 0;
            for (int j = 0; j < sec.size(); j++) {
                if ((i & (1 << j)) != 0) {
                    now += sec.get(j);
                }
            }
            s2.add(now % m);
        }

        Collections.sort(s1);
