public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        List<Integer> a = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            a.add(scanner.nextInt());
        }

        List<Integer> a1 = new ArrayList<>();
        List<Integer> a2 = new ArrayList<>();
        int n1 = n / 2;

        sums1(a, a1, 0, 0, n1, m);
        sums2(a, a2, n1, 0, n, m);

        Set<Integer> setA1 = new TreeSet<>(a1);
        a1 = new ArrayList<>(setA1);
        Collections.sort(a1);

        int ans = 0;
        int end = a2.size() - 1;

        for (int i : a2) {
            int j = bisectLeft(a1, m - i);
            if (j > 0 && ans < a1.get(j - 1) + i) {
                ans = a1.get(j - 1) + i;
            }
        }

        System.out.println(ans);
    }

    private static void sums1(List<Integer> a, List<Integer> a1, int i, int sum, int n1, int m) {
        if (i == n1) {
            a1.add(sum % m);
        } else {
            sums1(a, a1, i + 1, (sum + a.get(i)), n1, m);
            sums1(a, a1, i + 1, sum, n1, m);
        }
    }

    private static void sums2(List<Integer> a, List<Integer> a2, int i, int sum, int n, int m) {
        if (i == n) {
            a2.add(sum % m);
        } else {
            sums2(a, a2, i + 1, (sum + a.get(i)), n, m);
            sums2(a, a2, i + 1, sum, n, m);
        }
    }

    private static int bisectLeft(List<Integer> list, int key) {
        int low = 0;
        int high = list.size();

        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

