import java.util.Scanner;

public class Main {
    static int[][] pts = new int[64][2];

    public static int dist(int[] p, int[] q) {
        return Math.abs(p[0] - q[0]) + Math.abs(p[1] - q[1]);
    }

    public static int go(int i, int tt) {
        int ans = 0;
        for (int j = 0; j <= i; j++) {
            for (int k = i; k < 64; k++) {
                int jk = dist(pts[i], pts[j]) + dist(pts[j], pts[k]);
                int kj = dist(pts[i], pts[k]) + dist(pts[k], pts[j]);
                if (jk <= tt || kj <= tt) {
                    ans = Math.max(ans, Math.abs(j - k) + 1);
                }
            }
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int x0 = scanner.nextInt();
        int y0 = scanner.nextInt();
        int ax = scanner.nextInt();
        int ay = scanner.nextInt();
        int bx = scanner.nextInt();
        int by = scanner.nextInt();

        int xs = scanner.nextInt();
        int ys = scanner.nextInt();
        int t = scanner.nextInt();

        pts[0][0] = x0;
        pts[0][1] = y0;
        for (int i = 1; i < 64; i++) {
            int xi = ax * pts[i - 1][0] + bx;
            int yi = ay * pts[i - 1][1] + by;
            pts[i][0] = xi;
            pts[i][1] = yi;
        }

        int ans = 0;
        int[] s = {xs, ys};
        for (int i = 0; i < 64; i++) {
            int tt = t - dist(s, pts[i]);
            if (tt >= 0) {
                ans = Math.max(ans, go(i, tt));
            }
        }
        System.out.println(ans);
    }
}

