public class Main {
    static final int P = 1000000007;
    static final int N = 1000001;
    static long[] factorialNumInverse = new long[N + 1];
    static long[] naturalNumInverse = new long[N + 1];
    static long[] fact = new long[N + 1];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] a = readArrInt(scanner);
        int n = a[0];
        int k = a[1];
        if (k >= n) {
            System.out.println(power(2, n, P));
        } else {
            long ans = 0;
            inverseOfNumber(P);
            inverseOfFactorial(P);
            factorial(P);
            for (int i = 0; i <= k; i++) {
                ans = (ans + binomial(n, i, P)) % P;
            }
            System.out.println(ans);
        }
        scanner.close();
    }

    static long[] readArrInt(Scanner scanner) {
        String[] arr = scanner.nextLine().split(" ");
        long[] result = new long[arr.length];
        for (int i = 0; i < arr.length; i++) {
            result[i] = Long.parseLong(arr[i]);
        }
        return result;
    }

    static long power(long x, long y, long p) {
        long res = 1;
        x = x % p;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = (res * x) % p;
            }
            y >>= 1;
            x = (x * x) % p;
        }
        return res;
    }

    static void inverseOfNumber(int p) {
        naturalNumInverse[0] = naturalNumInverse[1] = 1;
        for (int i = 2; i <= N; i++) {
            naturalNumInverse[i] = (naturalNumInverse[p % i] * (p - p / i)) % p;
        }
    }

    static void inverseOfFactorial(int p) {
        factorialNumInverse[0] = factorialNumInverse[1] = 1;
        for (int i = 2; i <= N; i++) {
            factorialNumInverse[i] = (naturalNumInverse[i] * factorialNumInverse[i - 1]) % p;
        }
    }

    static void factorial(int p) {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = (fact[i - 1] * i) % p;
        }
    }

    static long binomial(int N, int R, int p) {
        return (((fact[N] * factorialNumInverse[R]) % p) * factorialNumInverse[N - R]) % p;
    }
}

