import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        List<Character> a = new ArrayList<>();
        for (char c : input[0].toCharArray()) {
            a.add(c);
        }
        int k = Integer.parseInt(input[1]);

        System.out.println(String.join("", yoba(a, k)));
    }

    public static List<Character> yoba(List<Character> a, int k) {
        if (a.isEmpty()) {
            return new ArrayList<>();
        } else if (k == 0) {
            return a;
        } else {
            int maxIndex = 0;
            char maxChar = a.get(0);
            for (int i = 0; i <= k && i < a.size(); i++) {
                if (a.get(i) > maxChar) {
                    maxChar = a.get(i);
                    maxIndex = i;
                }
            }
            if (maxChar > a.get(0)) {
                a.set(0, maxChar);
                for (int i = maxIndex; i > 0; i--) {
                    a.set(i, a.get(i - 1));
                }
                k -= maxIndex;
            }
            List<Character> result = new ArrayList<>();
            result.add(a.get(0));
            result.addAll(yoba(a.subList(1, a.size()), k));
            return result;
        }
    }
}

