                    resp = (resp + v[j] * deriv[j] % MOD) % MOD;
                }
                resp %= MOD;
                deriv[i - 1] = resp;
            }

            System.out.println(deriv[k - 1]);
        }
    }

    private static long inv(long a) {
        return power(a, MOD - 2, MOD);
    }

    private static long fat(long a) {
        long ans = 1;
        for (long i = 1; i <= a; i++) {
            ans = (ans * i) % MOD;
        }
        return ans;
    }

    private static long power(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % mod;
            }
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        int[] inputA = new int[3];
        int[] inputB = new int[3];

        for (int i = 0; i < 3; i++) {
            inputA[i] = scanner.nextInt();
        }

        for (int i = 0; i < 3; i++) {
            inputB[i] = scanner.nextInt();
        }

        int[] inputA2 = Arrays.copyOf(inputA, inputA.length);
        int[] inputB2 = Arrays.copyOf(inputB, inputB.length);

        System.out.println((n - getLostMaxFast(inputA2, inputB2)) + " " + getWonMaxFast(inputA, inputB));
    }

    public static int getWonMaxFast(int[] inputA, int[] inputB) {
        int[] wins = new int[3];
        for (int i = 0; i < 3; i++) {
            int good = (i + 1) % 3;
            wins[i] = Math.min(inputA[i], inputB[good]);
            inputA[i] -= wins[i];
            inputB[good] -= wins[i];
        }
        return Arrays.stream(wins).sum();
    }

    public static int getLostMaxFast(int[] inputA, int[] inputB) {
        int[][] waysToLose = {{0, 2}, {1, 0}, {2, 1}, {0, 0}, {1, 1}, {2, 2}};
        List<int[]> allWaysToLosePermutations = new ArrayList<>();

        permute(waysToLose, 0, allWaysToLosePermutations);

        int maxLost = 0;

        for (int[] permutation : allWaysToLosePermutations) {
            int[] losts = new int[3];
            int[] inputACopy = Arrays.copyOf(inputA, inputA.length);
            int[] inputBCopy = Arrays.copyOf(inputB, inputB.length);

            for (int[] wayToLose : waysToLose) {
                int lostAdd = Math.min(inputACopy[wayToLose[0]], inputBCopy[wayToLose[1]]);
                inputACopy[wayToLose[0]] -= lostAdd;
                inputBCopy[wayToLose[1]] -= lostAdd;
                losts[wayToLose[0]] += lostAdd;
            }

            int lostSum = Arrays.stream(losts).sum();

            if (lostSum > maxLost) {
                maxLost = lostSum;
            }
        }

        return maxLost;
    }

    private static void permute(int[][] array, int start, List<int[]> result) {
        if (start == array.length - 1) {
            result.add(array.clone());
        } else {
            for (int i = start; i < array.length; i++) {
                swap(array, start, i);
                permute(array, start + 1, result);
                swap(array, start, i);
            }
        }
    }

    private static void swap(int[][] array, int i, int j) {
        int[] temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

