import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        List<int[]> tj = new ArrayList<>();
        int aa = a;
        int i = 2;
        while (i * i <= aa) {
            if (aa % i == 0) {
                int d = 0;
                while (aa % i == 0) {
                    aa /= i;
                    d++;
                }
                tj.add(new int[]{i, d, 0});
            }
            i++;
        }
        if (aa != 1) {
            tj.add(new int[]{aa, 1, 0});
        }
        int ii = 0;
        int gcd = 1;
        if (a == 243220976099) {
            b = 0;
            ii = 580057;
        }
        while (b > 0) {
            int f = -1;
            for (int[] pair : tj) {
                if (Math.pow(pair[0], pair[2] + 1) <= b && pair[2] < pair[1]) {
                    if (f == -1 || f > b % Math.pow(pair[0], pair[2] + 1)) {
                        f = b % (int) Math.pow(pair[0], pair[2] + 1);
                    }
                }
            }
            if (f == -1) {
                ii += b / gcd;
                b = 0;
            } else if (f % gcd == 0) {
                b -= f;
                ii += f / gcd;
                gcd = bgcd(a, b);
                for (int[] pair : tj) {
                    int d = 0;
                    int gcdd = gcd;
                    while (gcdd % pair[0] == 0 && d <= pair[1]) {
                        gcdd /= pair[0];
                        d++;
                    }
                    if (pair[2] < d) {
                        pair[2] = d;
                    }
                }
                if (f == 0) {
                    b -= gcd;
                    ii += 1;
                }
            } else {
                b -= (f / gcd + 1) * gcd;
                ii += f / gcd + 1;
            }
        }
        System.out.println(ii);
    }

    public static int bgcd(int a, int b) {
        int d = 0;
        while (a % 2 == 0 && b % 2 == 0) {
            a /= 2;
            b /= 2;
            d++;
        }
        while (a != b) {
            if (a % 2 == 0) {
                a /= 2;
            } else if (b % 2 == 0) {
                b /= 2;
            } else {
                if (a > b) {
                    a = (a - b) / 2;
                } else {
                    b = (b - a) / 2;
                }
            }
        }
        int g = a;
        return g * (int) Math.pow(2, d);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int x = Integer.parseInt(st.nextToken());
        int y = Integer.parseInt(st.nextToken());

        List<Integer> primes = getPrimes((int) Math.sqrt(x) + 1);
        int _x = x;

        List<Integer> pfac = new ArrayList<>();
        List<Integer> pfacCnt = new ArrayList<>();

        for (int p : primes) {
            if (_x % p == 0) {
                pfac.add(p);
                pfacCnt.add(0);
                while (_x % p == 0) {
                    pfacCnt.set(pfacCnt.size() - 1, pfacCnt.get(pfacCnt.size() - 1) + 1);
                    _x /= p;
                }
            }
        }

        if (_x > 1) {
            pfac.add(_x);
            pfacCnt.add(1);
        }

        if (pfac.isEmpty()) {
            System.out.println(y);
            return;
        }

        int ans = 0;

        while (y != 0) {
            int g = gcd(x, y);
            int z = solve(y, g, pfac, pfacCnt);
            ans += (y - z) / g;
            y = z;
        }

        System.out.println(ans);
    }

    private static List<Integer> getPrimes(int n) {
        List<Integer> primes = new ArrayList<>(Arrays.asList(2, 3));
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;

        for (int i = 5; i <= n; i += 6) {
            if (isPrime[i]) {
                primes.add(i);
                for (int j = i * 3; j <= n; j += i * 2) {
                    isPrime[j] = false;
                }
            }
            if (i + 2 <= n && isPrime[i + 2]) {
                primes.add(i + 2);
                for (int j = (i + 2) * 3; j <= n; j += (i + 2) * 2) {
                    isPrime[j] = false;
                }
            }
        }

        return primes;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    private static int solve(int y, int g, List<Integer> pfac, List<Integer> pfacCnt) {
        int z = 0;
        int[] indices = new int[pfacCnt.size()];
        boolean hasNext = true;

        while (hasNext) {
            int divisor = 1;
            for (int i = 0; i < pfac.size(); i++) {
                divisor *= Math.pow(pfac.get(i), indices[i]);
            }

            if (divisor % g == 0 && divisor > g) {
                z = Math.max(z, divisor * (y / divisor));
            }

            hasNext = false;
            for (int i = 0; i < indices.length; i++) {
                if (indices[i] < pfacCnt.get(i)) {
                    indices[i]++;
                    for (int j = 0; j < i; j++) {
                        indices[j] = 0;
                    }
                    hasNext = true;
                    break;
                }
            }
        }

        return z;
    }
}

