import java.util.HashMap;
import java.util.Map;

public class Main {

    public static Map<Integer, Integer> nextc(Map<Integer, Integer> m) {
        Map<Integer, Integer> m2 = new HashMap<>();
        for (Map.Entry<Integer, Integer> entry : m.entrySet()) {
            int n = entry.getKey();
            int c = entry.getValue();
            int h = (n - 1) >> 1;
            m2.put(h, m2.getOrDefault(h, 0) + c);
            m2.put(n - 1 - h, m2.getOrDefault(n - 1 - h, 0) + c);
        }
        return m2;
    }

    public static int countseg(int l, int s, Map<String, Integer> cache) {
        String key = l + "," + s;
        if (s > l) return 0;
        if (s == l) return 1;
        if (cache.containsKey(key)) {
            return cache.get(key);
        }
        int h = (l - 1) >> 1;
        int out = countseg(h, s, cache) + countseg(l - 1 - h, s, cache);
        cache.put(key, out);
        return out;
    }

    public static int findx(int l, int q, int[] ss) {
        if (l <= max(ss)) {
            return ((l - 1) >> 1) + q;
        }
        int h = (l - 1) >> 1;
        int ns = 0;
        for (int s : ss) {
            ns += countseg(h, s, new HashMap<>());
        }
        if (q >= ns) {
            return h + 1 + findx(l - 1 - h, q - ns, ss);
        } else {
            return findx(h, q, ss);
        }
    }

    public static int f(int l, int r) {
        Map<Integer, Integer> m = new HashMap<>();
        m.put(l, 1);
        m.put(l - 1, 0);
        int q = 1;
        while (r >= q && min(m) > 2) {
            r -= q;
            q <<= 1;
            m = nextc(m);
        }
        int mn = min(m);
        int mx = max(m);
        if ((mx & 1) != 0) {
            if (r >= m.get(mx)) {
                if (mx == 3) {
                    return findx(l, r - m.get(mx), new int[]{1, 2});
                }
                return findx(l, r - m.get(mx), new int[]{mn});
            } else {
                return findx(l, r, new int[]{mx});
            }
        } else {
            return findx(l, r, new int[]{mn, mx});
        }
    }

    public static int ans(int n, int k) {
        if (k == 1) return 1;
        if (k == 2) return n;
        return 2 + f(n - 2, k - 3);
    }

    public static int brute_ans(int n, int k) {
        if (k == 1) return 1;
        if (k == 2) return n;
        return 2 + brute_f(n - 2, k - 2);
    }

    public static int brute_f(int l, int r) {
        int[][] s = new int[1][2];
        s[0] = new int[]{0, l};
        for (int i = 0; i < r; i++) {
            int maxIndex = 0;
            for (int j = 1; j < s.length; j++) {
                if (((s[j][1] - 1) >> 1) > ((s[maxIndex][1] - 1) >> 1)) {
                    maxIndex = j;
                }
            }
            int x = s[maxIndex][0];
            int d = s[maxIndex][1];
            int h = (d - 1) >> 1;
            int[][] newS = new int[s.length + 1][2];
            System.arraycopy(s, 0, newS, 0, maxIndex);
            newS[maxIndex] = new int[]{x, h};
            newS[maxIndex + 1] = new int[]{x + h + 1, d - 1 - h};
            System.arraycopy(s, maxIndex + 1, newS, maxIndex + 2, s.length - maxIndex - 1);
            s = newS;
        }
        return s[s.length - 1][0] + ((s[s.length - 1][1] - 1) >> 1);
    }

    public static int min(Map<Integer, Integer> map) {
        int min = Integer.MAX_VALUE;
        for (int key : map.keySet()) {
            if (key < min) {
                min = key;
            }
        }
        return min;
    }

    public static int max(int[] array) {
        int max = Integer.MIN_VALUE;
        for (int value : array) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }

    public static void test_n(int n) {
        for (int i = 1; i <= n; i++) {
            assert brute_ans(n, i) == ans(n, i);
        }
    }

    public static void main(String[] args) {
        // Assuming input is provided via console or other means
        int n = Integer.parseInt(args[0]);
        int k = Integer.parseInt(args[1]);
        System.out.println(ans(n, k));
    }
}

