import java.util.*;

public class Main {
    static final int MAXN = 110;
    static final long MOD = 1000000007;
    static List<List<Long>> com;

    public static void main(String[] args) {
        MakeCom();
        Scanner scanner = new Scanner(System.in);
        StringBuilder input = new StringBuilder();
        while (scanner.hasNext()) {
            input.append(scanner.nextLine()).append(" ");
        }
        String[] data = input.toString().trim().split(" ");
        int offset = 0;
        while (offset < data.length) {
            int n = Integer.parseInt(data[offset++]);
            int cap = Integer.parseInt(data[offset++]);
            int[] friends = new int[2];
            for (int i = 0; i < n; i++) {
                int x = Integer.parseInt(data[offset++]);
                friends[x / 50 - 1]++;
            }
            cap /= 50;
            Solve(cap, friends);
        }
        scanner.close();
    }

    static void MakeCom() {
        com = new ArrayList<>();
        com.add(new ArrayList<>(Collections.singletonList(1L)));
        for (int i = 1; i <= MAXN; i++) {
            List<Long> line = new ArrayList<>();
            line.add(1L);
            for (int j = 1; j < i; j++) {
                line.add((com.get(i - 1).get(j - 1) + com.get(i - 1).get(j)) % MOD);
            }
            line.add(1L);
            com.add(line);
        }
    }

    static void Solve(int cap, int[] friends) {
        Map<Integer[], Long> f = new HashMap<>();
        f.put(friends.clone(), 1L);
        for (int rides = 0; rides < Arrays.stream(friends).sum() * 5; rides++) {
            if ((rides & 1) == 1 && f.containsKey(friends)) {
                System.out.println(rides);
                System.out.println(f.get(friends));
                return;
            }
            Map<Integer[], Long> pf = new HashMap<>(f);
            f.clear();
            for (Integer[] remain : pf.keySet()) {
                for (int x = 0; x <= remain[0]; x++) {
                    if (x > cap) break;
                    for (int y = 0; y <= remain[1]; y++) {
                        if (x + y < 1) continue;
                        if (x + 2 * y > cap) break;
                        int[] nextRem = new int[2];
                        nextRem[0] = remain[0] - x + friends[0];
                        nextRem[1] = remain[1] - y + friends[1];
                        long value = (pf.get(remain) * com.get(remain[0]).get(x) % MOD) * com.get(remain[1]).get(y) % MOD;
