import java.util.ArrayList;
import java.util.List;

class NotAMatrixError extends Exception {
}

class MatrixSizeError extends Exception {
    public MatrixSizeError(String s1, String s2) {
        System.out.println("sizes do not match : " + s1 + ", " + s2);
    }
}

class NotSquareError extends Exception {
}

class Matrix {
    private List<List<Integer>> data;
    private int n, m;
    private List<Matrix> degrees;

    public Matrix(List<List<Integer>> L) throws NotAMatrixError {
        this.data = new ArrayList<>(L);
        this.n = L.size();
        this.m = L.get(0).size();
        this.degrees = new ArrayList<>();

        for (List<Integer> row : L) {
            if (row.size() != m) {
                throw new NotAMatrixError();
            }
        }
    }

    private void checkSize(Matrix M, String mode) throws NotAMatrixError, MatrixSizeError {
        int n = M.data.size();
        int m = M.data.get(0).size();

        for (List<Integer> row : M.data) {
            if (row.size() != m) {
                throw new NotAMatrixError();
            }
        }

        if (mode.equals("add") && (this.n != n || this.m != m)) {
            throw new MatrixSizeError("(" + this.n + ", " + this.m + ")", "(" + n + "," + m + ")");
        }
        if (mode.equals("mul") && this.m != n) {
            System.out.println(this.m + " " + n + " " + (this.m != n));
            throw new MatrixSizeError("(" + this.n + ", " + this.m + ")", "(" + n + "," + m + ")");
        }
    }

    public Matrix add(Matrix M) throws NotAMatrixError, MatrixSizeError {
        checkSize(M, "add");
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> row = new ArrayList<>();
            for (int j = 0; j < m; j++) {
                row.add(this.data.get(i).get(j) + M.data.get(i).get(j));
            }
            result.add(row);
        }
        return new Matrix(result);
    }

    public void iAdd(Matrix M) throws NotAMatrixError, MatrixSizeError {
        checkSize(M, "add");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                this.data.get(i).set(j, this.data.get(i).get(j) + M.data.get(i).get(j));
            }
        }
    }

    public Matrix multiply(Matrix M) throws NotAMatrixError, MatrixSizeError {
        checkSize(M, "mul");
        int l = M.data.get(0).size();
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> row = new ArrayList<>();
            for (int j = 0; j < l; j++) {
                int sum = 0;
                for (int k = 0; k < m; k++) {
                    sum += this.data.get(i).get(k) * M.data.get(k).get(j);
                }
                row.add(sum);
            }
            result.add(row);
        }
        return new Matrix(result);
    }

    public boolean isSquare() {
        return this.n == this.m;
    }

    public Matrix primary() throws NotSquareError {
        if (this.n != this.m) {
            throw new NotSquareError();
        }
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> row = new ArrayList<>();
            for (int j = 0; j < m; j++) {
                row.add(i == j ? 1 : 0);
            }
            result.add(row);
        }
        return new Matrix(result);
    }

    public Matrix pow(int n) throws NotSquareError, NotAMatrixError, MatrixSizeError {
        if (!isSquare()) {
            throw new NotSquareError();
        }
        if (n == 0) {
            return primary();
        } else if (n == 1) {
            return this;
        }
        if (degrees.isEmpty()) {
            degrees.add(multiply(this));
        }
        for (int i = 0; i < Integer.toBinaryString(n).length() - degrees.size() - 1; i++) {
            degrees.add(degrees.get(degrees.size() - 1).multiply(degrees.get(degrees.size() - 1)));
        }
        Matrix res = new Matrix(primary());
        for (int i = 0; i < Integer.toBinaryString(n).length(); i++) {
            if ((n >> i & 1) == 1) {
                res = res.multiply(degrees.get(i));
            }
        }
        return (n % 2 == 0) ? res : res.multiply(this);
    }

    public void dropDegrees() {
        degrees.clear();
    }

    public Integer get(int i, int j) {
        return data.get(i).get(j);
    }

    public int size() {
        return n;
    }

    public int colSize() {
        return m;
    }
}

class Remainder {
    private int value;
    private int p;

    public Remainder(int n, int p) {
        this.value = n % p;
        this.p = p;
    }

    public Remainder multiply(Remainder m) {
        return new Remainder(this.value * m.value, this.p);
    }

    public Remainder add(Remainder m) {
        return new Remainder(this.value + m.value, this.p);
    }

    public Remainder subtract(Remainder m) {
        return new Remainder(this.value - m.value, this.p);
    }

    public Remainder pow(int m) {
        return new Remainder((int) Math.pow(this.value, m) % this.p, this.p);
    }

    @Override
    public int intValue() {
        return value;
    }
}

public class Main {
    public static Matrix solve(int n, Remainder sx, Remainder sy, Remainder dx, Remainder dy, int t) throws NotAMatrixError, MatrixSizeError, NotSquareError {
        Remainder o = new Remainder(0, n);
        Remainder l = new Remainder(1, n);
        Remainder j = new Remainder(2, n);
        List<List<Integer>> N = List.of(
                List.of(j.intValue(), l.intValue(), l.intValue(), o.intValue(), l.intValue(), o.intValue()),
                List.of(l.intValue(), j.intValue(), o.intValue(), l.intValue(), l.intValue(), o.intValue()),
                List.of(l.intValue(), l.intValue(), l.intValue(), o.intValue(), l.intValue(), o.intValue()),
                List.of(l.intValue(), l.intValue(), o.intValue(), l.intValue(), l.intValue(), o.intValue()),
                List.of(o.intValue(), o.intValue(), o.intValue(), o.intValue(), l.intValue(), l.intValue()),
                List.of(o.intValue(), o.intValue(), o.intValue(), o.intValue(), o.intValue(), l.intValue())
        );
        Matrix M = new Matrix(N);
        List<List<Integer>> vData = List.of(
                List.of(sx.intValue()),
                List.of(sy.intValue()),
                List.of(dx.intValue()),
                List.of(dy.intValue()),
                List.of(o.intValue()),
                List.of(l.intValue())
        );
        Matrix v = new Matrix(vData);
        return M.pow(t).multiply(v);
    }

    public static void main(String[] args) throws NotAMatrixError, MatrixSizeError, NotSquareError {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        int n = scanner.nextInt();
        Remainder sx = new Remainder(scanner.nextInt(), n);
        Remainder sy = new Remainder(scanner.nextInt(), n);
        Remainder dx = new Remainder(scanner.nextInt(), n);
        Remainder dy = new Remainder(scanner.nextInt(), n);
        int t = scanner.nextInt();
        Matrix ans = solve(n, sx, sy, dx, dy, t);
        System.out.println((ans.get(0, 0) - 1) + 1 + " " + (ans.get(1, 0) - 1) + 1);
    }
}

