public class Main {
    private static final int MOD = 1000000007;
    private static final int MAX_N = 10000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.close();

        long[] fac = new long[MAX_N + 1];
        long[] fac_inv = new long[MAX_N + 1];
        fac[0] = 1;
        fac_inv[0] = 1;

        for (int i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1] * i) % MOD;
            fac_inv[i] = (fac_inv[i - 1] * power(i, MOD - 2, MOD)) % MOD;
        }

        long ans = 0;
        for (int i = 0; i <= n; i++) {
            long base = (power(k, n - i, MOD) * power(k - 1, i, MOD) % MOD - power(k - 1, n, MOD) + MOD) % MOD;
            long val = (power(-1, i, MOD) * mod_nCr(n, i, fac, fac_inv) % MOD * power(base, n, MOD)) % MOD;
            ans = (ans + val) % MOD;
        }

        System.out.println(ans);
    }

    private static long mod_nCr(int n, int r, long[] fac, long[] fac_inv) {
        if (n == 0 && r == 0) return 1;
        if (n < r || n < 0) return 0;
        long tmp = (fac_inv[n - r] * fac_inv[r]) % MOD;
        return (tmp * fac[n]) % MOD;
    }

    private static long power(long x, long y, long mod) {
        long result = 1;
        x = x % mod;
        while (y > 0) {
            if ((y & 1) == 1) result = (result * x) % mod;
            y >>= 1;
            x = (x * x) % mod;
        }
        return result;
    }
}

