import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        int mx = get(a, null);
        int lo = 0, hi = mx;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (get(a, mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        if (mx > 0) {
            for (int i = lo; i <= mx; i++) {
                System.out.print(i + " ");
            }
        } else {
            System.out.println(-1);
        }
    }

    private static boolean get(int[] a, Integer cnt) {
        Map<Integer, Integer> c = new HashMap<>();
        for (int x : a) {
            c.put(x, c.getOrDefault(x, 0) + 1);
        }

        List<Integer> last = new ArrayList<>();
        while (c.getOrDefault(1, 0) > 0 && (cnt == null || last.size() < cnt)) {
            int x = 1;
            while (c.getOrDefault(x, 0) > 0) {
                c.put(x, c.get(x) - 1);
                x *= 2;
            }
            last.add(x >> 1);
        }

        List<Integer> rem = new ArrayList<>(c.keySet());
        Collections.sort(rem);
        int i = 0;
        for (int x : last) {
            if (i < rem.size() && rem.get(i) < 2 * x) {
                i++;
            }
        }
        return i == rem.size();
    }
}

