    private static final String c = "0123456789";
    private static final Map<String, Pair> F = new HashMap<>();

    static {
        for (int a = 1; a < 10; a++) {
            for (int b = 0; b < 10; b++) {
                String key = "" + c.charAt(a) + c.charAt(b);
                if (a > b) {
                    F.put(key, new Pair("" + c.charAt(10 - a + b), 1));
                } else {
                    F.put(key, new Pair("" + c.charAt(10 - a), 2));
                }
            }
        }
        for (int b = 1; b < 10; b++) {
            F.put("0" + c.charAt(b), new Pair("0", 1));
        }
        F.put("00", new Pair("0", 0));
    }

    private static Pair f(String x) {
        if (F.containsKey(x)) return F.get(x);
        int a = x.charAt(0) - '0';
        int b = x.charAt(1) - '0';
        String y = x.substring(2);
        int s = 0;
        for (int i = b; i > a; i--) {
            Pair result = f("" + c.charAt(i) + y);
            y = result.value;
            s += result.count;
        }
        for (int i = 0; i <= Math.min(a, b); i++) {
            Pair result = f("" + x.charAt(0) + y);
            y = result.value;
            s += result.count;
        }
        F.put(x, new Pair("9" + y, s));
        return F.get(x);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println(f("0" + scanner.nextLine()).count);
    }

    private static class Pair {
        String value;
        int count;

        Pair(String value, int count) {
            this.value = value;
            this.count = count;
        }
    }
}

