import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int l1 = scanner.nextInt();
        int r1 = scanner.nextInt();
        int l2 = scanner.nextInt();
        int r2 = scanner.nextInt();

        int[] l = {l1, l2};
        int[] r = {r1, r2};
        int ans = 0;

        for (int s = 0; s < 31; s++) {
            List<int[]>[] z = new List[2];
            z[0] = new ArrayList<>();
            z[1] = new ArrayList<>();

            for (int hui = 0; hui < 2; hui++) {
                List<Integer> f = new ArrayList<>();
                int t = l[hui] - 1;

                for (int j = 0; j < 3; j++) {
                    t = nextWhere(t + 1, s);
                    if (t > r[hui]) {
                        break;
                    }
                    f.add(t);
                }

                if (f.isEmpty()) {
                    continue;
                } else if (f.size() == 1) {
                    z[hui].add(new int[]{Math.min(f.get(0) - l[hui], (1 << s) - 1), Math.min(r[hui] - f.get(0), (1 << s) - 1)});
                } else if (f.size() == 2) {
                    z[hui].add(new int[]{Math.min(f.get(0) - l[hui], (1 << s) - 1), (1 << s) - 1});
                    z[hui].add(new int[]{(1 << s) - 1, Math.min(r[hui] - f.get(1), (1 << s) - 1)});
                } else {
                    z[hui].add(new int[]{(1 << s) - 1, (1 << s) - 1});
                }
            }

            for (int[] i : z[0]) {
                for (int[] j : z[1]) {
                    ans = Math.max(ans, Math.min(i[0], j[0]) + Math.min(i[1], j[1]) + 1);
                }
            }
        }

        System.out.println(ans);
    }

    public static int nextWhere(int l, int s) {
        int fs = 1 << s;
        int st = 1 << (s + 1);
        return l % st == fs ? l : l + (st - (l - fs) % st);
    }
}

