        for (int i = 0; i <= lim; i++) {
            sm[i] = i - 1;
            if (i == 0) {
                la[i] = 0;
                continue;
            }
            la[i] = n / i - 1;
        }
        for (int p = 2; p <= lim; p++) {
            if (sm[p - 1] == sm[p]) {
                continue;
            }
            int cnt_p = sm[p - 1];
            int q = p * p;
            int en = Math.min(lim, n / q);
            for (int i = 1; i <= en; i++) {
                int d = i * p;
                if (d <= lim) {
                    la[i] -= la[d] - cnt_p;
                } else {
                    la[i] -= sm[n / d] - cnt_p;
                }
            }
            for (int i = lim; i > q - 1; i--) {
                sm[i] -= sm[i / p] - cnt_p;
            }
        }
        for (int i = 1; i <= lim; i++) {
            myp.put(i, sm[i]);
            myp.put(n / i, la[i]);
        }
