    public static int crt(int[] A, int[] B) {
        int N = 1;
        for (int val : A) {
            N *= val;
        }
        int ret = 0;
        for (int i = 0; i < A.length; i++) {
            int val = A[i];
            int md = B[i];
            int prodRem = N / val;
            ret += md * (prodRem * inv(prodRem, val)) % N;
        }
        return ret % N;
    }

