        int x = Integer.parseInt(input[2]);
        int y = Integer.parseInt(input[3]);
        int k = Integer.parseInt(input[4]);
        int M = Integer.parseInt(input[5]);

        long inv_n = inv(n);
        int base = lcmRange(1, Math.max(k, 2));
        long[] pr = new long[base];
        long result = 0;

        for (int i = 0; i < n; i++) {
            pr[a % base] = (pr[a % base] + inv_n) % MOD;
            result = (result + (a - a % base) * inv_n * k) % MOD;
            a = (a * x + y) % M;
        }

        for (int i = 1; i <= k; i++) {
            long sum = 0;
            for (int j = 0; j < base; j++) {
                sum = (sum + pr[j] * j) % MOD;
            }
            result = (result + sum) % MOD;
            for (int j = 0; j < base; j++) {
                long change = (pr[j] * inv_n) % MOD;
                pr[j] = (pr[j] - change + MOD) % MOD;
                pr[(j - j % i + base) % base] = (pr[(j - j % i + base) % base] + change) % MOD;
            }
        }

        result = (result * pow(n, k, MOD)) % MOD;
        System.out.println(result);
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static long lcm(long x, long y) {
        return x / gcd(x, y) * y;
    }

    static int lcmRange(int start, int end) {
        int lcm = 1;
        for (int i = start; i <= end; i++) {
            lcm = (int) (lcm * (i / gcd(lcm, i)));
        }
        return lcm;
    }

    static long inv(long n) {
        return pow(n, MOD - 2, MOD);
    }

    static long pow(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

