        if (r > n) return 0;
        return fact(n) / (fact(n - r) * fact(r));
    }

    static long P(int n, int r) {
        if (r > n) return 0;
        return fact(n) / fact(n - r);
    }

    static long fact(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result = (result * i) % MOD;
        }
        return result;
    }
}

