public class Main {
    static final int MOD = 998244353;
    static final double MODF = (double) MOD;
    static final double SHRT = (double) (1 << 16);
    static final double G = 3.0;
    static final int MAXSIZ = 1 << 20;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inp = br.readLine().split(" ");
        int n = Integer.parseInt(inp[0]);
        int k = Integer.parseInt(inp[1]);

        double[] f = new double[MAXSIZ];
        for (int i = 2; i <= k + 1; i++) {
            f[Integer.parseInt(inp[i])] = 1.0;
        }

        int m = MAXSIZ;
        int m2 = m / 2;
        double[] w = new double[m2];
        w[1] = fpow(G, (MOD - 1) / m);
        for (int i = 2; i < m2; i++) {
            w[i] = modProd(w[i - 1], w[1]);
        }

        int[] rev = new int[m];
        for (int i = 0; i < m; i++) {
            rev[i] = rev[i >> 1] >> 1;
            if ((i & 1) != 0) {
                rev[i] |= m2;
            }
        }

        nttTransform(f);
        for (int i = 0; i < m; i++) {
            f[i] = fpow(f[i], n >> 1);
        }
        nttTransform(f);

        double invM = fpow(m, MOD - 2);
        double ans = modProd(modProd(Arrays.stream(f).mapToDouble(x -> modProd(x, x)).sum() % MODF, invM), invM);
        System.out.println((int) ans);
    }

    static double fmod(double x) {
        return x - MODF * Math.floor(x / MODF);
    }

    static double modProd(double a, double b) {
        return fmod(Math.floor(a / SHRT) * fmod(b * SHRT) + (a - SHRT * Math.floor(a / SHRT)) * b);
    }

    static double fpow(double a, int b) {
        double r = 1.0;
        while (b > 0) {
            if ((b & 1) != 0) {
                r = modProd(r, a);
            }
            if (b > 1) {
                a = modProd(a, a);
            }
            b >>= 1;
        }
        return r;
    }

    static void nttTransform(double[] a) {
        int m = a.length;
        int m2 = m / 2;
        double[] w = new double[m2];
        w[1] = fpow(G, (MOD - 1) / m);
        for (int i = 2; i < m2; i++) {
            w[i] = modProd(w[i - 1], w[1]);
        }

        int[] rev = new int[m];
        for (int i = 0; i < m; i++) {
            rev[i] = rev[i >> 1] >> 1;
            if ((i & 1) != 0) {
                rev[i] |= m2;
            }
        }

        for (int i = 0; i < m; i++) {
            if (i < rev[i]) {
                double temp = a[i];
                a[i] = a[rev[i]];
                a[rev[i]] = temp;
            }
        }

        int l = 2;
        while (l <= m) {
            int half = l >> 1;
            int diff = m / l;
            for (int i = 0; i < m; i += l) {
                int pw = 0;
                for (int j = i; j < i + half; j++) {
                    double v = modProd(a[j + half], w[pw]);
                    a[j + half] = a[j] - v;
                    a[j] = a[j] + v;
                    pw += diff;
                }
            }
            l <<= 1;
        }
    }
}

