            for (Map.Entry<Integer, Integer> entry : dl[i].entrySet()) {
                int x = entry.getKey();
                int t = entry.getValue();
                for (int j = k - i; j <= k; j++) {
                    if (dr[j].containsKey(x)) {
                        ans += (long) t * dr[j].get(x);
                    }
                }
            }
        }
        System.out.println(ans);
    }

    private static Map<Integer, Integer>[][] f(int[] a, int start, int end, int k, int s) {
        Map<Integer, Integer>[][] res = new HashMap[k + 1][1];
        for (int i = 0; i <= k; i++) {
            res[i] = new HashMap<>();
        }
        res[k][0] = 1;

        for (int i = start; i < end; i++) {
            int x = a[i];
            Map<Integer, Integer>[][] nr = new HashMap[k + 1][1];
            for (int j = 0; j <= k; j++) {
                nr[j] = new HashMap<>();
            }

            for (int j = 0; j <= k; j++) {
                for (Map.Entry<Integer, Integer> entry : res[j].entrySet()) {
                    int y = entry.getKey();
                    int t = entry.getValue();

                    if (j > 0 && x <= 18 && factorial(x) + y <= s) {
                        nr[j - 1].put(factorial(x) + y, nr[j - 1].getOrDefault(factorial(x) + y, 0) + t);
                    }
                    if (x + y <= s) {
                        nr[j].put(x + y, nr[j].getOrDefault(x + y, 0) + t);
                    }
                    nr[j].put(y, nr[j].getOrDefault(y, 0) + t);
                }
            }
            res = nr;
        }
        return res;
