    private static Map<Integer, Integer>[][] g(int[] a, int start, int end, int k, int s) {
        Map<Integer, Integer>[][] res = new HashMap[k + 1][1];
        for (int i = 0; i <= k; i++) {
            res[i] = new HashMap<>();
        }
        res[k].put(s, 1);

        for (int i = start; i < end; i++) {
            int x = a[i];
            Map<Integer, Integer>[][] nr = new HashMap[k + 1][1];
            for (int j = 0; j <= k; j++) {
                nr[j] = new HashMap<>();
            }

            for (int j = 0; j <= k; j++) {
                for (Map.Entry<Integer, Integer> entry : res[j].entrySet()) {
                    int y = entry.getKey();
                    int t = entry.getValue();

                    if (j > 0 && x <= 18 && y - factorial(x) >= 0) {
                        nr[j - 1].put(y - factorial(x), nr[j - 1].getOrDefault(y - factorial(x), 0) + t);
                    }
                    if (y - x >= 0) {
                        nr[j].put(y - x, nr[j].getOrDefault(y - x, 0) + t);
                    }
                    nr[j].put(y, nr[j].getOrDefault(y, 0) + t);
                }
            }
            res = nr;
        }
        return res;
