        for (int i = 0; i < n; i++) {
            B.add(printMin(Arrays.copyOfRange(grid, i * m, (i + 1) * m), m, b));
        }

        double ans = 0.0;
        for (int i = 0; i < B.get(0).size(); i++) {
            List<Integer> temp = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                temp.add(B.get(j).get(i));
            }
            for (int tmp : printMin(temp, temp.size(), a)) {
                ans += tmp;
            }
        }
        out.println((int) ans);
        out.close();
    }

    private static List<Integer> printMin(int[] arr, int n, int k) {
        List<Integer> res = new ArrayList<>();
        Deque<Integer> Qi = new LinkedList<>();
        for (int i = 0; i < k; i++) {
            while (!Qi.isEmpty() && arr[i] <= arr[Qi.peekLast()]) {
                Qi.pollLast();
            }
            Qi.offerLast(i);
        }

        for (int i = k; i < n; i++) {
            res.add(arr[Qi.peekFirst()]);
            while (!Qi.isEmpty() && Qi.peekFirst() <= i - k) {
                Qi.pollFirst();
            }
            while (!Qi.isEmpty() && arr[i] <= arr[Qi.peekLast()]) {
                Qi.pollLast();
            }
            Qi.offerLast(i);
        }
        res.add(arr[Qi.peekFirst()]);
        return res;
    }

    private static int modMulAdd(int x, int y, int c, int z, double zinv) {
        long ans = (long) x * y + c - (long) (zinv * x * y + zinv * c) * z;
        if (ans >= z) {
            return (int) (ans - z);
        } else if (ans < 0) {
            return (int) (ans + z);
        } else {
            return (int) ans;
        }
    }

