        double zinv = 1.0 / z;

        int[] grid = new int[n * m];
        grid[0] = g;
        for (int i = 1; i < n * m; i++) {
            grid[i] = modMulAdd(grid[i - 1], x, y, z, zinv);
        }

        List<Integer>[] B = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            B[i] = printMin(Arrays.copyOfRange(grid, i * m, (i + 1) * m), m, b);
        }

        double ans = 0.0;
        for (int i = 0; i < B[0].size(); i++) {
            List<Integer> temp = new ArrayList<>();
            for (int j = 0; j < n; j++) {
