            System.out.println(modPow(n, n, MOD));
        } else {
            System.out.println(modPow(n, pairs, MOD));
        }
    }

    static void dfs(int n) {
        visited[n] = true;
        while (!visited[adj[n]]) {
            n = adj[n];
            visited[n] = true;
        }
    }

    static long modPow(long base, int exp, int mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

