            f[u] = true;
            while (!f[k[u]]) {
                u = k[u];
                f[u] = true;
                cnt++;
            }

            c[cnt]++;
        }

        for (int i = 1; i < P; i++) {
            if (c[i] != 0) {
                int cnt = i * c[i] + (i > 1 ? c[1] : 0);
                ans = (int) ((long) ans * power(cnt, c[i], M)) % M;
            }
        }

        System.out.println(ans);
    }

    private static int power(int base, int exp, int mod) {
        long result = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return (int) result;
