                    if (gg < maxPrime) {
                        gg = maxPrime;
                    }
                }
                b.add(gg);
                if (i == 9) {
                    b.add(2);
                    b.add(3);
                    b.add(3);
                } else {
                    for (int k = gg + 1; k <= i; k++) {
                        if (k == 6) {
                            b.add(3);
                        } else {
                            b.addAll(getPrimeFactors(k));
                        }
                    }
                }
            }
        }
        Collections.sort(b, Collections.reverseOrder());
        StringBuilder result = new StringBuilder();
        for (int num : b) {
            result.append(num);
        }
        System.out.println(result.toString());
    }

    private static int getMaxPrimeFactor(int n) {
        int maxPrime = -1;
        while (n % 2 == 0) {
            maxPrime = 2;
            n /= 2;
        }
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            while (n % i == 0) {
                maxPrime = i;
                n /= i;
            }
        }
        if (n > 2) {
            maxPrime = n;
        }
        return maxPrime;
    }

    private static List<Integer> getPrimeFactors(int n) {
        List<Integer> factors = new ArrayList<>();
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }
        if (n > 2) {
            factors.add(n);
        }
        return factors;
    }
}

