import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;
    private static final long[] fac = new long[2 * 100000 + 10];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        for (int i = 0; i < fac.length - 1; i++) {
            fac[i + 1] = fac[i] * (i + 1) % MOD;
        }
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        if (k == 0) {
            System.out.println(fac[n]);
        } else {
            k = n - k;
            if (k <= 0) {
                System.out.println(0);
                return;
            }
            long ans = 0;
            for (int i = 0; i <= k; i++) {
                long t = comb(k, i) * pow(k - i, n, MOD) % MOD;
                if (i % 2 != 0) {
                    ans -= t;
                } else {
                    ans += t;
                }
            }
            System.out.println(2 * ans * comb(n, k) % MOD);
        }
    }

    private static long comb(int n, int k) {
        return (fac[n] * pow(fac[n - k], MOD - 2, MOD) % MOD) * pow(fac[k], MOD - 2, MOD) % MOD;
    }

    private static long pow(long base, int exp, int mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % mod;
            }
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}

