        int m = scanner.nextInt();

        int[] c = new int[20];
        for (int bit = 1; bit < (1 << 20); bit++) {
            int bitcnt = 0;
            long L = 1;
            int mx = -1;
            int right = 1 << 30;
            int left = -1;
            for (int i = 0; i < 20; i++) {
                if ((bit & (1 << i)) != 0) {
                    bitcnt++;
                    mx = i;
                    left = i + 1;
                    right = Math.min(right, m * (i + 1));
                    if (L != -1) {
                        L = lcm(L, i + 1);
                        if (L > (1L << 28)) {
                            L = -1;
                        }
                    }
                }
            }
            if (L == -1) {
                continue;
            }
            if (bitcnt % 2 == 1) {
                c[mx] += Math.max(0, right / L - (left - 1) / L);
            } else {
                c[mx] -= Math.max(0, right / L - (left - 1) / L);
            }
        }

        for (int i = 1; i < 20; i++) {
            c[i] += c[i - 1];
        }

        boolean[] seen = new boolean[n + 1];
        seen[1] = true;
        int ans = 1;

        for (int i = 2; i <= n; i++) {
            if (seen[i]) {
                continue;
            }
            int tmp = 1;
            int now = i;
            seen[now] = true;
            while (now * i <= n) {
                tmp++;
                now *= i;
                seen[now] = true;
            }

            ans += c[tmp - 1];
        }

        System.out.println(ans);
    }

    public static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    public static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

