import java.util.*;

public class SonyaAndInformatics {

    private static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }
        BinomialDP binomDP = new BinomialDP();
        int P = solve(n, k, a, binomDP::calculate, MOD);
        if (P == 0) {
            System.out.println(0);
        } else {
            int Q = modPow(binomDP.calculate(n, 2), k, MOD);
            System.out.println((int) ((long) P * modInverse(Q, MOD) % MOD));
        }
    }

    private static int solve(int n, int k, int[] a, BiFunction<Integer, Integer, Integer> binom, int mod) {
        int ones = Arrays.stream(a).sum();
        int zeros = n - ones;
        int[][] M = new int[zeros + 1][zeros + 1];
        for (int row = Math.max(0, zeros - ones); row <= zeros; row++) {
            int preZeros = row;
            int preOnes = zeros - preZeros;
            int postZeros = preOnes;
            int postOnes = ones - preOnes;
            M[row][row] = (preOnes * postOnes + preZeros * postZeros + binom.apply(zeros, 2) + binom.apply(ones, 2)) % mod;
            if (row > Math.max(0, zeros - ones)) {
                M[row - 1][row] = (int) ((long) preZeros * postOnes % mod);
            }
            if (row < zeros) {
                M[row + 1][row] = (int) ((long) postZeros * preOnes % mod);
            }
        }
        M = new int[][]{matrixPow(M, k, mod)[M.length - 1]};
        int[] b = new int[zeros + 1];
        b[zeros - sum(a, 0, zeros)] = 1;
        int[] C = multiply(M, b, mod);
        return C[C.length - 1];
    }

    private static int[][] multiply(int[][] A, int[] B, int mod) {
        int[][] C = new int[A.length][B.length];
        for (int row = 0; row < A.length; row++) {
            for (int col = 0; col < B.length; col++) {
                long sum = 0;
                for (int k = 0; k < B.length; k++) {
                    sum += (long) A[row][k] * B[k];
                }
                C[row][col] = (int) (sum % mod);
            }
        }
        return C;
    }

    private static int[][] matrixPow(int[][] M, int n, int mod) {
        if (n == 2) {
            return multiply(M, M, mod);
        }
        if (n == 1) {
            return M;
        }
        int[][] subM = matrixPow(M, n / 2, mod);
        if (n % 2 == 0) {
            return multiply(subM, subM, mod);
        }
        return multiply(subM, matrixPow(M, n - n / 2, mod), mod);
    }

    private static int modPow(int base, int exp, int mod) {
        long result = 1;
        long baseLong = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * baseLong % mod;
            }
            baseLong = baseLong * baseLong % mod;
            exp >>= 1;
        }
        return (int) result;
    }

    private static int modInverse(int a, int m) {
        int[] result = egcd(a, m);
        if (result[0] != 1) {
            throw new IllegalArgumentException("modular inverse does not exist");
        } else {
            return (result[1] % m + m) % m;
        }
    }

    private static int[] egcd(int a, int b) {
        if (a == 0) {
            return new int[]{b, 0, 1};
        } else {
            int[] result = egcd(b % a, a);
            return new int[]{result[0], result[2] - (b / a) * result[1], result[1]};
        }
    }

    private static int sum(int[] array, int start, int end) {
        int sum = 0;
        for (int i = start; i < end; i++) {
            sum += array[i];
        }
        return sum;
    }

    @FunctionalInterface
    interface BiFunction<T, U, R> {
        R apply(T t, U u);
    }

    static class BinomialDP {
        private final int[][] dp;

        public BinomialDP() {
            this.dp = new int[110][110];
            for (int[] row : dp) {
                Arrays.fill(row, -1);
            }
        }

        public int calculate(int n, int k) {
            if (n < k) {
                return 0;
            }
            if (n == k || k == 0) {
                return 1;
            }
            if (dp[n][k] > 0) {
                return dp[n][k];
            } else {
                dp[n][k] = (calculate(n - 1, k - 1) + calculate(n - 1, k)) % MOD;
            }
            return dp[n][k];
        }
    }
}

