import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] disjointSet = new int[n];
        Arrays.fill(disjointSet, -1);

        for (int i = 0; i < n; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            points.add(new Point(a, b));
            if (vertPoints.containsKey(a)) {
                join(i, vertPoints.get(a), disjointSet);
            } else {
                vertPoints.put(a, i);
            }
            if (horizPoints.containsKey(b)) {
                join(i, horizPoints.get(b), disjointSet);
            } else {
                horizPoints.put(b, i);
            }
        }

        Map<Integer, List<Point>> sets = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int r = root(i, disjointSet);
            sets.computeIfAbsent(r, k -> new ArrayList<>()).add(points.get(i));
        }

        long ans = 1;
        for (List<Point> s : sets.values()) {
            Set<Integer> horiz = new HashSet<>();
            Set<Integer> vert = new HashSet<>();
            for (Point p : s) {
                horiz.add(p.x);
                vert.add(p.y);
            }
            int tmp = horiz.size() + vert.size();
            if (tmp <= s.size()) {
                ans = (ans * powerOfTwo(tmp)) % MOD;
            } else {
                ans = (ans * (powerOfTwo(tmp) - 1)) % MOD;
            }
        }

        System.out.println(ans);
    }

    private static int root(int x, int[] disjointSet) {
        List<Integer> dp = new ArrayList<>();
        while (disjointSet[x] >= 0) {
            dp.add(x);
            x = disjointSet[x];
        }
        for (int i : dp) {
            disjointSet[i] = x;
        }
        return x;
    }

    private static void join(int x, int y, int[] disjointSet) {
        int r1 = root(x, disjointSet);
        int r2 = root(y, disjointSet);
        if (r1 == r2) {
            return;
        }
        disjointSet[r2] = r1;
    }

    private static long powerOfTwo(int exp) {
        long result = 1;
        long base = 2;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static final int MOD = 1_000_000_007;
    static List<Point> points = new ArrayList<>();
    static Map<Integer, Integer> vertPoints = new HashMap<>();
    static Map<Integer, Integer> horizPoints = new HashMap<>();

    static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

