import java.math.BigInteger;
import java.util.Scanner;

class Fraction {
    private BigInteger numerator;
    private BigInteger denominator;

    public Fraction(BigInteger numerator, BigInteger denominator) {
        BigInteger gcd = numerator.gcd(denominator);
        this.numerator = numerator.divide(gcd);
        this.denominator = denominator.divide(gcd);
        if (this.denominator.compareTo(BigInteger.ZERO) < 0) {
            this.numerator = this.numerator.negate();
            this.denominator = this.denominator.negate();
        }
    }

    public Fraction(int numerator, int denominator) {
        this(BigInteger.valueOf(numerator), BigInteger.valueOf(denominator));
    }

    public Fraction subtract(Fraction other) {
        BigInteger newNumerator = this.numerator.multiply(other.denominator).subtract(this.denominator.multiply(other.numerator));
        BigInteger newDenominator = this.denominator.multiply(other.denominator);
        return new Fraction(newNumerator, newDenominator);
    }

    public boolean equals(Fraction other) {
        return this.numerator.equals(other.numerator) && this.denominator.equals(other.denominator);
    }

    @Override
    public String toString() {
        return numerator + "/" + denominator;
    }

    public boolean isBetweenZeroAndOne() {
        return numerator.compareTo(BigInteger.ZERO) > 0 && numerator.compareTo(denominator) < 0;
    }
}

public class Main {
    public static void main(String[] args) {
