                    long part2 = (power(k - j + 1, same * (i - 1 - same) + same * (same - 1) / 2, M) * comb(i - 1, same)) % M;
                    dp[i][j] += (part1 * part2) % M;
                    dp[i][j] %= M;
                }
            }
        }

        long result = 0;
        for (int j = 1; j <= k; j++) {
            result += dp[n][j];
            result %= M;
        }
        System.out.println(result);
    }

    static long power(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if (exp % 2 == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp /= 2;
        }
        return result;
    }

    static long fastfrac(long a, long b) {
        long numb = power(b, M - 2, M);
        return ((a % M) * (numb % M)) % M;
    }

    static long comb(int n, int k) {
        if (n < k) return 0;
        if (n == k) return 1;
        Pair key = new Pair(n, k);
        if (storecomb.containsKey(key)) return storecomb.get(key);

        long num1 = factor[n];
        long num2 = factor[k];
        long num3 = factor[n - k];
        long num = (num2 * num3) % M;
        long output = fastfrac(num1, num);
        storecomb.put(key, output);
        return output;
    }

    static class Pair {
        int n, k;

        Pair(int n, int k) {
            this.n = n;
            this.k = k;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair pair = (Pair) o;
            return n == pair.n && k == pair.k;
        }

        @Override
        public int hashCode() {
            return Objects.hash(n, k);
        }
    }
}

