                Min = Mid + 1;
            } else {
                Max = Mid;
            }
        }
        return (int) Min;
    }

    private static long loc(long x) {
        long p = x - 1;
        long doneUpto = (p + 1) / 2 - 1 + (p / 4) - 1;
        return valid(x) ? doneUpto + 1 : doneUpto;
    }

    private static boolean valid(long x) {
        return x % 4 == 0 || (x & 1) != 0;
    }

