import java.util.*;

public class Main {

    static class Dinic {
        private static final long INF = (long) 1e18;
        private int n;
        private List<int[]>[] links;
        private int[] depth;
        private int[] progress;
        private List<int[]> pos;

        public Dinic(int n) {
            this.n = n;
            links = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                links[i] = new ArrayList<>();
            }
            depth = new int[n];
            progress = new int[n];
            pos = new ArrayList<>();
        }

        public void addEdge(int from, int to, int cap) {
            pos.add(new int[]{from, links[from].size()});
            links[from].add(new int[]{cap, to, links[to].size()});
            links[to].add(new int[]{0, from, links[from].size() - 1});
        }

        private void bfs(int s) {
            Arrays.fill(depth, -1);
            depth[s] = 0;
            Queue<Integer> queue = new LinkedList<>();
            queue.offer(s);
            while (!queue.isEmpty()) {
                int v = queue.poll();
                for (int[] link : links[v]) {
                    int cap = link[0];
                    int to = link[1];
                    if (cap > 0 && depth[to] < 0) {
                        depth[to] = depth[v] + 1;
                        queue.offer(to);
                    }
                }
            }
        }

        private int dfs(int v, int t, int flow) {
            if (v == t) {
                return flow;
            }
            List<int[]> linksV = links[v];
            for (int i = progress[v]; i < linksV.size(); i++) {
                progress[v] = i;
                int[] link = linksV.get(i);
                int cap = link[0];
                int to = link[1];
                if (cap == 0 || depth[v] >= depth[to]) {
                    continue;
                }
                int d = dfs(to, t, Math.min(flow, cap));
                if (d == 0) {
                    continue;
                }
                link[0] -= d;
                links[to].get(link[2])[0] += d;
                return d;
            }
            return 0;
        }

        public long flow(int s, int t) {
            long flow = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0) {
                    return flow;
                }
                Arrays.fill(progress, 0);
                int currentFlow;
                while ((currentFlow = dfs(s, t, (int) INF)) > 0) {
                    flow += currentFlow;
                }
            }
        }

        public int[] getEdge(int i) {
            int[] e = links[pos.get(i)[0]].get(pos.get(i)[1]);
            int[] re = links[e[1]].get(e[2]);
            // from, to, cap, flow
            return new int[]{pos.get(i)[0], e[1], e[0] + re[0], re[0]};
        }

        public List<int[]> getEdges() {
            List<int[]> res = new ArrayList<>();
            for (int i = 0; i < pos.size(); i++) {
                res.add(getEdge(i));
            }
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int M = 3;
        int[] A = new int[M];
        int[] B = new int[M];
        for (int i = 0; i < M; i++) {
            A[i] = scanner.nextInt();
        }
        for (int i = 0; i < M; i++) {
            B[i] = scanner.nextInt();
        }

        int ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A[i], B[(i + 1) % M]);
        }

        int ans2 = 0;
        Dinic dinic = new Dinic(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;
        for (int i = 0; i < M; i++) {
            // s to Alice
            dinic.addEdge(s, i, N);
            // Bob to t
            dinic.addEdge(M + i, t, B[i]);
            // draw
            dinic.addEdge(i, M + i, A[i]);
            // Alice lose
            dinic.addEdge(i, M + (i - 1 + M) % M, A[i]);
        }
        ans2 = N - (int) dinic.flow(s, t);

        System.out.println(ans2 + " " + ans1);
    }
}

