import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    private static final int MOD = 1000000007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[] mem = new int[201];
        for (int i = 0; i < mem.length; i++) {
            mem[i] = -1;
        }

        List<Integer> sequence = new ArrayList<>();
        for (int i = 0; i < 201; i++) {
            sequence.add(DP(i, m, mem));
        }

        System.out.println(extrapolate(sequence, n) % MOD);
    }

    private static int DP(int n, int m, int[] mem) {
        if (n <= 0 || m == 1) {
            return n < 0 ? 0 : 1;
        }
        if (mem[n] < 0) {
            mem[n] = (DP(n - 1, m, mem) + DP(n - m, m, mem)) % MOD;
        }
        return mem[n];
    }

    private static List<Integer> polysub(List<Integer> P, List<Integer> Q) {
        int n = P.size();
        int m = Q.size();
        List<Integer> W = new ArrayList<>(Math.max(m, n));
        for (int i = 0; i < Math.max(m, n); i++) {
            W.add(0);
        }
        for (int i = 0; i < n; i++) {
            W.set(i, (W.get(i) + P.get(i)) % MOD);
        }
        for (int i = 0; i < m; i++) {
            W.set(i, (W.get(i) - Q.get(i) + MOD) % MOD);
        }
        while (!W.isEmpty() && W.get(W.size() - 1) == 0) {
            W.remove(W.size() - 1);
        }
        return W;
    }

    private static List<Integer> polydiv(List<Integer> P, List<Integer> Q) {
        List<Integer> q = new ArrayList<>(Q);
        while (!q.isEmpty() && q.get(q.size() - 1) % MOD == 0) {
            q.remove(q.size() - 1);
        }
        assert !q.isEmpty() && q.get(q.size() - 1) % MOD > 0;
        List<Integer> p = new ArrayList<>(P);
        List<Integer> ans = new ArrayList<>();
        int n = q.size();
        while (p.size() >= n) {
            int pLast = p.get(p.size() - 1);
            int qLast = q.get(q.size() - 1);
            int coeff = (int) ((long) pLast * modInverse(qLast, MOD)) % MOD;
            ans.add(coeff);
            for (int i = 0; i < n; i++) {
                p.set(p.size() - i - 1, (p.get(p.size() - i - 1) - (coeff * q.get(q.size() - i - 1)) % MOD + MOD) % MOD);
            }
            assert p.get(p.size() - 1) % MOD == 0;
            p.remove(p.size() - 1);
        }
        ans = reverse(ans);
        while (!ans.isEmpty() && ans.get(ans.size() - 1) == 0) {
            ans.remove(ans.size() - 1);
        }
        return ans;
    }

    private static List<Integer> polymod(List<Integer> P, List<Integer> Q) {
        List<Integer> q = new ArrayList<>(Q);
        while (!q.isEmpty() && q.get(q.size() - 1) % MOD == 0) {
            q.remove(q.size() - 1);
        }
        assert !q.isEmpty() && q.get(q.size() - 1) % MOD > 0;
        List<Integer> p = new ArrayList<>(P);
        int n = q.size();
        while (p.size() >= n) {
            int pLast = p.get(p.size() - 1);
            int qLast = q.get(q.size() - 1);
            int coeff = (int) ((long) pLast * modInverse(qLast, MOD)) % MOD;
            for (int i = 0; i < n; i++) {
                p.set(p.size() - i - 1, (p.get(p.size() - i - 1) - (coeff * q.get(q.size() - i - 1)) % MOD + MOD) % MOD);
            }
            assert p.get(p.size() - 1) % MOD == 0;
            p.remove(p.size() - 1);
        }
        for (int i = 0; i < p.size(); i++) {
            p.set(i, p.get(i) % MOD);
        }
        return p;
    }

    private static List<Integer> polyprod(List<Integer> P, List<Integer> Q) {
        int n = P.size();
        int m = Q.size();
        List<Integer> W = new ArrayList<>(n + m - 1);
        for (int i = 0; i < n + m - 1; i++) {
            W.add(0);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                W.set(i + j, (W.get(i + j) + (P.get(i) * Q.get(j)) % MOD) % MOD);
            }
        }
        return W;
    }

    private static List<Integer> polyxgcd(List<Integer> P, List<Integer> Q) {
        if (P.size() <= 1) {
            return new ArrayList<>(List.of(Q.get(0), 0, 1));
        }
        List<Integer> gcdXY = polyxgcd(polymod(Q, P), P);
        List<Integer> g = new ArrayList<>(List.of(gcdXY.get(0)));
        List<Integer> x = new ArrayList<>(List.of(gcdXY.get(2)));
        List<Integer> y = polysub(new ArrayList<>(List.of(gcdXY.get(1))), polyprod(polydiv(Q, P), x));
        return new ArrayList<>(List.of(g.get(0), y.get(0), x.get(0)));
    }

    private static List<Integer> power(List<Integer> A, List<Integer> B, int m, Multiplier mult) {
        if (m == 0) {
            return B;
        }
        while (m > 1) {
            if (m % 2 == 1) {
                B = mult.multiply(A, B);
            }
            A = mult.multiply(A, A);
            m /= 2;
        }
        return mult.multiply(A, B);
    }

    private static int calcNthTerm(List<Integer> init, List<Integer> linearCoeff, int n) {
        Multiplier mult = (A, B) -> polymod(polyprod(A, B), linearCoeff);
        List<Integer> ans = power(List.of(0, 1), List.of(1), n, mult);
        int result = 0;
        for (int i = 0; i < ans.size(); i++) {
            result = (result + (ans.get(i) * init.get(i)) % MOD) % MOD;
        }
        return result;
    }

    private static int extrapolate(List<Integer> seq, int n) {
        List<Integer> twom = new ArrayList<>();
        for (int i = 0; i <= seq.size(); i++) {
            twom.add(0);
        }
        twom.set(twom.size() - 1, 1);
        List<Integer> gcdXY = polyxgcd(seq, twom);
        List<Integer> C = new ArrayList<>(gcdXY.subList(1, gcdXY.size()));
        while (!C.isEmpty() && C.get(C.size() - 1) % MOD == 0) {
            C.remove(C.size() - 1);
        }
        int invc = modInverse(C.get(0), MOD);
        for (int i = 0; i < C.size(); i++) {
            C.set(i, (int) ((long) C.get(i) * invc) % MOD);
        }
        C = reverse(C);
        return calcNthTerm(seq, C, n);
    }

    private static int modInverse(int a, int m) {
        int m0 = m, t, q;
        int x0 = 0, x1 = 1;
        if (m == 1) {
            return 0;
        }
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m;
            a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) {
            x1 += m0;
        }
        return x1;
    }

    private static List<Integer> reverse(List<Integer> list) {
        List<Integer> reversed = new ArrayList<>(list);
        int left = 0, right = reversed.size() - 1;
        while (left < right) {
            int temp = reversed.get(left);
            reversed.set(left, reversed.get(right));
            reversed.set(right, temp);
            left++;
            right--;
        }
        return reversed;
    }

    interface Multiplier {
        List<Integer> multiply(List<Integer> A, List<Integer> B);
    }
}

