        for (int[][] order : new int[][][]{
            {A[0], A[1], A[2], A[3]},
            {A[0], A[2], A[1], A[3]},
            {A[0], A[1], A[3], A[2]},
            {A[0], A[2], A[3], A[1]},
            {A[0], A[3], A[1], A[2]},
            {A[0], A[3], A[2], A[1]},
        }) {
            int[][] sides = {
                vectorDiff(order[0], order[1]),
                vectorDiff(order[1], order[2]),
                vectorDiff(order[2], order[3]),
                vectorDiff(order[3], order[0]),
            };
            if (Arrays.stream(sides).allMatch(s -> scalarProduct(s, sides[(Arrays.asList(sides).indexOf(s) + 1) % sides.length]) == 0)) {
                return true;
            }
        }
        return false;
    }

    public static boolean checkSquare(int[][] points) {
        if (!checkRectangle(points)) {
            return false;
        }

        int[][] A = points;

        for (int[][] order : new int[][][]{
            {A[0], A[1], A[2], A[3]},
            {A[0], A[2], A[1], A[3]},
            {A[0], A[1], A[3], A[2]},
            {A[0], A[2], A[3], A[1]},
            {A[0], A[3], A[1], A[2]},
            {A[0], A[3], A[2], A[1]},
        }) {
            int[] sideLengths = new int[4];
            for (int i = 0; i < 4; i++) {
                int[] first = order[i];
                int[] next = order[(i + 1) % 4];
                sideLengths[i] = (first[0] - next[0]) * (first[0] - next[0]) + (first[1] - next[1]) * (first[1] - next[1]);
            }
            if (new HashSet<>(Arrays.asList(sideLengths)).size() == 1) {
                return true;
            }
        }
        return false;
    }

    public static boolean checkRight(int[][] p) {
        if (Arrays.deepEquals(p[0], p[1]) || Arrays.deepEquals(p[0], p[2]) || Arrays.deepEquals(p[1], p[2])) {
            return false;
        }

        int[] a = vectorDiff(p[0], p[1]);
        int[] b = vectorDiff(p[1], p[2]);
        int[] c = vectorDiff(p[2], p[0]);

        return scalarProduct(a, b) * scalarProduct(a, c) * scalarProduct(b, c) == 0;
    }

