        if (m1 != m2) {
            throw new AssertionError("Matrix dimensions do not match for multiplication");
        }

        int[][] r = new int[n][k];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < k; j++) {
                for (int l = 0; l < m1; l++) {
                    r[i][j] += a[i][l] * b[l][j];
