                    eLen = (int) (((long) eLen + (long) f(ele, i / ele) * expectedLen.get(ele) % MOD * inv[n]) % MOD);
                }
            }
            eLen = (int) ((((long) eLen + 1) * n % MOD * inv[n - f(i, 1)] % MOD) % MOD);
