import java.util.*;
import java.io.*;

public class Main {
    static final long INF = 999999999999999999999999L;
    static final long MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        if (n == 1) {
            System.out.println(0);
            return;
        }

        List<Integer> fac_ = primeFactorize(n);
        Map<Integer, Integer> fac = countFactors(fac_);
        long ans = 0;
        for (Map.Entry<Integer, Integer> entry : fac.entrySet()) {
            int p = entry.getKey();
            int e = entry.getValue();
            int x = e;
            for (int i = 1; i < 100000000; i++) {
                if (x >= i) {
                    x -= i;
                    ans++;
                } else {
                    break;
                }
            }
        }
        System.out.println(ans);
    }

    private static List<Integer> primeFactorize(int n) {
        List<Integer> a = new ArrayList<>();
        while (n % 2 == 0) {
            a.add(2);
            n /= 2;
        }
        int f = 3;
        while (f * f <= n) {
            if (n % f == 0) {
                a.add(f);
                n /= f;
            } else {
                f += 2;
            }
        }
        if (n != 1) {
            a.add(n);
        }
        return a;
    }

    private static Map<Integer, Integer> countFactors(List<Integer> factors) {
        Map<Integer, Integer> fac = new HashMap<>();
        for (int factor : factors) {
            fac.put(factor, fac.getOrDefault(factor, 0) + 1);
        }
        return fac;
    }
}

