public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] dimensions = scanner.nextLine().split(" ");
        int h = Integer.parseInt(dimensions[0]);
        int w = Integer.parseInt(dimensions[1]);

        int[][] graph = new int[h][w];
        for (int i = 0; i < h; i++) {
            char[] row = scanner.nextLine().toCharArray();
            for (int j = 0; j < w; j++) {
                graph[i][j] = row[j] == '#' ? 0 : Integer.MAX_VALUE;
            }
        }

        // Process each column from left to right
        for (int x = 0; x < w - 1; x++) {
            for (int y = 0; y < h; y++) {
                graph[y][x + 1] = Math.min(graph[y][x] + 1, graph[y][x + 1]);
            }
        }

        // Process each column from right to left
        for (int x = w - 1; x > 0; x--) {
            for (int y = 0; y < h; y++) {
                graph[y][x - 1] = Math.min(graph[y][x] + 1, graph[y][x - 1]);
            }
        }

        // Process each row from top to bottom
        for (int y = 0; y < h - 1; y++) {
            for (int x = 0; x < w; x++) {
                graph[y + 1][x] = Math.min(graph[y][x] + 1, graph[y + 1][x]);
            }
        }

        // Process each row from bottom to top
        for (int y = h - 1; y > 0; y--) {
            for (int x = 0; x < w; x++) {
                graph[y - 1][x] = Math.min(graph[y][x] + 1, graph[y - 1][x]);
            }
        }

        int maxDistance = 0;
        for (int[] row : graph) {
            for (int value : row) {
                maxDistance = Math.max(maxDistance, value);
            }
        }

        System.out.println(maxDistance);

        scanner.close();
    }
}

