import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Integer> nums = Arrays.stream(scanner.nextLine().trim().split(" "))
                                   .map(Integer::parseInt)
                                   .map(num -> num - 1)
                                   .toList();

        boolean noOne = !nums.contains(1);

        if (noOne) {
            nums.replaceAll(num -> num / 2);
        }

        boolean isOdd = false;
        for (int i = 0; i < nums.size(); i++) {
            if (!parityOfNCR(n - 1, i) && (nums.get(i) & 1) != 0) {
                isOdd ^= true;
            }
        }

        if (!isOdd) {
            System.out.println(0);
        } else {
            System.out.println(1 << noOne ? 1 : 0);
        }
    }

    private static int twosInFactorial(int n) {
        return n - Integer.bitCount(n);
    }

    private static boolean parityOfNCR(int n, int i) {
        int f = twosInFactorial(n);
        return f - twosInFactorial(n - i) - twosInFactorial(i) > 0;
    }
}

