public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        String[] vInput = scanner.nextLine().split(" ");
        int[] v = new int[n];
        for (int i = 0; i < n; i++) {
            v[i] = Integer.parseInt(vInput[i]);
        }

        List<Integer> ve = new ArrayList<>();
        List<Integer> vo = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            ve.add(v[2 * i]);
            vo.add(v[2 * i + 1]);
        }

        Map<Integer, Long> ce = new HashMap<>();
        for (int num : ve) {
            ce.put(num, ce.getOrDefault(num, 0L) + 1);
        }

        Map<Integer, Long> co = new HashMap<>();
        for (int num : vo) {
            co.put(num, co.getOrDefault(num, 0L) + 1);
        }

        int ans = n;
        List<Map.Entry<Integer, Long>> ceEntries = new ArrayList<>(ce.entrySet());
        Collections.sort(ceEntries, Comparator.comparing(Map.Entry::getValue).reversed());
        List<Map.Entry<Integer, Long>> coEntries = new ArrayList<>(co.entrySet());
        Collections.sort(coEntries, Comparator.comparing(Map.Entry::getValue).reversed());

