        int W = Integer.parseInt(line[1]);

        line = br.readLine().split(" ");
        int si = Integer.parseInt(line[0]) - 1;
        int sj = Integer.parseInt(line[1]) - 1;

        line = br.readLine().split(" ");
        int ti = Integer.parseInt(line[0]) - 1;
        int tj = Integer.parseInt(line[1]) - 1;

        int[][] S = new int[H][W];
        for (int i = 0; i < H; i++) {
            line = br.readLine().split("");
            for (int j = 0; j < W; j++) {
                S[i][j] = line[j].equals("#") ? 1 : 0;
            }
        }

        int[][] D = new int[H][W];
        for (int i = 0; i < H; i++) {
            Arrays.fill(D[i], -1);
        }

        Deque<int[]> que = new ArrayDeque<>();
        que.addLast(new int[]{0, si, sj});
        while (!que.isEmpty()) {
            int[] current = que.pollFirst();
            int c = current[0];
            int i = current[1];
            int j = current[2];

            if (D[i][j] != -1) {
                continue;
            }
            D[i][j] = c;

            for (int di = -2; di <= 2; di++) {
                for (int dj = -2; dj <= 2; dj++) {
                    int ni = i + di;
                    int nj = j + dj;

                    if (!(0 <= ni && ni < H && 0 <= nj && nj < W) ||
                            D[ni][nj] != -1 || ni == nj && ni == 0 || S[ni][nj] == 1) {
                        continue;
                    }

                    if ((di == 0 && Math.abs(dj) == 1) || (dj == 0 && Math.abs(di) == 1)) {
                        que.addFirst(new int[]{c, ni, nj});
                    } else {
                        que.addLast(new int[]{c + 1, ni, nj});
                    }
                }
            }
        }

        bw.write(String.valueOf(D[ti][tj]));
        bw.newLine();
        bw.flush();

        bw.close();
        br.close();
    }
}

