        int n = scanner.nextInt();

        int[][] F = new int[n][10];
        int[][] P = new int[n][1000]; // Adjusted size based on maximum possible sum of F

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 10; j++) {
                F[i][j] = scanner.nextInt();
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 1000; j++) { // Adjusted size based on maximum possible sum of F
                P[i][j] = scanner.nextInt();
            }
        }

        long ans = Long.MIN_VALUE;

        for (int i = 1; i < 1 << 10; i++) {
            long tmp = 0;
            int[] lst = new int[n];
            for (int j = 0; j < 10; j++) { // Time slot
                if ((i >> j) & 1 == 1) { // Opened this time slot
                    for (int k = 0; k < n; k++) {
                        lst[k] += F[k][j];
                    }
                }
            }
            for (int k = 0; k < n; k++) {
                tmp += P[k][lst[k]];
            }
            ans = Math.max(ans, tmp);
        }

        System.out.println(ans);
    }
