import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        List<Boolean> s = new ArrayList<>();
        String line = scanner.nextLine();
        for (char c : line.toCharArray()) {
            s.add(c == '1');
        }
        int m = s.size();
        List<List<Integer>> z = new ArrayList<>();
        z.add(List.of(0, 0));
        for (boolean c : s) {
            int ind = z.get(z.size() - 1).get((int) c);
            z.get(z.size() - 1).set((int) c, z.size());
            z.add(new ArrayList<>(z.get(ind)));
        }
        assert z.size() == m + 1;
        z.get(m).set(0, m); // make it sticky
        z.get(m).set(1, m);

        // how many things match directly
        int[] dp = new int[m + 1];
        dp[0] = 1;
        for (int i = 0; i < n; i++) {
            int[] ndp = new int[m + 1];
            for (int j = 0; j <= m; j++) {
                ndp[z.get(j).get((int) s.get(i))]++;
            }
            dp = ndp;
        }
        int res = dp[m];

        for (int k = 1; k < m; k++) {
            int s0 = 0;
            for (int j = s.size() - k; j < s.size(); j++) {
                s0 = z.get(s0).get((int) s.get(j));
            }
            dp = new int[m + 1];
            dp[s0] = 1;
            for (int i = 0; i < n - k; i++) {
                int[] ndp = new int[m + 1];
                for (int j = 0; j <= m; j++) {
                    ndp[z.get(j).get((int) s.get(i))]++;
                }
                dp = ndp;
            }
            for (int s1 = 0; s1 < m; s1++) { // skip m
                int v = dp[s1];
                for (int j = s.size() - k; j < s.size(); j++) {
                    if (s1 == m) v = 0;
                    s1 = z.get(s1).get((int) s.get(j));
                }
                if (s1 == m) res += v;
            }
        }
        System.out.println(res);
    }
}

