import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        int x = Integer.parseInt(input[0]);
        int n = Integer.parseInt(input[1]);

        ArrayList<Integer> prime = primeFactors(x);

        long MOD = 1000000007;
        long ans = 1;
        for (int num : prime) {
            long p = 0;
            long tmp = num;
            while (tmp <= n) {
                p += n / tmp;
                tmp *= num;
            }
            ans = (ans * power(num, p, MOD)) % MOD;
        }

        System.out.println(ans);
    }

    private static ArrayList<Integer> primeFactors(int x) {
        ArrayList<Integer> ans = new ArrayList<>();
        int i = 2;
        while (i * i <= x) {
            if (x % i == 0) {
                ans.add(i);
                while (x % i == 0) {
                    x /= i;
                }
            }
            i++;
        }
        if (x > 1) {
            ans.add(x);
        }
        return ans;
    }

    private static long power(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

