public class Main {
    private static final int MOD = (int) 1e9 + 7;
    private static final int CMOD = 998244353;
    private static final double INF = Double.POSITIVE_INFINITY;
    private static final double NINF = Double.NEGATIVE_INFINITY;
    private static final int MAXN = (int) 1e5 + 5;
    private static int[] spf = new int[MAXN];
    private static boolean[] prime = new boolean[MAXN];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int x = scanner.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        long[] cnt = new long[n];
        int k = x;
        for (int i = n - 1; i >= 0; i--) {
            int p = 1 << i;
            cnt[i] += k / p;
            k %= p;
        }

        long[] mnt = Arrays.copyOf(a, n);
        for (int i = 1; i < n; i++) {
            mnt[i] = Math.min(2 * mnt[i - 1], mnt[i]);
        }
