            ans += mnt[i] * cnt[i];
        }

        long thisVal = 0;
        for (int i = n - 1; i >= 0; i--) {
            thisVal += (cnt[i] + 1) * mnt[i];
            ans = Math.min(ans, thisVal);
            thisVal -= mnt[i];
        }
        System.out.println(ans);
    }

    private static void spfSieve() {
