    private static long inv(long a, int p) {
        long s = 1;
        long n = p - 2;
        while (n != 0) {
            if ((n & 1) == 1) {
                s = (s * a) % p;
            }
            a = (a * a) % p;
            n >>= 1;
        }
        return s;
    }
}

