import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    private static final BigInteger MOD = new BigInteger("998244353");

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int x = scanner.nextInt();
        System.out.println(solve(n, x));
    }

    private static BigInteger[] factorialAndInverseFactorial(int n, BigInteger mod) {
        BigInteger[] fact = new BigInteger[n + 1];
        BigInteger[] rFact = new BigInteger[n + 1];

        fact[0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1].multiply(BigInteger.valueOf(i)).mod(mod);
            rFact[i] = fact[i].modInverse(mod);
        }
        return new BigInteger[]{fact, rFact};
    }

    private static BigInteger binomial(int n, int k, BigInteger[] fact, BigInteger[] rFact) {
        return fact[n]
                .multiply(rFact[k])
                .multiply(rFact[n - k])
                .mod(MOD);
    }

    @SuppressWarnings("unchecked")
    private static BigInteger memo[][] = new BigInteger[1001][1001];

    private static BigInteger solve(int n, int x) {
        if (memo[n][x] != null)
            return memo[n][x];

        if (n == 1)
            return BigInteger.ZERO;
        if (x < n)
            return BigInteger.valueOf(x).pow(n).mod(MOD);

        BigInteger result = BigInteger.valueOf(n - 1).pow(n).mod(MOD);
        for (int i = 0; i < n - 1; i++)
            result = result.add(
                    factorialAndInverseFactorial(n, MOD)[0]
                            .multiply(factorialAndInverseFactorial(n, MOD)[1][i])
                            .multiply(factorialAndInverseFactorial(n, MOD)[1][n - i])
                            .multiply(BigInteger.valueOf(n - 1).pow(i).mod(MOD))
                            .multiply(solve(n - i, x - n + 1)))
                    .mod(MOD);

        memo[n][x] = result;
        return result;
    }
}

