                List<Integer> temp = new ArrayList<>();
                temp.add(a);
                graph.put(b, temp);
            }
        }

        int k = Integer.parseInt(scanner.nextLine());
        String[] wayStr = scanner.nextLine().split(" ");
        int[] way = new int[k];
        for (int i = 0; i < k; i++) {
            way[i] = Integer.parseInt(wayStr[i]) - 1;
        }

        Deque<Integer> bfs = new ArrayDeque<>();
        bfs.offerLast(way[k - 1]);
        int[] lvl = new int[n];
        Arrays.fill(lvl, -1);
        int[] ans = new int[n];
        boolean[][] a = new boolean[n][n];

        lvl[way[k - 1]] = 0;

        while (!bfs.isEmpty()) {
            int v = bfs.pollFirst();
            for (int u : graph.getOrDefault(v, Collections.emptyList())) {
                if (lvl[u] == -1) {
                    lvl[u] = lvl[v] + 1;
                    a[u][v] = true;
                    bfs.offerLast(u);
                } else if (lvl[u] == lvl[v] + 1) {
                    ans[u] = 1;
                    a[u][v] = true;
                }
            }
        }

        int ansv = 0;
