        for (int v = 0; v < k - 1; v++) {
            if ((k - v - 1 != lvl[way[v]]) && !a[way[v]][way[v + 1]]) {
                ans1++;
            } else if (k - v - 1 == lvl[way[v]]) {
                break;
            }
        }

        for (int v = 0; v < k - 1; v++) {
            if (ans[way[v]] || !a[way[v]][way[v + 1]]) {
                ansv++;
            }
        }

        System.out.println(ans1 + " " + ansv);
    }
