public class Main {
    private static final int BUFSIZE = 8192;
    private static FastIO fastIO;

    public static void main(String[] args) throws IOException {
        fastIO = new FastIO(System.in, System.out);
        int n = fastIO.nextInt();
        Map<Integer, Integer> d = new HashMap<>();
        Map<Integer, Integer> d1 = new HashMap<>();
        int m = 0, m1 = 0, mi = 9999999999999999999L, mi1 = 9999999999999999999L;
        List<int[]> l = new ArrayList<>();
        for (int i = 0; i < 4 * n + 1; i++) {
            int a = fastIO.nextInt(), b = fastIO.nextInt();
            l.add(new int[]{a, b});
            m = Math.max(m, a);
            mi = Math.min(mi, a);
            m1 = Math.max(m1, b);
            mi1 = Math.min(mi1, b);
            d.merge(a, 1, Integer::sum);
            d1.merge(b, 1, Integer::sum);
        }
        if (d.getOrDefault(m, 0) == 1) {
            doi(m, l, 0);
        } else if (d.getOrDefault(mi, 0) == 1) {
            doi(mi, l, 0);
        } else if (d1.getOrDefault(mi1, 0) == 1) {
            doi(mi1, l, 1);
        } else if (d1.getOrDefault(m1, 0) == 1) {
            doi(m1, l, 1);
        } else {
            int x1 = m, x2 = mi, y1 = m1, y2 = mi1;
            for (int[] arr : l) {
                int a = arr[0], b = arr[1];
                if ((a == x1 && y2 <= b && b <= y1) || (a == x2 && y2 <= b && b <= y1) ||
                    (b == y1 && x2 <= a && a <= x1) || (b == y2 && x2 <= a && a <= x1)) {
                    continue;
                } else {
                    fastIO.println(a + " " + b);
                    break;
                }
            }
        }
    }

    private static void doi(int it, List<int[]> l, int t) {
        for (int[] arr : l) {
            if (arr[t] == it) {
                fastIO.println(arr[0] + " " + arr[1]);
                return;
            }
        }
    }

    static class FastIO extends FilterInputStream {
        private byte[] buffer = new byte[BUFSIZE];
        private int bytesRead, bufferPointer;

        public FastIO(InputStream inputStream, OutputStream outputStream) {
            super(inputStream);
        }

        @Override
        public int read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = in.read(buffer);
                bufferPointer = 0;
            }
            return bytesRead > 0 ? buffer[bufferPointer++] & 0xFF : -1;
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int ch;
            while ((ch = read()) != -1 && ch != '\n') {
                sb.append((char) ch);
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            int result = 0;
            boolean negative = false;
            int c = read();
            while (c <= ' ') {
                c = read();
            }
            if (c == '-') {
                negative = true;
                c = read();
            }
            do {
                result = result * 10 + (c - '0');
                c = read();
            } while (c >= '0' && c <= '9');
            return negative ? -result : result;
        }

        public void println(String str) throws IOException {
            out.print(str);
            out.newLine();
        }
    }
}

