import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<List<Integer>> cube = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            cube.add(new ArrayList<>());
            for (Integer num : Arrays.asList(scanner.nextLine().split(" "))) {
                cube.get(i).add(num);
            }
        }

        List<Integer> nums = new ArrayList<>();

        for (List<Integer> list : cube) {
            for (Integer i : list) {
                nums.add(i);
            }
        }

        if (n == 2) {
            permuteTwo(nums, cube);
        } else if (n == 3) {
            permuteThree(nums, cube);
        }

        boolean check = true;
        int i = 1;
        while (check) {
            if (!nums.contains(i)) {
                System.out.println(i - 1);
                check = false;
            }
            i++;
        }
    }

    private static void permuteTwo(List<Integer> nums, List<List<Integer>> cube) {
        String[] perms = {"01", "02", "10", "12", "20", "21"};
        for (String perm : perms) {
            for (int a : cube.get(Integer.parseInt(perm.substring(0, 1)))) {
                for (int b : cube.get(Integer.parseInt(perm.substring(1, 2)))) {
                    if (a != 0) {
                        nums.add(a * 10 + b);
                    }
                }
            }
        }
    }

    private static void permuteThree(List<Integer> nums, List<List<Integer>> cube) {
        String[] perms = {"012", "013", "021", "023", "031", "032", "102", "103", "120", "123", "130", "132", "201", "203", "210", "213", "230", "231", "301", "302", "310", "312", "320", "321"};
        for (String perm : perms) {
            for (int a : cube.get(Integer.parseInt(perm.substring(0, 1)))) {
                for (int b : cube.get(Integer.parseInt(perm.substring(1, 2)))) {
                    for (int c : cube.get(Integer.parseInt(perm.substring(2, 3)))) {
                        if (a != 0 && b != 0 && c != 0) {
                            nums.add(a * 100 + b * 10 + c);
                        }
                    }
                }
            }
        }
    }
}

