import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int T = scanner.nextInt();
        List<Integer> array = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            array.add(scanner.nextInt());
        }
        if (T <= n + 1) {
            System.out.println(LIS(array.stream().flatMapToInt(List::stream).toArray()));
        } else {
            List<Integer> newArray = repeatArray(array, n);
            List<Integer> lis = LIS(newArray.stream().flatMapToInt(List::stream).toArray());
            newArray.addAll(array);
            List<Integer> newLis = LIS(newArray.stream().flatMapToInt(List::stream).toArray());
            System.out.println(newLis.size() + (newLis.size() - lis.size()) * (T - n - 1));
        }
    }

    private static List<Integer> repeatArray(List<Integer> array, int times) {
        List<Integer> result = new ArrayList<>(array);
        for (int i = 1; i < times; i++) {
            result.addAll(array);
        }
        return result;
    }

    private static int LIS(int[] arr) {
        List<Integer> L = new ArrayList<>();
        L.add(arr[0]);
        for (int a : Arrays.copyOfRange(arr, 1, arr.length)) {
            if (a >= L.get(L.size() - 1)) {
                L.add(a);
            } else {
                int pos = Collections.binarySearch(L, a);
                if (pos < 0) {
                    pos = ~pos;
                }
                L.set(pos, a);
            }
        }
        return L.size();
    }
}

