public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int S = scanner.nextInt();

        ArrayList<Integer> a = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            a.add(scanner.nextInt());
        }

        HashSet<Integer> aset = new HashSet<>(a);
        List<Integer> alist = new ArrayList<>(aset);
        Collections.sort(alist);

        List<List<int[]>> oplist = new ArrayList<>();
        for (int i : alist) {
            List<int[]> tlist = new ArrayList<>();
            if (i > 18) {
                for (int j = 0; j <= a.lastIndexOf(i); j++) {
                    tlist.add(new int[]{j * i, 0, comb(a.lastIndexOf(i), j)});
                }
            } else {
                int xfact = factorial(i);
                for (int nf = 0; nf <= a.lastIndexOf(i); nf++) {
                    for (int ii = nf; ii <= a.lastIndexOf(i); ii++) {
                        tlist.add(new int[]{nf * xfact + (ii - nf) * i, nf, comb(a.lastIndexOf(i), ii) * comb(ii, nf)});
                    }
                }
            }
            oplist.add(tlist);
        }

        Map<Integer, Map<Integer, Integer>> dl1 = new HashMap<>();
        for (int i = 0; i <= k; i++) {
            dl1.put(i, new HashMap<>());
        }
        dl1.get(0).put(0, 1);
        int nn = n / 2;
        Set<Integer> s = new HashSet<>();
        rec(1, dl1, s, 0, 0, nn);

        List<Integer> l1 = new ArrayList<>(s);
        l1.add(0);

        Map<Integer, Map<Integer, Integer>> dl2 = new HashMap<>();
        for (int i = 0; i <= k; i++) {
            dl2.put(i, new HashMap<>());
        }
        dl2.get(0).put(0, 1);
        s.clear();
        rec(1, dl2, s, nn, 0, n);

        List<Integer> l2 = new ArrayList<>(s);
        l2.add(0);

        int count = 0;
        Collections.sort(l1);
        Collections.sort(l2, Collections.reverseOrder());
        int i = 0;
        int j = 0;

        while (i < l1.size()) {
            while (l2.get(j) > S - l1.get(i)) {
                j++;
            }
            if (l1.get(i) + l2.get(j) == S) {
                for (int m = 0; m <= k; m++) {
                    for (int r = 0; r <= Math.min(m, l1.get(i)); r++) {
                        count += dl1.get(r).getOrDefault(l1.get(i), 0) * dl2.get(m - r).getOrDefault(l2.get(j), 0);
                    }
                }
            }
            i++;
        }

        System.out.println(count);
    }

    private static int factorial(int num) {
        long result = 1;
        for (int i = 1; i <= num; i++) {
            result *= i;
        }
        return (int) result;
    }

    private static double comb(int n, int r) {
        return (double) factorial(n) / (factorial(r) * factorial(n - r));
    }

    private static void rec(double mult, Map<Integer, Map<Integer, Integer>> d, Set<Integer> l, int i, int f, int nn, int s) {
        if (i < nn) {
            for (int[] arr : oplist.get(i)) {
                int add = arr[0];
                int nf = arr[1];
                double mm = arr[2];
                int x = s + add;
                int ff = f + nf;
                if (x <= S && ff <= k) {
                    if (add > 0) {
                        l.add(x);
                        d.get(ff).put(x, d.get(ff).getOrDefault(x, 0) + (int) (mult * mm));
                    }
                    rec(mult * mm, d, l, i + 1, ff, nn, x);
                }
            }
        }
    }
}

