import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int s = scanner.nextInt();
        List<Integer> a = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            a.add(scanner.nextInt());
        }

        Map<Integer, Integer>[] dl = f(a.subList(0, n / 2), k, s);
        Map<Integer, Integer>[] dr = g(a.subList(n / 2, n), k, s);

        long ans = 0;
        for (int i = 0; i <= k; i++) {
            for (Map.Entry<Integer, Integer> entry : dl[i].entrySet()) {
                int x = entry.getKey();
                int t = entry.getValue();
                for (int j = Math.max(0, k - i); j <= k; j++) {
                    ans += t * dr[j].getOrDefault(x, 0);
                }
            }
        }

        System.out.println(ans);
    }

    private static Map<Integer, Integer>[] f(List<Integer> a, int k, int s) {
        Map<Integer, Integer>[] res = new HashMap[k + 1];
        Arrays.setAll(res, o -> new HashMap<>());
        res[k].put(0, 1);

        for (int x : a) {
            Map<Integer, Integer>[] nr = new HashMap[k + 1];
            Arrays.setAll(nr, o -> new HashMap<>());

            for (int j = 0; j <= k; j++) {
                for (Map.Entry<Integer, Integer> entry : res[j].entrySet()) {
                    int y = entry.getKey();
                    int t = entry.getValue();

                    if (j > 0 && x <= 18 && factorial(x) + y <= s) {
                        nr[j - 1].merge(factorial(x) + y, t, Integer::sum);
                    }
                    if (x + y <= s) {
                        nr[j].merge(x + y, t, Integer::sum);
                    }
                    nr[j].merge(y, t, Integer::sum);
                }
            }

            res = nr;
        }

        return res;
    }

    private static Map<Integer, Integer>[] g(List<Integer> a, int k, int s) {
        Map<Integer, Integer>[] res = new HashMap[k + 1];
        Arrays.setAll(res, o -> new HashMap<>());
        res[k].put(s, 1);

        for (int x : a) {
            Map<Integer, Integer>[] nr = new HashMap[k + 1];
            Arrays.setAll(nr, o -> new HashMap<>());

            for (int j = 0; j <= k; j++) {
                for (Map.Entry<Integer, Integer> entry : res[j].entrySet()) {
                    int y = entry.getKey();
                    int t = entry.getValue();

                    if (j > 0 && x <= 18 && y - factorial(x) >= 0) {
                        nr[j - 1].merge(y - factorial(x), t, Integer::sum);
                    }
                    if (y - x >= 0) {
                        nr[j].merge(y - x, t, Integer::sum);
                    }
                    nr[j].merge(y, t, Integer::sum);
                }
            }

            res = nr;
        }

        return res;
    }

    private static int factorial(int n) {
        if (n == 0 || n == 1) return 1;
        int result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }
}

