            for (int j = 0; j <= K; j++) {
                ldp[i][j] = new HashMap<>();
            }
        }
        ldp[0][0].put(0, 1);

        for (int i = 0; i < N / 2; i++) {
            Arrays.stream(ldp[i & 1]).forEach((k, v) -> ldp[~i & 1][k].clear());
            for (int j = 0; j <= K; j++) {
