        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= K; j++) {
                rdp[i][j] = new HashMap<>();
            }
        }
        rdp[0][0].put(0, 1);

        for (int i = 0; i < N - N / 2; i++) {
            Arrays.stream(rdp[i & 1]).forEach((k, v) -> rdp[~i & 1][k].clear());
            for (int j = 0; j <= K; j++) {
