public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long MOD = 998244353;
        String[] input = scanner.nextLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int m = Integer.parseInt(input[1]);

        if (n == 2) {
            System.out.println(0);
            return;
        }

        int k = n - 2;
        int big = 300001;
        long[] choose = new long[big];
        choose[k] = 1;
        for (int i = k + 1; i < big; i++) {
            choose[i] = (choose[i - 1] * i * powMod(i - k, MOD - 2, MOD)) % MOD;
        }

        long s = 0;
        for (int maxval = n - 1; maxval <= m; maxval++) {
            s = (s + choose[maxval - 1] * powMod(2, n - 3, MOD) * (n - 2)) % MOD;
        }
        System.out.println(s);
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

