import java.util.HashMap;
import java.util.Map;

public class PossibleNumberFinder {
    private static String phoneNumbers;
    private static Map<String, Integer> possibleTable = new HashMap<>();

    public static void main(String[] args) {
        phoneNumbers = "input"; // Replace with actual input
        int firstNumber = Character.getNumericValue(phoneNumbers.charAt(0));
        int count = 0;

        for (int i = 0; i < 10; i++) {
            count += findPossibleNumber(i, 1);
        }

        if (hasException(Integer.parseInt(String.valueOf(firstNumber)))) {
            count -= 1;
        }

        System.out.println(count);
    }

    private static int findPossibleNumber(int guessNumber, int digit) {
        if (digit == phoneNumbers.length()) { // base condition
            return 1;
        }

        int mNumber = Character.getNumericValue(phoneNumbers.charAt(digit));
        int numIndexConfiguration = (guessNumber * 10) + digit;

        if (possibleTable.containsKey(numIndexConfiguration)) {
            return possibleTable.get(numIndexConfiguration);
        }

        possibleTable.put(numIndexConfiguration, 0);

        boolean hasRemainder = (mNumber + guessNumber) % 2 != 0;

        if (hasRemainder) {
            hasRemainderCase(mNumber, guessNumber, numIndexConfiguration, digit);
        } else {
            hasNoRemainderCase(mNumber, guessNumber, numIndexConfiguration, digit);
        }

        return possibleTable.get(numIndexConfiguration);
    }

    private static void hasRemainderCase(int mNumber, int guessNumber, int numIndexConfiguration, int digit) {
        int upperNumber = (int) Math.ceil((mNumber + guessNumber) / 2.0);
        int lowerNumber = (int) Math.floor((mNumber + guessNumber) / 2.0);

        possibleTable.put(numIndexConfiguration, possibleTable.getOrDefault(numIndexConfiguration, 0) +
                findPossibleNumber(upperNumber, digit + 1));

        possibleTable.put(numIndexConfiguration, possibleTable.getOrDefault(numIndexConfiguration, 0) +
                findPossibleNumber(lowerNumber, digit + 1));
    }

    private static void hasNoRemainderCase(int mNumber, int guessNumber, int numIndexConfiguration, int digit) {
        double nextNumber = (mNumber + guessNumber) / 2.0;
        int nextNumberInt = (int) nextNumber;

        possibleTable.put(numIndexConfiguration, possibleTable.getOrDefault(numIndexConfiguration, 0) +
                findPossibleNumber(nextNumberInt, digit + 1));
    }

    private static boolean hasException(int number) {
        for (int i = 0; i < phoneNumbers.length() - 1; i++) {
            if (Math.abs(Character.getNumericValue(phoneNumbers.charAt(i)) -
                    Character.getNumericValue(phoneNumbers.charAt(i + 1))) <= 1) {
                continue;
            } else {
                return false;
            }
        }
        return true;
    }
}

