        if(n - k >= 0) {
            return factorial(n) / factorial(k) / factorial(n - k);
        } else {
            return 0;
        }
    }

    private static long factorial(int number) {
        long result = 1;
        for(int i = 2; i <= number; i++) {
            result *= i;
        }
        return result;
    }
}

