            Z = (AX + R - BX) * (AY + C - BY);
        }

        long V = (long) N * M - (long) R * C * 2 + Z;

        if (AX == BX && AY == BY) {
            Z = 0;
        }

        System.out.println(powerMod(K, V + R * C - Z, mod));
        scanner.close();
    }

    private static long powerMod(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % mod;
            exp = exp >> 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

