import java.util.PriorityQueue;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        String[] input = reader.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int a = Integer.parseInt(input[1]);
        int b = Integer.parseInt(input[2]);

        if (a < b) {
            int temp = a;
            a = b;
            b = temp;
        }

        if (b == 0) {
            // 1 01 001 0001 ... is optimal, plus a long series of 0's
            System.out.println((n - 1) * a);
        } else {
            // Pascal's triangle thing
            int[][] pascal = new int[20005][20005];
            for (int i = 0; i < 20005; i++) {
                for (int j = 0; j <= i; j++) {
                    if (i == 0 || j == 0 || j == i) {
                        pascal[i][j] = 1;
                    } else {
                        pascal[i][j] = pascal[i - 1][j - 1] + pascal[i - 1][j];
                        if (pascal[i][j] > n) break;
                    }
                }
            }

            PriorityQueue<int[]> possible = new PriorityQueue<>((x, y) -> x[0] - y[0]);
            possible.add(new int[]{a + b, 1}); // [cost, count]

            int remain = n - 1;
            int ans = 0;

            while (!possible.isEmpty()) {
                // cost u, v leaves
                int[] current = possible.poll();
                int u = current[0], v = current[1];

                while (!possible.isEmpty() && possible.peek()[0] == u) {
                    v += possible.poll()[1];
                }

                if (remain <= v) {
                    ans += u * remain;
                    break;
                }

                ans += u * v;
                remain -= v;
                possible.offer(new int[]{u + a, v});
                possible.offer(new int[]{u + b, v});
            }

            System.out.println(ans);
        }
    }
}

