    static int L(int h, int n) {
        if (h == 0) {
            return 0;
        }
        int half = (int) Math.pow(2, h - 1);
        if (n <= half) {
            return 1 + R(h - 1, n);
        } else {
            return 2 * half + L(h - 1, n - half);
