public class Main {
    private static final int MAX_SIZE = 3000;
    private static BigDecimal MOD_F_INV;
    private static BigDecimal SHRT_INV;
    private static BigDecimal MAGIC = new BigDecimal("6755399441055744");
    private static BigDecimal SHRT = new BigDecimal("65536");

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] input = reader.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int m = Integer.parseInt(input[1]);
        int a = Integer.parseInt(input[2]);
        int b = Integer.parseInt(input[3]);

        input = reader.readLine().split(" ");
        double g = Double.parseDouble(input[0]);
        double x = Double.parseDouble(input[1]);
        double y = Double.parseDouble(input[2]);
        double z = Double.parseDouble(input[3]);

        long MOD = (long) z;
        MOD_F_INV = BigDecimal.ONE.divide(new BigDecimal(z), 10, BigDecimal.ROUND_HALF_UP);
        SHRT_INV = BigDecimal.ONE.divide(SHRT, 10, BigDecimal.ROUND_HALF_UP);

        BigDecimal[][] grid = new BigDecimal[MAX_SIZE][MAX_SIZE];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = new BigDecimal((int) (g % MOD)).setScale(0, BigDecimal.ROUND_DOWN);
                g = multiply(g, x, y, MOD);
            }
        }

        BigDecimal[][] aux1 = process(grid, b, n, m);
        BigDecimal[][] aux2 = process(aux1, a, m - b + 1, n);

        BigDecimal ans = BigDecimal.ZERO;
        for (int i = 0; i < n - a + 1; i++) {
            for (int j = 0; j < m - b + 1; j++) {
                ans = ans.add(aux2[i][j].setScale(0, BigDecimal.ROUND_DOWN));
            }
        }

        System.out.println(ans.toBigInteger());
    }

    private static BigDecimal multiply(BigDecimal a, BigDecimal b, BigDecimal c, BigDecimal mod) {
        BigDecimal shrt = new BigDecimal(65536);
        BigDecimal shrtInv = BigDecimal.ONE.divide(shrt, 10, BigDecimal.ROUND_HALF_UP);
        BigDecimal modF = new BigDecimal(mod.doubleValue());
        BigDecimal modFInv = BigDecimal.ONE.divide(modF, 10, BigDecimal.ROUND_HALF_UP);

        BigDecimal roundA = a.add(MAGIC).subtract(MAGIC);
        BigDecimal roundB = b.add(MAGIC).subtract(MAGIC);
        BigDecimal roundC = c.add(MAGIC).subtract(MAGIC);

        BigDecimal mul1 = a.multiply(roundB).multiply(shrtInv).setScale(0, BigDecimal.ROUND_DOWN);
        BigDecimal mul2 = a.multiply(b.subtract(shrt.multiply(roundB))).add(c).setScale(0, BigDecimal.ROUND_DOWN);
        BigDecimal mul3 = shrt.multiply(roundB).multiply(shrtInv).setScale(0, BigDecimal.ROUND_DOWN);

        BigDecimal result = mul1.multiply(mul3).add(mul2).add(mul3.multiply(mul2)).setScale(0, BigDecimal.ROUND_DOWN);
        result = result.subtract(modF.multiply(result.multiply(modFInv))).setScale(0, BigDecimal.ROUND_DOWN);
        result = result.setScale(0, BigDecimal.ROUND_DOWN);

        return result;
    }

    private static BigDecimal[][] process(BigDecimal[][] grid, int a, int n, int m) {
        BigDecimal[][] aux = new BigDecimal[MAX_SIZE][MAX_SIZE];
        for (int i = 0; i < n; i++) {
            Queue<BigDecimal> mi = new ArrayDeque<>();
            for (int j = 0; j < a; j++) {
                while (!mi.isEmpty() && grid[i][j].compareTo(mi.peekLast()) < 0) {
                    mi.pollLast();
                }
                mi.offer(grid[i][j]);
            }

            aux[0][i] = mi.peekFirst();
            for (int j = a; j < m; j++) {
                if (mi.peekFirst().equals(grid[i][j - a])) {
                    mi.pollFirst();
                }
                while (!mi.isEmpty() && grid[i][j].compareTo(mi.peekLast()) < 0) {
                    mi.pollLast();
                }
                mi.offer(grid[i][j]);
                aux[j - a + 1][i] = mi.peekFirst();
            }
        }
        return aux;
    }
}

