        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long z = scanner.nextLong();

        double zinv = 1.0 / z;

        List<Long> grid = new ArrayList<>(Collections.nCopies(n * m, 0L));
        grid.set(0, g);

        for (int i = 1; i < n * m; i++) {
            grid.set(i, modMulAdd(grid.get(i - 1), x, y, z, zinv));
        }

