        for (List<Integer> row : B) {
            for (int value : row) {
                flatB.add((long) value);
            }
        }

        List<Integer> minValues = printMin(flatB, flatB.size(), a);

        for (int value : minValues) {
            ans += value;
        }

        System.out.println((int) ans);
    }

