        return (int) ((a - b + Integer.MAX_VALUE) % Integer.MAX_VALUE);
    }

    private static long mul(long a, long b) {
        return (a * b) % Integer.MAX_VALUE;
    }

    private static List<Integer> printMin(List<Long> arr, int n, int k) {
        List<Integer> res = new ArrayList<>();
        Deque<Integer> Qi = new ArrayDeque<>();

        for (int i = 0; i < k; i++) {
            while (!Qi.isEmpty() && arr.get(i) <= arr.get(Qi.peekLast())) {
                Qi.pollLast();
            }
            Qi.offerLast(i);
