        for (int i = 1; i < Math.min(a, Math.abs(n - a) + 1); i++) {
            ans += (c[a - 1 - i] & c[a - 1 + i]) * 2;
        }

        if (a == (n + 1) / 2) {
            System.out.println(ans);
