        String s = scanner.nextLine();
        int k = Integer.parseInt(scanner.nextLine());
        int n = s.length();
        Integer[][][][] dp = new Integer[n][k + 1][2][2];
        Integer[][][][] dp1 = new Integer[n][k + 1][2][2];

        System.out.println(Math.max(sol(0, k, 0, -1, dp), -sol1(0, k, 0, -1, dp1)));
    }

    private static int sol(int i, int j, int t, int c, Integer[][][][] dp) {
        if (i == dp.length) {
            if (j != 0) {
                return -10000000;
            } else {
                return 0;
            }
        }

        if (dp[i][j][t][c] != null) {
            return dp[i][j][t][c];
        }

        int ans = 0;
        if (c == -1) {
            c = (s.charAt(i) == 'F') ? 1 : 0;
        }

        if (c == 1) {
            if (t == 1) {
                ans = -1 + sol(i + 1, j, t, -1, dp);
            } else {
                ans = 1 + sol(i + 1, j, t, -1, dp);
            }
            if (j > 0) {
                ans = Math.max(ans, sol(i, j - 1, t, 0, dp));
            }
        } else {
            ans = sol(i + 1, j, !t, -1, dp);
            if (j > 0) {
                ans = Math.max(ans, sol(i, j - 1, t, 1, dp));
            }
        }

        dp[i][j][t][c] = ans;
        return dp[i][j][t][c];
    }

    private static int sol1(int i, int j, int t, int c, Integer[][][][] dp1) {
        if (i == dp1.length) {
            if (j != 0) {
                return 10000000;
            } else {
                return 0;
            }
        }

        if (dp1[i][j][t][c] != null) {
            return dp1[i][j][t][c];
        }

        int ans = 0;
        if (c == -1) {
            c = (s.charAt(i) == 'F') ? 1 : 0;
        }

        if (c == 1) {
            if (t == 1) {
                ans = -1 + sol1(i + 1, j, t, -1, dp1);
            } else {
                ans = 1 + sol1(i + 1, j, t, -1, dp1);
            }
            if (j > 0) {
                ans = Math.min(ans, sol1(i, j - 1, t, 0, dp1));
            }
        } else {
            ans = sol1(i + 1, j, !t, -1, dp1);
            if (j > 0) {
                ans = Math.min(ans, sol1(i, j - 1, t, 1, dp1));
            }
        }

        dp1[i][j][t][c] = ans;
        return dp1[i][j][t][c];
    }
}

