    }

    public static int solve(int a, int b, int c, int d) {
        int ans = 0;
        int[] pre = new int[b + c + 2];
        for (int i = b; i >= a; i--) {
            pre[i + b]++;
            pre[i + c + 1]--;
        }
        for (int i = 1; i < pre.length; i++) {
            pre[i] += pre[i - 1];
        }
        for (int i = 1; i < pre.length; i++) {
            pre[i] += pre[i - 1];
        }
        int maxPre = Arrays.stream(pre).max().getAsInt();
        int last = 0;
        for (int i = c; i <= d; i++) {
            if (i < b + c + 1) {
                last = maxPre - pre[i];
            }
            ans += last;
        }
        return ans;
    }
}

