import java.util.*;

public class Main {
    public static boolean isGood(int[] f, int p, int k) {
        for (int i = 0; i < p; i++) {
            if (f[(k * i) % p] != (k * f[i]) % p) {
                return false;
            }
        }
        return true;
    }

    public static int gen(int[] f, int p, int k, int i) {
        if (i == p) {
            return isGood(f, p, k) ? 1 : 0;
        } else {
            int ans = 0;
            for (int j = 0; j < p; j++) {
                f[i] = j;
                ans += gen(f, p, k, i + 1);
            }
            return ans;
        }
    }

    public static int solve(int p, int k) {
        int num = 0;
        Set<Integer> used = new HashSet<>();
        for (int j = 0; j < p; j++) {
            if (!used.contains(j)) {
                num++;
            }
            int i = j;
            while (!used.contains(i)) {
                used.add(i);
                i = (i * k) % p;
            }
        }
        return (int) Math.pow(p, num - (k != 1), (long) 1e9 + 7);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        // System.out.println(gen(new int[0], p, k, 0));
        System.out.println(solve(p, k));
    }
}

