import java.util.Scanner;

public class Main {
    static final int M = 1000000007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // scanner.useDelimiter("\n");
        int T = 1;

        while (scanner.hasNext()) {
            process(scanner);
        }
    }

    public static void process(Scanner scanner) {
        String[] line = scanner.nextLine().split(" ");
        int P = Integer.parseInt(line[0]);
        int K = Integer.parseInt(line[1]);

        long[] k = new long[P];
        for (int x = 0; x < P; x++) {
            k[x] = (K * x) % P;
        }

        if (K == 0) {
            System.out.println(powerMod(P, P - 1, M));
            return;
        }

        boolean[] f = new boolean[P];
        int[] c = new int[P];
        long ans = 1;

        for (int i = 0; i < P; i++) {
            if (f[i]) continue;

            int cnt = 1;
            int u = i;
            f[u] = true;
            while (!f[(int)k[u]]) {
                u = (int)k[u];
                f[u] = true;
                cnt++;
            }

            c[cnt]++;
        }

        for (int i = 1; i < P; i++) {
            if (c[i] != 0) {
                int cnt = i * c[i] + (i > 1 ? 1 : 0);
                ans = (ans * powerMod(cnt, c[i], M)) % M;
            }
        }

        System.out.println(ans);
    }

    private static long powerMod(long base, int exp, int mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp = exp >> 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

