import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    private static boolean[] visited;
    private static int[] adj;
    private static int mod = (int) 1e9 + 7;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] nk = br.readLine().trim().split(" ");
        int n = Integer.parseInt(nk[0]);
        int k = Integer.parseInt(nk[1]);

        visited = new boolean[n + 1];
        adj = new int[n + 1];

        for (int i = 0; i < n; i++) {
            adj[i] = (i * k) % n;
        }

        int pairs = 0;
        for (int i = 1; i < n; i++) {
            if (!visited[i]) {
                dfs(i);
                pairs++;
            }
        }

        if (k == 1) {
            System.out.println(powerMod(n, n));
        } else {
            System.out.println(powerMod(n, pairs));
        }
    }

    private static void dfs(int n) {
        visited[n] = true;
        while (!visited[adj[n]]) {
            n = adj[n];
            visited[n] = true;
        }
    }

    private static long powerMod(long base, long exp) {
        if (exp == 0) return 1;
        if (exp % 2 == 0) {
            long halfPower = powerMod(base, exp / 2);
            return (halfPower * halfPower) % mod;
        } else {
            return (base * powerMod(base, exp - 1)) % mod;
        }
    }
}

import java.util.Scanner;

public class Main {
    static final int MOD = (int) (1e9 + 7);

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int p = scanner.nextInt();
        int k = scanner.nextInt();

        int cmps = 0;
        boolean[] vis = new boolean[p];

        for (int x = 0; x < p; x++) {
            if (vis[x]) continue;

            cmps++;
            int st = x;
            vis[st] = true;
            st *= k;
            if (st >= p) st %= p;

            while (st != x && st != 0) {
                vis[st] = true;
                st *= k;
                if (st >= p) st %= p;
            }
        }

        if (k != 1) cmps--;

        System.out.println(powerMod(p, cmps, MOD));
    }

    private static long powerMod(long base, long exponent, long mod) {
        long result = 1;
        base = base % mod;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % mod;
            }
            exponent = exponent >> 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        long MOD = (long) 1e9 + 7;
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        long p;
        if (k < 2) {
            p = (long) n - (1 - k);
        } else {
            long t = 1;
            long a = k;

            while (a != 1) {
                a = (a * k) % n;
                t += 1;
            }

            p = (n - 1) / t;
        }

        System.out.println((long) Math.pow(n, p) % MOD);

        scanner.close();
    }
}

