import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] x = scanner.nextLine().split(" ");

        boolean hazZero = false;
        String binary = Integer.toBinaryString(Integer.parseInt(x[0]));
        for (int i = 0; i < binary.length(); i++) {
            if (binary.charAt(i) == '0') {
                hazZero = true;
                break;
            }
        }

        if (!hazZero) {
            binary = Integer.toBinaryString(Integer.parseInt(x[0]) + 1);
        }

        boolean isFirst = true;
        StringBuilder new_binary = new StringBuilder();
        for (int i = 0; i < binary.length(); i++) {
            if (binary.charAt(i) == '0') {
                if (isFirst) {
                    new_binary.append('0');
                    isFirst = false;
                } else {
                    new_binary.append('1');
                }
            } else {
                new_binary.append(binary.charAt(i));
            }
        }

        int inDecimal = Integer.parseInt(new_binary.toString(), 2);

        int total = 0;
        while (Integer.parseInt(x[0]) <= inDecimal && inDecimal <= Integer.parseInt(x[1])) {
            total++;
            if (new_binary.toString().equals("1")) {
                total--;
                new_binary = new StringBuilder("10");
            } else if (new_binary.charAt(new_binary.length() - 1) == '0') {
                new_binary.setLength(new_binary.length() - 1);
                new_binary.insert(0, "10");
            } else {
                new_binary.setLength(new_binary.length() - 1);
                new_binary.insert(0, "1");
            }
            inDecimal = Integer.parseInt(new_binary.toString(), 2);
        }

        System.out.println(total);
    }
}

