import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.next());
        int m = Integer.parseInt(scanner.next());
        int[] sabs = new int[n];
        for (int i = 0; i < n; i++) {
            sabs[i] = Integer.parseInt(scanner.next()) - 1;
        }
        int[] cols = new int[m];
        for (int i = 0; i < m; i++) {
            cols[i] = Integer.parseInt(scanner.next());
        }
        int t = 0;
        for (int col : cols) {
            t += col;
        }

        boolean[] K = new boolean[cols.length];
        for (int i = 0; i < t; i++) {
            K[sabs[i]] = true;
        }

        for (int i = t; i < n; i++) {
            if (ok(K, cols)) {
                System.out.println("YES");
                return;
            }
            K[sabs[i]] = true;
            K[sabs[i - t]] = false;
        }

        if (ok(K, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private static boolean ok(boolean[] K, int[] cols) {
        for (int i = 0; i < cols.length; i++) {
            if (K[i] != (i < cols.length ? cols[i] : 0)) {
                return false;
            }
        }
        return true;
    }
}

