                {9447267, 1, 16, 4723633, 4723633},
                {1181362, 3, 22, 0, 0}
            };

            for (int[] val : vals) {
                int b = val[0];
                int d = val[1];
                int a = val[2];
                int c = val[3];
                int answer = val[4];

                int result = solve(a, b, c, d);

                if (result == answer) {
                    System.out.println("++++++++++++++++++++++++++++");
                } else {
                    System.out.println("-----------------------------");
                    System.out.print(Arrays.toString(val));
                    System.out.println(result);
                    System.out.println("-----------------------------");
                    try {
                        System.in.read();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }
        }
    }

    public static int solve(int a, int b, int c, int d) {
        for (int i = 0; i < c; i++) {
            if (a[i] != c[i]) {
                return 0;
            }
        }

        int ind1 = 0;
        int ind2 = 0;
        int cnt1 = 1;
        int cnt2 = 0;
        List<Integer> phases = new ArrayList<>();
        List<int[]> phases2 = new ArrayList<>();

        while (true) {
            if (a[ind1] == c[ind2]) {
                ind2++;
                if (ind2 == c) {
                    cnt2++;
                    ind2 = 0;
                    if (ind1 >= phases.size()) {
                        phases.add(ind1);
                        phases2.add(new int[]{cnt1, cnt2});
                    } else {
                        int cnt1_ = phases2.get(phases.indexOf(ind1))[0];
                        int cnt2_ = phases2.get(phases.indexOf(ind1))[1];
                        int step1 = cnt1 - cnt1_;
                        int step2 = cnt2 - cnt2_;
                        cnt = (b - cnt1) / step1;
                        cnt1 += step1 * cnt;
                        cnt2 += step2 * cnt;
                        phases.clear();
                        phases2.clear();
                        phases.add(ind1);
                        phases2.add(new int[]{cnt1, cnt2});
                    }
                }
            }

            ind1++;
            if (ind1 == a) {
                cnt1++;
                ind1 = 0;
                if (cnt1 > b) {
                    return cnt2 / d;
                }
            }
        }
    }
}

