import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());

        List<List<int[]>>[][] graph = new ArrayList[3][];
        for (int i = 0; i < 3; i++) {
            graph[i] = new ArrayList[n][n];
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    graph[i][j] = new ArrayList<>();
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) {
                        graph[0][i][j].add(new int[]{k, j});
                        graph[0][i][j].add(new int[]{i, k});
                    }
                }
                graph[0][i][j].removeIf(p -> p[0] == i && p[1] == j);

                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < n; l++) {
                        if (Math.abs(k - i) == Math.abs(l - j) && (k != i || l != j)) {
                            graph[1][i][j].add(new int[]{k, l});
                        }
                    }
                }

                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < n; l++) {
                        if (Math.abs(k - i) + Math.abs(l - j) == 3) {
                            graph[2][i][j].add(new int[]{k, l});
                        }
                    }
                }
            }
        }

        int[][][][] dists = new int[3][3][n][n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 3; k++) {
                    dists[k][k][i][j][i] = 0;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 3; k++) {
                    List<List<int[]>>[] layers = new List[]{new ArrayList<>(List.of(new int[]{i, j, k, 0})), new ArrayList<>(), new ArrayList<>(), new ArrayList<>(), new ArrayList<>()};
                    for (int l = 0; l < 4; l++) {
                        for (int[] guy : layers[l]) {
                            for (int m = 0; m < 3; m++) {
                                if (m != guy[2]) {
                                    int key = Arrays.hashCode(new Object[]{i, j, guy[0], guy[1]});
                                    if (!dists[k][m][key]) {
                                        layers[l + 1].add(new int[]{guy[0], guy[1], m, guy[3] + 1});
                                        dists[k][m][key] = true;
                                    }
                                }
                                for (int[] boi : graph[guy[2]][i][j]) {
                                    int key = Arrays.hashCode(new Object[]{i, j, boi[0], boi[1]});
                                    if (!dists[k][guy[2]][key]) {
                                        layers[l + 1].add(new int[]{boi[0], boi[1], guy[2], guy[3]});
                                        dists[k][guy[2]][key] = true;
                                    } else if (1000 * (l + 1) + guy[3] < dists[k][guy[2]][key]) {
                                        layers[l + 1].add(new int[]{boi[0], boi[1], guy[2], guy[3]});
                                        dists[k][guy[2]][key] = 1000 * (l + 1) + guy[3];
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        List<Integer> locs = new ArrayList<>();
        String[] inputs = scanner.nextLine().split(" ");
        for (int i = 0; i < n; i++) {
            int value = Integer.parseInt(inputs[i]);
            locs.add(value - 1);
        }

        int[] best = {Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE};

        for (int i = 0; i < n * n - 1; i++) {
            int x1 = locs.get(i) / n;
            int y1 = locs.get(i) % n;
            int x2 = locs.get(i + 1) / n;
            int y2 = locs.get(i + 1) % n;

            int[] distances = {dists[0][0][x1][y1][x2] + dists[0][0][x2][y2],
                               dists[1][0][x1][y1][x2] + dists[1][0][x2][y2],
                               dists[2][0][x1][y1][x2] + dists[2][0][x2][y2]};
            for (int d : distances) {
                if (d < best[0]) {
                    best[0] = d;
                } else if (d < best[1]) {
                    best[1] = d;
                } else if (d < best[2]) {
                    best[2] = d;
                }
            }
        }

        int minDist = Math.min(Math.min(best[0], best[1]), best[2]);
        System.out.println(minDist / 1000 + " " + minDist % 1000);
    }
}

