import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        int lo, hi;

        if (m < 1000000) {
            lo = m * 4;
            hi = m * 8;
        } else {
            lo = (int) (4.949 * m);
            hi = (int) (4.9492 * m);
        }

        while (lo < hi - 1) {
            int mid = (lo + hi) / 2;
            int nPoss = countPoss(mid);

            if (nPoss < m) {
                lo = mid;
            } else {
                hi = mid;
            }
        }

        if (m == countPoss(hi)) {
            System.out.println(hi);
        } else {
            System.out.println(-1);
        }

        scanner.close();
    }

    private static int countPoss(int maxTake) {
        int k = 2;
        int ans = 0;

        while (true) {
            int term = maxTake / (k * k * k);
            if (term == 0) {
                return ans;
            }
            ans += term;
            k++;
        }
    }
}

