import java.util.*;

public class Main {
    private static final long MOD = 10_000_000_007;
    private static final long INF = 1_000_000_000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String s = scanner.next();

        List<List<Integer>> num = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            num.add(new ArrayList<>(Collections.nCopies(s.length() - i, 0)));
            for (int j = i + 1; j <= s.length(); j++) {
                int val = Integer.parseInt(s.substring(i, j), 2);
                num.get(i).set(j - i - 1, val);
            }
        }

        List<Long> neededForM = new ArrayList<>();
        long cur = 0;
        for (int x = 1; x < 1000; x++) {
            cur += String.format("%d", x).length();
            neededForM.add(cur);
        }

        List<String> bins = new ArrayList<>();
        for (int x = 0; x < 1000; x++) {
            bins.add(Integer.toBinaryString(x));
        }

        Map<Pair, Long> cache = new HashMap<>();
        long ans = 0;
        for (int i = 0; i < s.length(); i++) {
            long curAns = solve(1, 0, 1, i, num, neededForM, bins, cache);
            ans = (ans + curAns) % MOD;
            System.err.println(i + " " + curAns + " " + ans);
        }
        System.out.println(ans);
    }

    private static long solve(int state, int used, int maxm, int pos, List<List<Integer>> num, List<Long> neededForM, List<String> bins, Map<Pair, Long> cache) {
        Pair key = new Pair(state, pos);
        if (!cache.containsKey(key)) {
            long res = 0;

            if (state == (1 << (maxm + 1)) - 1) {
                res++;
            }

            for (int add = 1; add < 100; add++) {
                if (pos + add > num.size()) {
                    break;
                }
                int val = num.get(pos).get(add - 1);
                if (val == 0) {
                    continue;
                }
                if (val >= 100) {
                    break;
                }

                int used2 = used;
                if ((state & (1 << val)) == 0) {
                    used2 += bins.get(val).length();
                }
                int maxm2 = Math.max(maxm, val);
                int pos2 = pos + add;
                long needed = maxm2 <= 100 ? neededForM.get(maxm2) : INF;
                if (needed - used2 <= num.size() - pos2) {
                    res = (res + solve((state | (1 << val)), used2, maxm2, pos2, num, neededForM, bins, cache)) % MOD;
                }
            }
            cache.put(key, res);
        }
        return cache.get(key);
    }

    static class Pair {
        int first;
        int second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair pair = (Pair) o;
            return first == pair.first && second == pair.second;
        }

        @Override
        public int hashCode() {
            return Objects.hash(first, second);
        }
    }
}

