import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int x0 = scanner.nextInt();
        int y0 = scanner.nextInt();
        int n = scanner.nextInt();
        int d = scanner.nextInt();

        int[][] mvs = new int[n][2];
        for (int i = 0; i < n; i++) {
            mvs[i][0] = scanner.nextInt();
            mvs[i][1] = scanner.nextInt();
        }

        boolean[][] dp = new boolean[2 * d + 1][2 * d + 1];

        for (int i = 2 * d; i >= 0; i--) {
            for (int j = 2 * d; j >= 0; j--) {
                int x = i - d;
                int y = j - d;

                if (dist(x, y, d)) {
                    for (int[] mv : mvs) {
                        int x1 = x + mv[0];
                        int y1 = y + mv[1];

                        if (dist(x1, y1, d) && !dp[x1 + d][y1 + d]) {
                            dp[i][j] = true;
                            break;
                        }
                    }
                }
            }
        }

        if (dp[x0 + d][y0 + d]) {
            System.out.println("Anton");
        } else {
            System.out.println("Dasha");
        }

        scanner.close();
    }

    private static double dist(int x, int y, int d) {
        return Math.sqrt((x * x) + (y * y));
    }
}

