        int n = Integer.parseInt(inputs[0]);
        int k = Integer.parseInt(inputs[1]);
        int m = Integer.parseInt(inputs[2]);

        if (k == 1) {
            System.out.println((9 * powerMod(10, n - 1, m)) % m);
            return;
        }
        if (n == 1) {
            long count = 0;
            for (int i = 1; i < 10; i++) {
                if (i % k == 0) {
                    count++;
                }
            }
            System.out.println(count % m);
            return;
        }

        int[] dp = new int[k];
        for (int i = 0; i < 10; i++) {
            if (i % k != 0) {
                dp[i % k]++;
            }
        }
        int t = 10 % k;
        int[][] kk = new int[k][11];
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < 11; j++) {
                kk[i][j] = (i * j) % k;
            }
        }

        for (int i = 0; i < n - 1; i++) {
            int[] ndp = new int[k];
            for (int j = 1; j < k; j++) {
                for (int l = (i == n - 2 ? 1 : 0); l < 10; l++) {
                    int x = (j + kk[t][l]);
                    if (x >= k) {
                        x -= k;
                    }
                    if (x != 0) {
                        ndp[x] += dp[j];
                        if (ndp[x] >= m) {
                            ndp[x] -= m;
                        }
                    }
                }
            }
            for (int l = (i == n - 2 ? 1 : 0); l < 10; l++) {
                if (kk[t][l] != 0) {
                    ndp[kk[t][l]] += 1;
                }
            }
            dp = ndp.clone();
            t = kk[t][10];
        }
        System.out.println(((9 * powerMod(10, n - 1, m)) - sum(dp) % m + m) % m);
    }

    private static int powerMod(long base, int exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return (int) result;
    }

    private static int sum(int[] array) {
        int total = 0;
        for (int value : array) {
            total += value;
        }
        return total;
    }
}

