import java.util.Arrays;
import java.util.Scanner;

public class Main {
    private static final int M = 1000000007;
    private static long[] c = new long[32];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        int[] n = new int[input.length()];
        for (int i = 0; i < input.length(); i++) {
            n[i] = input.charAt(i) - '0';
        }

        int k = n.length;
        accumulate(k, 0, 0);

        for (int i = 0; i < k; i++) {
            for (int j = 0; j < n[i]; j++) {
                if (j == 4 || j == 7) {
                    accumulate(k - i - 1, 1, 1);
                } else {
                    accumulate(k - i - 1, 0, 1);
                }
            }

            if (n[i] == 4 || n[i] == 7) {
                c[1]++;
            }
        }

        c[0]--;
        System.out.println(win(0, 0, 1));
    }

    private static void accumulate(int k, int s, long v) {
        if (k > 0) {
            accumulate(k - 1, s + 1, v * 2 % M);
            accumulate(k - 1, s, v * 8 % M);
        } else {
            c[s] += v;
        }
    }

    private static long win(int u, int v, int w) {
        long x = 0;
        if (v < 10) {
            if (u < 6) {
                for (int i = 0; i <= 11; i++) {
                    if (c[i] > 0) {
                        c[i]--;
                        x = (x + win(u + 1, v + i, (c[i] + 1) % M)) % M;
                        c[i]++;
                    }
                }
            } else {
                for (int i = v + 1; i < 10; i++) {
                    x = (x + ((long) w * c[i])) % M;
                }
            }
        }
        return x;
    }
}

