import java.util.*;

public class LuckySubset {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        int[] mArr = Arrays.stream(input.split("")).mapToInt(Integer::parseInt).toArray();
        Arrays.sort(mArr);
        reverseArray(mArr);
        int[] lucky = new int[mArr.length + 1];
        for (int luckySize = 0; luckySize < mArr.length + 1; luckySize++) {
            lucky[luckySize] = getLuckyCount(mArr, luckySize);
        }
        System.out.println(resultMod(lucky, (int) Math.pow(10, 9) + 7));
    }

    private static void reverseArray(int[] array) {
        for (int i = 0; i < array.length / 2; i++) {
            int temp = array[i];
            array[i] = array[array.length - 1 - i];
            array[array.length - 1 - i] = temp;
        }
    }

    private static int getLuckySubsetCount(int[] mArr, Set<Integer> luckySubset) {
        int width = mArr.length;
        int[][] A = new int[width][3];
        for (int i = 0; i < width; i++) {
            A[i][0] = (luckySubset.contains(i)) ? 2 : 8;
            A[i][1] = (int) filterCount(mArr[i], luckySubset);
            List<Integer> list = filterList(mArr[i], luckySubset);
            A[i][2] = list.isEmpty() ? false : (list.get(list.size() - 1) == mArr[i]);
        }
        int[][] B = new int[width][2];
        for (int i = 0; i < width; i++) {
            if (i == 0) {
                B[i][0] = A[i][0];
                B[i][1] = A[i][1];
            } else {
                B[i][0] = B[i - 1][0] * A[i][0];
                B[i][1] = (A[i][1] - 1) * B[i - 1][0] + (A[i][2] ? B[i - 1][1] : B[i - 1][0]);
            }
        }
        return B[width - 1][1];
    }

    private static long filterCount(int num, Set<Integer> luckySubset) {
        if (!luckySubset.isEmpty()) {
            return IntStream.rangeClosed(1, num).filter(x -> x == 7 || x == 4).count();
        } else {
            return IntStream.rangeClosed(1, num).filter(x -> x != 7 && x != 4).count();
        }
    }

    private static List<Integer> filterList(int num, Set<Integer> luckySubset) {
        if (!luckySubset.isEmpty()) {
            return IntStream.rangeClosed(1, num).filter(x -> x == 7 || x == 4).boxed().collect(Collectors.toList());
        } else {
            return IntStream.rangeClosed(1, num).filter(x -> x != 7 && x != 4).boxed().collect(Collectors.toList());
        }
    }

    private static int getLuckyCount(int[] mArr, int luckySize) {
        int maxWidth = mArr.length;
        int result = 0;
        for (Integer[] combination : combinations(maxWidth, luckySize)) {
            Set<Integer> luckySubset = new HashSet<>();
            for (Integer index : combination) {
                luckySubset.add(index);
            }
            result += getLuckySubsetCount(mArr, luckySubset);
        }
        // do not count number '0'
        return result - (luckySize == 0 ? 1 : 0);
    }

    private static Integer[][] combinations(int n, int k) {
        Integer[][] combinations = new Integer[nCr(n, k)][];
        int[] indices = new int[k];
        for (int i = 0; i < k; i++) {
            indices[i] = i;
        }
        combinations[0] = Arrays.copyOf(indices, k);

        int i = 0;
        while (true) {
            boolean found = false;
            for (int j = k - 1; j >= 0; j--) {
                if (indices[j] != j + n - k) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                break;
            }

            int nextIndex = indices[k - 1] + 1;
            for (i = k - 2; i >= 0; i--) {
                if (indices[i] < nextIndex - 1) {
                    indices[i]++;
                    for (int l = i + 1; l < k; l++) {
                        indices[l] = indices[l - 1] + 1;
                    }
                    combinations[nextCombination(combinations, i)] = Arrays.copyOf(indices, k);
                    break;
                }
            }
        }
        return combinations;
    }

    private static int nextCombination(Integer[][] combinations, int i) {
        int count = 0;
        for (int j = 0; j < i; j++) {
            if (combinations[j][j] > combinations[i][i]) {
                count++;
            }
        }
        return count;
    }

    private static long nCr(int n, int r) {
        long result = 1;
        for (int i = 0; i < r; i++) {
            result *= (n - i);
            result /= (i + 1);
        }
        return result;
    }

    private static long combinationMod(long n, long r, long mod) {
        if (n >= r) {
            long value = 1;
            for (long i = 0; i < r; i++) {
                value *= (n - i);
                value /= (i + 1);
            }
            return value % mod;
        }
        return 0;
    }

    private static long resultMod(int[] lucky, int modulo) {
        long result = 0;
        for (int luckyDigits = 1; luckyDigits < lucky.length; luckyDigits++) {
            Set<Integer> combinations = new HashSet<>(Arrays.asList(sumCombinations(luckyDigits - 1, 6)));
            Map<List<Integer>, Long> counterMap = new HashMap<>();
            for (Integer[] combination : combinations) {
                List<Integer> key = new ArrayList<>(Arrays.asList(combination));
                key.sort(Comparator.comparingInt(a -> a));
                counterMap.put(key, counterMap.getOrDefault(key, 0L) + 1);
            }
            for (Map.Entry<List<Integer>, Long> entry : counterMap.entrySet()) {
                long subResult = lucky[luckyDigits];
                for (Integer k : entry.getKey()) {
                    subResult *= combinationMod((long) lucky[k], (long) Collections.frequency(entry.getKey(), k), modulo);
                    subResult %= modulo;
                }
                result += subResult * entry.getValue();
                result %= modulo;
            }
        }
        return result;
    }

    private static Integer[][] sumCombinations(int n, int r) {
        Integer[][] combinations = new Integer[nCr(n, r)][];
        int[] indices = new int[r];
        for (int i = 0; i < k; i++) {
            indices[i] = i;
        }
        combinations[0] = Arrays.copyOf(indices, k);

        int i = 0;
        while (true) {
            boolean found = false;
            for (int j = k - 1; j >= 0; j--) {
                if (indices[j] != j + n - k) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                break;
            }

            int nextIndex = indices[k - 1] + 1;
            for (i = k - 2; i >= 0; i--) {
                if (indices[i] < nextIndex - 1) {
                    indices[i]++;
                    for (int l = i + 1; l < k; l++) {
                        indices[l] = indices[l - 1] + 1;
                    }
                    combinations[nextCombination(combinations, i)] = Arrays.copyOf(indices, k);
                    break;
                }
            }
        }
        return combinations;
    }
}

