public class Main {
    private static final int MOD = 998244353;
    private static long[] fact;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        if (0 <= k && k < n) {
            fact = new long[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % MOD;
            }
            int m = n - k;
            long ans = 0;
            for (int i = 0; i < m; i++) {
                long sign = i % 2 == 0 ? 1 : -1;
                long term = (nCr(m, i) * powerMod(m - i, n)) % MOD;
                ans = (ans + (sign * term)) % MOD;
            }
            ans = (ans * nCr(n, k)) % MOD;
            ans = (ans * (1 + (k > 0))) % MOD;
            System.out.println(ans);
        } else {
            System.out.println(0);
        }
        scanner.close();
    }

    private static long nCr(int n, int k) {
        assert 0 <= k && k <= n;
        return ((fact[n] * powerMod((fact[k] * fact[n - k]) % MOD, MOD - 2)) % MOD);
    }

    private static long powerMod(long base, int exp) {
        long result = 1;
        while (exp != 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }
}

