public class Main {
    private static final long MOD = 998244353;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        long[] modinv = new long[(int) 1e6 + 20];
        modinv[1] = 1;
        for (int i = 2; i < modinv.length; i++) {
            modinv[i] = ((-MOD / i) + MOD) % MOD * modinv[MOD % i] % MOD;
        }

        long[] fac = new long[(int) 1e6 + 20];
        fac[1] = 1;
        for (int i = 2; i < fac.length; i++) {
            fac[i] = fac[i - 1] * i % MOD;
        }

        long[] invfac = new long[(int) 1e6 + 20];
        invfac[1] = 1;
        for (int i = 2; i < invfac.length; i++) {
            invfac[i] = invfac[i - 1] * modinv[i] % MOD;
        }

        long ans = 0;
        long extra = 0;
        for (int i = 1; i <= n; i++) {
            long base = pow(3, n - i, MOD);
            long tmp = (pow(-base + 1, n, MOD) - pow(-base, n, MOD) + MOD) % MOD;
            ans = (ans + par(i + 1 + n) * choose(n, i) * tmp % MOD + MOD) % MOD;

            long exp = (n * (n - i) * pow(MOD - 2, 1, MOD - 1) + i) % MOD;
            extra = (extra + par(i + 1) * choose(n, i) * pow(3, exp, MOD) % MOD + MOD) % MOD;
        }

        System.out.println((3 * ans + 2 * extra) % MOD);
        scanner.close();
    }

    private static long pow(long x, long y, long p) {
        long res = 1;
        x = x % p;
        while (y > 0) {
            if (y % 2 == 1)
                res = (res * x) % p;
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }

    private static long choose(long n, long k) {
        return fac[(int) n] * invfac[(int) k] % MOD * invfac[(int) (n - k)] % MOD;
    }

    private static long par(int x) {
        return (x & 1) == 1 ? -1 : 1;
    }
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main {
    private static final BigInteger MOD = new BigInteger("1000000007");
    private static BigInteger[] precalc;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        precalc = new BigInteger[k + 1];
        precalc[0] = BigInteger.ZERO;
        for (int i = 0; i <= k; i++) {
            precalc[i] = precalc[i - 1].add(BigInteger.valueOf(i).modPow(BigInteger.valueOf(k), MOD)).mod(MOD);
        }

        System.out.println(interpolate(precalc, new BigInteger(String.valueOf(n + 1))).subtract(BigInteger.valueOf(k == 0)).mod(MOD));
    }

    private static BigInteger interpolate(BigInteger[] samples, BigInteger x) {
        x = x.mod(MOD);

        int m = samples.length;
        if (x.compareTo(BigInteger.valueOf(m)) < 0) {
            return samples[x.intValue()];
        }

        BigInteger[] modinv = new BigInteger[m];
        modinv[1] = BigInteger.ONE;
        for (int i = 2; i < m; i++) {
            modinv[i] = modinv[MOD.modInverse(BigInteger.valueOf(i)).intValue()].multiply(new BigInteger("-1")).mod(MOD);
        }

        BigInteger[] invfac = new BigInteger[m];
        invfac[0] = BigInteger.ONE;
        for (int i = 1; i < m; i++) {
            invfac[i] = invfac[i - 1].multiply(modinv[i]).mod(MOD);
        }
        BigInteger[] invnegFac = new BigInteger[m];
        for (int i = 0; i < m; i++) {
            invnegFac[i] = invfac[i].multiply(BigInteger.valueOf(1 - 2 * (i & 1))).mod(MOD);
        }

        BigInteger base = BigInteger.ONE;
        for (int j = (-x.intValue()); j < m - x.intValue(); j++) {
            base = base.multiply(BigInteger.valueOf(j).mod(MOD)).mod(MOD);
        }

        BigInteger s = BigInteger.ZERO;
        for (int i = 0; i < m; i++) {
            BigInteger pr = precalc[i].multiply(BigInteger.valueOf(i - x.intValue()).modPow(MOD.subtract(BigInteger.TWO), MOD)).mod(MOD);
            pr = pr.multiply(invnegFac[i].multiply(invfac[m - i - 1]).mod(MOD)).mod(MOD);
            s = s.add(pr).mod(MOD);
        }
        return s.multiply(base).mod(MOD);
    }
}

