import java.util.*;

public class Main {
    static int n, m, capacity;
    static List<Planet> planets;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputs = scanner.nextLine().split(" ");
        n = Integer.parseInt(inputs[0]);
        m = Integer.parseInt(inputs[1]);
        capacity = Integer.parseInt(inputs[2]);

        planets = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Planet p = new Planet();
            p.name = scanner.nextLine();
            for (int j = 0; j < m; j++) {
                String[] values = scanner.nextLine().split(" ");
                int a = Integer.parseInt(values[0]);
                int b = Integer.parseInt(values[1]);
                int c = Integer.parseInt(values[2]);
                p.a.add(a);
                p.b.add(b);
                p.c.add(c);
            }
            planets.add(p);
        }

        int maxProfit = -1;
        for (int n1 = 0; n1 < n; n1++) {
            for (int n2 = 0; n2 < n; n2++) {
                if (n1 != n2) {
                    int profit = calcProfit(planets.get(n1), planets.get(n2));
                    maxProfit = Math.max(maxProfit, profit);
                }
            }
        }

        System.out.println(maxProfit);
    }

    static int calcProfit(Planet p1, Planet p2) {
        List<int[]> profits = new ArrayList<>();
        for (int j = 0; j < m; j++) {
            if (p1.c.get(j) == 0) {
                continue;
            }
            int profit = p2.b.get(j) - p1.a.get(j);
            if (profit > 0) {
                profits.add(new int[]{profit, p1.c.get(j)});
            }
        }

        Collections.sort(profits, Comparator.comparingInt(o -> o[0]).reversed());

        int load = 0;
        int totalProfit = 0;
        for (int[] p : profits) {
            int c = Math.min(capacity - load, p[1]);
            totalProfit += p[0] * c;
            load += c;
            if (c != p[1]) {
                break;
            }
        }

        return totalProfit;
    }

    static class Planet {
        String name;
        List<Integer> a = new ArrayList<>();
        List<Integer> b = new ArrayList<>();
        List<Integer> c = new ArrayList<>();
    }
}

