import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int T = scanner.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = scanner.nextInt();
        }
        if (sumArray(A) > N / 2) {
            A = reverseFlipArray(A);
        }
        int K = sumArray(A);
        int S = sumArrayLastK(A, K);
        int M = K + 1;
        int P = 1000000007;
        long inv = powerMod(N * (N - 1) / 2, P - 2, P);
        long[][] X = new long[M][M];
        for (int i = 0; i < M; i++) {
            if (i > 0) {
                X[i - 1][i] = mod(((K - i + 1L) * (K - i + 1)) * inv, P);
            }
            if (i < M - 1) {
                X[i + 1][i] = mod((N - 2 * K + i + 1) * (i + 1) * inv, P);
            }
            X[i][i] = mod(1 - ((K - i) * (K - i) * inv) - ((N - 2 * K + i) * i * inv), P);
        }

        X = powerModMatrix(X, T, P);

        System.out.println(X[S][K]);
    }

    private static long sumArray(int[] array) {
        long sum = 0;
        for (int value : array) {
            sum += value;
        }
        return sum;
    }

    private static int[] reverseFlipArray(int[] array) {
        int[] flipped = new int[array.length];
        for (int i = 0; i < array.length; i++) {
            flipped[i] = 1 - array[i];
        }
        for (int i = 0; i < array.length / 2; i++) {
            int temp = flipped[i];
            flipped[i] = flipped[flipped.length - 1 - i];
            flipped[flipped.length - 1 - i] = temp;
        }
        return flipped;
    }

    private static int sumArrayLastK(int[] array, int K) {
        int sum = 0;
        for (int i = array.length - K; i < array.length; i++) {
            sum += array[i];
        }
        return sum;
    }

    private static long mod(long a, int p) {
        return a % p;
    }

    private static long powerMod(long base, long exp, int mod) {
        if (exp == 1) {
            return base;
        }
        if (exp % 2 != 0) {
            return mod(base * powerMod(base, exp - 1, mod), mod);
        } else {
            long halfPower = powerMod(base, exp / 2, mod);
            return mod(halfPower * halfPower, mod);
        }
    }

    private static long[][] powerModMatrix(long[][] matrix, long exponent, int mod) {
        int size = matrix.length;
        long[][] result = identityMatrix(size);

        while (exponent > 0) {
            if (exponent % 2 != 0) {
                result = multiplyMatrices(result, matrix, mod);
            }
            matrix = multiplyMatrices(matrix, matrix, mod);
            exponent /= 2;
        }

        return result;
    }

    private static long[][] identityMatrix(int size) {
        long[][] identity = new long[size][size];
        for (int i = 0; i < size; i++) {
            identity[i][i] = 1;
        }
        return identity;
    }

    private static long[][] multiplyMatrices(long[][] m1, long[][] m2, int mod) {
        int size = m1.length;
        long[][] result = new long[size][size];

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                for (int k = 0; k < size; k++) {
                    result[i][j] = (result[i][j] + m1[i][k] * m2[k][j]) % mod;
                }
            }
        }

        return result;
    }
}

