import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.math.BigInteger;

public class Main {

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] line = reader.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int k = Integer.parseInt(line[1]);
        line = reader.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(line[i]);
        }
        BigInteger mod = BigInteger.valueOf((long)Math.pow(10, 9) + 7);
        BigInteger[][] dp = new BigInteger[110][110];
        for (int i = 0; i <= 109; i++) {
            for (int j = 0; j <= 109; j++) {
                dp[i][j] = BigInteger.valueOf(-1);
            }
        }

        BigInteger result = solve(n, k, a, dp, mod);
        if (result.equals(BigInteger.ZERO)) {
            System.out.println(0);
        } else {
            BigInteger binomN2K = binomialCoefficient(n, 2).modPow(BigInteger.valueOf(k), mod);
            BigInteger modInvQ = binomN2K.modInverse(mod);
            System.out.println(result.multiply(modInvQ).mod(mod));
        }
    }

    private static BigInteger binomialCoefficient(int n, int k) {
        BigInteger[] binom = new BigInteger[n + 1];
        binom[0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            binom[i] = BigInteger.valueOf(i).multiply(binom[i - 1]).divide(BigInteger.valueOf(i));
        }
        return binom[k];
    }

    private static BigInteger solve(int n, int k, int[] a, BigInteger[][] dp, BigInteger mod) {
        int ones = 0;
        for (int value : a) {
            ones += value;
        }
        int zeros = n - ones;
        BigInteger[][] M = new BigInteger[zeros + 1][zeros + 1];
        for (int row = Math.max(0, zeros - ones); row <= zeros; row++) {
            int preZeros = row;
            int preOnes = zeros - preZeros;
            int postZeros = preOnes;
            int postOnes = ones - preOnes;
            M[row][row] = BigInteger.valueOf(preOnes * postOnes + preZeros * postZeros + binomialCoefficient(zeros, 2).add(binomialCoefficient(ones, 2)));
            if (row > Math.max(0, zeros - ones)) {
                M[row - 1][row] = BigInteger.valueOf(preZeros * postOnes);
            }
            if (row < zeros) {
                M[row + 1][row] = BigInteger.valueOf(postZeros * preOnes);
            }
        }
        BigInteger[] b = new BigInteger[zeros + 1];
        b[zeros - countZerosBefore(a, zeros)] = BigInteger.ONE;
        BigInteger[] C = multiply(M, b, mod);
        return C[C.length - 1];
    }

    private static int countZerosBefore(int[] a, int index) {
        int count = 0;
        for (int i = 0; i < index; i++) {
            if (a[i] == 0) {
                count++;
            }
        }
        return count;
    }

    private static BigInteger[] multiply(BigInteger[][] A, BigInteger[] B, BigInteger mod) {
        int lenA = A.length;
        int lenB = B.length;
        BigInteger[] C = new BigInteger[lenA];
        for (int row = 0; row < lenA; row++) {
            if (sumRow(A[row]) == 0) {
                continue;
            }
            for (int col = 0; col < lenB; col++) {
                BigInteger sum = BigInteger.ZERO;
                for (int k = 0; k < lenB; k++) {
                    sum = sum.add(A[row][k].multiply(B[k].modPow(BigInteger.TWO, mod)).mod(mod));
                }
                C[row] = C[row].add(sum);
            }
        }
        return C;
    }

    private static BigInteger sumRow(BigInteger[] row) {
        BigInteger sum = BigInteger.ZERO;
        for (BigInteger value : row) {
            sum = sum.add(value);
        }
        return sum;
    }

    private static BigInteger modInverse(BigInteger a, BigInteger m) {
        BigInteger m0 = m;
        BigInteger y = BigInteger.ZERO;
        BigInteger x = BigInteger.ONE;
        if (m.compareTo(BigInteger.ONE) == 0) {
            return BigInteger.ZERO;
        }
        while (a.compareTo(BigInteger.ONE) > 0) {
            BigInteger q = a.divide(m);
            BigInteger t = m;
            m = a.mod(m);
            a = t;
            t = y;
            y = x.subtract(q.multiply(y));
            x = t;
        }
        if (x.compareTo(BigInteger.ZERO) < 0) {
            x = x.add(m0);
        }
        return x;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long mod = 1000000007;

        if (n % (mod - 1) == 0) {
            System.out.println(1);
        } else {
            long result = (power(2, n - 1, mod) + power(2, 2 * n - 1, mod)) % mod;
            System.out.println(result);
        }

        scanner.close();
    }

    private static long power(long base, int exponent, long mod) {
        long result = 1;
        while (exponent > 0) {
            if (exponent % 2 == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exponent /= 2;
        }
        return result;
    }
}

