import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] nums = Arrays.stream(scanner.nextLine().split(" "))
                           .mapToInt(Integer::parseInt)
                           .toArray();
        String[] o = scanner.nextLine().split(" ");

        double min = Double.MAX_VALUE;
        for (int[] perm : getPermutations(nums)) {
            int a = perm[0];
            int b = perm[1];
            int c = perm[2];
            int d = perm[3];
            double result = eval(o[0], o[1], a, b, c, d);
            if (result < min) {
                min = result;
            }
        }

        System.out.println(min);
    }

    private static int[][] getPermutations(int[] nums) {
        if (nums.length != 4) {
            throw new IllegalArgumentException("Input array must have exactly 4 elements");
        }
        return new int[][]{
            {nums[0], nums[1], nums[2], nums[3]},
            {nums[0], nums[1], nums[3], nums[2]},
            {nums[0], nums[2], nums[1], nums[3]},
            {nums[0], nums[2], nums[3], nums[1]},
            {nums[0], nums[3], nums[1], nums[2]},
            {nums[0], nums[3], nums[2], nums[1]},
            {nums[1], nums[0], nums[2], nums[3]},
            {nums[1], nums[0], nums[3], nums[2]},
            {nums[1], nums[2], nums[0], nums[3]},
            {nums[1], nums[2], nums[3], nums[0]},
            {nums[1], nums[3], nums[0], nums[2]},
            {nums[1], nums[3], nums[2], nums[0]},
            {nums[2], nums[0], nums[1], nums[3]},
            {nums[2], nums[0], nums[3], nums[1]},
            {nums[2], nums[1], nums[0], nums[3]},
            {nums[2], nums[1], nums[3], nums[0]},
            {nums[2], nums[3], nums[0], nums[1]},
            {nums[2], nums[3], nums[1], nums[0]},
            {nums[3], nums[0], nums[1], nums[2]},
            {nums[3], nums[0], nums[2], nums[1]},
            {nums[3], nums[1], nums[0], nums[2]},
            {nums[3], nums[1], nums[2], nums[0]},
            {nums[3], nums[2], nums[0], nums[1]},
            {nums[3], nums[2], nums[1], nums[0]}
        };
    }

    private static double eval(String op1, String op2, int a, int b, int c, int d) {
        double subResult1 = applyOp(op1.charAt(0), a, b);
        double subResult2 = applyOp(op1.charAt(0), c, d);
        double result1 = applyOp(op2.charAt(0), subResult1, subResult2);

        subResult1 = applyOp(op1.charAt(0), a, b);
        result1 = applyOp(op2.charAt(0), result1, applyOp(op1.charAt(0), c, d));

        return Math.min(result1, subResult1);
    }

    private static double applyOp(char op, int a, int b) {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return (double) a * b; // Ensure floating point division
            case '/': if (b == 0) throw new ArithmeticException("Division by zero"); else return (double) a / b;
            default: throw new IllegalArgumentException("Invalid operator: " + op);
        }
    }
}

