public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int b = scanner.nextInt();
        System.out.println(findFactors(b));
        scanner.close();
    }

    private static int findFactors(int b) {
        HashSet<Integer> used = new HashSet<>();
        if (b == 1) {
            return 1;
        }
        used.add(1);
        used.add(b);
        for (int i = 2; i <= Math.sqrt(b); i++) {
            if (b % i == 0) {
                used.add(i);
                used.add(b / i);
            }
        }
        return used.size();
    }
}

