import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int M = scanner.nextInt();
        int K = scanner.nextInt();

        int np = 1 << N;
        int[][] dp = new int[np][np];
        int[][] g = new int[N][N];

        for (int i = 0; i < M; i++) {
            int v = scanner.nextInt() - 1;
            int u = scanner.nextInt() - 1;
            g[u][v] = 1;
            g[v][u] = 1;
            int s = (1 << v) | (1 << u);
            dp[s][s] = 1;
        }

        for (int i = 0; i < np; i++) {
            int bs = bits(i);
            if (bs <= 2) {
                continue;
            }
            int j = i;
            while (j != 0) {
                get(i, j, dp, g, N);
                j = (j - 1) & i;
            }
        }

        int ans = 0;
        for (int i = 0; i < np; i++) {
            if (bits(i) == K) {
                ans += dp[np - 1][i];
            }
        }

        System.out.println(ans);
    }

    public static int bits(int i) {
        int tmp = i;
        int ans = 0;
        while (tmp != 0) {
            if ((tmp & 1) == 1) {
                ans += 1;
            }
            tmp >>= 1;
        }
        return ans;
    }

    public static void get(int i, int j, int[][] dp, int[][] g, int N) {
        int k = 0;
        while (((1 << k) & j) == 0) {
            k += 1;
        }

        int tj = j - (1 << k);
        int ti = i - (1 << k);
        for (int p = 0; p < N; p++) {
            if (g[k][p] == 0 || ((1 << p) & ti) == 0 || ((1 << p) & tj)) {
                continue;
            }
            dp[i][j] += dp[ti][tj] + dp[ti][tj + (1 << p)];
        }
    }
}

