        long startTime = System.currentTimeMillis();

        int s = 0;
        int mi = (int) Math.pow(10, 20);
        for (int i = 0; i < 8; i++) {
            if (s + M[i] * (i + 1) <= W) {
                s += M[i] * (i + 1);
                A[i] = M[i];
            } else {
                int t = (W - s) / (i + 1);
                s += t * (i + 1);
                A[i] += t;
            }

            if (s <= W) {
                mi = Math.min(mi, W - s);
            }
