import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String orig = scanner.nextLine();

        Set<String> s = new HashSet<>();
        for (String c : permute(orig)) {
            s.add(incrementalInstance(c));
        }
        System.out.println(s.size());
    }

    private static List<String> permute(String str) {
        return str.length() == 0 
                ? Collections.singletonList("") 
                : IntStream.range(0, str.length())
                        .flatMap(i -> permute(str.substring(0, i) + str.substring(i + 1)).stream()
                                .map(t -> str.charAt(i) + t))
                        .collect(Collectors.toList());
    }

    private static String incrementalInstance(String curr) {
        Set<String> s = new HashSet<>();
        int[] l1 = {1, 2, 3, 0, 4, 5};
        int[] l2 = {4, 1, 5, 3, 2, 0};
        int[] l3 = {0, 4, 2, 5, 3, 1};

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    s.add(curr);
                    curr = perm(curr, l1);
                }
                curr = perm(curr, l3);
            }
            curr = perm(curr, l2);
        }
        return Collections.min(new ArrayList<>(s));
    }

    private static String perm(String curr, int[] mapping) {
        StringBuilder sb = new StringBuilder();
        for (char c : curr.toCharArray()) {
            sb.append(mapping[Character.getNumericValue(c)]);
        }
        return sb.toString();
    }
}

