import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        long inf = 998244353;

        Comb c1 = new Comb(n, inf);
        long ans = 0;

        int i = 1;
        while (i * k <= n) {
            long cnt = n / i - 1;
            long r = k - 1;
            ans = (ans + c1.ncr(cnt, r)) % inf;
            i++;
        }

        System.out.println(ans);
    }

    static class Pow3 {
        public static long pow3(long a, long b, long mod) {
            long ans = 1;
            while (b > 0) {
                if ((b & 1) != 0) {
                    ans = (ans * a) % mod;
                }
                a = (a * a) % mod;
                b >>= 1;
            }
            return ans;
        }
    }

    static class Comb {
        private final long inf;
        private final long[] fact;
        private final long[] inv;

        public Comb(int n, long infi) {
            this.inf = infi;
            this.fact = new long[n + 1];
            this.inv = new long[n + 1];
            this.fact[0] = 1;
            for (int i = 1; i <= n; i++) {
                this.fact[i] = (this.fact[i - 1] * i) % inf;
            }
            for (int i = 0; i <= n; i++) {
                this.inv[i] = Pow3.pow3(this.fact[i], inf - 2, inf);
            }
        }

        public long ncr(int n, int r) {
            long ans = this.fact[n];
            ans = (ans * this.inv[r]) % inf;
            ans = (ans * this.inv[n - r]) % inf;
            return ans;
        }

        public long f(int n) {
            return this.fact[n];
        }

        public long iv(int n) {
            return this.inv[n];
        }
    }
}

