public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        String[] parts = line.split(" ");
        int n = Integer.parseInt(parts[0]);
        int s = Integer.parseInt(parts[1]);

        System.out.println(reallyBig(n, s));
    }

    public static int reallyBig(int n, int s) {
        if (s >= n) {
            return 0;
        }
        for (int i = s + 1; i <= n; i++) {
            int sumOfDigits = 0;
            int t = i;
            while (t > 0) {
                sumOfDigits += t % 10;
                t /= 10;
            }
            if (i - sumOfDigits >= s) {
                return n - i + 1;
            }
        }
        return 0;
    }
}

