            for (int j = 0; j < n; j++) {
                for (int l = 0; l <= n; l++) {
                    q[i][j][l] = -1;
                }
            }
        }

        System.out.println(g(0, 0, k));
    }

    private static int g(int i, int z, int k) {
        if (i >= n) return 0;
        if (q[i][z][k] > -1) return q[i][z][k];

