public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int prime = 998244353;
        String[] inputs = scanner.nextLine().split(" ");
        int n = Integer.parseInt(inputs[0]);
        int m = Integer.parseInt(inputs[1]);
        long z = 0;

        for (int i = 1; i <= n; i++) z += modInverse(i, prime);
        long ans = (1L + m * z) * (1L + n * modInverse(m + 1, prime));
        System.out.println(ans % prime);

        scanner.close();
    }

    public static long modInverse(long a, int m) {
        int m0 = m, y = 0, x = 1;
        if (m == 1) return 0;
        while (a > 1) {
            int q = a / m;
            long t = m;
            m = a % m;
            a = t;
            t = y;
            y = x - q * y;
            x = t;
        }
        if (x < 0) x += m0;
        return x;
    }
}

