import java.util.HashSet;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        HashSet<Integer> st = new HashSet<>();
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        if (ch(x, y, 0, st)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
        scanner.close();
    }

    private static int debin(String s) {
        int ret = 0;
        int mn = 1;
        for (int i = s.length() - 1; i >= 0; i--) {
            ret += Character.getNumericValue(s.charAt(i)) * mn;
            mn *= 2;
        }
        return ret;
    }

    private static boolean ch(int x, int y, int deep, HashSet<Integer> st) {
        if (st.contains(x)) {
            return false;
        }
        st.add(x);
        if (x == y) {
            return true;
        }
        if (deep == 150) {
            return false;
        }
        String s = Integer.toBinaryString(x);
        return ch(debin(new StringBuilder(s).reverse().toString()), y, deep + 1, st) ||
               ch(debin("1" + new StringBuilder(s).reverse().toString()), y, deep + 1, st);
    }
}

import java.util.*;

public class Main {
    private static final long INF = (long) 1e10;
    private static final String YES = "YES";
    private static final String NO = "NO";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long X = scanner.nextLong();
        long Y = scanner.nextLong();
        System.out.println(solve(X, Y));
    }

    private static boolean dfs(String s, String SY, Set<Long> ng) {
        if (s.equals(SY)) {
            return true;
        }
        long n = Long.parseLong(s);
        if (ng.contains(n)) {
            return false;
        }
        if (s.length() > 100) {
            return false;
        }
        ng.add(n);

        String s1 = new StringBuilder(new StringBuilder(s).reverse()).toString();
        String s2 = new StringBuilder((s + "1")).reverse().toString();

        if (!ng.contains(Long.parseLong(s1)) && dfs(s1, SY, ng)) {
            return true;
        }
        if (!ng.contains(Long.parseLong(s2)) && dfs(s2, SY, ng)) {
            return true;
        }

        return false;
    }

    private static String solve(long X, long Y) {
        if (X == Y) {
            return YES;
        }

        String SX = Long.toBinaryString(X);
        String SY = Long.toBinaryString(Y);

        Set<Long> ng = new HashSet<>();
        if (dfs(SX, SY, ng)) {
            return YES;
        }

        return NO;
    }
}

