public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int r = 0;
        while (n != 0) {
            int d = prime(n);
            if (d == n) {
                r += 1;
                break;
            } else {
                if (n % 2 == 0) {
                    r = r + n / 2;
                    break;
                } else {
                    n -= d;
                    r += 1;
                }
            }
        }
        System.out.println(r);
        scanner.close();
    }

    public static int prime(int n) {
        int i = 2;
        while (i <= Math.sqrt(n)) {
            if (n % i == 0) {
                return i;
            } else {
                if (i == 2) {
                    i += 1;
                } else {
                    i += 2;
                }
            }
        }
        return n;
    }
}

