                    H[i][j] = 1;
                } else if (j >= i) {
                    H[i][j] = (H[i - 1][j] + H[i][j - 1]) % MOD;
                }
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (j == 0) {
                    G[i][0] = i;
                } else if (i == 0) {
                    G[0][j] = 0;
                } else {
                    G[i][j] = (G[i - 1][j] + G[i][j - 1] + H[i][j - 1] + B[i - 1][j] - B[i][j - 1]) % MOD;
                }
            }
        }

        System.out.println(G[n][m]);
    }
}

