import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputs = scanner.nextLine().split(" ");
        BigInteger n = new BigInteger(inputs[0]);
        BigInteger mod = new BigInteger(inputs[1]);

        BigInteger[] mem = new BigInteger[n.intValue() + 1];
        mem[0] = BigInteger.ZERO;
        mem[1] = BigInteger.ONE;
        BigInteger su = BigInteger.ONE;

        for (BigInteger i = BigInteger.valueOf(2); i.compareTo(n) <= 0; i = i.add(BigInteger.ONE)) {
            BigInteger sq = i.sqrt();
            sq = sq.add(BigInteger.ONE);
            BigInteger cur = su;

            for (BigInteger f = BigInteger.valueOf(2); f.compareTo(sq) < 0; f = f.add(BigInteger.ONE)) {
                cur = cur.add(modAdd(cur, mem[i.divide(f)]));
            }

            BigInteger be = i;
            for (BigInteger j = BigInteger.ONE; j.compareTo(i.divide(sq).add(BigInteger.ONE)) < 0; j = j.add(BigInteger.ONE)) {
                BigInteger nxt = i.divide(j.add(BigInteger.ONE));
                cur = cur.add(modMul(modSub(be, nxt), mem[j]));
                be = nxt;
            }

            su = modAdd(su, cur);
            mem[i.intValue()] = cur;
        }

        System.out.println(mem[n.intValue()]);
    }

    private static BigInteger modAdd(BigInteger a, BigInteger b) {
        return a.add(b).mod(a);
    }

    private static BigInteger modSub(BigInteger a, BigInteger b) {
        return a.subtract(b).mod(a);
    }

    private static BigInteger modMul(BigInteger a, BigInteger b) {
        return a.multiply(b).mod(a);
    }
}

import java.util.Scanner;

public class Main {
    static long[] fac;
    static final long mod = (long) 1e9 + 7;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long f = scanner.nextLong();
        long w = scanner.nextLong();
        long h = scanner.nextLong();

        fac = buildFac();
        long cnt = cf(f, w, h);
        long result = (cnt * inv(ncr(f + w, w))) % mod;

        System.out.println(result);
    }

    static long[] buildFac() {
        long[] fac = new long[(int) 3e5 + 1];
        fac[0] = 1;
        for (int i = 1; i < fac.length - 1; i++) {
            fac[i] = (i * fac[i - 1]) % mod;
        }
        return fac;
    }

    static long inv(long x) {
        return power(x, mod - 2, mod);
    }

    static long ncr(long n, long r) {
        if (n < 0 || n < r) return 0;
        return (fac[(int) n] * inv(fac[(int) r])) % mod * inv(fac[(int) (n - r)]) % mod;
    }

    static long cf(long f, long w, long h) {
        if (w == 0) return 1;
        long rs = 0;
        for (long k = 1; k <= Math.min(w / (h + 1), f); k++) {
            rs = (rs + ncr(f + 1, k) * ncr(w - k * h - 1, k - 1)) % mod;
        }
        return rs;
    }

    static long power(long base, long exp, long mod) {
        if (exp == 0) return 1;
        long halfPower = power(base, exp / 2, mod);
        if ((exp & 1) == 0) return (halfPower * halfPower) % mod;
        else return (((halfPower * halfPower) % mod) * base) % mod;
    }
}

