            if (i == 0) {
                break;
            }
            tree[i] = (tree[2 * i] + tree[2 * i + 1]) % mod;
            i /= 2;
        }
    }

    private static int getSum(int s, int t) {
        s += tree.length / 2;
        t += tree.length / 2;
        int ans = 0;
        while (true) {
            if (s > t) {
                break;
            }
            if (s % 2 == 0) {
                s /= 2;
            } else {
                ans = (ans + tree[s]) % mod;
                s = (s + 1) / 2;
            }
            if (t % 2 == 1) {
                t /= 2;
            } else {
                ans = (ans + tree[t]) % mod;
                t = (t - 1) / 2;
            }
        }
        return ans;
    }

    private static int[] primeFactorize(int n) {
        int[] ans = new int[0];
        for (int i = 2; i <= Math.sqrt(n); i++) {
            while (true) {
                if (n % i != 0) {
                    break;
                }
                ans = append(ans, i);
                n /= i;
            }
            if (n == 1) {
                break;
            }
        }
        if (n != 1) {
            ans = append(ans, n);
        }
        return ans;
    }

    private static int eulerFunc(int n) {
        int[] p = removeDuplicates(primeFactorize(n));
        long x = n;
        for (int i : p) {
            x = (x * (i - 1)) / i;
        }
        return (int) x;
    }

