    }

    public static int solve(int n, int mod) {
        if (n <= 3) {
            return 0;
        } else {
            int lastAns = 17;
            int ans = 17;
            int size = (n - 1) * (n - 2) / 2 + 1;
            int inv = 1;
            int[][] record = new int[2][size + 1];
            record[0][0] = 1;
            record[0][1] = 2;
            record[0][2] = 2;
            record[0][3] = 1;
            for (int m = 4; m < n; m++) {
                int tpSize = m * (m - 1) / 2;
                ans = (m + 1) * lastAns % mod;
                int tp = 0;
                for (int i = 0; i < m; i++) {
                    tp += record[inv ^ 1][i];
                    record[inv][i] = tp % mod;
                }
                for (int i = m; i <= tpSize / 2; i++) {
                    tp += record[inv ^ 1][i];
                    tp -= record[inv ^ 1][i - m];
                    record[inv][i] = tp % mod;
                }
                for (int i = tpSize / 2 + 1; i < tpSize; i++) {
                    record[inv][tpSize - i] = record[inv][i];
                }
                int total = 0;
                for (int i = 0; i < tpSize - 1; i++) {
                    tp = 0;
                    for (int j = Math.max(1, -tpSize + i + m + 2); j <= m; j++) {
                        tp += j * record[inv][m + 2 - j + i];
                    }
                    total += record[inv][i];
                    total %= mod;
                    tp *= total;
                    tp %= mod;
                    ans += tp;
                    ans %= mod;
                }
                lastAns = ans;
                inv ^= 1;
            }
            return ans % mod;
        }
    }
