        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int mod = Integer.parseInt(line[1]);

        if (n == 1) {
            System.out.println(0);
            return;
        }

        long[] z = {1};
        long aaa = 0L;
        for (int i = 2; i <= n; i++) {
            long[] nz = new long[i * i / 2];
            for (int j = 0; j < z.length; j++) {
                for (int k = 0; k < i; k++) {
                    if (z[j] > 0) {
                        nz[i - k - 1 + j] += z[j];
                    }
                }
            }
            long bbb = 0L;
            long[] d = new long[z.length + 1];
            for (int w = z.length - 1; w >= 0; w--) {
                d[w] = (d[w + 1] + z[w]) % mod;
            }
            long[] e = new long[d.length + 1];
            long[] f = new long[d.length + 1];
            for (int w = 0; w < e.length - 1; w++) {
                e[w + 1] = (e[w] + d[w]) % mod;
                f[w + 1] = (f[w] - (long) w * d[w]) % mod;
            }
            for (int jj = 0; jj < z.length; jj++) {
                long ccc = 0L;
                int L = jj + 2;
                int R = Math.min(z.length - 1, i + jj);
                if (R >= L) {
                    ccc = ((e[R + 1] - e[L]) * (i + 1 + jj) +
                            (f[R + 1] - f[L])) % mod;
                }
                bbb = (bbb + ccc * z[jj]) % mod;
            }
            aaa += (bbb * A(n, n - i)) % mod;
            z = nz;
        }
        System.out.println(aaa % mod);
    }

    private static long A(long n, long k) {
        return factorial(n) / factorial(n - k);
    }

    private static long factorial(long num) {
        if (num <= 1) {
            return 1;
        } else {
            return num * factorial(num - 1);
        }
    }
}

