import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        long a1 = scanner.nextLong();
        long b1 = scanner.nextLong();
        long a2 = scanner.nextLong();
        long b2 = scanner.nextLong();
        long l = scanner.nextLong();
        long r = scanner.nextLong();

        if (b2 < b1) {
            long tempA = a1; a1 = a2; a2 = tempA;
            long tempB = b1; b1 = b2; b2 = tempB;
        }

        long[] result = xgcd(a1, a2);
        long g = result[0], x = result[1], y = result[2];

        if ((b2 - b1) % g != 0) {
            System.out.println(0);
        } else {
            x *= ((b2 - b1) / g);
            y *= ((b2 - b1) / g);

            long li1 = Math.max(upw(-x * g, a2), upw(y * g, a1));
            long li2 = upw((l - a1 * x - b1) * g, a1 * a2);
            long ls = dwn((r - a1 * x - b1) * g, a1 * a2);
            long li = Math.max(li1, li2);

            if (li > ls) {
                System.out.println(0);
            } else {
                System.out.println(ls - li + 1);
            }
        }

        scanner.close();
    }

    public static double upw(long a, long b) {
        if (a > 0) return (double)(a + b - 1) / b;
        a = -a;
        return -(double)a / b;
    }

    public static double dwn(long a, long b) {
        if (a > 0) return (double)a / b;
        a = -a;
        return -(double)((a + b - 1) / b);
    }

    public static long[] xgcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] result = xgcd(b, a % b);
        long g = result[0], x1 = result[1], y1 = result[2];
        return new long[]{g, y1, x1 - (a / b) * y1};
    }
}

