import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] inputs = reader.readLine().trim().split(" ");
        int n = Integer.parseInt(inputs[0]);
        int k = Integer.parseInt(inputs[1]);

        long[][] memo3 = new long[k + 1][(n * (n - 1)) / 2 + 2];
        for (int i = 0; i <= k; i++) {
            memo3[i][0] = 1;
            for (int j = 1; j < (n * (n - 1)) / 2 + 2; j++) {
                memo3[i][j] = memo3[i][j - 1] * i;
                memo3[i][j] %= MOD;
            }
        }

        System.out.println(go(n - 1, 0, memo3, new Long[n * n], new Long[(n * (n - 1)) / 2]));
    }

    private static long go(int left, int last, long[][] memo3, Long[] memo, Long[] invMemo) {
        if (left == 0) {
            return 1;
        }
        if (last == memo.length - 1) {
            return 0;
        }
        int st = left * 300 + last;
        if (memo[st] == null) {
            long scale = 1;
            memo[st] = 0;
            int comp = n - left;
            for (int i = 0; i <= left; i++) {
                long ex = (long) (comp - 1) * i + (i * (i - 1)) / 2;
                memo[st] += go(left - i, last + 1, memo3, memo, invMemo) * scale * memo3[memo.length - 1 - last][i];
                scale *= (left - i);
                scale *= inv(i + 1, invMemo);
                scale %= MOD;
            }
            memo[st] %= MOD;
        }
        return memo[st];
    }

    private static long inv(int x, Long[] invMemo) {
        if (invMemo[x] == null) {
            invMemo[x] = powMod(x, MOD - 2, MOD);
        }
        return invMemo[x];
    }

    private static long powMod(long base, long exp, long mod) {
        if (exp == 0) {
            return 1;
        }
        if (exp == 1) {
            return base % mod;
        }
        long s = powMod(base, exp >> 1, mod);
        return (s * s * (base & 1) + s * s * (1 - (base & 1))) % mod;
    }
}

