    public static List<Integer> find(int n, int k, int length) {
        if (k < n) {
            List<Integer> list = new ArrayList<>();
            list.add(k);
            return list;
        } else {
            int max = 0;
            int index = 1;

            for (int i = 1; i <= length; i++) {
                int temp = k % (int) Math.pow(10, i);
                if (temp >= n) {
                    break;
                } else {
                    if (temp >= (int) Math.pow(10, i - 1)) {
                        max = temp;
                        index = i;
                    }
                }
            }

            int res = k - max;
            res /= (int) Math.pow(10, index);
            return find(n, res, length).add(max);
        }
    }
}

