        while (x <= p) {
            int a = Math.min(s[i][1] * 3 + 2, p);
            int b = Math.min(s[j][1] * 3 / 2, p);
            int c = 0;
            for (int k = 0; k < 3; k++) {
                if (!contains(new int[]{s[i][2], s[j][2]}, k)) {
                    c = k;
                    break;
                }
            }
            if (a <= b) {
