import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        long ans = 0;
        for (int i = 1; i <= n; i++) {
            long pp = 1;
            int i1 = i;
            for (int j = 2; j <= i; j++) {
                int sch = 0;
                while (i1 % j == 0) {
                    sch++;
                    i1 /= j;
                }
                if (sch != 0) {
                    pp *= cou(sch + k - 1, sch);
                }
            }
            ans += pp;
            ans %= 1000000007;
        }

        System.out.println(ans);
    }

    public static long cou(int n, int k) {
        long w = 1;
        for (int i = n - k + 1; i <= n; i++) {
            w *= i;
        }
        for (int i = 1; i <= k; i++) {
            w /= i;
        }
        return w;
    }
}

