        }

        int n = scanner.nextInt();
        long deno = 1L << n;
        long inv = modInverse(deno, m - 2, m);
        long ans = (fibo[n - 1] * inv) % m;
        System.out.println(ans);

        scanner.close();
    }

    private static long modInverse(long a, long b, long m) {
        if (b == 1) return a;
        long p = modInverse(a, b / 2, m);
        p = (p * p) % m;
        return (b % 2 != 0) ? ((a * p) % m) : p;
    }
}

