public class Main {
    static final int MOD = (int)1e9 + 7;
    static Map<Integer, Integer> fact = new HashMap<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        fact.put(0, 1);
        for (int i = 1; i <= n; i++) {
            fact.put(i, (fact.get(i - 1) * i) % MOD);
        }

        long ans = 0;
        for (int i = 0, j = n; i <= n; i++, j--) {
            String combined = String.valueOf(a * i + b * j);
            boolean isValid = true;
            for (char c : combined.toCharArray()) {
                if (!(c == Character.forDigit(a, 10) || c == Character.forDigit(b, 10))) {
                    isValid = false;
                    break;
                }
            }
            if (isValid) {
                ans += ((long) fact.get(n) * powMod(fact.get(n - i) * fact.get(i) % MOD, MOD - 2, MOD)) % MOD;
            }
        }

        System.out.println(ans % MOD);
    }

    private static int powMod(long base, int exp, int mod) {
        if (exp == 0) return 1;
        long result = powMod(base, exp / 2, mod);
        result = (result * result) % mod;
        if (exp % 2 != 0) result = (result * base) % mod;
        return (int) result;
    }
}

