public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        int a = scanner.nextInt();
        int b = scanner.nextInt();

        int GCD = gcd(a, b);

        // when a > b,
        int[] MODLIST = new int[a];
        for (int i = 0; i < MODLIST.length; i++) {
            MODLIST[i] = -1;
        }

        int NOWMAX = a;
        int NOW = a;
        MODLIST[0] = a;
        while (true) {
            while (NOW - b > 0 && MODLIST[(NOW - b) % a] == -1) {
                NOW -= b;
                MODLIST[NOW] = NOWMAX;
            }
            NOW += a;
            NOWMAX = Math.max(NOW, NOWMAX);

            if (MODLIST[(NOW - b) % a] != -1) {
                break;
            }
        }

        int ANS = m + 1; // 0
        int MAX = getMaxValueInArray(MODLIST);
        for (int i = 1; i < Math.min(m + 1, MAX); i++) {
            if (MODLIST[i % a] == -1) {
                continue;
            }
            ANS += Math.max((m + 1 - Math.max(MODLIST[i % a], i)), 0);
        }

        if (MAX <= m) {
            ANS += (m - MAX + 1 + (m - m / GCD * GCD) + 1) * ((m / GCD * GCD - MAX) / GCD + 1) / 2;
        }

        System.out.println(ANS);
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    private static int getMaxValueInArray(int[] array) {
        int max = Integer.MIN_VALUE;
        for (int value : array) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }
}

import java.util.*;

public class Main {
    public static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        int a = scanner.nextInt();
        int b = scanner.nextInt();

        int m0 = Math.min(a + b - 1, m);

        boolean[] canGet = new boolean[m0 + 1];
        Arrays.fill(canGet, false);
        canGet[0] = true;
        int count = 1;
        int total = 1;

        Queue<Integer> queue = new ArrayDeque<>();
        for (int x = 1; x <= m0; x++) {
            if (x - a >= 0 && canGet[x - a]) {
                canGet[x] = true;
                count++;
                queue.add(x);
                while (!queue.isEmpty()) {
                    int j = queue.poll();
                    if (j + a <= x && !canGet[j + a]) {
                        canGet[j + a] = true;
                        count++;
                        queue.add(j + a);
                    }
                    if (j - b >= 0 && !canGet[j - b]) {
                        canGet[j - b] = true;
                        count++;
                        queue.add(j - b);
                    }
                }
            }
            total += count;
        }

        int g = gcd(a, b);

        int m1 = Math.min(m, ((m0 + g) / g) * g - 1);
        total += (m1 - m0) * count;

        int m2 = (m / g) * g - 1;
        if (m2 >= m1) {
            total += ((m2 - m1) / g) * g * ((m1 + 1) / g + (m2 + 1) / g + 1) / 2;
            total += (m - m2) * (m / g + 1);
        }

        System.out.println(total);
    }
}

