        int a = scanner.nextInt();
        int b = scanner.nextInt();
        unusualSeq(a, b);
    }

    public static void unusualSeq(int a, int b) {
        if (b % a != 0) {
            System.out.println(0);
        } else {
            b /= a;
            Set<Integer> set = new HashSet<>();
            for (int i = 1; i <= Math.sqrt(b); i++) {
                if (b % i == 0) {
                    set.add(i);
                    set.add(b / i);
                }
            }
            List<Integer> list = new ArrayList<>(set);
            Collections.sort(list);

            List<Long> f = new ArrayList<>(Collections.nCopies(list.size(), 0L));
            for (int i = 0; i < list.size(); i++) {
                f.set(i, pow(2, list.get(i) - 1, (int) 1e9 + 7));
                for (int j = 0; j < i; j++) {
                    if (list.get(i) % list.get(j) == 0) {
                        f.set(i, f.get(i) - f.get(j));
                    }
                }
            }
            System.out.println(f.get(f.size() - 1) % (int) 1e9 + 7);
        }
    }

    private static long pow(long base, long exp, int mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

