public class Main {
    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        long p = 1_000_000_007;
        int l = scanner.nextInt();
        int r = scanner.nextInt();
        System.out.println((G(r, p) - G(l - 1, p) + p) % p);
    }

    private static long S(int x, long p) {
        if (x == 0) {
            return 0;
        } else if (x == 1) {
            return 4;
        } else if ((x & 1) != 0) {
            return (11 * pow(3, x / 2, p) - 7 + p) % p;
        } else {
            return (19 * pow(3, x / 2 - 1, p) - 7 + p) % p;
        }
    }

    private static long G(int x, long p) {
        return (S(x, p) + S(x + 1 >> 1, p)) * pow(2, p - 2, p) % p;
    }

    private static long pow(long base, int exp, long mod) {
        if (exp == 0) {
            return 1;
        }
        long halfPower = pow(base, exp / 2, mod);
        long result = (halfPower * halfPower) % mod;
        if (exp % 2 != 0) {
            result = (result * base) % mod;
        }
        return result;
    }
}

