public class Main {
    private static final int MOD = 1000000007;

    public static int[][] multMM(int[][] a, int[][] b) {
        int n = a.length;
        int[][] r = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    r[i][j] += a[i][k] * b[k][j];
                    r[i][j] %= MOD;
                }
            }
        }
        return r;
    }

    public static int[] multMV(int[][] a, int[] v) {
        int n = a.length;
        int[] r = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                r[i] += a[i][j] * v[j];
                r[i] %= MOD;
            }
        }
        return r;
    }

    public static int[][] powM(int[][] a, int p) {
        int n = a.length;
        if (p == 0) {
            int[][] identity = new int[n][n];
            for (int i = 0; i < n; i++) {
                identity[i][i] = 1;
            }
            return identity;
        }
        if (p % 2 == 0) {
            int[][] t = powM(a, p / 2);
            return multMM(t, t);
        } else {
            return multMM(a, powM(a, p - 1));
        }
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
