import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        char[] a = input[0].toCharArray();
        int k = Integer.parseInt(input[1]);

        char[] result = yoba(a, k);
        for (char c : result) {
            System.out.print(c);
        }
    }

    public static char[] yoba(char[] a, int k) {
        if (a.length == 0) {
            return new char[0];
        } else if (k == 0) {
            return a;
        } else {
            int m = -1;
            int mi = -1;
            for (int i = 0; i <= k; i++) {
                if (a[i] > m) {
                    m = a[i];
                    mi = i;
                }
            }
            if (m > a[0]) {
                System.arraycopy(a, 0, a, 1, mi);
                a[0] = m;
                k -= mi;
            }
            char[] temp = new char[a.length - 1];
            System.arraycopy(a, 1, temp, 0, temp.length);
            return prepend(yoba(temp, k), a[0]);
        }
    }

    public static char[] prepend(char[] array, char element) {
        char[] result = new char[array.length + 1];
        result[0] = element;
        System.arraycopy(array, 0, result, 1, array.length);
        return result;
    }
}

