    private static int cnt(int n, int m, int k, int r, int c) {
        int a = k;
        if (n == 1) {
            return (a / m) + ((a % m) >= c ? 1 : 0);
        }
        int res = a / ((2 * n - 2) * m);
        if (r != 1 && r != n) {
            res *= 2;
        }
        a %= (2 * n - 2) * m;
        if (a > n * m) {
            return res + 1 + ((r != n && a - n * m >= (n - r - 1) * m + c) ? 1 : 0);
        } else {
            return res + ((a >= (r - 1) * m + c) ? 1 : 0);
        }
    }
}

import java.util.*;

public class Main {
    static final long INF = (long) 1e18;
    static final int MOD = (int) 1e9 + 7;
    static final double EPS = 1e-10;

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = 3;
        List<Integer> A = new ArrayList<>();
        List<Integer> B = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            A.add(sc.nextInt());
        }

        for (int i = 0; i < M; i++) {
            B.add(sc.nextInt());
        }

        int ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A.get(i), B.get((i + 1) % M));
        }

        int ans2 = 0;
        int nVertices = 2 * M + 2;
        Dinic dinic = new Dinic(nVertices);
        int s = 2 * M;
        int t = 2 * M + 1;

        for (int i = 0; i < M; i++) {
            // s to Alice
            dinic.addEdge(s, i, N);
            // Bob to t
            dinic.addEdge(M + i, t, B.get(i));
            // draw
            dinic.addEdge(i, M + i, A.get(i));
            // Alice lose
            dinic.addEdge(i, M + (i - 1 + M) % M, A.get(i));
        }

        ans2 = N - dinic.flow(s, t);

        System.out.println(ans2 + " " + ans1);
    }

    static class Dinic {
        private int n;
        private List<int[]>[] links;
        private int[] depth;
        private int[] progress;
        private int[][] pos;

        public Dinic(int n) {
            this.n = n;
            links = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                links[i] = new ArrayList<>();
            }
            depth = new int[n];
            progress = new int[n];
            pos = new int[0][];
        }

        public void addEdge(int from, int to, int cap) {
            pos = Arrays.copyOf(pos, pos.length + 1);
            pos[pos.length - 1] = new int[]{from, links[from].size()};
            links[from].add(new int[]{cap, to, links[to].size()});
            links[to].add(new int[]{0, from, links[from].size() - 1});
        }

        public void bfs(int s) {
            Queue<Integer> queue = new ArrayDeque<>();
            Arrays.fill(depth, -1);
            depth[s] = 0;
            queue.offer(s);
            while (!queue.isEmpty()) {
                int v = queue.poll();
                for (int[] edge : links[v]) {
                    int cap = edge[0];
                    int to = edge[1];
                    if (cap > 0 && depth[to] < 0) {
                        depth[to] = depth[v] + 1;
                        queue.offer(to);
                    }
                }
            }
        }

        public int dfs(int v, int t, int flow) {
            if (v == t) {
                return flow;
            }
            int[] linksV = links[v].toArray(new int[0][]);
            for (int i = progress[v]; i < linksV.length; i++) {
                progress[v] = i;
                int[] link = linksV[i];
                int cap = link[0];
                int to = link[1];
                int rev = link[2];
                if (cap == 0 || depth[v] >= depth[to]) {
                    continue;
                }
                int d = dfs(to, t, Math.min(flow, cap));
                if (d == 0) {
                    continue;
                }
                link[0] -= d;
                links[to][rev][0] += d;
                return d;
            }
            return 0;
        }

        public int flow(int s, int t) {
            int flow = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0) {
                    return flow;
                }
                Arrays.fill(progress, 0);
                int currentFlow = dfs(s, t, (int) INF);
                while (currentFlow > 0) {
                    flow += currentFlow;
                    currentFlow = dfs(s, t, (int) INF);
                }
            }
        }

        public int[] getEdge(int i) {
            int[] e = links[pos[i][0]].get(pos[i][1]);
            int[] re = links[e[1]].get(e[2]);
            return new int[]{pos[i][0], e[1], e[0] + re[0], re[0]};
        }

        public List<int[]> getEdges() {
            List<int[]> res = new ArrayList<>();
            for (int i = 0; i < pos.length; i++) {
                res.add(getEdge(i));
            }
            return res;
        }
    }
}

