        Scanner scanner = new Scanner(System.in);
        String[] nm = scanner.nextLine().split(" ");
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);

        int[][] G = new int[n][n];
        for (int i = 0; i < m; i++) {
            String[] uv = scanner.nextLine().split(" ");
            int u = Integer.parseInt(uv[0]) - 1;
            int v = Integer.parseInt(uv[1]) - 1;
            G[u][v] = G[v][u] = 1;
        }

        char[] s = new char[n];

        Arrays.fill(s, ' ');

        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (G[i][j] == 1) {
                    count++;
                }
            }
            if (count == n - 1) {
                s[i] = 'b';
            }
        }

        int anode = -1;
        for (int i = 0; i < n; i++) {
            if (s[i] == ' ') {
                anode = i;
                break;
            }
        }

        if (anode == -1) {
            System.out.println("Yes");
            System.out.println(new String(s));
            return;
        }

        s[anode] = 'a';

        for (int i = 0; i < n; i++) {
            if (s[i] == ' ' && G[anode][i] == 1) {
                s[i] = 'a';
            } else if (s[i] == ' ' && G[anode][i] == 0) {
                s[i] = 'c';
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if ((s[i] != s[j] && s[i] != 'b' && s[j] != 'b') != G[i][j]) {
                    System.out.println("No");
                    return;
                }
            }
        }

        System.out.println("Yes");
        System.out.println(new String(s));
    }
}

