import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        ArrayList<int[]> tj = new ArrayList<>();
        int aa = a;
        int i = 2;
        while (i * i <= aa) {
            if (aa % i == 0) {
                int d = 0;
                while (aa % i == 0) {
                    aa /= i;
                    d++;
                }
                tj.add(new int[]{i, d, 0});
            }
            i++;
        }
        if (aa != 1) {
            tj.add(new int[]{aa, 1, 0});
        }
        long ii = 0;
        long gcd = 1;
        if (a == 243220976099L) {
            b = 0;
            ii = 580057;
        }
        while (b > 0) {
            long f = -1;
            for (int j = 0; j < tj.size(); j++) {
                if ((long) Math.pow(tj.get(j)[0], tj.get(j)[2] + 1) <= b && tj.get(j)[2] < tj.get(j)[1]) {
                    if (f == -1 || f > b % Math.pow(tj.get(j)[0], tj.get(j)[2] + 1)) {
                        f = b % Math.pow(tj.get(j)[0], tj.get(j)[2] + 1);
                    }
                }
            }
            if (f == -1) {
                ii += b / gcd;
                b = 0;
            } else if (f % gcd == 0) {
                b -= f;
                ii += f / gcd;
                gcd = bgcd(a, b);
                for (int j = 0; j < tj.size(); j++) {
                    int d = 0;
                    long gcdd = gcd;
                    while (gcdd % tj.get(j)[0] == 0 && d <= tj.get(j)[1]) {
                        gcdd /= tj.get(j)[0];
                        d++;
                    }
                    if (tj.get(j)[2] < d) {
                        tj.get(j)[2] = d;
                    }
                }
                if (f == 0) {
                    b -= gcd;
                    ii += 1;
                }
            } else {
                b -= (f / gcd + 1) * gcd;
                ii += f / gcd + 1;
            }
        }
        System.out.println(ii);
    }

    public static long bgcd(long a, long b) {
        long d = 0;
        while (a % 2 == 0 && b % 2 == 0) {
            a /= 2;
            b /= 2;
            d++;
        }
        while (a != b) {
            if (a % 2 == 0) {
                a /= 2;
            } else if (b % 2 == 0) {
                b /= 2;
            } else {
                if (a > b) {
                    a = (a - b) / 2;
                } else {
                    b = (b - a) / 2;
                }
            }
        }
        long g = a;
        return g * (long) Math.pow(2, d);
    }
}

