import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static Map<String, Integer> dp = new HashMap<>();

    public static int count(int n, int low) {
        String k = n + "," + low;
        if (dp.containsKey(k)) return dp.get(k);
        int l1 = (int) Math.floor((double) (n - 1) / 2);
        if (l1 < low) return 0;
        int l2 = n - 1 - l1;
        int result = 1 + count(l1, low) + count(l2, low);
        dp.put(k, result);
        return result;
    }

    public static int getPos(int l, int r, int low, int want) {
        int m = (l + r) / 2;
        want -= 1;
        if (want == 0) return m;
        int c1 = count(m - l, low);
        int c2 = count(r - m, low + 1);
        if (c1 + c2 >= want) {
            return getPos(l, m - 1, low, want - c2);
        } else {
            return getPos(m + 1, r, low, want - c1);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        if (k == 1) System.out.println(1);
        else if (k == 2) System.out.println(n);
        else {
            int lo = 0, hi = n + 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (count(n - 2, mid) >= k - 2) {
                    lo = mid;
                } else {
                    hi = mid - 1;
                }
            }
            System.out.println(getPos(2, n - 1, lo, k - 2));
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        long M = 1000000007;
        long[][] d = new long[64][64];
        for (int i = 0; i < 64; i++) {
            for (int j = 0; j < 64; j++) {
                if (i == 0 || i == j) {
                    d[i][j] = 1;
                } else {
                    d[i][j] = (d[i - 1][j - 1] + d[i - 1][j]) % M;
                }
            }
        }

        int[] v = {0, 0};
        for (int x : readArray(scanner)) {
            if (x > 50) {
                v[1]++;
            } else {
                v[0]++;
            }
        }
        k /= 50;

        long[] t = new long[8192];
        int[] c = new int[8192];
        int[] q = new int[8192];
        int h = 0;

        for (int i = 0; i < 8192; i++) {
            t[i] = M;
            c[i] = 0;
        }

        q[h++] = K(0, v[0], v[1]);
        t[q[0]] = 0;
        c[q[0]] = 1;

        while (h < q.length && q[h - 1] >= 0) {
            int u = q[--h];
            int x = (int) (u / 3600);
            int y = (int) ((u / 60) % 60);
            int z = (int) (u % 60);

            for (int i = 0; i <= y; i++) {
                for (int j = 0; j <= z; j++) {
                    if ((i + j) != 0 && i + j * 2 <= k) {
                        int w = K(1 - x, v[0] - y + i, v[1] - z + j);
                        if (t[w] >= M) {
                            t[w] = t[u] + 1;
                            q[h++] = w;
                        }
                        if (t[w] == t[u] + 1) {
                            c[w] = (int)((c[w] + c[u] * d[y][i] * d[z][j]) % M);
                        }
                    }
                }
            }
        }

        int u = K(1, v[0], v[1]);
        System.out.println(t[u] < M ? t[u] : -1);
        System.out.println(c[u]);

        scanner.close();
    }

    private static long K(long x, long y, long z) {
        return ((x * 60) + y) * 60 + z;
    }

    private static int[] readArray(Scanner scanner) {
        String[] parts = scanner.nextLine().split(" ");
        int[] array = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            array[i] = Integer.parseInt(parts[i]);
        }
        return array;
    }
}

