        int ra = Integer.parseInt(inputs[1]);
        int ta = Integer.parseInt(inputs[2]);

        inputs = scanner.nextLine().trim().split("\\s+");

        int lb = Integer.parseInt(inputs[0]);
        int rb = Integer.parseInt(inputs[1]);
        int tb = Integer.parseInt(inputs[2]);

        long k = (long)(la - lb) / gcd(ta, tb);
        long klo = Math.floor(k);
        long khi = Math.ceil(k);

        long ans = 0;

        for (long dk : new long[]{klo, khi}) {
            long df = lb - la + dk * gcd(ta, tb);
            long bx = la + df;
            long by = bx + rb - lb;
            ans = Math.max(ans, intersection(la, ra, bx, by));
        }

        System.out.println(ans);
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    private static long intersection(long ax, long ay, long bx, long by) {
        long l = Math.max(ax, bx);
        long r = Math.min(ay, by);
        if (l > r) return 0;
        return r - l + 1;
    }
}

