public class Main {
    private static Map<String, Integer> all = new HashMap<>();
    private static Map<String, Integer> limit = new HashMap<>();
    private static int n, m;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        n = Integer.parseInt(input[0]);
        m = Integer.parseInt(input[1]);

        int ret = searchAll(1, n) - searchLimit(1, n, 1);
        System.out.println(ret);

        scanner.close();
    }

    private static int searchAll(int lo, int hi) {
        if (lo == hi) {
            return 1;
        }
        String key = "searchAll:" + lo + ":" + hi;
        if (all.containsKey(key)) {
            return all.get(key);
        }
        all.put(key, 0);
        all.put(key, all.get(key) + searchAll(lo + 1, hi));
        all.put(key, all.get(key) + searchAll(lo, hi - 1));

        for (int i = lo + 1; i < hi; i++) {
            all.put(key, all.get(key) + searchAll(lo, i - 1) * searchAll(i + 1, hi));
        }

        return all.get(key);
    }

    private static int searchLimit(int lo, int hi, int depth) {
        if (lo == hi) {
            if (depth < m) {
                return 1;
            } else {
                return 0;
            }
        }
        String key = "searchLimit:" + lo + ":" + hi + ":" + depth;
        if (limit.containsKey(key)) {
            return limit.get(key);
        }
        limit.put(key, 0);
        limit.put(key, limit.get(key) + searchLimit(lo + 1, hi, depth + 1));
        limit.put(key, limit.get(key) + searchLimit(lo, hi - 1, depth + 1));

        for (int i = lo + 1; i < hi; i++) {
