import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static Map<Integer, Integer> tab1 = new HashMap<>();
    private static Map<Pair<Integer, Integer>, Integer> tab2 = new HashMap<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();
        System.out.println(num1(n) - num2(n, h));
    }

    private static int num1(int n) {
        if (n < 0) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (!tab1.containsKey(n)) {
            int r = 0;
            for (int i = 0; i < n; i++) {
                r += num1(i) * num1(n - 1 - i);
            }
            tab1.put(n, r);
        }
        return tab1.get(n);
    }

    private static int num2(int n, int h) {
        if (n < 0 || h <= 0 || n >= Math.pow(2, h - 1)) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (n < h) {
            return num1(n);
        }
        if (!tab2.containsKey(new Pair<>(n, h))) {
            int r = 0;
            for (int i = 0; i < n; i++) {
                r += num2(i, h - 1) * num2(n - 1 - i, h - 1);
            }
            tab2.put(new Pair<>(n, h), r);
        }
        return tab2.get(new Pair<>(n, h));
    }
}

class Pair<K, V> {
    private K key;
    private V value;

    public Pair(K key, V value) {
        this.key = key;
        this.value = value;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Pair<?, ?> pair = (Pair<?, ?>) o;
        return key.equals(pair.key) && value.equals(pair.value);
    }

    @Override
    public int hashCode() {
        return key.hashCode() ^ value.hashCode();
    }
}

