import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputs = scanner.nextLine().split(" ");
        int l1 = Integer.parseInt(inputs[0]);
        int r1 = Integer.parseInt(inputs[1]);
        int l2 = Integer.parseInt(inputs[2]);
        int r2 = Integer.parseInt(inputs[3]);

        int[] l = {l1, l2};
        int[] r = {r1, r2};

        int ans = 0;
        for (int s = 0; s < 31; s++) {
            int[][] z = {{}, {}};
            for (int hui = 0; hui < 2; hui++) {
                int[] f = new int[3];
                int t = l[hui] - 1;
                for (int j = 0; j < 3; j++) {
                    t = nextWhere(t + 1, s);
                    if (t > r[hui]) {
                        break;
                    }
                    f[j] = t;
                }

                if (f[0] == 0 && f[1] == 0 && f[2] == 0) {
                    continue;
                } else if (f[1] == 0 && f[2] == 0) {
                    z[hui][0] = Math.min(f[0] - l[hui], (1 << s) - 1);
                    z[hui][1] = Math.min(r[hui] - f[0], (1 << s) - 1);
                } else if (f[2] == 0) {
                    z[hui][0] = Math.min(f[0] - l[hui], (1 << s) - 1);
                    z[hui][1] = (1 << s) - 1;
                    z[hui][2] = Math.min(r[hui] - f[1], (1 << s) - 1);
                } else {
                    z[hui][0] = (1 << s) - 1;
                    z[hui][1] = (1 << s) - 1;
                    z[hui][2] = (1 << s) - 1;
                }
            }

            for (int i : z[0]) {
                for (int j : z[1]) {
                    ans = Math.max(ans, Math.min(i[0], j[0]) + Math.min(i[1], j[1]) + 1);
                }
            }
        }
        System.out.println(ans);
    }

    public static int[] nextWhere(int l, int s) {
        int fs = 1 << s;
        int st = 1 << (s + 1);
        return l % st == fs ? l : l + (st - (l - fs) % st);
    }
}

