import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    private static final BigInteger MOD = BigInteger.valueOf((long) Math.pow(10, 9) + 7);
    private static ArrayList<Integer>[] factors;
    private static ArrayList<Integer>[] primeFactors;
    private static BigInteger[] inv;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        factors = new ArrayList[n + 1];
        primeFactors = new ArrayList[n + 1];
        inv = new BigInteger[n + 1];

        for (int i = 0; i <= n; i++) {
            factors[i] = new ArrayList<>();
            primeFactors[i] = new ArrayList<>();
        }

        for (int i = 0; i <= n; i++) {
            inv[i] = modInverse(BigInteger.valueOf(i), MOD).mod(MOD);
        }

        for (int i = 1; i <= n; i++) {
            boolean primeFact = false;
            if (primeFactors[i].size() < 2) {
                primeFactors[i].add(i);
                primeFact = true;
            }
            factors[i].add(i);

            for (int j = 2 * i; j <= n; j += i) {
                factors[j].add(i);
                if (primeFact) {
                    primeFactors[j].add(i);
                }
            }
        }

        ArrayList<Long> expectedLen = new ArrayList<>();
        expectedLen.add(0L);
        expectedLen.add(1L);

        for (int i = 2; i <= n; i++) {
            long eLen = 0;
            for (Integer ele : factors[i]) {
                if (ele != i) {
                    eLen += (f(ele, i / ele) * expectedLen.get(ele)) % MOD.longValue();
                }
            }
            eLen = ((eLen + 1) * n * inv[n - f(i, 1)].longValue()) % MOD.longValue();
            expectedLen.add(eLen);
        }

        System.out.println((sum(expectedLen) * inv[n]).mod(MOD));
    }

    private static BigInteger modInverse(BigInteger a, BigInteger m) {
        BigInteger m0 = m, t, q;
        BigInteger x0 = BigInteger.ZERO, x1 = BigInteger.ONE;

        if (m.equals(BigInteger.ONE))
            return BigInteger.ZERO;

        while (!a.equals(BigInteger.ONE)) {
            q = a.divide(m);
            t = m;
            m = a.mod(m);
            a = t;

            t = x0;
            x0 = x1.subtract(q.multiply(x0));
            x1 = t;
        }

        if (x1.compareTo(BigInteger.ZERO) < 0)
            x1 = x1.add(m0);

        return x1;
    }

    private static BigInteger sum(ArrayList<Long> list) {
        BigInteger sum = BigInteger.ZERO;
        for (Long value : list) {
            sum = sum.add(BigInteger.valueOf(value));
        }
        return sum;
    }

    private static long f(int x, int y) {
        int remain = 0;
        int newN = n / x;
        int newY = 1;
        for (Integer fact : primeFactors[y]) {
            newY *= fact;
        }
        for (Integer fact : factors[newY]) {
            if (fact != 1) {
                if ((primeFactors[fact].size() & 1) == 1) {
                    remain -= newN / fact;
                } else {
                    remain += newN / fact;
                }
            }
        }
        return (newN - remain) % MOD.intValue();
    }
}

