import java.util.*;

public class Main {
    static int K, N;
    static long MOD = 998244353;
    static List<Long> g1 = new ArrayList<>(Arrays.asList(1L, 1L));
    static List<Long> g2 = new ArrayList<>(Arrays.asList(1L, 1L));
    static List<Long> inverse = new ArrayList<>(Arrays.asList(0L, 1L));

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        K = Integer.parseInt(input[0]);
        N = Integer.parseInt(input[1]);

        for (int i = 2; i <= 8000; i++) {
            g1.add((g1.get(g1.size() - 1) * i) % MOD);
            inverse.add((-inverse.get((int) (MOD % i)) * (MOD / i)) % MOD);
            g2.add((g2.get(g2.size() - 1) * inverse.get(inverse.size() - 1)) % MOD);
        }

        List<Long> ans = new ArrayList<>();
        for (int i = 2; i <= 2 * K; i++) {
            if (i <= K + 1) {
                long tmp = solve(i) % MOD;
                ans.add(tmp);
                System.out.println(tmp);
            } else {
                System.out.println(ans.get(-i + K));
            }
        }
    }

    static long cmb(int n, int r, long mod) {
        if (r < 0 || r > n) {
            return 0;
        }
        r = Math.min(r, n - r);
        return (g1.get(n) * g2.get(r) % mod) * g2.get(n - r) % mod;
    }

    static long kumiawase(int p, int q) {
        return cmb(p + q - 1, q - 1, MOD);
    }

    static long solve(int n) {
        assert n <= K + 1;
        long ans = 0;
        int kumi = (n - 1) / 2;
        for (int p = 0; p <= kumi; p++) {
            if (p > N) {
                break;
            }
            ans += (1 << p) * cmb(kumi, p, MOD) * kumiawase(N - p, p + (K - kumi * 2 - ((n % 2 == 0) ? 1 : 0)));
            if (n % 2 == 0 && N - p - 1 >= 0) {
                ans += (1 << p) * cmb(kumi, p, MOD) * kumiawase(N - p - 1, p + (K - kumi * 2 - ((n % 2 == 0) ? 1 : 0)));
            }
        }
        return ans;
    }
}

