        int mod = (int) 1e9 + 7;
        String[] input = scanner.nextLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);

        long[] A = new long[n + 1];
        long[] B = new long[n + 1];
        long[] C = new long[n + 1];
        long[] F = new long[n + 1];
        long[] G = new long[n + 1];

        F[0] = G[0] = 1;
        for (int i = 1; i <= n; i++) {
            G[i] = F[i] = F[i - 1] * i % mod;
            G[i] = power(G[i], mod - 2, mod);
        }

        for (int i = 0; i < n; i++) {
            if (i * 2 > n) {
                break;
            }
            B[i] = (F[n - i] * G[i] * G[n - i * 2]) % mod;
        }

        for (int i = 0; i <= n / 2; i++) {
            for (int j = 0; j <= n / 2; j++) {
                A[i + j] = (A[i + j] + B[i] * B[j]) % mod;
            }
        }

        for (int i = 0; i <= n; i++) {
            A[i] = A[i] * F[n - i] % mod;
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                C[j] = (C[j] + A[i] * F[i] * G[j] * G[i - j] * (1 - (i - j) % 2 * 2)) % mod;
            }
        }

        System.out.println(C[k] % mod);
    }

    private static long power(long base, long exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % mod;
            }
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}

