import java.util.Arrays;

public class Main {
    private static final long MOD = 998244353;
    private static final double MODF = (double) MOD;
    private static final double SHRT = (double) (1L << 16);

    public static void main(String[] args) throws Exception {
        String[] line1 = System.in.readLine().trim().split(" ");
        int n = Integer.parseInt(line1[0]);
        int k = Integer.parseInt(line1[1]);

        int[] f = new int[5 * n + 5];
        Arrays.fill(f, 0);
        String[] line2 = System.in.readLine().trim().split(" ");
        for (int d : Arrays.stream(line2).mapToInt(Integer::parseInt).toArray()) {
            f[d]++;
        }

        transform(f, 3);
        f = powerArray(f, n / 2);
        transform(f, 3, true);

        double ans = 0;
        for (int x : f) {
            ans = modProd((double) x, (double) x) % MODF;
        }
        System.out.println((int) ans);
    }

    private static void transform(int[] a, int G, boolean inv) {
        int n = 1, k = 0;
        while (n < a.length) {
            k++;
            n *= 2;
        }
        if (inv) {
            Arrays.fill(a, 0, a.length, 0);
        } else {
            Arrays.fill(a, 0, n, a[n - 1]);
        }

        int n2 = n / 2;
        double[] w = new double[n2];
        w[1] = pow(G, (MOD - 1) / n);
        if (inv) w[1] = pow(w[1], MOD - 2);
        for (int i = 2; i < n2; i++) {
            w[i] = modProd(w[i - 1], w[1]);
        }

        int[] rev = new int[n];
        for (int i = 0; i < n; i++) {
            rev[i] = rev[i >> 1] >> 1;
            if ((i & 1) == 1) rev[i] |= n2;
            if (i < rev[i]) {
                swap(a, i, rev[i]);
            }
        }

        int l = 2;
        while (l <= n) {
            int half = l / 2, diff = n / l;
            for (int i = 0; i < n; i += l) {
                int pw = 0;
                for (int j = i; j < i + half; j++) {
                    double v = modProd((double) a[j + half], w[pw]);
                    a[j + half] = (int) (a[j] - v >= 0 ? a[j] - v : a[j] - v + MOD);
                    a[j] = (int) (a[j] + v < MOD ? a[j] + v : a[j] + v - MOD);
                    pw += diff;
                }
            }
            l *= 2;
        }

        if (inv) {
            int invN = (int) pow(n, MOD - 2);
            for (int i = 0; i < n; i++) {
                a[i] = (int) modProd((double) a[i], (double) invN);
            }
        }
    }

    private static double modProd(double x, double y) {
        return (x - MODF * Math.floor(x / MODF)) * (y - MODF * Math.floor(y / MODF));
    }

    private static double pow(double base, long exp) {
        double result = 1.0;
        while (exp != 0) {
            if ((exp & 1) == 1) {
                result = modProd(result, base);
            }
            base = modProd(base, base);
            exp >>= 1;
        }
        return result;
    }

    private static double powerArray(int[] arr, int exp) {
        double[] result = new double[arr.length];
        for (int i = 0; i < arr.length; i++) {
            result[i] = modPow(arr[i], exp);
        }
        return result;
    }

    private static double modPow(int x, long exp) {
        double result = 1.0;
        while (exp != 0) {
            if ((exp & 1) == 1) {
                result = modProd(result, x);
            }
            x = modProd(x, x);
            exp >>= 1;
        }
        return result;
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

