import java.math.BigInteger;

public class Main {
    private static final int MOD = 998244353;
    private static BigInteger[] W;
    private static BigInteger[] iW;
    private static BigInteger g = BigInteger.valueOf(3);
    private static BigInteger ig = g.modInverse(BigInteger.valueOf(MOD - 2));

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        String[] inputs = br.readLine().split(" ");
        int n = Integer.parseInt(inputs[0]);
        int k = Integer.parseInt(inputs[1]);
        int f = Integer.parseInt(inputs[2]);

        if (f > 2 * k) {
            bw.write("0");
            bw.newLine();
            bw.close();
            return;
        }

        BigInteger[] A = new BigInteger[k + 1];
        for (int i = 0; i < k + 1; i++) {
            A[i] = BigInteger.ONE;
        }

        BigInteger[] B = null;
        BigInteger tot = BigInteger.ZERO;

        for (int i = 0; i < n; i++) {
            B = convolve(A.clone(), A.clone());
            if (i == n - 1) {
                break;
            }

            tot = B.stream().skip(k + 1).reduce(BigInteger.ZERO, BigInteger::add).mod(BigInteger.valueOf(MOD));

            A = new BigInteger[k + 1];
            BigInteger cum = BigInteger.ZERO;
            for (int j = k; j >= 0; j--) {
                A[j] = tot.add(B[j].multiply(BigInteger.valueOf(k + 1 - j))).mod(BigInteger.valueOf(MOD)).add(cum).mod(BigInteger.valueOf(MOD));
                tot = tot.add(B[j]).mod(BigInteger.valueOf(MOD));
                if (tot.compareTo(BigInteger.ZERO) >= 0) {
                    tot = tot.subtract(BigInteger.valueOf(MOD));
                }
            }
        }

        bw.write(B[f].toString());
        bw.newLine();
        bw.close();
    }

    private static BigInteger[] convolve(BigInteger[] A, BigInteger[] B) {
        int n0 = A.length + B.length - 1;
        int k = Integer.toBinaryString(n0).length();
        int n = 1 << k;

        A = extendArray(A, n);
        B = extendArray(B, n);

        fft(k, A);
        fft(k, B);

        for (int i = 0; i < n; i++) {
            A[i] = A[i].multiply(B[i]).mod(BigInteger.valueOf(MOD));
        }

        ifft(k, A);

        BigInteger inv = BigInteger.valueOf(n).modInverse(BigInteger.valueOf(MOD));
        for (int i = 0; i < n; i++) {
            A[i] = A[i].multiply(inv).mod(BigInteger.valueOf(MOD));
        }

        return trimArray(A, n0);
    }

    private static BigInteger[] extendArray(BigInteger[] arr, int length) {
        BigInteger[] newArr = new BigInteger[length];
        System.arraycopy(arr, 0, newArr, 0, Math.min(arr.length, length));
        return newArr;
    }

    private static BigInteger[] trimArray(BigInteger[] arr, int length) {
        BigInteger[] newArr = new BigInteger[length];
        System.arraycopy(arr, 0, newArr, 0, length);
        return newArr;
    }

