                    A[s] = A[s].add(temp).mod(BigInteger.valueOf(MOD));
                    A[s + d] = A[s].subtract(temp).mod(BigInteger.valueOf(MOD));
                }
            }
        }
    }

    private static void ifft(int k, BigInteger[] A) {
