            int ordK = 1;
            int kPowOrd = k;
            while (kPowOrd != 1) {
                ordK++;
                kPowOrd = (k * kPowOrd) % p;
            }
            int comps = (p - 1) / ordK;
            System.out.println(powerMod(p, comps, (int) Math.pow(10, 9) + 7));
        }
    }

    private static long powerMod(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % mod;
            exp = exp >> 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

