import java.util.*;

public class BinaryField {
    private long poly;
    private int deg;

    public BinaryField(String s) {
        if (s == null || s.isEmpty()) {
            this.poly = 0;
            this.deg = Integer.MIN_VALUE;
            return;
        }

        this.poly = 0;
        boolean firstOneFound = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '1') {
                if (!firstOneFound) {
                    this.deg = i;
                    firstOneFound = true;
                }
                this.poly = (this.poly << 1) | 1;
            } else if (c == '0') {
                if (firstOneFound) {
                    this.poly = this.poly << 1;
                }
            }
        }
    }

    public BinaryField(long poly) {
        this.poly = poly;
        if (poly == 0) {
            this.deg = Integer.MIN_VALUE;
        } else {
            this.deg = Long.toBinaryString(poly).length() - 1;
        }
    }

    public String toString() {
        return "BinaryField(poly=" + Long.toBinaryString(this.poly) + ", deg=" + this.deg + ")";
    }

    public boolean equals(Object obj) {
        if (obj instanceof BinaryField) {
            BinaryField other = (BinaryField) obj;
            return this.poly == other.poly;
        }
        return false;
    }

    public BinaryField add(BinaryField other) {
        return new BinaryField(this.poly ^ other.poly);
    }

    public BinaryField multiply(BinaryField other) {
        long temp = other.poly;
        long answer = 0;
        long align = this.poly;

        while (temp > 0) {
            if ((temp & 1) != 0) {
                answer ^= align;
            }

            align <<= 1;
            temp >>= 1;
        }

        return new BinaryField(answer);
    }

    public BinaryField divide(BinaryField other) throws ArithmeticException {
        if (other.poly == 0) {
            throw new ArithmeticException("Divide by zero");
        }

        long answer = 0;
        long temp = this.poly;

        for (int d = Math.max(this.deg - other.deg, 0); d >= 0; d--) {
            if ((temp & (1L << (other.deg + d))) != 0) {
                answer |= (1L << d);
                temp ^= (other.poly << d);
            }
        }

        return new BinaryField(answer);
    }

    public BinaryField modulo(BinaryField other) throws ArithmeticException {
        if (other.poly == 0) {
            throw new ArithmeticException("Modulo by zero");
        }

        long answer = 0;
        long temp = this.poly;

        for (int d = Math.max(this.deg - other.deg, 0); d >= 0; d--) {
            if ((temp & (1L << (other.deg + d))) != 0) {
                answer |= (1L << d);
                temp ^= (other.poly << d);
            }
        }

        return new BinaryField(temp);
    }

    public BinaryField square() {
        long answer = 0;
        long temp = this.poly;

        while (temp > 0) {
            long lsb = temp & (-temp);
            answer += lsb * lsb;

            temp -= lsb;
        }

        return new BinaryField(answer);
    }

    public BinaryField powmod(int exp, BinaryField mod) {
        BinaryField answer = new BinaryField(1);
        BinaryField temp = this;

        while (exp > 0) {
            if ((exp & 1) != 0) {
                answer = answer.multiply(temp).modulo(mod);
            }

            exp >>= 1;
            temp = temp.square().modulo(mod);
        }

        return answer;
    }

    public static BinaryField gcd(BinaryField poly1, BinaryField poly2) {
        if (poly1.deg < poly2.deg) {
            BinaryField temp = poly1;
            poly1 = poly2;
            poly2 = temp;
        }

        BinaryField p1 = poly1, p2 = poly2;
        while (p2.poly != 0) {
            BinaryField tempP1 = p2;
            p2 = p1.modulo(p2);
            p1 = tempP1;
        }

        return p1;
    }

    public static List<Tuple<BinaryField, Integer>> factorize(BinaryField poly) {
        List<Tuple<BinaryField, Integer>> answer = new ArrayList<>();
        BinaryField temp = poly;

        for (long d = 2; d <= (1L << (1 + poly.deg / 2)); d++) {
            BinaryField div = new BinaryField(d);

            int e = 0;
            while (temp.modulo(div).equals(new BinaryField(0))) {
                temp = temp.divide(div);
                e++;
            }

            if (e > 0) {
                answer.add(new Tuple<>(div, e));
            }

            if (temp.equals(new BinaryField(1))) {
                break;
            }
        }

        if (!temp.equals(new BinaryField(1))) {
            answer.add(new Tuple<>(temp, 1));
        }

        return answer;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();

        try {
            main(s);
        } catch (ArithmeticException e) {
            System.out.println("-1");
        }
    }

    public static void main(String s) {
        s = s.replaceFirst("^0+", "");
        int leadingZero = s.indexOf('1');

        if (leadingZero == -1) {
            System.out.println("-1");
            return;
        }

        BinaryField f2s = new BinaryField(s);
        BinaryField x = new BinaryField(2);
        List<Tuple<BinaryField, Integer>> factorsBin = factorize(f2s);

        long answer = 1;

        for (Tuple<BinaryField, Integer> pair : factorsBin) {
            BinaryField f = pair.first;
            int exp = pair.second;
            List<Integer> factorsPow = new ArrayList<>();

            for (long i = 2; i <= (1L << f.deg) - 1; i++) {
                if ((i & (i - 1)) == 0) {
                    factorsPow.add((int) i);
                }
            }

            for (int e : factorsPow) {
                if (x.powmod(e, f).equals(new BinaryField(1))) {
                    int need = exp == 1 ? e : e * (1 << (Integer.toBinaryString(exp - 1).length() - 2));

                    long g = gcd(answer, need).poly;
                    answer = answer * need / g;

                    break;
                }
            }
        }

        System.out.println(1 + leadingZero + " " + (1 + leadingZero + answer));
    }
}

