import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        int[] disjointSet = new int[n];
        Arrays.fill(disjointSet, -1);

        List<int[]> points = new ArrayList<>();
        Map<Integer, Integer> vertPoints = new HashMap<>();
        Map<Integer, Integer> horizPoints = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String[] parts = scanner.nextLine().split(" ");
            int a = Integer.parseInt(parts[0]);
            int b = Integer.parseInt(parts[1]);
            points.add(new int[]{a, b});

            if (vertPoints.containsKey(a)) {
                join(i, vertPoints.get(a), disjointSet);
            } else {
                vertPoints.put(a, i);
            }

            if (horizPoints.containsKey(b)) {
                join(i, horizPoints.get(b), disjointSet);
            } else {
                horizPoints.put(b, i);
            }
        }

        Map<Integer, List<int[]>> sets = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int r = root(i, disjointSet);
            if (sets.containsKey(r)) {
                sets.get(r).add(points.get(i));
            } else {
                sets.put(r, new ArrayList<>(Collections.singletonList(points.get(i))));
            }
        }

        long ans = 1;
        for (List<int[]> set : sets.values()) {
            List<Integer> horiz = new ArrayList<>();
            List<Integer> vert = new ArrayList<>();
            for (int[] point : set) {
                horiz.add(point[0]);
                vert.add(point[1]);
            }

            Set<Integer> uniqueHoriz = new HashSet<>(horiz);
            Set<Integer> uniqueVert = new HashSet<>(vert);

            int tmp = uniqueHoriz.size() + uniqueVert.size();
            if (tmp <= set.size()) {
                ans *= Math.pow(2, tmp);
            } else {
                ans *= Math.pow(2, tmp) - 1;
            }

            ans %= 1_000_000_007;
        }

        System.out.println(ans % 1_000_000_007);
    }

    private static int root(int x, int[] disjointSet) {
        List<Integer> path = new ArrayList<>();
        while (disjointSet[x] >= 0) {
            path.add(x);
            x = disjointSet[x];
        }
        for (int i : path) {
            disjointSet[i] = x;
        }
        return x;
    }

    private static void join(int x, int y, int[] disjointSet) {
        int r1 = root(x, disjointSet);
        int r2 = root(y, disjointSet);
        if (r1 == r2) return;
        disjointSet[r2] = r1;
    }
}

