public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[][][] dp = new int[110][110][2];
        int mod = 1000000007;
        int[] data = Arrays.stream(scanner.nextLine().split(" "))
                .mapToInt(Integer::parseInt)
                .toArray();

        int n = data[0];
        int k = data[1];
        int d = data[2];

        dp[0][0][0] = 1;
        int ans = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int g = 1; g <= k; g++) {
                    if (g > j) {
                        break;
                    }
                    if (g >= d) {
                        dp[i][j][1] += dp[i - 1][j - g][0];
                        dp[i][j][1] += dp[i - 1][j - g][1];
                    } else {
                        dp[i][j][0] += dp[i - 1][j - g][0];
                        dp[i][j][1] += dp[i - 1][j - g][1];
                    }

                    dp[i][j][1] %= mod;
                    dp[i][j][0] %= mod;
                }
                ans += dp[i][n][1];
                ans %= mod;
            }
        }

        System.out.println(ans);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Get the customer's requested board: 8 lines of input
        String[] order = new String[8];
        for (int i = 0; i < 8; i++) {
            order[i] = scanner.nextLine();
        }

        // Firstly, we create a variable allBlack (reference to an all-black row) and set it to be true
        boolean allBlack = true;
        // We instantiate the count of strokes as zero
        int count = 0;

        // Now, we iterate through the board, row by row
        for (String row : order) {
            // If we find a row with all 8 squares marked as black ('B')
            if ("BBBBBBBB".equals(row)) {
                // We clearly add 1 stroke to the count
                count += 1;
            } else {
                // Else, we say that it's not an all-black row
                allBlack = false;
            }
        }

        // Let's assume that all of the board's squares are marked with 'B'
        // It doesn't matter if we have already iterated through rows,
        // it's allowed to over-paint a square when rows of black cross columns of black
        // The next loop is actually to find columns of black squares
        for (int i = 0; i < 8; i++) {
            count += 1;
            for (int ii = 0; ii < 8; ii++) { // This is the second loop, because we have a board of 8x8
                // If the square is marked with 'W', we bring the count one step back
                if ("W".equals(order[ii].charAt(i))) {
                    count -= 1;
                    break;
                }
            }
        }

        // The simpliest case: if we got the count result to be 16 black squares,
        // we will subsequently need 8 strokes
        // We print this directly, just so our program wouldn't bother
        // to count the obvious and return a bigger count
        if (count == 16) {
            System.out.println("8");
        } else {
            System.out.println(count);
        }

        scanner.close();
    }
}

