import java.util.*;
public class Main {
    private static int mod = 1000000007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int T = scanner.nextInt();

        List<List<Integer>> A = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            List<Integer> row = new ArrayList<>();
            for (int j = 0; j < N; j++)
                row.add(scanner.nextInt());
            A.add(row);
        }

        int s = 0;
        for (int i = 1; i <= N; i++) {
            List<List<Integer>> comb = combinations(A, i);
            for (List<Integer> x : comb) {
                if (sumColumn(x, 0) == T) {
                    int a = countValueInColumn(x, 1, 1);
                    int b = countValueInColumn(x, 1, 2);
                    int c = countValueInColumn(x, 1, 3);
                    s = (s + ((out1(a, b, c) % mod + out2(a, b, c) % mod + out3(a, b, c) % mod)) % mod) % mod;
                }
            }
        }
        System.out.println(s);
    }

    private static List<List<Integer>> combinations(List<List<Integer>> arr, int k) {
        List<List<Integer>> ans = new ArrayList<>();
        combine(arr, new boolean[arr.size()], ans, k, 0);
        return ans;
    }

    private static void combine(List<List<Integer>> arr, boolean[] chosen, List<List<Integer>> ans, int k, int start) {
        if (k == 0) {
            List<Integer> temp = new ArrayList<>();
            for (int i = 0; i < arr.size(); i++) {
                if (chosen[i])
                    temp.addAll(arr.get(i));
            }
            ans.add(temp);
            return;
        }
        for (int i = start; i < arr.size(); i++) {
            chosen[i] = true;
            combine(arr, chosen, ans, k - 1, i + 1);
            chosen[i] = false;
        }
    }

    private static int sumColumn(List<List<Integer>> A, int col) {
        int sum = 0;
        for (List<Integer> row : A)
            sum += row.get(col);
        return sum;
    }

    private static int countValueInColumn(List<List<Integer>> A, int col, int value) {
        int count = 0;
        for (List<Integer> row : A)
            count += row.get(col) == value ? 1 : 0;
        return count;
    }

    private static int out1(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0)
            return 0;
        if (a == 1 && b == 0 && c == 0)
            return 1;
        return a * (modAdd(out2(a - 1, b, c), out3(a - 1, b, c)));
    }

    private static int out2(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0)
            return 0;
        if (a == 0 && b == 1 && c == 0)
            return 1;
        return b * (modAdd(out1(a, b - 1, c), out3(a, b - 1, c)));
    }

    private static int out3(int a, int b, int c) {
        if (a < 0 || b < 0 || c < 0)
            return 0;
        if (a == 0 && b == 0 && c == 1)
            return 1;
        return c * (modAdd(out2(a, b, c - 1), out1(a, b, c - 1)));
    }

    private static int modAdd(int a, int b) {
        return (a + b) % mod;
    }
}

