import java.util.Arrays;
import java.util.Scanner;

public class Main {
    static final int MOD = (int) 1e9 + 7;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        long[][] f = new long[60][60];
        long[][] g = new long[60][60];
        long[][] s = new long[60][60];

        Arrays.stream(f).forEach(row -> Arrays.fill(row, 0));
        Arrays.stream(g).forEach(row -> Arrays.fill(row, 0));
        Arrays.stream(s).forEach(row -> Arrays.fill(row, 0));

        f[0][0] = s[0][0] = 1;
        long[] inv = new long[60];
        inv[0] = 1;

        pow(inv, 0);

        for (int i = 1; i <= n; i++) {
            inv[i] = pow(i, MOD - 2);
        }

        for (int node = 1; node <= n; node++) {
            for (int cut = 1; cut <= n; cut++) {
                long tmp = 0;
                for (int ln = 0; ln < node; ln++) {
                    for (int lc = cut - 1; lc <= n; lc++) {
                        if (f[ln][lc] == 0) continue;
                        if (lc == cut - 1) {
                            tmp = (tmp + f[ln][lc] * s[node - ln - 1][cut - 1]) % MOD;
                        } else {
                            tmp = (tmp + f[ln][lc] * f[node - ln - 1][cut - 1]) % MOD;
                        }
                    }
                }
                long cnt = 1;
                if (tmp != 0) {
                    int cn = 0, cc = 0;
                    for (int i = 1; i <= n; i++) {
                        cn += node;
                        cc += cut;
                        cnt = (cnt * (tmp + i - 1) % MOD * inv[i] % MOD) % MOD;
                        if (cn > n || cc > n) break;
                        for (int j = n - cn; j >= 0; j--) {
                            for (int k = n - cc; k >= 0; k--) {
                                if (f[j][k] == 0) continue;
                                g[j + cn][k + cc] += f[j][k] * cnt;
                                g[j + cn][k + cc] %= MOD;
                            }
                        }
                    }
                    for (int i = 0; i <= n; i++) {
                        for (int j = 0; j <= n; j++) {
                            f[i][j] = (f[i][j] + g[i][j]) % MOD;
                            g[i][j] = 0;
                        }
                    }
                }
            }

            for (int cut = n; cut >= 0; cut--) {
                s[node][cut] = (s[node][cut + 1] + f[node][cut]) % MOD;
            }
        }

        System.out.println(f[n][m - 1]);
    }

    private static void pow(long[] inv, int exp) {
        inv[0] = 1;
        for (int i = 1; i < 60; i++) {
            inv[i] = (inv[i - 1] * (MOD - MOD / i)) % MOD;
        }
    }
}

