import java.util.Scanner;
import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        Function<String[], Integer> InputList = (dtypeArray) -> {
            int[] result = new int[dtypeArray.length];
            for (int i = 0; i < dtypeArray.length; i++) {
                result[i] = Integer.parseInt(dtypeArray[i]);
            }
            return result[0]; // Assuming you need only one value from the split array
        };

        int t = 1;
        if (!true) { // Change this condition based on your logic
            t = scanner.nextInt();
        }

        for (int i = 0; i < t; i++) {
            int ans = solve(scanner);
            System.out.println(ans);
        }
    }

    private static int solve(Scanner scanner) {
        int N = scanner.nextInt();
        int[] ans = {0, 3, 5, 7, 8};
        if (N < 5) return ans[N];

        return binarySearch(N, scanner);
    }

    private static boolean valid(int x) {
        return x % 4 == 0 || (x & 1) != 0;
    }

    private static int loc(int x) {
        int p = x - 1;
        int doneUpto = ((p + 1) / 2 - 1) + (p / 4) - 1;
        return valid(x) ? doneUpto + 1 : doneUpto;
    }

    private static int binarySearch(int N, Scanner scanner) {
        int Min = 0;
        int Max = 3 * 1000000000;

        while (Min < Max) {
            int Mid = (Min + Max) / 2;
            int locValue = loc(Mid);

            if (locValue == N) {
                return valid(Mid) ? Mid : Mid - 1;
            } else if (locValue < N) {
                Min = Mid + 1;
            } else {
                Max = Mid;
            }
        }

        return -1; // In case no solution is found
    }
}

