import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    private static boolean[][] edges;
    private static boolean[][] nodes;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] nm = scanner.nextLine().split(" ");
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);

        edges = new boolean[n][n];
        nodes = new boolean[n][3];

        // Initialize nodes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 3; j++) {
                nodes[i][j] = true;
            }
        }

        // Read edges
        for (int i = 0; i < m; i++) {
            String[] ab = scanner.nextLine().split(" ");
            int a = Integer.parseInt(ab[0]) - 1;
            int b = Integer.parseInt(ab[1]) - 1;
            edges[a][b] = true;
            edges[b][a] = true;
        }

        // Complete graph
        if (m == n * (n - 1) / 2) {
            List<Character> solution = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                solution.add('b');
            }
            System.out.println("Yes");
            System.out.println(solution.stream().map(String::valueOf).collect(Collectors.joining()));
            return;
        }

        // Guess one node to be 'a' and another to be 'c'
        int a = 0;
        int b = 1;
        nodes[a][2] = false;   // node[a] be 'a'
        nodes[b][0] = false;   // node[b] be 'c'

        boolean updated = true;
        boolean hasDeadNode = false;
        while (updated) {
            updated = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i != j) {
                        if (deduce(i, j)) {
                            updated = true;
                        }
                        if (isDeadNode(j)) {
                            hasDeadNode = true;
                            break;
                        }
                    }
                }
                if (hasDeadNode) {
                    break;
                }
            }
            if (hasDeadNode) {
                break;
            }
        }

        if (hasDeadNode) {
            System.out.println("No");
        } else {
            System.out.println("Yes");
            List<Character> solution = generateSolution();
            System.out.println(solution.stream().map(String::valueOf).collect(Collectors.joining()));
        }
    }

    private static boolean hasEdge(int a, int b) {
        return edges[a][b];
    }

    private static boolean deduce(int n1, int n2) {
        if (hasEdge(n1, n2) && certain(n1)) {
            int val1 = get(n1);
            if (val1 == 0 && nodes[n2][2]) {
                nodes[n2][2] = false;
                return true;
            }
            if (val1 == 2 && nodes[n2][0]) {
                nodes[n2][0] = false;
                return true;
            }
        } else if (!hasEdge(n1, n2) && certain(n1)) {
            int val1 = get(n1);
            if (val1 == 0 && nodes[n2][0]) {
                nodes[n2][0] = false;
                return true;
            }
            if (val1 == 2 && nodes[n2][2]) {
                nodes[n2][2] = false;
                return true;
            }
        }
        return false;
    }

    private static boolean certain(int k) {
        return nodes[k][0] + nodes[k][1] + nodes[k][2] == 1;
    }

    private static boolean freeNode(int k) {
        return nodes[k][0] + nodes[k][1] + nodes[k][2] == 3;
    }

    private static boolean isDeadNode(int k) {
        return nodes[k][0] + nodes[k][1] + nodes[k][2] == 0;
    }

    private static int get(int k) {
        if (nodes[k][0]) {
            return 0;
        }
        if (nodes[k][1]) {
            return 1;
        }
        return 2;
    }

    private static List<Character> generateSolution() {
        List<Character> solution = new ArrayList<>();
        for (int i = 0; i < nodes.length; i++) {
            if (nodes[i][0]) {
                solution.add('a');
            } else if (nodes[i][1]) {
                solution.add('b');
            } else {
                solution.add('c');
            }
        }
        return solution;
    }
}

