                Arrays.stream(new int[]{7, 8, 9, 10, 11}, 0, 5).toArray(), Arrays.stream(new int[]{12, 13, 14, 15}, 0, 4).toArray(),
                Arrays.stream(new int[]{16, 17, 18}, 0, 3).toArray(), 
                new int[]{7, 12, 16}, new int[]{3, 8, 13, 17}, new int[]{0, 4, 9, 14, 18}, new int[]{1, 5, 10, 15}, new int[]{2, 6, 11});

        Scanner scanner = new Scanner(System.in);
        String[] inputs = new String[5];
        for (int i = 0; i < 5; i++) {
            inputs[i] = scanner.nextLine();
        }
        int px = calculatePx(inputs, a1List);

        int size = 600000;
        q = new boolean[size];
        Collections.sort(m);
        for (int i = 0; i <= px; i++) {
            if (q[i]) continue;
            for (int p : m) {
                if ((i & p) != 0) continue;
                q[i | p] = true;
            }
        }

        System.out.println(q[px] ? "Karlsson" : "Lillebror");
    }

    private static void addAll(List<int[]> lists, int... arrays) {
        for (int[] array : arrays) {
            for (int value : array) {
                madd(value);
            }
        }
    }

    private static void madd(int... values) {
        int sum = 0;
        for (int value : values) {
            sum += (int)Math.pow(2, value);
        }
        m.add(sum);
    }

    private static int calculatePx(String[] inputs, List<int[]> a1List) {
        int totalSum = 0;
        for (String input : inputs) {
            int index = Integer.parseInt(input.trim());
            for (int[] sublist : a1List) {
                for (int num : sublist) {
                    if (num == index) {
                        totalSum += (int)Math.pow(2, num);
                        break;
                    }
                }
            }
        }
        return totalSum;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();

        long M = (long) Math.pow(10, 9) + 7;
        Function<int[], Integer> K = (x -> ((x[0] * 60) + x[1]) * 60 + x[2]);

        int[] v = {0, 0};
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            if (x > 50) {
                v[0]++;
            } else {
                v[1]++;
            }
        }

        k /= 50;

        int[][] t = new int[8192][];
        for (int[] row : t) {
            Arrays.fill(row, (int) M);
        }
        int[] c = new int[8192];
        List<Integer> q = new ArrayList<>();
        int h = 0;
        int[] initial = K.apply(new int[]{0, v[0], v[1]});
        t[initial][0] = 0;
        c[initial] = 1;

        int[][] d = new int[64][64];
        for (int i = 0; i < 64; i++) {
            Arrays.fill(d[i], 1);
            for (int j = 1; j < i; j++) {
                d[i][j] = (int)((d[i - 1][j - 1] + d[i - 1][j]) % M);
            }
        }

        while (h < q.size()) {
            int[] u = K.apply(new int[]{q.get(h) / 3600, (q.get(h) / 60) % 60, q.get(h) % 60});
            h++;

            for (int i = 0; i <= u[1]; i++) {
                for (int j = 0; j <= u[2]; j++) {
                    if ((i + j) != 0 && (i + j) * 2 <= k) {
                        int[] w = K.apply(new int[]{1 - u[0], v[0] - u[1] + i, v[1] - u[2] + j});
                        if (t[w[0]][w[1]] >= M) {
                            t[w[0]][w[1]] = t[u[0]][u[1]] + 1;
                            q.add(K.apply(w));
                        }
                        if (t[w[0]][w[1]] == t[u[0]][u[1]] + 1) {
                            c[w[0]][w[1]] = (int)((c[w[0]][w[1]] + (long)c[u[0]][u[1]] * d[i][j] * d[j][i]) % M);
                        }
                    }
                }
            }
        }

        int[] finalState = K.apply(new int[]{1, v[0], v[1]});
        System.out.println(t[finalState[0]][finalState[1]] < M ? t[finalState[0]][finalState[1]] : -1);
        System.out.println(c[finalState[0]][finalState[1]]);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int k = scanner.nextInt();
        List<Integer> ls = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            ls.add(scanner.nextInt());
        }

        Collections.sort(ls);

        Set<Integer> arrSet = new HashSet<>();

        for (Integer i : ls) {
            while (i != 0) {
                arrSet.add(i);
                i /= 2;
            }
            arrSet.add(0);
        }

        List<Integer> arr = new ArrayList<>(arrSet);
        Collections.sort(arr);

        long m = Long.MAX_VALUE;

        for (Integer x : arr) {
            long Cnt = 0;
            long S = 0;

            for (Integer i : ls) {
                long cnt = 0;

                while (i > x) {
                    i /= 2;
                    cnt++;
                }

                if (i == x && Cnt < k) {
                    S += cnt;
                    Cnt++;
                }
            }

            if (Cnt == k) {
                m = Math.min(m, S);
            }
        }

        System.out.println(m);

        scanner.close();
    }
}

