        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        long[][] s = new long[n + 1][];
        long[][] t = new long[n + 1][];

        // Initialize arrays
        for (int i = 0; i <= n; i++) {
            s[i] = new long[n + 1];
            t[i] = new long[n + 1];
            s[i][i] = 1;
            t[i][i] = 1;
        }

        // Calculate s values
        for (int m = 1; m <= n; m++) {
            for (int k = 0; k < m; k++) {
                s[m][m] += s[m - 1 - k][k] * s[k];
            }
        }

        // Calculate t values
        for (int j = 0; j < h; j++) {
            for (int m = 1; m <= n; m++) {
                for (int k = 0; k < m; k++) {
                    t[m][m] += ((s[k][m] - t[k][m]) * t[m - 1 - k][k] + s[m - 1 - k][m] * t[k][m]);
                }
            }
        }

        System.out.println(t[n][n]);
        scanner.close();
    }
